def _render_killer_loc(table, loc_key, kname):
    """Localized death-method text -> Chinese phrase with the killer name substituted.

    The raw table value is used because `L.loc` would strip the [TARGET_CHARACTER...] slots;
    '' when a slot or template reference stays unresolved."""
    raw = table.get(str(loc_key))
    if not isinstance(raw, str) or not raw:
        return ""
    s = raw.replace("[CHARACTER.GetHerHis]的", "\x03")
    s = s.replace("[TARGET_CHARACTER.GetUINamePossessive]", "\x01")
    s = s.replace("[TARGET_CHARACTER.GetUIName]", "\x02")
    s = s.replace("[CHARACTER.GetHerHis]", "\x03")
    s = L.clean_loc_value(s, table)
    s = s.replace("\x01", kname).replace("\x02", kname).replace("\x03", "其")
    if "[" in s or "$" in s or "\x01" in s or "\x02" in s or "\x03" in s:
        return ""
    return s


# Death reasons that are public by themselves: common/deathreasons/*.txt marks them with
# `public_knowledge = yes` (death_execution, death_murder_known), so the killer counts as common
# knowledge; the others depend on the save flag `dead_data.killer_known`.
_PUBLIC_DEATH_REASONS = frozenset({"death_execution", "death_murder_known"})

# Public-archive death wording. `style.FLAVOR_DEATH_ZH` is omniscient and belongs to the assassin
# chapter only; the public reading is the game localization value, listed here when it differs.
PUBLIC_DEATH_ZH = {
    "death_mysterious": "神秘死亡",
}


def _death_clause(table, reason_key, killer, name_of, public=False):
    """Death reason -> natural Chinese clause with the agent embedded (被XXX谋杀, 与XXX决斗而亡
    or a bare cause when there is no agent); killer is a character id or None, name_of maps ids
    to names, and public=True takes the public wording."""
    reason = _death_reason(table, reason_key, public=public)
    kname = name_of(killer) if killer is not None else ""
    if killer is not None and kname:
        verb = _DEATH_KILLER_VERB.get(reason_key)
        if verb:
            return f"被{kname}{verb}"
        verb = _DEATH_EXECUTOR_VERB.get(reason_key)
        if verb:
            return f"被{kname}{verb}"
        verb = _DEATH_OPPONENT_VERB.get(reason_key)
        if verb:
            return f"与{kname}{verb}而亡"
        role = _DEATH_AGENT_TAIL.get(reason_key)
        if role:
            return f"{reason}，{role}为{kname}"
        return reason  # a battlefield/accident/illness killer is not a murderer, so no name
    # no agent: a bare action cause gets 被 (被处决/被谋杀/被毒杀)
    if reason in ("处决", "谋杀", "毒杀"):
        reason = "被" + reason
    return reason


def render_motto(motto, table):
    """House motto -> Chinese. `dynasty_house.motto` is either a string (already-rendered
    Chinese, or a localization key) or a template dict {key, variables:[...]} whose $N$ slots
    are filled and whose remaining dynamic references are stripped."""
    if isinstance(motto, str):
        s = motto.strip()
        if not s:
            return ""
        if any("\u3400" <= ch <= "\u9fff" for ch in s):
            return s
        v = L.loc(table, s)
        return v or s
    if isinstance(motto, dict):
        key = motto.get("key") or ""
        tpl = L.loc(table, key)
        if not tpl:
            return ""
        slots = {}
        for v in motto.get("variables") or []:
            if not isinstance(v, dict):
                continue
            sv = v.get("value")
            if not sv:
                continue
            slots[str(v.get("key"))] = L.loc(table, sv) or sv
        text = tpl
        for sk, sv in slots.items():
            text = text.replace("${" + sk + "}", sv)
        text = re.sub(r"\$\d+\$", "", text)  # 未填充的空槽清理
        return L.strip_ck3_format(text).strip()
    return ""


# ---------------------------------------------------------------------------
# Facts context
# ---------------------------------------------------------------------------

# A title-level word is not appended when the name already ends in a state suffix (汗国/教宗国/…).
_STATE_SUFFIX_RE = re.compile(
    r"(帝国|王国|汗国|大公国|公国|侯国|伯国|苏丹国|哈里发国|酋长国|"
    r"教宗国|属邦|皇朝|王朝|行台|天朝|国|邦|朝)$")

# Save flags for a custom origin with no genealogy (see `Facts.is_custom_start`): scripted landless
# adventurers and designed characters get no parents and no ruler_designer_characters entry.
_NO_GENEALOGY_FLAGS = {
    "do_not_generate_starting_family",
    "special_laamp_char",
    "has_scripted_appearance",
}

# Prince word overrides: localization renders a feudal kingdom's daughter as 郡主 (a Tang-style East
# Asian title), while a western kingdom's or empire's daughter always reads 公主; the celestial
# government's 皇女/郡主/公女 are deliberate flavor and are not overridden (see `_prince_word`).
_PRINCE_WORD_OVERRIDE = {
    "princess_kingdom_feudal_chinese": "公主",
}


# Fallback sort key for an empty date: it must share the type of `cl.date_key`'s return (a tuple)
# and sort last, since comparing it against a tuple raises TypeError and would fail the facts build.
_DATE_KEY_MAX = (9999, 0, 0)


def _date_ord(d):
    """Approximate day ordinal (year*372 + (month-1)*31 + day); no calendar arithmetic, so
    month-end crossings are off by a day or two. Invalid input returns a very small number."""
    try:
        y, m, dd = (int(x) for x in str(d).split(".")[:3])
    except (TypeError, ValueError):
        return -10 ** 9
    return y * 372 + (m - 1) * 31 + dd


class Facts:
    """Context of one build_facts run: cache + melt + name/title/localization resolution.

    as_of caps every fact (offices, nicknames, holder history, timeline, court) at that
    date; decade (1, 2, 3…) restricts timeline/overview/summary to (as_of−10y, as_of].
    """

    def __init__(self, cache, melt, names_path, as_of=None, decade=None,
                 nickname_override=None, cfg=None, campaign=None):
        self.cache = cache
        self.melt = melt
        self.names_path = names_path
        self.as_of = as_of
        self.decade = decade
        # All subject caches of the same campaign {player_id: cache}, used to resolve
        # kinship and labels against a subject chain's predecessors/successors.
        self.campaign = dict(campaign or {})
        if cache.get("player_id") is not None:
            self.campaign.setdefault(cache.get("player_id"), cache)
        # Config: single source of truth for switches (defaults to config.json).
        self.cfg = cfg if cfg is not None else llm.load_config()
        # Whether Carnalitas event opinion families reach the facts (off by default).
        self._show_carnal_opinions = bool(
            (self.cfg or {}).get("carnal_opinions"))
        # Per-era nickname overrides {cid: nickname}: a decade rebuild reads that
        # decade's melt, so its nicknames do not drift to the latest save.
        self._nick_override = dict(nickname_override or {})
        self._lt = ((melt.get("landed_titles") or {}).get("landed_titles") or {})
        self._tl = melt.get("traits_lookup") or []
        self._chars = cl.all_characters(melt)
        self.table = L.table()
        self.provmap = L.province_map()
        # Currency band table (defines thresholds for piety/prestige/influence/merit)
        # and court-position display-name variants.
        self._bands = (L.currency_levels() or {}).get("bands") or {}
        self._cp_variants = L.court_positions()
        # Game flavorization table: authority for ruler address forms and title suffixes.
        self._flavor = FZ.table()
        # Doctrines granting human sacrifice; the gate for the "sacrifice" execution
        # method (see execution_method).
        try:
            self._sacrifice_doctrines = L.doctrines_granting("human_sacrifice_active")
        except Exception:
            self._sacrifice_doctrines = set()
        self._council_tasks = L.council_tasks()
        # Ordered bishop-title arms and council seat name chain (game GetActualBishopTitle /
        # `council_positions.name`): authority for court chaplain church words and seat names.
        try:
            self._bishop_titles = L.bishop_titles()
        except Exception:
            self._bishop_titles = {"arms": []}
        # Custom-localization arms for theocracy office titles (GetActualDukeTheocracyTitle /
        # GetActualCountTheocracyTitle); Christian theocratic rulers delegate their office
        # word entirely to them (see `_office_word` → `_loc_or_custom_word`).
        try:
            self._theocracy_titles = L.theocracy_titles()
        except Exception:
            self._theocracy_titles = {"blocks": {}}
        # Spiritual fulfillment bands (game `common/spiritual_fulfillment/*.txt`); level
        # words reuse the game's own level names (christian_fulfillment_level_N / default_…).
        try:
            self._sf_types = L.spiritual_fulfillment()
        except Exception:
            self._sf_types = {"types": []}
        try:
            self._council_names = L.council_names()
        except Exception:
            self._council_names = {"positions": {}}
        self._title_by_key = {}
        for tid, t in self._lt.items():
            if not isinstance(t, dict):  # guard against none entries
                continue
            k = t.get("key")
            if k:
                self._title_by_key[k] = int(tid)
        self._gov_cache = {}
        self._regnal_cache = {}  # regnal number (cid, tid, date) -> ordinal
        self._mem_date_cache = {}  # title memory fact date (tid, cid, d, reason, type)
        self._dyn_hist_cache = {}  # per-save dynamic name evolution (this cache + campaign peers)
        self._label_cache = {}   # person label (cid, date, style) -> text
        # Label registry filled while building event sentences (see log_names/index_names).
        # The stack is per-thread: biography.py's ThreadPool runs blocks concurrently and
        # another block's labels must not leak into this line's attributives.
        self._tls = threading.local()
        self.name_index = {}     # line text -> [[cid, label], …] in emission order
        # line text -> this line's subject cid (who the sentence is about). Third-party
        # names in a line take their kinship word from it, otherwise the protagonist's
        # in-law word lands in a sentence about someone else. Lines without a subject
        # (multi-dialect asides outside the timeline) are absent and fall back to the
        # subject of the biography.
        self.line_owner = {}
        # line text -> counterparty cids whose relation the sentence already states
        # (marriage/birth/bereavement); see `_REL_STATED_TYPES`.
        self.line_stated = {}
        # game opinion reasons (index over opinions.active_opinions, built lazily)
        self._opinion_index = None
        # Relation reasons from the cache (cache["relation_reasons"], built lazily):
        # fallback when the melt entry vanished with a death or a broken relation
        # (see relation_reasons).
        self._cached_opinion_idx = None
        # Index over all pairs in the melt's opinions (no subject filter), for third-party pairs
        self._any_opinion_idx = None
        self._rel_reason_cache = {}
        # language -> culture templates (one language is shared by several cultures,
        # e.g. language_norse held by norman/norse and others)
        self._lang_to_tpl = {}
        for _cid, _e in ((melt.get("culture_manager") or {}).get("cultures") or {}).items():
            if not isinstance(_e, dict):
                continue
            _lg = _e.get("language")
            if _lg:
                self._lang_to_tpl.setdefault(_lg, []).append(_e.get("culture_template") or "")
        # culture template -> language, used to infer a mother tongue when a character's
        # culture id has been cleared
        self._tpl_to_lang = {}
        for _cid, _e in ((melt.get("culture_manager") or {}).get("cultures") or {}).items():
            if not isinstance(_e, dict):
                continue
            _tpl = _e.get("culture_template")
            _lg = _e.get("language")
            if _tpl and _lg:
                self._tpl_to_lang.setdefault(_tpl, _lg)
        # O(1) independence: full vassal id set plus a per-character cache
        # keyed by (cid, date) (holder/office code calls this heavily).
        self._vassal_ids = set()
        for _k, _c in ((melt.get("vassal_contracts") or {}).get("database") or {}).items():
            if isinstance(_c, dict) and _c.get("vassal") is not None:
                try:
                    self._vassal_ids.add(int(_c["vassal"]))
                except Exception:
                    pass
        self._indep_cache = {}
        # Per-executioner criterion {executioner: {date: frozenset(purged houses)}},
        # see `purged_houses`.
        self._purge_houses_map = {}
        self._hold_cache = {}  # (cid, as_of) -> holding intervals, reused by offices/nicknames
        # Precomputed title holder sequences, reused by several full-table scans.
        self._title_seqs = {}
        for _tid, _t in self._lt.items():
            if not isinstance(_t, dict):
                continue
            _h = _t.get("history") or {}
            if isinstance(_h, dict) and _h:
                self._title_seqs[int(_tid)] = sorted(
                    _h.items(), key=lambda x: cl.date_key(x[0]))
        # Holder index {cid: {tid: [(gain, loss|None, loss_type), ...]}}, built in one pass
        # over all title history so holder/office/nickname lookups are O(1) per character.
        # A regained title keeps one segment per holding; events after as_of are dropped
        # and open intervals extend to as_of.
        self._holder_intervals = {}
        # How a title was gained and from whom: _holder_intervals keeps only
        # (gain, loss, loss_type), so the gain event type (conquest/created/
        # inheritance/appointment…) and the previous holder are stored separately.
        self._gain_reason = {}     # (cid, tid, gain_date) -> reason
        self._gain_prev = {}       # (cid, tid, gain_date) -> previous holder id
        _ao = cl.date_key(as_of) if as_of else None
        for _tid, _seq in self._title_seqs.items():
            cur = None
            gain = None
            prev = None
            for _d, _ev in _seq:
                if _ao is not None and cl.date_key(_d) > _ao:
                    break
                # Several events can share one date (e.g. destroyed+created): duplicate
                # keys are merged into a list.
                entries = _ev if isinstance(_ev, list) else [_ev]
                for _e in entries:
                    _h = _e.get("holder") if isinstance(_e, dict) else _e
                    _typ = _e.get("type") if isinstance(_e, dict) else ""
                    if _h is None:
                        if cur is not None and gain is not None:
                            self._holder_intervals.setdefault(cur, {}).setdefault(
                                _tid, []).append((gain, _d, _typ or ""))
                        cur, gain, prev = None, None, None
                        continue
                    try:
                        _hid = int(_h)
                    except (TypeError, ValueError):
                        continue
                    if _hid == cur:
                        if _typ == "destroyed":
                            if gain is not None:
                                self._holder_intervals.setdefault(cur, {}).setdefault(
                                    _tid, []).append((gain, _d, "destroyed"))
                            cur, gain, prev = None, None, None
                        continue
                    if cur is not None and gain is not None:
                        self._holder_intervals.setdefault(cur, {}).setdefault(
                            _tid, []).append((gain, _d, _typ or ""))
                    self._gain_reason[(_hid, _tid, _d)] = _typ or ""
                    if prev is not None and prev != _hid:
                        self._gain_prev[(_hid, _tid, _d)] = prev
                    prev = _hid
                    cur, gain = _hid, _d
            if cur is not None and gain is not None:
                self._holder_intervals.setdefault(cur, {}).setdefault(
                    _tid, []).append((gain, None, ""))
        # Co-rulers: co_* entries in the save's diarchies.database plus the character
        # variable use_co_ruler_title. Both are required for the game to add the co-ruler
        # form to that person's label (common/flavorization/00_title_holders.txt,
        # co_ruler_male: flag = use_co_ruler_title).
        self._diarchies = []
        for _v in ((melt.get("diarchies") or {}).get("database") or {}).values():
            if not isinstance(_v, dict):
                continue
            _t = str(_v.get("type") or "")
            if not _t.startswith("co_"):
                continue
            _l, _d2 = _v.get("liege"), _v.get("diarch")
            if not isinstance(_l, int) or not isinstance(_d2, int):
                continue
            self._diarchies.append({
                "liege": int(_l), "diarch": int(_d2), "type": _t,
                "start": str(_v.get("start_date") or ""),
            })
        self._diarchies.sort(key=lambda x: cl.date_key(x["start"] or "9999.9.9"))
        self._co_ruler_flag = set()   # character ids carrying use_co_ruler_title
        for _cid, _c in self._chars.items():
            if not isinstance(_c, dict):
                continue
            _vars = ((_c.get("alive_data") or {}).get("variables") or {}).get("data")
            for _e in _vars or []:
                if not isinstance(_e, dict) or _e.get("flag") != "use_co_ruler_title":
                    continue
                _dd = _e.get("data")
                if isinstance(_dd, dict) and _dd.get("identity"):
                    try:
                        self._co_ruler_flag.add(int(_cid))
                    except (TypeError, ValueError):
                        pass
                break
        # Main-branch index {dynasty_id: house_id}: the founding house shares the dynasty
        # name. Used only to test whether a branch house shares the dynasty name; never
        # written into the facts.
        self._dyn_first_house = {}
        _dyn_house = (melt.get("dynasties") or {}).get("dynasty_house") or {}
        for _h, _e in _dyn_house.items():
            if not isinstance(_e, dict):
                continue
            _did = _e.get("dynasty")
            if _did is None:
                continue
            try:
                _did = int(_did)
            except (TypeError, ValueError):
                continue
            _fd = str(_e.get("found_date") or "9999.9.9")
            _hit = self._dyn_first_house.get(_did)
            if _hit is None or cl.date_key(_fd) < cl.date_key(_hit[1]):
                self._dyn_first_house[_did] = (int(_h), _fd)
        # Index over realm_history snapshots {cid: {tid: [snapshot indices]}}, covering
        # titles that title history does not (kingdoms cut from the record).
        self._realm_snaps = [h for h in (cache.get("realm_history") or [])
                             if not as_of or cl.date_key(h.get("date")) <= cl.date_key(as_of)]
        self._realm_snaps.sort(key=lambda h: cl.date_key(h.get("date")))
        self._realm_holder_titles = {}  # cid -> {tid: set(index)}
        for _i, _h in enumerate(self._realm_snaps):
            for _tid, _holder in (_h.get("holders") or {}).items():
                if _holder is not None and int(_tid) not in self._holder_intervals.get(int(_holder), {}):
                    self._realm_holder_titles.setdefault(int(_holder), {}).setdefault(
                        int(_tid), set()).add(_i)
        # Union of every tier word (generic + per-government + Islamic name suffixes), so a
        # name that already contains a tier word is not given another one.
        self._rank_words = set(L.GENERIC_TIER_ZH.values()) | {"哈里发国", "苏丹国"}
        for _g in ("celestial", "administrative", "feudal", "clan",
                   "tribal", "theocracy", "republic"):
            for _tier in ("empire", "kingdom", "duchy", "county",
                          "barony", "hegemon"):
                w = L.tier_word(self.table, _g + "_government", _tier)
                if w and not w.startswith("$"):
                    self._rank_words.add(w)
        # custom characters (ruler_designer_characters) have a designed origin, no genealogy
        self._custom_starts = set()
        for x in (melt.get("ruler_designer_characters") or []):
            try:
                self._custom_starts.add(int(x))
            except Exception:
                pass
        # Beyond ruler_designer_characters, scripted landless adventurers also have no
        # genealogy: no parents in the save, but alive_data.variables carries
        # do_not_generate_starting_family / special_laamp_char / has_scripted_appearance.
        for _cid, _c in self._chars.items():
            if not isinstance(_c, dict):
                continue
            try:
                _i = int(_cid)
            except (TypeError, ValueError):
                continue
            _fd = _c.get("family_data") or {}
            if _fd.get("father") or _fd.get("mother"):
                continue
            _fam = (((self.cache.get("characters") or {}).get(str(_i)) or {})
                    .get("family") or {})
            if _fam.get("father") or _fam.get("mother"):
                continue
            _flags = set()
            for _e in (((_c.get("alive_data") or {}).get("variables") or {})
                       .get("data") or []):
                if isinstance(_e, dict) and _e.get("flag"):
                    _flags.add(str(_e["flag"]))
            if _flags & _NO_GENEALOGY_FLAGS:
                self._custom_starts.add(_i)
        # Name rendering cache: the underlying cache is immutable within one build_facts.
        self._name_cache = {}
        self._tpl_memo = {}

    # ---- names ----
    def name(self, cid, date=None):
        """Character id -> display name; patronymic cultures render name+patronymic (the
        patronymic replaces the house name), others follow the culture's name order
        (eastern family name first, western name+family name). `date` selects the family
        name of that date, so an early decade uses the name of its time; results are cached
        per (cid, date)."""
        if cid is None:
            return ""
        ck = (cid, date or "")
        c = self._name_cache.get(ck)
        if c is not None:
            return c
        c = cl.display_name(self.cache, cid, melt=self.melt,
                            names_path=self.names_path, chars=self._chars,
                            memo=self._tpl_memo, date=date)
        self._name_cache[ck] = c
        return c

    def name_or(self, cid, fallback="某人", date=None):
        """Display name, or the chronicle-style placeholder when unavailable (the code's fallback
        literal); the label outlet person_label returns '' for placeholders."""
        n = self.name(cid, date=date)
        return n or fallback

    def _regnal_name_zh(self, cid, date=None):
        """Regnal name (papal name / monastic name) in Chinese, '' when there is none.

        Taken from the cache (`characters.<id>.regnal_name`, synced per save by cache_lib)
        and falling back to the melt character; the Chinese text comes from localization
        keys such as `Sergius_regnal` / `Nicolaus_regnal`. Deliberately not truncated by
        `date`: the game uses the regnal name across the character's whole display surface
        and the save stores no rename history, so truncating would give one person two
        names inside a single biography.
        """
        if cid is None:
            return ""
        memo = getattr(self, "_regnal_zh_memo", None)
        if memo is None:
            memo = self._regnal_zh_memo = {}
        if cid in memo:
            return memo[cid]
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        rn = rec.get("regnal_name")
        if not rn:
            rn = (self._chars.get(str(cid)) or {}).get("regnal_name")
        out = ""
        if rn:
            v = L.loc(self.table, str(rn)) or ""
            if v and not v.startswith("$") and not v.startswith("["):
                out = v
        memo[cid] = out
        return out

    def regnal_birth_name(self, cid, date=None):
        """Birth name in Chinese of a character who took a regnal name, '' when absent or
        identical to the regnal name.

        `regnal_name` is the authoritative display-name field (granted on accession and
        driven by title definitions), while `first_name` disappears from every game display
        surface after accession, so the regnal name leads and the birth name is a note.
        """
        rn = self._regnal_name_zh(cid, date)
        if not rn:
            return ""
        c = self._chars.get(str(cid)) or {}
        birth = ""
        if c:
            try:
                birth = cl.name_zh(c) or ""
            except Exception:                                     # noqa: BLE001
                birth = ""
        if not birth:
            birth = (((self.cache.get("characters") or {}).get(str(cid)) or {})
                     .get("name_zh")) or ""
        if not birth or birth == rn:
            return ""
        return birth

    def label_with_birth_name(self, cid, label, date=None):
        """Label plus a birth-name note.

        Used for identifying sections only (religious leader, current pope, character file
        rows), never for every timeline line, so the note does not repeat dozens of times.
        The note is joined with a comma rather than parentheses, matching the fact layer's
        natural-language style (verify_fast asserts on it).
        """
        b = self.regnal_birth_name(cid, date)
        return f"{label}，本名{b}" if b else label

    # ---- regnal numbers (II/III) ----
    # The game stores no ordinal: it is computed as the number of same-named predecessors
    # in the primary title's holder history, plus one. I is not displayed.

    def regnal_number(self, cid, tid, date=None):
        """Regnal ordinal of cid on title tid: 1 + the number of same-named predecessors
        before accession, compared on the raw first_name. A character who took a regnal name
        is compared by that name, which is what the game's REGNAL_NAME_ONE_NAME $NUMBER$
        counts. Returns an integer >= 1."""
        key = (cid, tid, date)
        v = self._regnal_cache.get(key)
        if v is not None:
            return v
        _me = self._chars.get(str(cid)) or {}
        fn = self._regnal_name_zh(cid) or _me.get("first_name") or ""
        _by_regnal = bool(self._regnal_name_zh(cid))
        n = 1
        if fn and tid is not None:
            hist = (self._lt.get(str(tid)) or {}).get("history") or {}
            if isinstance(hist, dict) and hist:
                acc = None
                for d in sorted(hist, key=cl.date_key):
                    h = hist[d]
                    hid = h.get("holder") if isinstance(h, dict) else h
                    if hid == cid:
                        acc = d
                        break
                limit = None
                if acc:
                    limit = cl.date_key(acc)
                elif date:
                    limit = cl.date_key(date)
                elif self.as_of:
                    limit = cl.date_key(self.as_of)
                if limit is not None:
                    for d, h in hist.items():
                        hid = h.get("holder") if isinstance(h, dict) else h
                        if hid == cid or not isinstance(hid, int):
                            continue
                        if cl.date_key(d) >= limit:
                            continue
                        _o = self._chars.get(str(hid)) or {}
                        if _by_regnal:
                            _onm = self._regnal_name_zh(hid) or ""
                        else:
                            _onm = _o.get("first_name") or ""
                        if fn == _onm:
                            n += 1
        self._regnal_cache[key] = n
        return n

    # "Another holder existed" test on title history, same meaning as the game's
    # `var:landed_title = { any_past_holder = { this != scope:owner } }` in
    # character_memories_1.txt; feeds reason=created bucketing and test assertions.
    def title_had_other_holder(self, tid, cid, date=None):
        """True when tid had another holder at or before date.

        history entries come as a bare id, {type, holder} or a list of same-day events;
        a None holder (holderless destroyed entry) does not count. False without history.
        """
        return self.title_prev_other_holder(tid, cid, date) is not None

    def title_prev_other_holder(self, tid, cid, date=None):
        """Id of the last holder of tid other than cid at or before date, else None."""
        if tid is None or cid is None:
            return None
        hist = (self._lt.get(str(tid)) or {}).get("history")
        if not isinstance(hist, dict) or not hist:
            return None
        limit = cl.date_key(date) if date else None
        found = None
        for d in sorted(hist, key=lambda x: cl.date_key(x)):
            if limit is not None and cl.date_key(d) > limit:
                continue
            v = hist[d]
            for e in (v if isinstance(v, list) else [v]):
                h = e.get("holder") if isinstance(e, dict) else e
                if h is None:
                    continue
                try:
                    hid = int(h)
                except (TypeError, ValueError):
                    continue
                if hid != int(cid):
                    found = hid
        return found

    def created_verb_kind(self, tid, cid, date=None):
        """Wording bucket for reason=created: first / restored / founded.

        No previous holder -> first; previous holder of the same dynasty -> restored;
        previous holder of another dynasty on a hegemon title (h_ key) -> founded (a
        celestial claim to the mandate of heaven). Other titles with a previous holder stay
        restored, so duchy creations are unaffected.
        """
        prev = self.title_prev_other_holder(tid, cid, date)
        if prev is None:
            return "first"
        my_d = self._dynasty_of_cid(cid)
        prev_d = self._dynasty_of_cid(prev)
        if my_d is not None and prev_d is not None and my_d == prev_d:
            return "restored"
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if key.startswith("h_"):
            return "founded"
        return "restored"

    # Two criteria for the timeline title-memory gate.
    _TENURE_ZERO_DAY_TOL = 2   # tolerance between memory date and title history event date
    _MINISTER_KEY_PREFIX = "e_minister_"

    def is_landless_office_title(self, tid):
        """True for a landless office title (Chinese ministries, censorate, privy council).

        The game marks these `landless = yes` in `common/landed_titles/02_china.txt`, but the
        save's landed_titles entries omit that field, so the key prefix decides.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        return key.startswith(self._MINISTER_KEY_PREFIX)

    def title_rank_since_at(self, cid, date):
        """(rank of the highest title, its tenure start) at date; (0, '') without a title.

        Feeds the ordering after a same-day imprisonment cluster collapses (highest title
        first, earliest tenure first). Rank comes from `_eff_rank`, so a character holding
        only a house estate counts as level 0 and does not compete with real landholders.
        """
        if cid is None or not date:
            return 0, ""
        try:
            _tier, tid = self._primary_title_at(cid, as_of=date)
        except Exception:
            return 0, ""
        if tid is None:
            return 0, ""
        rank = self._eff_rank(tid)
        since = ""
        for (g, _l, _lt) in (self._hold_intervals(cid, date) or {}).get(tid) or []:
            if g and (not since or cl.date_key(g) > cl.date_key(since)):
                since = g
        return rank, since

    def title_tenure_zero_day(self, cid, tid, date):
        """True when this acquisition was a zero-day tenure (gain date == loss date).

        A celestial emperor creating a title and granting it the same day
        (`create_title_and_vassal_change` then `change_title_holder`) looks like a Chinese
        ministry appointment; such a grant is an investiture, not a tenure, so the timeline
        must not report it as a creation. Dates match within _TENURE_ZERO_DAY_TOL days.
        """
        if cid is None or tid is None or not date:
            return False
        for (gain, loss, _lt) in (self._hold_intervals(cid) or {}).get(tid) or []:
            if not gain or not loss:
                continue
            if _date_ord(gain) != _date_ord(loss):
                continue
            if abs(_date_ord(gain) - _date_ord(date)) <= self._TENURE_ZERO_DAY_TOL:
                return True
        return False

    # Event date of a title gain/loss sentence: the game writes the memory one day after the
    # title change (title_event.9900 has cooldown=1), so creation_date is often 0-1 days late
    # while the title history entry holds the event day. Other memories keep creation_date.
    _TITLE_DATE_NEAR_DAYS = 31   # max event-to-memory gap (loose, avoids stale matches)

    def mem_date(self, cid, mem):
        """Date a memory uses in the facts: title gain/loss memories take the title history
        event date and fall back to creation_date; other memories use creation_date."""
        d = mem.get("creation_date") or ""
        mtype = mem.get("type")
        if not d or mtype not in TITLE_VAR_TYPES:
            return d
        tid = None
        reason = ""
        for v in mem.get("vars") or []:
            if v.get("flag") == "landed_title" and v.get("identity"):
                tid = v.get("identity")
            elif v.get("flag") == "reason":
                reason = str(v.get("value") or "")
        if tid is None:
            return d
        if mtype == "lost_title_memory" and reason == "migration":
            # A migration lost-title memory always names the original county, so its event
            # date cannot be mapped directly: recover the real title first.
            _rt = self.migration_lost_title(
                cid, d, (mem.get("participants") or {}).get("new_holder"))
            if _rt is not None:
                tid = _rt
        key = (tid, cid, d, reason, mtype)
        hit = self._mem_date_cache.get(key)
        if hit is None:
            hit = self._title_event_date(tid, cid, d, reason,
                                         lost=(mtype == "lost_title_memory")) or d
            self._mem_date_cache[key] = hit
        return hit

    def _title_event_date(self, tid, cid, mem_date, reason="", lost=False):
        """Nearest title history event date at or before mem_date, else ''.

        Entries whose type equals reason win (a destroyed loss entry matches even though its
        holder is the former owner); otherwise the holder side decides (gain: holder==cid,
        loss: holder!=cid). A match further than _TITLE_DATE_NEAR_DAYS from the memory date
        counts as a mismatch.
        """
        hist = (self._lt.get(str(tid)) or {}).get("history")
        if not isinstance(hist, dict) or not hist:
            return ""
        mk = cl.date_key(mem_date)
        typed = side = None
        for d, v in hist.items():
            dk = cl.date_key(d)
            if dk > mk:
                continue
            for e in (v if isinstance(v, list) else [v]):
                h = e.get("holder") if isinstance(e, dict) else e
                typ = (e.get("type") or "") if isinstance(e, dict) else ""
                if reason and typ == reason and (typed is None or dk > typed[0]):
                    typed = (dk, d)
                if h is None:
                    continue
                try:
                    hid = int(h)
                except (TypeError, ValueError):
                    continue
                ok = (hid != int(cid)) if lost else (hid == int(cid))
                if ok and (side is None or dk > side[0]):
                    side = (dk, d)
        for cand in (typed, side):
            if cand and 0 <= _date_ord(mem_date) - _date_ord(cand[1]) \
                    <= self._TITLE_DATE_NEAR_DAYS:
                return cand[1]
        return ""

    def _last_high_title_before(self, cid, date=None):
        """Highest-tier title cid last held at or before date, else None.

        Fallback for regnal numbering when the title changed hands the same day (death and
        succession on one date) and `_primary_title_at` finds nothing.
        """
        ao = cl.date_key(date) if date else \
            (cl.date_key(self.as_of) if self.as_of else None)
        best_tid, best_rank, best_gain = None, -1, None
        for tid, ivs in self._hold_intervals(cid, date).items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            rank = self._TT_RANK.get(key[:2], 0)
            for (g, _l, _lt) in ivs:
                if not g:
                    continue
                gk = cl.date_key(g)
                if ao is not None and gk > ao:
                    continue
                if rank > best_rank or \
                        (rank == best_rank and best_gain is not None and gk > best_gain):
                    best_tid, best_rank, best_gain = tid, rank, gk
        return best_tid

    def nickname(self, cid):
        """Character nickname from the melt's nickname_text (already Chinese), else ''.

        An era override wins, so a decade rebuild reads that decade's melt.
        """
        ov = self._nick_override or {}
        if cid in ov:
            return ov[cid] or ""
        c = self._chars.get(str(cid)) or {}
        return (c.get("nickname_text") or "").strip()

    def _insert_nickname(self, nm, nick):
        """Join a nickname into a display name: the nickname leads, quotes are dropped, and
        the nickname displaces the regnal number."""
        return f"{nick}{nm}"

    def name_with_regnal(self, cid, date=None):
        """Display name + nickname + regnal number.

        With a nickname the nickname leads and the number is dropped; without one the number
        goes right after the given name of a western name order (name·house), never on the
        house name. Eastern single-token names get no number, and non-ruling children of the
        Japanese throne use the name + prince/princess form with no dynasty name.
        """
        tn = self._tenno_prince_name(cid, date)
        if tn:
            nick = self.nickname(cid)
            if nick:
                return f"{nick}{tn}"
            return tn
        nm = self.name_or(cid, date=date)
        if not nm:
            return nm
        nick = self.nickname(cid)
        if nick:
            return self._insert_nickname(nm, nick)
        if "·" not in nm:
            # Eastern names (family+given with no separator) and single-token names get no
            # regnal number, except characters who took a regnal name: their name is one
            # token by nature and the number is part of their identity.
            if not self._regnal_name_zh(cid, date):
                return nm
        try:
            _tier, tid = self._primary_title_at(cid, as_of=date)
        except Exception:
            return nm
        if tid is None:
            # fall back to the last high title when the title changed hands on the death day
            tid = self._last_high_title_before(cid, date)
        if tid is None:
            return nm
        n = self.regnal_number(cid, tid, date)
        if n >= 2:
            # number right after the given name, house/patronymic after it; never on the family name
            head, sep, tail = nm.partition("·")
            return f"{head}{_ordinal_zh(n)}{sep}{tail}"
        return nm

    # ---- titles ----
    def _title_government(self, tid, date=None):
        """Government of the title at date: that of its then-holder, walking up
        de_facto_liege for the then-liege's government when the holder's is missing.

        The holder's government must be the dated one, not the final save's: a fief held
        under feudalism would otherwise take the last save's administrative_government and
        turn all tier and address words into military-district ones. Government history comes
        from cache["char_government_history"] (change points per save).
        """
        date = date or self.as_of
        ck = (tid, date)
        if ck in self._gov_cache:
            return self._gov_cache[ck]
        gov = ""
        seen = set()
        cur = str(tid)
        while cur and cur not in seen:
            seen.add(cur)
            t = self._lt.get(cur) or {}
            if not t:
                break
            holder = self._holder_at_or_now(t, cur, date)
            if isinstance(holder, int):
                gov = self._character_government_or_earliest(holder, date)
                if gov:
                    break
            liege = t.get("de_facto_liege")
            cur = str(liege) if liege is not None else None
        # Title-side government fallback for the Japanese top titles: when the holder's
        # government history is unavailable, the title's own history_government decides
        # (japan_administrative_government = regency, japan_feudal_government = shogunate).
        # Still a government value from the game data, never guessed from the era.
        if gov == "" and \
                ((self._lt.get(str(tid)) or {}).get("key") or "") in self._JAPAN_TOP_TITLE_KEYS:
            gov = self._title_government_hist(tid, date) \
                or (self._lt.get(str(tid)) or {}).get("history_government") or ""
        self._gov_cache[ck] = gov
        return gov

    def _title_government_hist(self, tid, date=None):
        """Last government explicitly recorded in the title history at or before date, else ''.

        Fallback for the Japanese top titles: title history entries carry a `government`
        field on the day it changes (e.g. history/titles/e_japan.txt), so the wording comes
        from the game's own record instead of the final save's or a guess from the era.
        """
        t = self._lt.get(str(tid)) or {}
        hist = t.get("history") or {}
        if not isinstance(hist, dict):
            return ""
        ao = cl.date_key(date) if date else None
        best_d, best_g = None, ""
        for d, e in hist.items():
            if not isinstance(e, dict):
                continue
            g = e.get("government") or ""
            if not g:
                continue
            dk = cl.date_key(d)
            if ao is not None and dk > ao:
                continue
            if best_d is None or dk >= best_d:
                best_d, best_g = dk, g
        return best_g

    def _gov_for_word(self, cid, tid, date):
        """Government used for address wording, following the game's own rule.

        The game evaluates flavorization `governments` on the holder character, and Japanese
        `special = holder` entries are always `top_liege = no`, so a vassal's wording never
        comes from the liege's government. Order: the character's dated government, the
        earliest known entry of that history, dead_data.government for a dead character with
        no history, then — for the Japanese top titles only — the title's own government
        record. '' makes the caller fall back to the generic tier word.
        """
        gov = self._character_government(cid, date) if cid is not None else ""
        if gov:
            return gov
        hist = self._gov_history(cid)
        if hist:
            # date before the history's start: use the earliest known government, the same
            # "before the first point take the first point" rule as `_hist_value_at`.
            first = hist[0].get("government") or ""
            if first:
                return first
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        dd = (rec.get("death") or {}).get("date")
        if not dd:
            dd = (self._chars.get(str(cid)) or {}).get("death") or {}
            dd = dd.get("date") if isinstance(dd, dict) else None
        if dd and (not date or cl.date_key(date) <= cl.date_key(dd)):
            gov = ((self._chars.get(str(cid)) or {}).get("dead_data") or {}) \
                .get("government") or ""
            if gov:
                return gov
        if tid is not None:
            _t = self._lt.get(str(tid)) or {}
            if (_t.get("key") or "") in self._JAPAN_TOP_TITLE_KEYS:
                gov = self._title_government_hist(tid, date) \
                    or _t.get("history_government") or ""
                if gov:
                    return gov
        return ""

    def _holder_at_or_now(self, title, tid, date):
        """Holder of the title at date; past the last save, the melt's current holder."""
        if date is not None:
            h = self.holder_at(int(tid), date)
            if isinstance(h, int):
                return h
        h = title.get("holder")
        return int(h) if isinstance(h, int) else None

    def _gov_history(self, cid):
        """Merged per-save government history of a character.

        Each save's cache records only the characters it lived through, so the observations of
        every cache in the campaign are merged; this cache alone would hide an earlier start
        and push early dates onto the liege's government word.
        """
        if cid is None:
            return []
        merged = {}
        for src in [self.cache] + list((self.campaign or {}).values()):
            if not isinstance(src, dict):
                continue
            for h in ((src.get("char_government_history") or {}).get(str(cid))
                      or []):
                if not isinstance(h, dict):
                    continue
                d = h.get("date") or ""
                g = h.get("government") or ""
                if d and g:
                    merged.setdefault(d, g)
        return [{"date": d, "government": merged[d]}
                for d in sorted(merged, key=cl.date_key)]

    def _character_government(self, cid, date=None):
        """Government of the character at date: per-save history first, melt state as fallback.

        The history comes from cache["char_government_history"] (change points per save). A
        date earlier than the history's start returns '' rather than passing the final save's
        government off as history.
        """
        if cid is None:
            return ""
        hist = self._gov_history(cid)
        if hist and date:
            dk = cl.date_key(date)
            hit = ""
            for h in hist:
                if h.get("date") and cl.date_key(h["date"]) <= dk:
                    hit = h.get("government") or ""
                else:
                    break
            if hit:
                return hit
            # before the history's start the government is unknown
            if hist[0].get("date") and cl.date_key(hist[0]["date"]) > dk:
                return ""
        # fallback: the melt state (no date given, or the character has no government history)
        if date:
            last = self.cache.get("last_date")
            if last and cl.date_key(date) < cl.date_key(last):
                return ""
        c = self._chars.get(str(cid)) or {}
        return (c.get("landed_data") or {}).get("government") or ""

    def _character_government_or_earliest(self, cid, date):
        """Government of the character at date; before the history's start only a celestial
        chain government is backfilled with the earliest known value.

        The celestial system is one unchanged institution across the whole period, so
        backfilling keeps the tier word consistent with the office word of the same day;
        governments that do change (feudal -> administrative) still return ''.
        """
        gov = self._character_government(cid, date)
        if gov or not date:
            return gov
        hist = self._gov_history(cid)
        if not hist:
            return ""
        first = hist[0].get("government") or ""
        return first if first in self._CELESTIAL_CHAIN_GOVS else ""


    # Government prefix normalization applies only to tier-prefixed keys: a key such as
    # `count_feudal_male_japanese` differs from `japan_feudal_government` by the `japan_`
    # prefix, while non-office keys (spouse keys, for instance) must stay unnormalized or
    # official_title's flavor branch would return a bare spouse word.
    _GOV_NORM_RANK_PREFIXES = ("count_", "duke_", "king_", "emperor_",
                               "baron_", "hegemon_")

    @staticmethod
    def _gov_prefix_norm(p):
        """Strip the `japan_` prefix so a flavorization key's government segment
        (`feudal` / `administrative`) matches the game's own government names
        (`japan_feudal` / `japan_administrative`)."""
        s = str(p or "")
        return s[len("japan_"):] if s.startswith("japan_") else s

    def _dead_flavor_consistent(self, fkey, cid, date):
        """Whether a save-baked flavor key (`dead_data.flavor`) agrees with that day's government.

        The key is `<tier prefix>_<government prefix>_<sex>[_culture]`, and its government prefix is
        compared with `_character_government(cid, date)`; a missing or unknown date is not trusted,
        since the key was baked from the final save. Two same-source fallbacks exist: the death window
        (using the dead_data.government baked at that moment) and the title-side government of a
        hegemon (h_) title held that day.
        """
        if not fkey or date is None:
            return False
        parts = str(fkey).split("_")
        if len(parts) < 3:
            return True
        gov_prefix = "_".join(parts[1:-1]) if len(parts) > 3 else parts[1]
        # the key may carry a culture suffix (…_byzantine_group): cut at _male/_female
        for anchor_word in ("male", "female"):
            if anchor_word in parts:
                i = parts.index(anchor_word)
                gov_prefix = "_".join(parts[1:i])
                break
        # normalize the Japanese government prefix only for tier-prefixed keys
        _norm = str(fkey).startswith(self._GOV_NORM_RANK_PREFIXES)

        def _eq_gov(x, y):
            if _norm:
                return self._gov_prefix_norm(x) == self._gov_prefix_norm(y)
            return x == y

        cur = self._character_government(cid, date)
        dd = (self._chars.get(str(cid)) or {}).get("dead_data") or {}
        ddate = dd.get("date")
        # Inside the death window a baked flavor key may be accepted when it agrees with the
        # dead_data.government baked at the same moment: `_gov_history` can borrow a single
        # observation from another subject's cache that covers only early years, which would
        # make a decades-old value look like the government at death. The check only lets keys
        # through (it never turns a True into False); outside the death window only the dated
        # history counts.
        if ddate and abs(_date_ord(date) - _date_ord(ddate)) <= 1 \
                and (dd.get("government") or ""):
            if _eq_gov(L.government_prefix(dd["government"]), gov_prefix):
                return True
            if not cur:
                cur = dd["government"]
        # An unknown government (before the dated history) does not trust the baked key: it
        # was computed from the final save's government and would mislabel early years.
        if not cur:
            # Fallback 1: inside the death window, dead_data.government is the value baked
            # together with dead_data.flavor, so that pair is faithful when the anchor is the
            # death date or the day before it.
            if ddate and abs(_date_ord(date) - _date_ord(ddate)) <= 1:
                cur = dd.get("government") or ""
        if not cur:
            # Fallback 2: the title's own recorded government, only for a hegemon (h_) title
            # this character held that day (h_china always carries
            # history_government = celestial_government). Needed because fallback 1 covers only
            # the moment of death, while lifetime event lines are dated. Hegemon only: tier
            # words for other levels have their own entries and must follow the dated history.
            want = None
            for pfx, rk in (("hegemon_", 6), ("emperor_", 5), ("king_", 4),
                            ("duke_", 3), ("count_", 2), ("baron_", 1)):
                if str(fkey).startswith(pfx):
                    want = rk
                    break
            if want is not None:
                ptid = None
                try:
                    _pt, ptid = self._primary_title_at(cid, as_of=date)
                except Exception:
                    ptid = None
                if ptid is not None and self._eff_rank(ptid) == want:
                    tt = self._lt.get(str(ptid)) or {}
                    if (tt.get("key") or "").startswith("h_"):
                        cur = self._title_government_hist(ptid, date) \
                            or tt.get("history_government") or ""
        if not cur:
            return False
        return _eq_gov(L.government_prefix(cur), gov_prefix)

    def title(self, tid, date=None, site=False, site_cid=None):
        """Title id -> Chinese name plus the dynamic tier word.

        The tier word follows the then-holder's government at date (feudal duchy vs
        administrative military district). The name prefers the dynamic name of that date
        (specific_title_name -> title_history_names -> custom -> name -> localization -> key);
        landless camps (x_) get the name alone. `site=True` switches the naming outlet to
        _site_name (the place name as of the save before the subject took it) and skips the two
        `specific` early returns; the default False leaves existing callers unchanged.
        """
        if tid is None:
            return ""
        t = self._lt.get(str(tid)) or {}
        key = t.get("key") or ""
        tnd = t.get("title_name_data") or {}
        # dynamic realm name first (title_history_names); static custom/name only as fallback
        if site:
            name = self._site_name(tid, cid=site_cid, date=date)
            # A game-provided display name (nomadic or house-named realm) is complete, so no
            # tier word is appended; otherwise the tier word chain runs as usual.
            if self._dyn_named(tid):
                return name
        else:
            name = self._name_at_date(tid, date) \
                or (tnd.get("custom") or "").strip() \
                or (tnd.get("name") or "").strip() \
                or L.loc(self.table, key) or key
        if key.startswith("x_"):  # landless camps/orders and similar: name only
            return name if site else (self._specific_name(tid) or name)
        # Cardinal titles (d_cd_*) take no tier word: they are landless titular titles
        # (`landless = yes`, `destroy_on_succession = yes`), and a tier word would read as if
        # the character had governed a province.
        if self._is_cardinal_title(tid):
            return name
        # House estates (`c_nf_`/`d_nf_`) are landless too: name only, no tier word.
        if self._is_estate_title(tid):
            return name
        # Landless adventurer camps (`d_laamp_*`) take the game's
        # `<tier>_landless_adventurer_camp` word on every date and never the generic duchy
        # word.
        if self.title_kind(tid) == "camp":
            w = self._camp_tier_word(tid)
            return f"{name}{w}" if w and not _STATE_SUFFIX_RE.search(name) else name
        # Court offices (the Chinese ministries, e_minister_*) are posts, not fiefs: name
        # only, with no empire-level word appended.
        if key.startswith("e_minister_"):
            return name
        # An empty throne gets the office word only; name + tier word would be a mechanical string
        _tw = self.throne_word(tid)
        if _tw:
            return _tw
        # A dynamic title name (nomadic or house-named) is the game's display name and wins
        # over the Islamic realm name and the tier word. With site=True and a dynamic name,
        # _site_name already returned above, so the final save's sticky name cannot answer;
        # titles without one fall through to the tier word chain.
        if not site:
            specific = self._specific_name(tid)
            if specific:
                return specific
        rn = self.realm_name(tid)  # Islamic rulers' dynamic realm name takes priority
        if rn and not site:
            return rn
        tier = ""
        for pfx, tv in L.TIER_KEY_OF_PREFIX.items():
            if key.startswith(pfx):
                tier = tv
                break
        if tier:
            # The tier word follows the then-holder, not the final save's holder, which would
            # judge a 910 tenure by the independence/culture/top liege of 924.
            holder = self._holder_at_or_now(t, tid, date)
            # The government is the holder's own: the game evaluates flavorization
            # `governments` on the Context Character, while a title-side government would walk
            # de_facto_liege up to the liege.
            gov = self._gov_for_word(holder, tid, date)
            word = ""
            if not (key.startswith("h_") and gov != "celestial_government"):
                word = self._title_tier_word(tier, holder, tid, gov, date)
            # hegemon titles (h_): the celestial word applies only to celestial_government
            if key.startswith("h_") and gov != "celestial_government":
                word = ""
            # The administrative empire word appears only when a hegemon title sits above;
            # without one the generic empire word is used.
            generic_word = L.tier_word(self.table, "", tier)
            if (gov == "administrative_government" and tier == "empire"
                    and word != generic_word
                    and not self._has_hegemon_above(tid)):
                word = generic_word
            # A Chinese administrative place name (ending in a prefecture/commandery suffix)
            # stays as it is; western place names still take the tier word.
            if key.startswith("c_") and word and _CN_PLACE_SUFFIX_RE.search(name):
                return name
            # no tier word when the name already carries a state suffix, or the word is empty
            if word and not _STATE_SUFFIX_RE.search(name):
                return f"{name}{word}"
        return name

    def _has_hegemon_above(self, tid):
        """True when a hegemon (h_) title sits above along de_facto_liege."""
        seen = set()
        cur = str(tid)
        while cur and cur not in seen:
            seen.add(cur)
            t = self._lt.get(cur) or {}
            if not t:
                break
            if (t.get("key") or "").startswith("h_"):
                return True
            liege = t.get("de_facto_liege")
            cur = str(liege) if liege is not None else None
        return False

    # ---- dated title names / holder history (primary title evolution) ----

    _TT_RANK = {"h_": 6, "e_": 5, "k_": 4, "d_": 3, "c_": 2, "b_": 1, "x_": 0}

    # Governments that use the celestial tier word chain, matching the `governments` list of
    # the `*_celestial_chinese_*` entries. administrative_government is excluded: it has its
    # own conditional entries (military district, province…) that the celestial word must not
    # override.
    _CELESTIAL_CHAIN_GOVS = {"celestial_government", "meritocratic_government",
                              "steppe_admin_government"}

    def _celestial_chain_word(self, tier, government, independent):
        """Celestial tier word chain: an emperor holding in his own right -> the realm word,
        a vassal appointed -> the circuit word.

        The game's `*_celestial_chinese_independent` entries carry
        `name_lists = { name_list_han }`, which a non-Han emperor cannot match, so they would
        fall back to the generic kingdom/empire/duchy words. Celestial wording is
        culture-independent in this project, so the chain keys are looked up directly instead of
        passing the flavorization name-list gate. '' when not applicable.
        """
        if government not in self._CELESTIAL_CHAIN_GOVS:
            return ""
        if tier == "hegemon":
            key = "hegemony_celestial_chinese"
        elif independent and tier in ("empire", "kingdom", "duchy"):
            key = f"{tier}_celestial_chinese_independent"
        else:
            key = f"{tier}_celestial_chinese_vassal"
        v = L.loc(self.table, key)
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        return ""

    def _title_tier_word(self, tier, cid, tid, government, date,
                         independent=None):
        """Single outlet for a title's tier word.

        Order: the holder-specific flavorization entry with a `governments` condition, otherwise the
        celestial chain word for a chain government (`_celestial_chain_word`), otherwise the
        localization tier word. The barony level never emits one, because the game's barony words are
        either a rank noun or holding-gated land types, neither of which belongs in a place name.
        """
        if tier == "barony" or self._is_cardinal_title(tid):
            # Barony level emits no tier word (see the docstring); cardinal titles
            # (`d_cd_*`, landless titular) are treated the same way.
            return ""
        if independent is None:
            independent = self._is_independent(cid, date) if cid is not None else True
            if independent is None:
                independent = False
        if cid is not None:
            fk = self._flavor_key("title", tier, cid, tid=tid, gov=government,
                                  date=date)
            if fk:
                e = (FZ.table().get("entries") or {}).get(fk) or {}
                if e.get("governments"):
                    v = L.loc(self.table, fk)
                    if v and not v.startswith("$") and not v.startswith("["):
                        return v
        w = self._celestial_chain_word(tier, government, bool(independent))
        if w:
            return w
        return L.tier_word(self.table, government, tier)

    def _tier_word_at(self, tid, government, independent=False, cid=None, date=None):
        """Tier word of the title: the flavorization `type = title` entry that supplies `$TIER$`
        in the game's TITLE_TIERED_NAME, then the celestial independent-kingdom case and the
        per-government tier word table. The three-step order lives in `_title_tier_word`.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        tier = ""
        for pfx, tv in L.TIER_KEY_OF_PREFIX.items():
            if key.startswith(pfx):
                tier = tv
                break
        if not tier:
            return ""
        # camp tier words come from the game's camp key, not from flavorization's feudal words
        if self.title_kind(tid) == "camp":
            return self._camp_tier_word(tid)
        return self._title_tier_word(tier, cid, tid, government, date,
                                     independent=independent)

    def _custom_name(self, tid):
        """Player-customized title name (`title_name_data.custom`), else ''.

        The game's custom title window writes its name field into `custom`, which becomes the
        title's display name: scripted triggers compare it (`has_custom_title_name` /
        `custom_title_name`) and the save envelope's `meta_data.meta_title_name` agrees.
        `specific_title_name` and `name` are therefore generation-time names only.
        """
        t = self._lt.get(str(tid)) or {}
        return ((t.get("title_name_data") or {}).get("custom") or "").strip()

    def _has_reign_history(self, tid):
        """True when the title's display name comes from a realm-name history.

        The game resolves `$NAME$` as custom -> localization_key -> title_history_names[<=date]
        -> specific_title_name -> static name, so a title with a `dynn_title_*` rename history or
        a non-empty `localization_key` takes its name from the realm name, while its
        `specific_title_name` is a generated name for the current holder's house that goes stale
        and is no longer refreshed. Such titles yield entirely to the rename history. Titles
        without one (nomadic yurts, camps, house-named realms) return False and keep using the
        generated name.
        """
        tnd = (self._lt.get(str(tid)) or {}).get("title_name_data") or {}
        if (tnd.get("localization_key") or "").strip():
            return True
        for h in (tnd.get("title_history_names") or []):
            if isinstance(h, dict) and \
                    str(h.get("name") or "").startswith("dynn_title_"):
                return True
        return False

    def _specific_name(self, tid):
        """The game-computed dynamic title name (a nomadic or house-named realm name), else ''.

        The static `name` is only a place name and differs from what the game displays. Returns ''
        when the title carries a custom name (the generated name is not displayed then) or a
        realm-name history (see `_has_reign_history`), so callers use custom and the rename
        history instead.
        """
        if self._has_reign_history(tid):
            return ""
        t = self._lt.get(str(tid)) or {}
        tnd = t.get("title_name_data") or {}
        if (tnd.get("custom") or "").strip():
            return ""
        return (tnd.get("specific_title_name") or "").strip()

    def _name_at_date(self, tid, date):
        """Name of the title on a given date, without the tier word.

        Order: the dynamic title name (dated through `_dyn_reign_name`, tenure-aware, falling
        back to the final save's `specific_title_name` when the history does not cover it); the
        latest title_history_names rename at or before the date (localization key or literal
        name); then the base name (custom -> name). A custom name disables the first step
        entirely, because a camp's generated name may not exist during the years it was alive
        and would otherwise displace the player's own name.
        """
        t = self._lt.get(str(tid)) or {}
        tnd = t.get("title_name_data") or {}
        # Step 1 applies only without a custom name, and is gated off as well for titles with a
        # realm-name history: their generated name must not compete with the realm name.
        specific = "" if ((tnd.get("custom") or "").strip()
                          or self._has_reign_history(tid)) \
            else (self._dyn_reign_name(tid, date) or self._specific_name(tid))
        if specific:
            return specific
        base = (tnd.get("custom") or "").strip() or (tnd.get("name") or "").strip()
        best = self._history_name_at(tid, date)
        if best is not None:
            v = L.loc(self.table, str(best))
            if v:
                return v
            s = str(best)
            if re.search(r"[A-Za-z_]", s):
                # when the localization table lacks the rename key, fall back to the base name
                # instead of emitting a bare key
                return base
            return s  # a literal (already Chinese) name is returned as is
        return base

    def _site_cid_for(self, tid, default_cid):
        """Anchor character for the [place name] mode: the biography's subject whenever he ever
        held the title.

        One event appears as two timeline lines (the subject leaving, a rival moving in); if each
        used its own acquisition date as anchor, one place would carry two names in a single
        biography. Anchoring on the subject keeps one name per place, and third-party lines
        follow it too. The speaker is used when the subject never held the title.
        """
        pid = self.cache.get("player_id")
        if pid is None or pid == default_cid:
            return default_cid
        ivs = self._hold_intervals(pid) or {}
        if ivs.get(tid) or ivs.get(str(tid)):
            return pid
        return default_cid

    def _dyn_hist(self, tid):
        """Per-save name evolution of a title, merged by date from this cache and the campaign's other
        subject caches.

        Each cache covers only its own subject's saves, so this cache alone would name events after its
        range with the earliest name and give one event different names in different biographies. This
        cache's values win; another playthrough's caches are skipped and the result is memoized.
        """
        if self._has_reign_history(tid):
            return []
        hit = self._dyn_hist_cache.get(tid)
        if hit is not None:
            return hit
        mine = self.cache
        _pt = mine.get("playthrough_id")
        merged = {}
        for src in list((self.campaign or {}).values()) + [mine]:
            if not isinstance(src, dict):
                continue
            if _pt and src.get("playthrough_id") \
                    and str(src.get("playthrough_id")) != str(_pt):
                continue
            tbl = (src.get("title_dyn_names") or {}).get(str(tid))
            if not tbl:
                continue
            for h in tbl:
                if isinstance(h, dict) and h.get("from"):
                    merged[str(h["from"])] = (h.get("name") or "").strip()
        out = [{"from": d, "name": n}
               for d, n in sorted(merged.items(), key=lambda kv: cl.date_key(kv[0]))]
        self._dyn_hist_cache[tid] = out
        return out

    def _dyn_reign_name(self, tid, date):
        """Dated dynamic name, tenure-aware (step 1 of `_name_at_date`).

        Save granularity hides mid-year renames: a title taken on 936.6.23 already carries its
        new holder's name, but the next save is not until 937.1.1, so the plain "latest point at
        or before date" rule would use the previous holder's name for all of 936. When the chosen
        point precedes the then-holder's tenure start, the first non-empty point after that start
        is used instead; otherwise the point is returned as is.
        """
        hist = self._dyn_hist(tid)
        if not hist or not date:
            return ""
        dk = cl.date_key(date)
        pick, pick_d = "", ""
        for h in hist:
            d = h.get("from")
            if not d:
                continue
            try:
                if cl.date_key(d) <= dk:
                    pick, pick_d = h.get("name"), d
                else:
                    break
            except Exception:
                break
        if not pick_d:
            return pick
        hid = self.holder_at(tid, date)
        if hid is None:
            return pick
        ivs = self._hold_intervals(hid) or {}
        gain = None
        for iv in (ivs.get(tid) or ivs.get(str(tid)) or []):
            if not iv or not iv[0]:
                continue
            if cl.date_key(iv[0]) <= dk and (not iv[1] or dk <= cl.date_key(iv[1])):
                gain = iv[0]
        if not gain or cl.date_key(pick_d) >= cl.date_key(gain):
            return pick
        gk = cl.date_key(gain)
        for h in hist:                      # first non-empty rename after the tenure start
            d = h.get("from")
            if not d:
                continue
            try:
                if cl.date_key(d) <= gk:
                    continue
            except Exception:
                continue
            nm = (h.get("name") or "").strip()
            if nm:
                return nm
        return pick

    def _dyn_name_at(self, tid, date):
        """Dynamic name of the title at the save containing date, from the dated change-point
        history (`_dyn_hist`, latched by `cache_lib._latch_title_dyn_names`), else ''.

        The melt keeps only the last version of `specific_title_name`, so reading it alone would
        put a later name on an earlier event. Before the first point, without a table, or without
        a record, '' is returned so the caller uses the static name.
        """
        hist = self._dyn_hist(tid)
        if not hist or not date:
            return ""
        dk = cl.date_key(date)
        pick = ""
        for h in hist:
            d = h.get("from")
            if not d:
                continue
            try:
                if cl.date_key(d) <= dk:
                    pick = h.get("name")
                else:
                    break
            except Exception:
                break
        return (pick or "").strip()

    def _site_ok(self, tid):
        """Whether the [place name] mode applies: land titles only (c_/d_/k_/b_/e_/h_…).

        Camps, yurts and estates keep their own naming (camp-purpose words and house-estate
        words), since "what the place was called then" does not apply to them and a camp's
        dynamic name is often fixed before its holder acquires it.
        """
        if tid is None:
            return False
        if self.title_kind(tid):
            return False
        return not ((self._lt.get(str(tid)) or {}).get("key") or "").startswith("x_")

    def _dyn_named(self, tid):
        """True when the title ever had a non-empty dynamic name (a nomadic or house-named
        realm), in which case that name is the whole display name and no tier word is appended.

        Both sources count: the dated history (including the campaign's other caches) and the
        melt's current value, the latter covering caches the history does not reach.
        """
        hist = self._dyn_hist(tid)
        if hist and any((h.get("name") or "").strip() for h in hist):
            return True
        return bool(self._specific_name(tid))

    def _dyn_name_before(self, tid, before):
        """Latest dynamic name strictly before `before` in the dated history, else ''.

        The anchor is "before the earliest acquisition", so points inside the subject's own
        tenure fall after it and taking an old place back does not restore his own last name for
        it.
        """
        hist = self._dyn_hist(tid)
        bk = cl.date_key(before)
        pick = ""
        for h in hist:
            d = h.get("from")
            if not d:
                continue
            try:
                if cl.date_key(d) >= bk:
                    break
            except Exception:
                break
            pick = (h.get("name") or "").strip()
        return pick

    def _site_name(self, tid, cid=None, date=None):
        """[Place name] of a title in this biography, for place contexts such as migration or a
        seat of power.

        The dynamic name is read from the save before the subject's earliest acquisition of the
        title; a title he never held uses the name at date (default as_of); if both are empty,
        the melt's value, then the rename history at that date, then the static custom/name, the
        localization table and finally the key. One place keeps one name across the biography, so
        "moved to X" and "moved away from X" pair up.
        """
        t = self._lt.get(str(tid)) or {}
        tnd = t.get("title_name_data") or {}
        base = (tnd.get("custom") or "").strip() or (tnd.get("name") or "").strip()
        hist = self._dyn_hist(tid)
        before = None
        if cid is not None:
            ivs = self._hold_intervals(cid).get(tid) or []
            gains = [iv[0] for iv in ivs if iv and iv[0]]
            if gains:
                before = min(gains, key=cl.date_key)
        nm = self._dyn_name_before(tid, before) if before \
            else self._dyn_name_at(tid, date or self.as_of)
        if nm:
            return nm
        if not hist:
            sp = self._specific_name(tid)
            if sp:
                return sp
        best = self._history_name_at(tid, date or before)
        if best is not None:
            v = L.loc(self.table, str(best))
            if v:
                return v
            s = str(best)
            if not re.search(r"[A-Za-z_]", s):
                return s      # a literal (already Chinese) name is returned as is
        if base:
            return base
        return L.loc(self.table, t.get("key") or "") or (t.get("key") or "")

    def migration_lost_title(self, owner_id, date, new_holder, days=3):
        """Recover the real title behind a migration lost-title memory, else None.

        The game records the `landed_title` of a `reason == migration` memory as always the
        original county, so the timeline would render every migration with the same title and
        could not map the event date. This looks the title up in title history instead: the one
        the subject handed to `new_holder` with `type == 'migration'` within `days` of date.
        Candidates come from his holdings at that time; several same-day transfers are matched on
        `new_holder`, and an ambiguous or missing match returns None.
        """
        if owner_id is None or not date:
            return None
        dk = _daynum(date)
        pool = []
        for tid, ivs in (self._hold_intervals(owner_id) or {}).items():
            for iv in ivs or []:
                if not iv or not iv[0] or not iv[1]:
                    continue
                if (iv[2] or "") != "migration":
                    continue
                if abs(_daynum(iv[1]) - dk) > days:
                    continue
                pool.append((tid, iv[1]))
        if not pool:
            return None
        if isinstance(new_holder, int):
            hit = [t for (t, ld) in pool if self.holder_at(t, ld) == new_holder]
            if len(hit) == 1:
                return hit[0]
        if len(pool) == 1:
            return pool[0][0]
        return None

    def _history_name_at(self, tid, date):
        """Key or literal name in title_history_names in effect at date, else None.

        For h_china the one-day realm name of the mandate-of-heaven proclamation is replaced the
        next day, so the name chosen the next day is used.
        """
        t = self._lt.get(str(tid)) or {}
        names = (t.get("title_name_data") or {}).get("title_history_names") or []
        if not date or not names:
            return None
        dk = cl.date_key(str(date))
        best, best_i = None, None
        for i, h in enumerate(names):
            try:
                if h.get("date") and cl.date_key(str(h["date"])) <= dk:
                    best, best_i = h.get("name"), i
            except Exception:
                continue
        key = t.get("key") or ""
        if key == "h_china" and best_i is not None and best_i + 1 < len(names):
            nxt = names[best_i + 1]
            nd = nxt.get("date")
            try:
                if nd and 0 < (_date_ord(nd) - _date_ord(date)) <= 2:
                    best = nxt.get("name")
            except Exception:
                pass
        return best

    def _name_source_key(self, tid, date):
        """Source key of the name in use at date: the title_history_names entry in effect
        (dynn_title_* / h_china / a literal name), or '' without a rename history.

        Used to tell whether the realm name is a house/dynasty name, which is what the "Great"
        prefix is reserved for.
        """
        return str(self._history_name_at(tid, date) or "")

    def _is_short_title(self, tid):
        """True for a game "short name" title (`definite_form = yes` in landed_titles).

        Such a title's own name already carries the state or tier word, so no tier word is
        appended.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if not key:
            return False
        try:
            return key in L.short_titles()
        except Exception:
            return False

    def throne_word(self, tid, cid=None, date=None):
        """Wording for an empty throne: a throne name is a title of office, not a place, so only
        the office word (emperor / king) is returned.

        `k_chrysanthemum_throne` is landless and figurehead, and the game's mechanical
        TITLE_TIERED_NAME would turn it into a place-like string. '' when the throne is not
        recognized, letting the caller keep its own wording. cid and date exist for signature
        compatibility only: the throne word does not vary by government or date.
        """
        if tid is None:
            return ""
        key = ((self._lt.get(str(tid)) or {}).get("key") or "")
        loc_key = self._THRONE_OFFICE_KEYS.get(key)
        if not loc_key:
            return ""
        v = L.loc(self.table, loc_key)
        return v if v and not v.startswith(("$", "[")) else ""

    def _title_name_at(self, tid, date, cid=None, site=False):
        """Full name of the title on a date: the dated name plus the tier word (an independent
        kingdom uses the realm word). cid, when given, supplies the character's independence.

        Independence is judged by the then-holder at that date, because whether the title is a
        realm or a circuit depends on whether it stood alone at that moment. With site=True the
        naming outlet is `_site_name` ([place name]), and a title that ever had a dynamic name
        returns that name with no tier word; the default False keeps the existing wording.
        """
        if tid is None:
            return ""
        t = self._lt.get(str(tid)) or {}
        key = t.get("key") or ""
        # An empty throne gets the office word only; name + tier word would be a mechanical string
        _tw = self.throne_word(tid)
        if _tw:
            return _tw
        if site:
            nm = self._site_name(tid, cid=cid, date=date)
            if self._dyn_named(tid) or key.startswith(("x_", "e_minister_")):
                return nm
        elif key.startswith("x_"):  # camps/house titles and similar: name only
            return self._name_at_date(tid, date) or L.loc(self.table, key) or key
        else:
            # a dynamic title name is already the game's complete display name: no tier word
            specific = self._specific_name(tid)
            if specific:
                return specific
            nm = self._name_at_date(tid, date)
        if not nm:
            nm = L.loc(self.table, key)
        if not nm:
            nm = key
        if key.startswith("e_minister_"):  # court offices get the name only
            return nm
        # without an explicit cid, independence comes from the then-holder at that date
        # (the holder recorded in title history for that moment)
        if cid is None:
            cid = self.holder_at(tid, date)
        # the government is the holder's own (see `_gov_for_word`)
        gov = self._gov_for_word(cid, tid, date)
        independent = self._is_independent(cid, date) if cid is not None else False
        if independent is None:
            independent = False
        word = self._tier_word_at(tid, gov, bool(independent), cid=cid, date=date)
        # same rule as title(): a Chinese administrative place name takes no tier word, which
        # avoids duplicated forms
        if key.startswith("c_") and word and _CN_PLACE_SUFFIX_RE.search(nm):
            return nm
        if word and not any(nm.endswith(w) for w in self._rank_words):
            return f"{nm}{word}"
        return nm

    def _name_in_span(self, tid, start, end, cid=None):
        """Stable name of the title over [start, end].

        The sample point is the tenure start, not the interval midpoint: renames produce 1-2 day
        transitional names at the start and end of a tenure, so naming from the start yields the
        version after the rename and keeps one name per tenure. A midpoint sample would emit two
        names in a single tenure when a rename falls inside it.
        """
        if tid is None:
            return ""
        return self._title_name_at(tid, start, cid)

    def _hold_intervals(self, cid, as_of=None):
        """Holding intervals of the character {tid: [(gain, loss|None, loss_type), ...]}.

        Title history provides exact dates through an O(1) index, while realm_history snapshots cover
        titles that title history has pruned (destroyed kingdoms, for instance). Cached per (cid, as_of).
        """
        as_of = as_of or self.as_of
        cache_key = (cid, as_of)
        if cache_key in self._hold_cache:
            return self._hold_cache[cache_key]
        out = {}
        base = self._holder_intervals.get(cid) or {}
        if as_of == self.as_of:
            out = {tid: list(ivs) for tid, ivs in base.items()}
        else:
            # different as_of: filter by date, folding open intervals to as_of
            ao = cl.date_key(as_of) if as_of else None
            for tid, ivs in base.items():
                kept = []
                for (g, l, lt) in ivs:
                    if ao is not None and cl.date_key(g) > ao:
                        continue
                    if l and ao is not None and cl.date_key(l) > ao:
                        kept.append((g, None, lt))
                    else:
                        kept.append((g, l, lt))
                if kept:
                    out[tid] = kept
        # realm snapshot fallback: consecutive snapshots become one interval (loss = next snapshot date)
        ridx = self._realm_holder_titles.get(cid) or {}
        n_snaps = len(self._realm_snaps)
        for tid, idxs in ridx.items():
            if tid in out:
                continue
            runs = []
            cur_run = None
            prev_i = None
            for i in sorted(idxs):
                if cur_run is None:
                    cur_run = i
                elif i == prev_i + 1:
                    pass
                else:
                    runs.append((cur_run, prev_i))
                    cur_run = i
                prev_i = i
            if cur_run is not None:
                runs.append((cur_run, prev_i))
            for (a, b) in runs:
                gain = self._realm_snaps[a].get("date")
                loss = self._realm_snaps[b + 1].get("date") if b + 1 < n_snaps else None
                out.setdefault(tid, []).append((gain, loss, ""))
        self._hold_cache[cache_key] = out
        return out

    # ------------------------------------------------------------------
    # Title succession chains
    # ------------------------------------------------------------------
    # In the save's `landed_titles[tid].history` a day with several successive holders holds a
    # list (Clausewitz duplicate keys merged by `_merge_dup_pairs`), and `_title_seqs` is already
    # date-sorted. This expands it into a "who took over from whom, when" sequence used by two
    # tests: `seat_note(cid)`, a succession sentence when the predecessors of a current title
    # died at the subject's hand (house biography child files only), and `seat_succession(cid)`,
    # the holder chain after a death, exposed as a top-level fact key for verification.

    def _title_holder_seq(self, tid):
        """Holder sequence of the title [(date, holder_id, type), …], same-day lists in order."""
        if tid is None:
            return []
        out = []
        for d, ev in (self._title_seqs.get(int(tid)) or []):
            for e in (ev if isinstance(ev, list) else [ev]):
                if not isinstance(e, dict):
                    continue
                h = e.get("holder")
                if isinstance(h, int):
                    out.append((str(d), int(h), str(e.get("type") or "")))
        return out

    def _is_landed_tid(self, tid):
        """True for a landed title (excludes camps, yurts, house estates and court offices)."""
        key = ((self._lt.get(str(tid)) or {}).get("key") or "")
        return bool(key) and not key.startswith(("x_", "e_minister_")) \
            and not self._is_estate_title(tid)

    def _seat_killed_ids(self):
        """Ids the subject killed, from the same sources as `_killed_by_player` but cacheable."""
        if getattr(self, "_seat_killed_cache", None) is not None:
            return self._seat_killed_cache
        pid = self.cache.get("player_id")
        out = set()
        if pid is not None:
            prec = (self.cache.get("characters") or {}).get(str(pid)) or {}
            for k in prec.get("kills") or []:
                if isinstance(k, int):
                    out.add(k)
            for k in (self.cache.get("player_death") or {}).get("kills") or []:
                if isinstance(k, int):
                    out.add(k)
            for mem in prec.get("memories") or []:
                if str(mem.get("type") or "") == "successful_murder":
                    v = (mem.get("participants") or {}).get("victim")
                    if isinstance(v, int):
                        out.add(v)
            for cid, rec in (self.cache.get("characters") or {}).items():
                if str(cid).isdigit() and (rec.get("death") or {}).get("killer") == pid:
                    out.add(int(cid))
            for cid, c in self._chars.items():
                if not str(cid).isdigit() or int(cid) == pid:
                    continue
                d = (c or {}).get("dead_data") or {}
                if isinstance(d.get("killer"), int) and d["killer"] == pid:
                    out.add(int(cid))
        self._seat_killed_cache = out
        return out

    def _seat_prior_killed(self, cid, tid, gain):
        """Chain of predecessors on this title who immediately precede this person and died at
        the subject's hand, as [(date, id), …] in chronological order.

        Walking back stops at the first predecessor who neither shares the day nor was killed by
        the subject. A same-day predecessor counts as a pass-through and does not break the chain.
        """
        seq = self._title_holder_seq(tid)
        if not seq:
            return []
        killed = self._seat_killed_ids()
        pid = self.cache.get("player_id")
        idx = None
        for i, (d, h, _t) in enumerate(seq):
            if h == cid and cl.date_key(d) >= cl.date_key(gain):
                idx = i
                break
        if idx is None:
            return []
        prev, j = [], idx - 1
        while j >= 0:
            d, h, _t = seq[j]
            if h == cid:
                j -= 1
                continue
            if cl.date_key(d) >= cl.date_key(gain):
                j -= 1                      # same-day pass-through (including the subject): skip
                continue
            if h in killed:
                prev.append((d, h))
                j -= 1
                continue
            break
        prev.reverse()
        return prev

    def _death_info(self, cid):
        """(death date, death reason, killer): cache first, melt dead_data as fallback."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        d = rec.get("death") or {}
        dd = (self._chars.get(str(cid)) or {}).get("dead_data") or {}
        k = d.get("killer")
        if k is None:
            k = dd.get("killer")
        return (d.get("date") or dd.get("date"), d.get("reason") or dd.get("reason"), k)

    def seat_note(self, cid):
        """Succession sentence for the children's files of the house biography, else ''.

        Computed entirely from data: the run of consecutive predecessors of the character's
        current landed title who died at the subject's hand — the deaths that cleared the seat
        for his child. The first predecessor's fate uses the public `death_clause` wording and
        the rest are summarized; the killer is named only when every death in the chain is
        already public.
        """
        pid = self.cache.get("player_id")
        if pid is None or cid is None:
            return ""
        bits = []
        for tid, ivs in (self._hold_intervals(cid) or {}).items():
            if not self._is_landed_tid(tid):
                continue
            spans = [iv for iv in (ivs or []) if iv and iv[0]]
            if not spans:
                continue
            gain = max(iv[0] for iv in spans)
            prev = self._seat_prior_killed(cid, tid, gain)
            if not prev:
                continue
            tname = self.title_office_text(cid, tid, gain) \
                or self._name_at_date(tid, gain) or self.title_base_name(tid)
            if not tname:
                continue
            d0, h0 = prev[0]
            d_death, reason, killer = self._death_info(h0)
            clause = self.death_clause(h0, date=d_death or d0, reason=reason,
                                       killer=killer if killer is not None else pid)
            l0 = self.kin_label(h0) or self.name_or(h0)
            _all_public = all(self.killer_is_public(h) for _d, h in prev)
            head = (f"{l0}{self.date(d_death or d0)}{clause}" if clause
                    else (f"{l0}{self.date(d_death or d0)}死于{self.name_or(pid)}之手"
                          if _all_public
                          else f"{l0}{self.date(d_death or d0)}卒"))
            rest = [self.name_or(h) for _d, h in prev[1:]]
            if rest:
                mid = ("、".join(rest)
                       + (f"相继居之，皆死于{self.name_or(pid)}之手" if _all_public
                          else "相继居之，未几皆卒"))
            else:
                mid = ""
            bits.append(f"承位：{tname}之任：{head}" + (f"；{mid}" if mid else "")
                        + f"；{self.date(gain)}归{self.name_or(cid)}。")
        return "；".join(bits)

    def seat_succession(self, cid):
        """Holder chain after this character's death or loss of office, as
        [{"title", "chain": [...], "settled": {...}}].

        The chain starts at the next holder and runs to the first holder not killed by the
        subject, including same-day successors. Computed from data, sharing the title sequence
        with `Facts.seat_note`.
        """
        out = []
        if cid is None:
            return out
        killed = self._seat_killed_ids()
        pid = self.cache.get("player_id")
        for tid, ivs in (self._hold_intervals(cid) or {}).items():
            if not self._is_landed_tid(tid):
                continue
            ends = [iv[1] for iv in (ivs or []) if iv and iv[0] and iv[1]]
            if not ends:
                continue
            end = max(ends)
            tname = self._name_at_date(tid, end) or self.title_base_name(tid)
            chain, settle, stop = [], None, None
            for d, h, _t in self._title_holder_seq(tid):
                if cl.date_key(d) < cl.date_key(end) or h == cid:
                    continue
                if stop is not None and cl.date_key(d) > cl.date_key(stop):
                    break
                chain.append({"date": d, "holder_id": h,
                              "holder_label": self.kin_label(h) or self.name_or(h),
                              "kin": kin_key(self.cache, pid, h) or ""})
                if h not in killed and settle is None:
                    settle, stop = {"date": d, "holder_id": h}, d
            if chain:
                out.append({"title": tname, "date": end, "chain": chain,
                            "settled": settle})
        return out

    def _is_nomad_camp(self, tid):
        """True for a nomadic yurt title (x_c_nomad_*), a dwelling rather than land."""
        return ((self._lt.get(str(tid)) or {}).get("key") or "") \
            .startswith("x_c_nomad_")

    # Three kinds of landless/house title: house estates (_nf_), landless adventurer camps
    # (_laamp_ and similar) and nomadic yurts (x_c_nomad_). An x_ prefix alone does not make a
    # title an adventurer camp.
    _ESTATE_KEY_MARK = "_nf_"
    _CAMP_KEY_PREFIXES = ("x_mc_", "x_script_", "x_ho_")

    def _is_estate_title(self, tid):
        """True for a house-estate title (x_nf_/c_nf_/d_nf_: clans, warrior houses, family land)."""
        if tid is None:
            return False
        return self._ESTATE_KEY_MARK in ((self._lt.get(str(tid)) or {}).get("key") or "")

    def _eff_rank(self, tid):
        """Effective rank of a title: a house estate (`_nf_`) is family property, not land, so it
        counts as rank 0 like a landless camp or yurt.

        Those titles carry `landless = yes` / `noble_family = yes`
        (`common/landed_titles/04_china_noble_families.txt`) and the UI land column is empty, so
        ranking an estate by its `c_`/`d_` prefix would let a landless clan enter the primary
        title slot as a county.
        """
        if tid is None:
            return 0
        if self._is_estate_title(tid):
            return 0
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        return self._TT_RANK.get(key[:2], 0)

    def _is_adventurer_camp(self, tid):
        """True for a landless adventurer camp title (x_d_laamp_* and similar), not a yurt/estate."""
        if tid is None:
            return False
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if self._is_nomad_camp(tid) or self._is_estate_title(tid):
            return False
        return "_laamp_" in key or key.startswith(self._CAMP_KEY_PREFIXES)

    # Adventurer (camp) period intervals: the adventurer itinerary section covers only these.
    def camp_intervals(self, cid=None, kind="camp"):
        """Intervals [(gain, loss|None)] in which the character held this kind of dwelling title,
        sorted by start date.

        kind is "camp" (landless adventurer camp) or "nomad" (yurt); the two itinerary sections
        each take one.
        """
        pid = self.cache.get("player_id") if cid is None else cid
        if pid is None:
            return []
        out = []
        for tid, ivs in (self._hold_intervals(pid) or {}).items():
            if self.title_kind(tid) != kind:
                continue
            for iv in ivs:
                if iv and iv[0]:
                    out.append((iv[0], iv[1] if len(iv) > 1 else None))
        out.sort(key=lambda x: cl.date_key(x[0]))
        return out

    def in_camp_period(self, date, cid=None, kind="camp"):
        """True when date falls inside a dwelling-title interval (endpoints included); kind as in
        `camp_intervals`."""
        dk = cl.date_key(date) if date else None
        if dk is None:
            return False
        for g, l in self.camp_intervals(cid, kind=kind):
            if cl.date_key(g) <= dk and (not l or dk <= cl.date_key(l)):
                return True
        return False

    def title_kind(self, tid):
        """Semantic kind of a title: 'estate' house estate, 'nomad' yurt, 'camp' adventurer camp,
        '' for a landed title (including counties and baronies)."""
        if tid is None:
            return ""
        if self._is_nomad_camp(tid):
            return "nomad"
        if self._is_estate_title(tid):
            return "estate"
        if self._is_adventurer_camp(tid):
            return "camp"
        return ""

    _EAST_ASIAN_ESTATE_TPL = {"han", "chinese", "bai", "yi"}

    def estate_kind_word(self, tid, cid=None, date=None):
        """Chinese category word for an estate, taken from the game's own wording: Japanese ->
        warrior-house estate; East Asian culture (han/chinese/bai/yi) or celestial government ->
        clan estate; otherwise the plain noble-family word, which is how administrative realms
        refer to powerful clans. Culture, not government, decides the East Asian case.
        """
        tpl = self.culture_template(cid) if cid is not None else ""
        if tpl == "japanese":
            return "武家庄园"
        if tpl in self._EAST_ASIAN_ESTATE_TPL:
            return "世族庄园"
        gov = self._gov_for_word(cid, tid, date or self.as_of)
        if gov == "celestial_government":
            return "世族庄园"
        if tpl in self._KOREAN_ESTATE_TPL:
            return "家族庄园"
        return "世族"

    def _primary_group(self, held, cid=None):
        """Primary title group for a holding set {tid: gain_date} -> [(gain_date, tid)].

        Counties and baronies never enter; at duchy level or above, kingdom rank keeps only the primary
        while duchy/camp level keeps the primary plus every camp. Court offices are posts, not land,
        and nomadic yurts are dwellings (`landless: true`), so neither occupies the slot and [] means
        the land lost that day is reported by `held_titles`.
        """
        if not held:
            return []
        items = []
        for tid, gain in held.items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            if key.startswith("e_minister_"):
                continue
            items.append((tid, self._eff_rank(tid), gain))
        if not items:
            return []  # court offices only (posts, not land)
        order = self._domain_order(cid) if cid is not None else {}
        majors = [it for it in items
                  if (it[1] >= 3 or it[1] == 0)
                  and not self._is_nomad_camp(it[0])
                  and not self._is_estate_title(it[0])]
        if not majors:
            # Counties/baronies only (or estates/yurts only): highest rank, earliest gain.
            # Estates never occupy the slot while there is land, baronies (rank 1) never enter at
            # all, and yurts never occupy it either (see the docstring) — the loss of land is
            # reported by `held_titles` instead.
            cands = [it for it in items
                     if it[1] != 1 and not self._is_nomad_camp(it[0])]
            if not cands:
                return []
            t0 = sorted(cands, key=lambda it: (-it[1], order.get(int(it[0]), 10 ** 6),
                                               cl.date_key(it[2])))[0]
            return [(t0[2], t0[0])]
        max_tier = max(r for _t, r, _g in majors)
        tops = sorted([it for it in majors if it[1] == max_tier],
                      key=lambda it: (order.get(int(it[0]), 10 ** 6),
                                      cl.date_key(it[2])))
        if max_tier >= 4:  # kingdom and above: primary title only
            t0 = tops[0]
            return [(t0[2], t0[0])]
        camps = [it for it in majors if self.title_kind(it[0]) == "camp"]
        picked = tops[:1] + [c for c in camps if c != tops[0]]
        return [(g, t) for t, _r, g in sorted(picked, key=lambda it: cl.date_key(it[2]))]

    def _domain_order(self, cid):
        """Order of the character's domain list -> {tid: index}.

        The game's `domain` list puts the primary title first, so ties at the same rank are broken
        by this index rather than by title id. Read from a dead character's `dead_data.domain`
        (baked at death, most reliable), then `landed_data.domain`, then the cache's
        `landed.domain` (players only). {} when unavailable.
        """
        if cid is None:
            return {}
        key = str(cid)
        memo = getattr(self, "_domain_order_memo", None)
        if memo is None:
            memo = self._domain_order_memo = {}
        if key in memo:
            return memo[key]
        c = self._chars.get(key) or {}
        dom = ((c.get("dead_data") or {}).get("domain")
               or (c.get("landed_data") or {}).get("domain"))
        if not dom:
            dom = (((self.cache.get("characters") or {}).get(key) or {})
                   .get("landed") or {}).get("domain")
        out = {}
        for i, tid in enumerate(dom or []):
            try:
                out[int(tid)] = i
            except (TypeError, ValueError):
                continue
        memo[key] = out
        return out

    def inherit_consumed(self, cid):
        """Ids of memory objects already consumed by a merged inheritance sentence (same source as
        `inherit_pairs`)."""
        memo = getattr(self, "_inherit_consumed_memo", None)
        if memo is None:
            memo = self._inherit_consumed_memo = {}
        key = str(cid)
        if key in memo:
            return memo[key]
        ids = set()
        for _line, _ids, _dd in self.inherit_pairs(cid).values():
            ids |= _ids
        memo[key] = ids
        return ids

    # ---- merged inheritance sentences (who died, who inherited which land from him) ----
    #
    # The save records a parent's death and the child's inheritance as two separate same-day
    # memories: `relative_died` with participants {dead_relation: <parent>} and
    # `ascended_throne_memory` with vars reason=inheritance, landed_title=<title> and participants
    # {flavor_character: <parent>}. Emitting them separately hides the causal link, so memories
    # that are near in date and share the deceased are merged into one sentence. The heir's label
    # is taken from the day before the inheritance, when he does not yet wear the new title.
    _INHERIT_MERGE_DAYS = 3

    def _mem_var(self, mem, flag):
        """Value of a flag in a memory's vars (identity first, then value)."""
        for v in (mem.get("vars") or []):
            if v.get("flag") == flag:
                return v.get("identity") if v.get("identity") is not None \
                    else v.get("value")
        return None

    def _inherited_title_names(self, cid, prev, date):
        """Names of the titles cid inherited from prev on date, from title history."""
        idx = getattr(self, "_inherit_title_index", None)
        if idx is None:
            idx = {}
            for (hid, tid, d), p in (self._gain_prev or {}).items():
                if p is None:
                    continue
                if self.gain_reason(hid, tid, d) != "inheritance":
                    continue
                idx.setdefault((hid, str(d), p), []).append(tid)
            self._inherit_title_index = idx
        tids = list(idx.get((int(cid), str(date), int(prev))) or [])
        out = []
        for tid in tids:
            nm = self._title_name_at(tid, date, cid)
            if nm:
                out.append(nm)
        return out

    def _inherit_line(self, heir, prev, date, landed_title=None):
        """Body of a merged inheritance sentence, without the date prefix; '' when nothing to say."""
        dead = self.person_label(prev, date=date, style="brief") or self.name_or(prev)
        # the heir's label comes from the day before: on the day itself he already wears the new title
        heir_lbl = self.person_label(heir, date=_day_before(date), style="brief") \
            or self.name_or(heir)
        if not dead or not heir_lbl:
            return ""
        titles = self._inherited_title_names(heir, prev, date)
        if not titles and landed_title:
            nm = self._title_name_at(landed_title, date, heir)
            if nm:
                titles = [nm]
        if not titles:
            return ""
        if len(titles) > 3:
            tname = "、".join(titles[:3]) + f"等{len(titles)}处领地"
        else:
            tname = "、".join(titles)
        return f"{dead}去世，{heir_lbl}从其手中承袭{tname}。"

    def inherit_pairs(self, cid):
        """Pair the character's death memories with his inheritance memories (memoized per cid).

        Returns {death memory object id: (merged sentence, {consumed memory object ids})}; the
        caller skips the consumed memories and emits the merged sentence, adding the date prefix
        itself.
        """
        memo = getattr(self, "_inherit_pairs_memo", None)
        if memo is None:
            memo = self._inherit_pairs_memo = {}
        key = str(cid)
        if key in memo:
            return memo[key]
        rec = (self.cache.get("characters") or {}).get(key) or {}
        mems = [m for m in (rec.get("memories") or []) if isinstance(m, dict)]
        deaths = []
        for m in mems:
            if m.get("type") not in _DIED_TYPES:
                continue
            dead = (m.get("participants") or {}).get("dead_relation")
            if isinstance(dead, int):
                deaths.append((self.mem_date(cid, m) or m.get("creation_date"),
                               m, dead))
        out = {}
        for m in mems:
            if m.get("type") != "ascended_throne_memory":
                continue
            if str(self._mem_var(m, "reason") or "") != "inheritance":
                continue
            prev = (m.get("participants") or {}).get("flavor_character")
            if not isinstance(prev, int):
                continue
            d = self.mem_date(cid, m) or m.get("creation_date")
            if not d:
                continue
            for dd, dm, dead in deaths:
                if dead != prev or not dd:
                    continue
                if abs(_daynum(dd) - _daynum(d)) > self._INHERIT_MERGE_DAYS:
                    continue
                body = self._inherit_line(cid, prev, d,
                                          self._mem_var(m, "landed_title"))
                if body:
                    out[id(dm)] = (body, {id(dm), id(m)}, dd)
                break
        memo[key] = out
        return out

    def _primary_title_at(self, cid, as_of=None, held_through=None):
        """Primary title of the character at as_of -> (tier, tid); (None, None) if none qualifies.

        Baronial titles (rank 1) never qualify and stay place names, while camps and estates (rank 0)
        count. Acquisitions after as_of are filtered out. `held_through` tests intersection instead of
        "still held in the last save", which a dead subject needs or losing every title on his death
        day would let the court-office government gate fail open.
        """
        held = {}
        ao = cl.date_key(as_of) if as_of else None
        through = cl.date_key(held_through) if held_through else None
        for tid, ivs in self._hold_intervals(cid, as_of).items():
            if through is not None:
                gain = None
                for (g, l, _lt) in ivs:      # the segment that intersects held_through
                    if g and cl.date_key(g) > through:
                        continue
                    if l and cl.date_key(l) < through:
                        continue
                    gain = g
                    break
                if gain is None:
                    continue
            else:
                if not (ivs and ivs[-1][1] is None):
                    continue
                gain = ivs[-1][0]
                if ao is not None and gain and cl.date_key(gain) > ao:
                    continue
            if self._eff_rank(tid) == 1:
                continue
            held[tid] = gain
        if not held:
            return None, None
        items = [(tid, self._eff_rank(tid), g) for tid, g in held.items()]
        max_tier = max(r for _t, r, _g in items)
        tops = sorted([it for it in items if it[1] == max_tier],
                      key=lambda it: (self._domain_order(cid).get(int(it[0]), 10 ** 6),
                                      cl.date_key(it[2])))
        tid = tops[0][0]
        tier = self._RANK_TIER.get(max_tier) if max_tier >= 1 else None
        return tier, tid

    def held_titles(self, cid):
        """Office history: one line per change of primary title, with same-rank camps/estates
        written alongside when the rank is a duchy or below.

        Built from title history (exact dates) with realm_history snapshots as fallback. Stage lines
        use the game's ruler address words (culture family x tier x government). Returns one string per
        phase, each beginning with its date.
        """
        intervals = self._hold_intervals(cid)
        events = []
        loss_types = {}  # (tid, date_key) -> type
        for tid, ivs in intervals.items():
            # Baronial titles (rank 1) never enter the office history and serve only as place
            # names; ranks come from `_eff_rank`, so estates count as rank 0 and still appear
            # (family property is part of one's standing).
            if self._eff_rank(tid) == 1:
                continue
            for (g, l, lt) in ivs:
                events.append((cl.date_key(g), g, tid, 1))
                if l:
                    events.append((cl.date_key(l), l, tid, -1))
                    loss_types[(tid, cl.date_key(l))] = lt
        events.sort(key=lambda x: x[0])
        # apply per day: same-day events take effect together, avoiding intermediate states
        by_day = {}
        for dk, d, tid, delta in events:
            by_day.setdefault(dk, []).append((d, tid, delta))
        held = {}
        phases = []
        prev_group = None
        prev_held = set()
        for dk in sorted(by_day):
            batch = by_day[dk]
            d = batch[0][0]
            for _dd, tid, delta in batch:
                if delta == 1:
                    held[tid] = _dd
                else:
                    held.pop(tid, None)
            group = self._primary_group(held, cid)
            # A phase with only nomadic yurts left: yurts are not land, so no office is recorded,
            # but the land lost that day must be logged as an empty-group phase.
            nomad_only = (not group) and any(
                self.title_kind(t) == "nomad" for t in held)
            if group and group != prev_group:
                phases.append((d, group, set(prev_held) - set(held), False))
                prev_group = group
            elif nomad_only and prev_group:
                phases.append((d, [], set(prev_held) - set(held), True))
                prev_group = group
            prev_held = set(held)
        if not phases:
            return []
        # phase end: the next phase's start, else as_of (or the last save)
        span_end = self.as_of or self.cache.get("last_date")
        out = []
        prev_ids = []
        for i, (d, group, lost_now, nomad_only) in enumerate(phases):
            end = phases[i + 1][0] if i + 1 < len(phases) else span_end
            ids = [tid for _g, tid in group]
            parts = []
            for t in ids:
                key = (self._lt.get(str(t)) or {}).get("key") or ""
                if key.startswith("x_") or self.title_kind(t) in ("camp", "estate"):
                    # Camp phases use the game's camp-purpose word (chief/leader/captain…) and
                    # fall back to "lord of X". Yurts get no camp word, only the yurt name; house
                    # estates use a holder word (squire/head of house) plus their category. The
                    # decision goes through `title_kind`, because landless adventurer camps and
                    # estates do not use an x_ prefix. Holder lines show the base name only.
                    # Camps, yurts and estates never use the [place name] mode: their names come
                    # from camp-purpose and family-estate words, and a camp's dynamic name is
                    # often fixed before its holder acquires it, so no history anchor exists.
                    nm = self._name_at_date(t, d) or self.title_base_name(t)
                    if self._is_nomad_camp(t):
                        parts.append(nm)
                        continue
                    if self._is_estate_title(t):
                        ew = self.estate_kind_word(t, cid)
                        w = self._estate_holder_word(cid)
                        base = f"{nm}{w}" if nm and w else (nm or "")
                        # the category word follows as a comma appositive
                        parts.append(f"{base}，{ew}" if base else "")
                        continue
                    w = self._camp_holder_word(cid, d)
                    base = f"{nm}{w}" if nm and w else (f"{nm}之主" if nm else "")
                    parts.append(f"{base}，无地冒险者营地" if base else "")
                else:
                    # Land phases use the title's place name plus the game's ruler address word
                    # (culture- and government-aware). The place name comes from the [place name]
                    # mode, sampled at the phase midpoint so a mid-tenure rename does not split
                    # one tenure into two names; its anchor is the subject's earliest acquisition
                    # and is independent of the midpoint. An inherited phase uses the name of the
                    # day instead, because the inherited realm name (a house-named khanate or
                    # sultanate) is exactly what that line reports.
                    mid = self._span_mid(d, end)
                    if self.gain_reason(cid, t, d) == "inheritance":
                        nm = self._name_at_date(t, mid) or self.title_base_name(t)
                    else:
                        nm = self._site_name(t, cid=cid, date=mid) \
                            or self.title_base_name(t)
                    w = self._ruler_word_at(cid, t, d)
                    parts.append(f"{nm}{w}" if nm and w else (f"{nm}之主" if nm else ""))
            parts = [p for p in parts if p]
            # titles genuinely lost (absent from the held set) that were in the group before
            lost_names = []
            _seen_lost = set()
            for t in prev_ids:
                if t in ids or t not in lost_now:
                    continue
                lt = loss_types.get((t, cl.date_key(d)))
                # loss lines use the [place name] mode too, or several different titles would
                # share the last save's name; camps/yurts/estates are excluded (see _site_ok)
                nm = self._title_name_at(t, d, cid, site=self._site_ok(t))
                if not nm or nm in _seen_lost:
                    continue
                # The loss verb comes from the title history event type; an unknown type falls
                # back to a generic verb, and destruction is listed separately. On a nomad's
                # migration day the game destroys his top land title
                # (`09_dlc_mpo_scripted_effects.txt`, Change 4), which shares its name with the
                # county lost that day, so the migration verb is used instead of the destruction
                # verb; names are de-duplicated. Ranks come from `_eff_rank`.
                _rank = self._eff_rank(t)
                if lt == "destroyed":
                    verb = "迁离" if (nomad_only and _rank >= 2) else "毁弃"
                else:
                    verb = TITLE_LOSS_VERBS.get(lt or "", "让出")
                _seen_lost.add(nm)
                lost_names.append(f"{verb}{nm}")
            if not ids:
                # empty-group phase: no office to hold, so only the land lost that day is written
                if lost_names:
                    out.append(self.date(d) + "、".join(lost_names))
                prev_ids = ids
                continue
            if not parts:
                continue
            # A stage line reports how the top title was gained: the title history event type plus
            # the previous holder or grantor, as in a conquest from a named holder. Without it the
            # reader cannot tell war, inheritance and intrigue apart.
            top = max(ids, key=lambda t: self._eff_rank(t))
            gain = self._gain_clause(cid, top, d)
            # Founding/restoring/creating are title-making verbs, so their object is the title
            # name, while appointment, inheritance and conquest keep the personal form.
            reason = self.gain_reason(cid, top, d)
            if gain and reason == "created":
                tname = self._title_name_at(top, d, cid) or parts[0]
                line = f"{self.date(d)}{gain}{tname}"
            elif gain:
                line = f"{self.date(d)}{gain}{'／'.join(parts)}"
            else:
                line = f"{self.date(d)}任{'／'.join(parts)}"
            prev_ids = ids
            if lost_names:
                # the loss clause joins with a comma, not a parenthetical
                line += "，并" + "、".join(lost_names)
            out.append(line)
        return out

    # ---- how a title was gained / previous holder / government changes ----

    def gain_reason(self, cid, tid, date):
        """Event type recorded in title history when cid gained the title on date
        (conquest/created/inheritance/appointment/granted/usurped…), else ''."""
        if cid is None or tid is None or date is None:
            return ""
        return self._gain_reason.get((int(cid), int(tid), str(date)), "")

    def prev_holder(self, tid, date, exclude=None):
        """Id of the previous holder of the title on date (last history entry before that day with
        a holder != exclude), else None."""
        if tid is None or date is None:
            return None
        seq = self._title_seqs.get(int(tid)) or []
        lim = cl.date_key(str(date))
        found = None
        for d, ev in seq:
            if cl.date_key(d) > lim:
                break
            for e in (ev if isinstance(ev, list) else [ev]):
                h = e.get("holder") if isinstance(e, dict) else e
                if h is None:
                    continue
                try:
                    hid = int(h)
                except (TypeError, ValueError):
                    continue
                if exclude is not None and hid == int(exclude):
                    continue
                found = hid
        return found

    def _gain_clause(self, cid, tid, date):
        """Phrase describing how a title was gained ("took from X", "inherited", "created",
        "appointed by X"), up to but not including the office verb; '' without evidence.

        Same sources as the memory sentence (style.TITLE_GAIN_VERBS, the created/restored bucket
        of `title_had_other_holder`, and `grant_actor`'s grantor) but dated by the title history
        event day rather than the memory day, so the date and verb of a stage line agree.
        """
        reason = self.gain_reason(cid, tid, date)
        if not reason:
            return ""
        if reason == "created":
            kind = self.created_verb_kind(tid, cid, date)
            verb = _style.TITLE_GAIN_CREATED_VERBS.get(kind) \
                or _style.TITLE_GAIN_VERBS.get("created") or ""
            return verb
        verb = _style.TITLE_GAIN_VERBS.get(reason) or ""
        if not verb:
            return ""
        if reason in _TITLE_TAKE_REASONS:
            ph = self.prev_holder(tid, date, exclude=cid)
            pn = self.person_label(ph, date=date, style="brief") \
                if isinstance(ph, int) else ""
            return f"自{pn}手中{verb}" if pn else verb
        # appointment/grant/inheritance from someone: name the source
        if reason in _TITLE_FROM_REASONS:
            ph = self.prev_holder(tid, date, exclude=cid)
            pn = self.person_label(ph, date=date, style="brief") \
                if isinstance(ph, int) else ""
            return f"承袭自{pn}" if (pn and reason == "inheritance") else verb
        return verb

    def government_changes(self, cid=None):
        """One sentence per dated change of government, e.g. a switch to feudalism followed by the
        lord address words of that government.

        Data source: `cache["char_government_history"][cid]` (cache_lib records change points per
        save for every in-scope character), with `cache["government_history"]` (player only) as the
        older fallback. The predecessor is the immediately preceding entry, not the earliest one.
        Dates are the save dates of the change points, not the accession date, because accession
        and a government change are separate events. '' when there are fewer than two governments.
        """
        pid = self.cache.get("player_id") if cid is None else cid
        if pid is None:
            return ""
        hist = [h for h in self._government_history(pid)
                if isinstance(h, dict) and h.get("date") and h.get("government")]
        # only change points up to this biography's as_of, so an early decade cannot announce a
        # government change that has not happened yet
        if self.as_of:
            _ao = cl.date_key(self.as_of)
            hist = [h for h in hist if cl.date_key(str(h["date"])) <= _ao]
        if len(hist) < 2:
            return ""
        lines = []
        for i in range(1, len(hist)):
            old, new = hist[i - 1], hist[i]
            ngov = self._government_zh(str(new["government"]))
            ogov = self._government_zh(str(old["government"]))
            if not ngov or ngov == ogov:
                continue
            line = f"{self.date(str(new['date']))}，"
            line += (f"{self.name_or(pid)}由{ogov}改行{ngov}" if ogov
                     else f"{self.name_or(pid)}改行{ngov}")
            words = []
            for tier in ("duchy", "county", "kingdom"):
                w = self._office_word(tier, str(new["government"]),
                                      independent=False, female=False, cid=pid,
                                      date=str(new["date"]))
                if w and w not in words:
                    words.append(w)
            if words:
                line += "；此后诸领主依次称" + "、".join(words)
            lines.append(line + "。")
        return "".join(lines)

    def _government_history(self, cid):
        """Per-save government history [{date, government}] for the character.

        The per-character table (`char_government_history`) wins; older caches only have the player
        table (`government_history`).
        """
        ch = self.cache.get("char_government_history") or {}
        hist = ch.get(str(cid))
        if isinstance(hist, list) and hist:
            return hist
        if cid == self.cache.get("player_id"):
            return list(self.cache.get("government_history") or [])
        return []

    def _government_zh(self, gov):
        """Chinese name of a government: localization table first, built-in fallback table second."""
        if not gov:
            return ""
        return L.loc(self.table, gov) or GOVERNMENT_ZH.get(gov, "")

    # ---- dynasty branches ----

    def clan_line(self, cid, date=None):
        """Dynasty-branch sentence, e.g. "X is a branch of the Y dynasty", so branches of one
        dynasty read as kin instead of strangers. The main branch is never named.

        Returns '' when the dynasty name is missing, when the branch shares the dynasty name (the
        founding house), or when the culture's name order is known — there the house label already
        contains the dynasty name and the sentence would only repeat the family line. Family names
        are the dated ones, so a rename makes the sentence disappear by itself.
        """
        if cid is None:
            return ""
        dn, hn = self._house_names_at(cid, date)
        if not dn or not hn or dn == hn:
            return ""
        if self.name_order(cid) is not None:
            return ""
        return f"{hn}为{dn}宗族的分支。"

    def _house_names_at(self, cid, date=None):
        """(dynasty name, house name) at date, dynasty first, in display form (a single-character name
        takes the house-name suffix, as in `_dynasty_display`).

        The dynasty name is $DYNASTY$ (the eastern name order's surname) and the house name is
        $HOUSE$ (the western one); the order matches `_dynasty_display(dn, hn)`.
        """
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        h, dn = cl._house_names_at(rec, self.melt, date or self.as_of,
                                   rec.get("house_name") or "",
                                   rec.get("dynasty_name") or "",
                                   memo=self._tpl_memo)
        return house_display(dn or h), house_display(h)

    def house_history_lines(self, cid):
        """House-status history lines: only a per-save diff can record founding a new house or
        renaming one.

        Source: the cache's `house_history` (cache_lib diffs the house id and the house/dynasty
        display names per save; the founding point is dated by the game's `found_date`). [] without
        at least two points. Returns a single line prefixed with the house-status label, or [].
        """
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        hist = [h for h in (rec.get("house_history") or []) if h.get("from")]
        if len(hist) < 2:
            return []
        ao = cl.date_key(self.as_of) if self.as_of else None
        pts = []
        for h in hist:
            try:
                if ao is not None and cl.date_key(h["from"]) > ao:
                    break
            except Exception:
                continue
            hid = h.get("house_id")
            hn = house_display(h.get("house_name") or "")
            dn = house_display(h.get("dynasty_name") or "")
            if not (hn or dn):
                continue
            pts.append((str(h["from"]), hid, hn, dn))
        if len(pts) < 2:
            return []

        segs = []
        for i, (d, hid, hn, dn) in enumerate(pts):
            dm = self.date(d)
            if not dm or "未知" in dm:
                dm = d
            nm = _house_shi(hn or dn)
            if i == 0:
                segs.append(f"原属{nm}")
                continue
            p_hid, p_hn, p_dn = pts[i - 1][1], pts[i - 1][2], pts[i - 1][3]
            new_house = hid != p_hid
            house_changed = hn != p_hn
            dyn_changed = dn != p_dn
            # The dynasty name is added only when a new house was founded or the dynasty itself was
            # renamed, and never when the house label already contains it (eastern name order),
            # which would be redundant.
            _east = self.name_order(cid) in cl.EASTERN_NAME_ORDERS
            clan = f"，属{dn}宗族" if dn and hn and dn != hn and not _east \
                and (new_house or dyn_changed) else ""
            if new_house:
                segs.append(f"{dm}起别立{nm}{clan}")
            elif house_changed and dyn_changed:
                segs.append(f"{dm}起家族与宗族并称{_house_shi(dn or hn)}")
            elif house_changed:
                segs.append(f"{dm}起家族改称{nm}{clan}")
            elif dyn_changed:
                segs.append(f"{dm}起宗族改称{_house_shi(dn)}")
        return ["家格：" + "，".join(segs) + "。"] if len(segs) > 1 else []

    def _kin_word(self, a, b):
        """Kinship side term of a relative to b (for the subject chain): "his father", "his elder
        brother", "his spouse"…

        Delegates to the module-level `kin_key` and uses the single-character chronicle form
        (`kin_word_short`). Former spouses do not count, so "spouse" means the current one. ''
        when the relation cannot be determined.
        """
        key = kin_key(self.cache, a, b, spouse_back=self._spouse_back_index())
        if not key:
            return ""
        return f"其{kin_word_short(key)}"

    def kin_word_for(self, cid, subject):
        """Kinship word of subject relative to cid (single outlet; see the module-level `kin_word`).

        The character table always comes from the cache, because the cache holds the kinship graph
        (the melt's family_data is often empty); kin_key falls back only for records the cache
        lacks.
        """
        return kin_word(self.cache, subject, cid,
                        spouse_back=self._spouse_back_index(),
                        rev=self._kin_rev_index())

    def blood_kin_word_for(self, cid, subject):
        """Blood-relation term of subject relative to cid; affinal, step and spousal relations
        return ''.

        Same test as `kin_word_for`, but the spouse edge between the two is removed first, so a
        double relation (both concubine and niece) resolves to the blood one. Used to label the
        blood tie in concubine/wife lists.
        """
        chars = mask_spouse_edges(self.cache.get("characters") or {}, (subject, cid))
        key = kin_key(self.cache, subject, cid, chars=chars,
                      spouse_back={}, rev=self._kin_rev_index())
        if not kin_key_is_blood(key):
            return ""
        return kin_text(key)

    def consort_of_line(self, cid):
        """Rank line for the character's own file when the subject took her but her file does not
        record the relation; a blood tie takes precedence over the consort rank.

        Needed because the concubinage pointer is stored on the other party's record, leaving the
        concubine's own file with no husband line. Returns a phrase naming the blood tie and the consort
        rank (no final period), or '' when undeterminable or when her own file already states the
        relation.
        """
        pid = self.cache.get("player_id")
        if pid is None or cid is None or int(cid) == int(pid):
            return ""
        pfam_raw = ((self.cache.get("characters") or {}).get(str(pid)) or {}).get("family") or {}
        # `merge_spouse_latch` mutates in place, so a copy must be passed: feeding the cache record
        # directly would write the latched spouse rows back into the cache and change what later
        # reads see within the same run.
        pfam = dict(pfam_raw)
        for _k in ("primary_spouse", "spouse", "concubine",
                   "former_spouses", "former_concubines"):
            if _k in pfam:
                pfam[_k] = list(pfam[_k] or [])
        pfam = self.merge_spouse_latch(pfam, self.as_of)
        kind = ""
        if cid in (pfam.get("primary_spouse") or []):
            kind = "妻"
        elif cid in (pfam.get("spouse") or []):
            kind = "妻"
        elif cid in (pfam.get("concubine") or []):
            # the rank word follows the subject's sex (same rule as the biography's concubine labels)
            kind = "男宠" if self._is_female(pid) else "妾"
        if not kind:
            return ""
        # skip when her own spouse/concubine rows already state it (read-only, also unlatched, or
        # this test would always be true)
        own = ((self.cache.get("characters") or {}).get(str(cid)) or {}).get("family") or {}
        for k in ("primary_spouse", "spouse", "concubine"):
            if pid in (own.get(k) or []):
                return ""
        who = self.kin_label(pid, self.as_of)
        if not who:
            return ""
        bk = self.blood_kin_word_for(cid, pid)
        if bk:
            return f"本为{who}之{bk}，入侍为其{kind}"
        return f"为{who}之{kind}"

    def _kin_rev_index(self):
        """Reverse sibling/child index, built lazily once for kin_key's two-way union."""
        if getattr(self, "_kin_rev", None) is None:
            self._kin_rev = kin_rev_index(self.cache.get("characters") or {})
        return self._kin_rev

    def _spouse_back_index(self):
        """Reverse spouse index {cid: [spouse ids…]}: the cache may record a spouse edge only on
        one side (about 0.65% of reverse edges are missing), so this is built once for `kin_word`'s
        two-way union."""
        if getattr(self, "_spouse_back_idx", None) is None:
            idx = {}
            for k, rec in (self.cache.get("characters") or {}).items():
                if not str(k).isdigit() or not isinstance(rec, dict):
                    continue
                fam = rec.get("family") or {}
                for f in ("primary_spouse", "spouse", "concubine"):
                    for x in (fam.get(f) or []):
                        if isinstance(x, int):
                            idx.setdefault(x, []).append(int(k))
            self._spouse_back_idx = idx
        return self._spouse_back_idx

    def spouses_now(self, cid):
        """Ids of cid's current spouses, reverse edges included and former spouses excluded."""
        fam = _fam_of(self.cache, cid)
        out = spouses_now_family(fam)
        out |= set(self._spouse_back_index().get(int(cid), []))
        return out

    def kin_attrib_label(self, cid, subject=None, date=None, style="brief",
                         scope=None, base=None):
        """Label plus a kinship attributive (single outlet).

        With scope=None the behavior is identical to `person_label`. With a scope, a person
        appearing for the first time in that block and having a determinable relation to
        scope.subject gets the relation prefixed to the label. `base` lets the caller pass an
        already computed label (such as a murder victim's dated label) instead of calling
        person_label.
        """
        if base is None:
            base = self.person_label(cid, date, style)
        if scope is None or not base:
            return base
        return scope.mark(cid, base, self, date=date)


    def _older_than(self, a, b):
        """True when a is older than b by birth date; None when either birth date is missing."""
        ra = (self.cache.get("characters") or {}).get(str(a)) or {}
        rb = (self.cache.get("characters") or {}).get(str(b)) or {}
        ba, bb = ra.get("birth"), rb.get("birth")
        if not ba or not bb:
            return None
        try:
            return cl.date_key(ba) < cl.date_key(bb)
        except Exception:
            return None

    # ---- subject chain (previous and next subject) ----

    def _chain_person(self, cid, date=None):
        """Name of one member of the subject chain, falling back to that member's own cache.

        A member with no real landed title prefers his cache's `player_name`, the game's own rendering
        (`meta_player_name`) and the authoritative record of a regnal rename; a member with real land
        uses the melt rebuild instead, because the cache envelope name may postdate his accession.
        """
        gname = self._chain_game_name(cid)
        if gname and self._chain_no_landed_dignity(cid, date):
            return gname
        nm = self.person_label(cid, date=None, style="brief")
        if not nm:
            other = self.campaign.get(int(cid)) if str(cid).isdigit() else None
            if isinstance(other, dict):
                rec = (other.get("characters") or {}).get(str(cid)) or {}
                nm = rec.get("name_full") or rec.get("name_zh") or ""
            if not nm:
                nm = self.name(cid, date=None)
        return nm or ""

    def _chain_game_name(self, cid):
        """The game's own rendered name of a chain member (his cache's `player_name`), else ''.

        The value looks like "<dignity>，<name>" or "<dignity><name>III"; commas are removed by
        `_clean_ck3_loc` and a trailing Roman numeral is converted by `_roman_ordinal_zh`.
        """
        if cid is None:
            return ""
        try:
            own = (self.campaign or {}).get(int(cid))
        except (TypeError, ValueError):
            own = None
        if not isinstance(own, dict):
            return ""
        pn = _clean_ck3_loc(str(own.get("player_name") or "")).strip()
        if not pn:
            return ""
        return _roman_ordinal_zh(pn)

    def _chain_no_landed_dignity(self, cid, date=None):
        """True when a chain member holds only a landless dignity (a cardinal title, `d_cd_*`), a
        case where the melt cannot rebuild his real identity.

        Deliberately narrow: it applies only when the primary title is a cardinal title. A member
        with no title at all is excluded, because the melt then gives a bare name and a bare name
        is right for the moment of accession.
        """
        if cid is None:
            return False
        try:
            _tier, tid = self._primary_title_at(cid, as_of=date)
        except Exception:
            return False
        return self._is_cardinal_title(tid)

    def reign_end_word(self, re_end):
        """Wording for how a reign ended (tonsured abdication, abdication, loss of all land, …)."""
        kind = str((re_end or {}).get("kind") or "unknown")
        W = _style.FACT_WORDING
        return W.get("reign_end_" + kind) or W.get("reign_end_unknown") or "让位"

    def reign_end_clause(self, cid, re_end):
        """Closing sentence for a subject whose reign ended without death, e.g. a tonsured
        abdication handing power to a successor.

        Source: `cache["reign_end"]`, derived by `pipeline._cross_check_reign_ends` from the save's
        `played_character.legacy` succession chain. Wording follows `kind` (tonsured, abdicated,
        landless, unknown). The successor's name goes through `_chain_person` and `_kin_word` with
        the same kinship words used for a predecessor. The returned sentence has no final period,
        which the caller adds.
        """
        re_end = re_end or {}
        kind = str(re_end.get("kind") or "unknown")
        W = _style.FACT_WORDING
        word = self.reign_end_word(re_end)
        date = self.date(re_end.get("date"))
        succ = re_end.get("successor")
        nm = ""
        if isinstance(succ, int):
            nm = self._chain_person(succ)
            kin = self._kin_word(cid, succ)
            if nm and kin:
                nm = f"{kin}{nm}"
        if date and nm:
            line = (W.get("reign_end_line_successor")
                    or "{date}，{word}，传位于{succ}。").format(
                        date=date, word=word, succ=nm)
        elif date:
            line = (W.get("reign_end_line") or "{date}，{word}").format(
                date=date, word=word)
        else:
            line = f"{word}，传位于{nm}" if nm else word
        return line.rstrip("。")

    def succession_lines(self):
        """Subject-chain facts: previous and next subject with the succession dates.

        Source: the save's `played_character.legacy` (stored per save as cache["played_legacy"]);
        kinship comes from this cache's graph and names from person_label. Returns the predecessor and
        successor lines; [] without a chain or when the subject is the only member.
        """
        cache = self.cache
        pid = cache.get("player_id")
        chain = [e for e in (cache.get("played_legacy") or [])
                 if isinstance(e, dict) and isinstance(e.get("cid"), int)]
        if pid is None or len(chain) < 2:
            return []
        idx = next((i for i, e in enumerate(chain) if e["cid"] == int(pid)), None)
        if idx is None:
            return []
        out = []
        if idx > 0:
            prev = chain[idx - 1]
            pcid = int(prev["cid"])
            start = chain[idx].get("date") or ""
            nm = self._chain_person(pcid)
            kin = self._kin_word(pid, pcid)
            pv = self.campaign.get(pcid)
            death = ""
            re_end = {}
            if isinstance(pv, dict):
                death = ((pv.get("player_death") or {}).get("date")) or ""
                re_end = pv.get("reign_end") or {}
            # no parentheticals: the relation and the predecessor title are comma-joined
            lead = f"{kin}、" if kin else ""
            # a predecessor whose reign ended without death (abdication) must not be called dead
            re_date = re_end.get("date") or ""

            def _death_fate(when):
                """Death phrase for the predecessor, including the specific cause when known.

                The cause is in the data (`death_clause` reads that subject's cache `death`), so a
                specific cause is written out; when it is missing or only the generic word, the
                chronicle-style "died on <date>" form is kept rather than inventing detail.
                """
                why = ""
                try:
                    why = self.death_clause(pcid, date=death) or ""
                except Exception:                                 # noqa: BLE001
                    why = ""
                if why and why != "去世":
                    return f"于{when}{why}"
                return f"崩于{when}"

            if re_date and start and cl.date_key(re_date) == cl.date_key(start):
                fate = "于是日让位"
            elif re_date:
                fate = f"让位于{self.date(re_date)}"
            elif death and start and cl.date_key(death) == cl.date_key(start):
                fate = _death_fate("当日")
            elif death:
                fate = _death_fate(self.date(death))
            else:
                fate = ""
            if nm and start:
                if fate:
                    out.append(f"承继：{self.date(start)}，{lead}前代传主{nm}{fate}，"
                               f"传主之位自此归本传主。")
                else:
                    out.append(f"承继：{self.date(start)}，本传主继{lead}"
                               f"前代传主{nm}之位。")
            elif nm:
                out.append(f"承继：本传主继{lead}前代传主{nm}之位。")
        if idx + 1 < len(chain):
            nxt = chain[idx + 1]
            ncid = int(nxt["cid"])
            start = nxt.get("date") or ""
            nm = self._chain_person(ncid)
            kin = self._kin_word(pid, ncid)
            if nm:
                body = f"{kin}{nm}继为传主。" if kin else f"传主之位归于{nm}。"
                out.append(f"后任：{self.date(start)}，{body}" if start
                           else f"后任：其后{body}")
        return out

    def protagonist_era(self):
        """Start of the subject's reign -> (era_start, has_predecessor).

        era_start is his entry's date in `cache["played_legacy"]` (as in `succession_lines`), falling
        back to the cache's first source. Needed for the timeline gate: a successor's save still holds
        the previous reign's memories, which would otherwise pass the related-ids test.
        """
        cache = self.cache
        pid = cache.get("player_id")
        srcs = [str(s) for s in (cache.get("sources") or []) if s]
        start = srcs[0] if srcs else ""
        has_prev = False
        if pid is None:
            return start, has_prev
        chain = [e for e in (cache.get("played_legacy") or [])
                 if isinstance(e, dict) and isinstance(e.get("cid"), int)]
        idx = next((i for i, e in enumerate(chain) if e["cid"] == int(pid)), None)
        if idx is None:
            return start, has_prev
        return (chain[idx].get("date") or start), idx > 0

    # ---- co-ruler address forms ----

    def _co_ruler_hit(self, cid, date=None):
        """Diarchy record (type co_*) making this character a co-ruler on date, or None."""
        if cid is None:
            return None
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return None
        dk = cl.date_key(date) if date else None
        hit = None
        for e in self._diarchies:
            if e["diarch"] != cid:
                continue
            # a diarchy record stores only start_date (the save has no end), so as_of is the limit
            if dk is not None and e["start"] and cl.date_key(e["start"]) > dk:
                continue
            if e["start"] and (hit is None
                               or cl.date_key(e["start"]) > cl.date_key(hit["start"])):
                hit = e
        return hit

    # co-ruler type -> court-position localization key (the game's <diarchy_type>_diarch_title)
    _CO_RULER_TITLE_KEYS = {
        "co_emperorship": "co_emperorship_diarch_title",
        "co_monarchy": "co_monarchy_diarch_title",
        "junior_emperorship": "junior_emperorship_diarch_title",
        "grand_secretariat": "grand_secretariat_diarch_title",
    }

    def co_ruler_title_word(self, cid, date=None):
        """Court-position name of the co-ruler (the game's `<type>_diarch_title`), else ''."""
        hit = self._co_ruler_hit(cid, date)
        if not hit:
            return ""
        key = self._CO_RULER_TITLE_KEYS.get(hit["type"])
        if not key:
            return ""
        v = L.loc(self.table, key) or ""
        if not v or v.startswith("$") or v.startswith("["):
            return ""
        return v

    def co_ruler_word(self, cid, date=None):
        """Ruler address form of the co-ruler, exactly as the game renders it: the co- prefix plus
        the liege's ruler address word.

        The game's `co_ruler_male`/`co_ruler_female` culture_titles rule is
        "co-" + <the liege title's ruler address>, so the liege's word is used verbatim and the
        court-position name is the fallback when that is unavailable. Both conditions of the game
        must hold: a co_* diarchy record and the character variable `use_co_ruler_title`. A decade
        biography passes date=as_of, and '' is returned before the co-rule starts.
        """
        hit = self._co_ruler_hit(cid, date)
        if not hit:
            return ""
        try:
            if int(cid) not in self._co_ruler_flag:
                return ""
        except (TypeError, ValueError):
            return ""
        liege = hit["liege"]
        base = ""
        t, tid = self._primary_title_at(liege, as_of=date)
        if tid is not None and t is not None:
            _indep = self._is_independent(liege, date)
            base = self._office_word(
                t, self._gov_for_word(liege, tid, date),
                independent=bool(_indep) if _indep is not None else True,
                female=self._is_female(liege), tid=tid, cid=liege, date=date)
        if not base:
            return self.co_ruler_title_word(cid, date)
        return "共治" + base

    def co_ruler_note(self, cid, date=None):
        """Identity sentence of a co-ruler: the co-ruler address form plus the liege's label, so
        both "he is a co-ruler" and "whose co-ruler" are stated once. '' for non-co-rulers."""
        w = self.co_ruler_word(cid, date)
        if not w:
            return ""
        hit = self._co_ruler_hit(cid, date)
        liege = hit["liege"] if hit else None
        ln = self.person_label(liege, date, "brief") if liege is not None else ""
        return f"{w}，君主{ln}。" if ln else f"{w}。"

    def _span_mid(self, start, end):
        """Midpoint date of an interval, used for stable phase naming."""
        if start and end:
            try:
                sy = [int(x) for x in str(start).split(".")[:3]]
                ey = [int(x) for x in str(end).split(".")[:3]]
                if len(sy) == 3 and len(ey) == 3:
                    return ".".join(str((a + b) // 2) for a, b in zip(sy, ey))
            except Exception:
                pass
        return start

    def _ruler_word_at(self, cid, tid, date):
        """Ruler address word for a land phase, chosen by (culture family x tier x government x
        independence x sex); same source as official_title.

        The government comes from `_gov_for_word` (title government, then the character's, then
        his dead_data government), so even on the day he lost the title the word is his own.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        tier = ""
        for pfx, tv in L.TIER_KEY_OF_PREFIX.items():
            if key.startswith(pfx):
                tier = tv
                break
        if not tier:
            return ""
        gov = self._gov_for_word(cid, tid, date)
        female = self._is_female(cid)
        indep = self._is_independent(cid, date)
        if indep is None:
            indep = False
        return self._office_word(tier, gov, independent=bool(indep),
                                 female=female, tid=tid, cid=cid, date=date)

    def _camp_purpose_at(self, cid, date=None):
        """Camp purpose of the character at a date (`camp_purpose_brigands` -> 'brigands').

        A current camp (cache landed government = landless) reads the current laws; earlier phases
        read the dated `cache.camp_purposes` history. '' when unknown.
        """
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        ld = rec.get("landed") or {}
        if ld.get("government") == "landless_adventurer_government":
            for law in ld.get("laws") or []:
                if str(law).startswith("camp_purpose_"):
                    return str(law).split("_", 2)[2]
        hist = self.cache.get("camp_purposes") or []
        if not hist:
            return ""
        dk = cl.date_key(date) if date else None
        purpose = None
        for h in hist:
            if not h.get("date"):
                continue
            if dk is None or cl.date_key(h["date"]) <= dk:
                purpose = h.get("purpose")
        if purpose is None:
            purpose = (hist[0] or {}).get("purpose")
        return purpose or ""

    def _camp_holder_word(self, cid, date=None):
        """Camp holder word from the game key `<duke|duchess>_landless_adventurer_camp_<purpose>`
        (brigands = chief, explorers = leader, mercenaries = captain…); '' when unavailable."""
        purpose = self._camp_purpose_at(cid, date)
        if not purpose:
            return ""
        female = self._is_female(cid)
        key = f"{'duchess' if female else 'duke'}_landless_adventurer_camp_{purpose}"
        v = L.loc(self.table, key)
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        return ""

    def _camp_holder_word_default(self, female=False):
        """Holder word when the camp purpose is unknown, from the game key
        `duke_landless_adventurer_{male|female}_camp`."""
        for k in (f"duke_landless_adventurer_{'female' if female else 'male'}_camp",
                  "duke_landless_adventurer_male_camp"):
            v = L.loc(self.table, k)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        return ""

    def _camp_tier_word(self, tid):
        """Tier word of a landless adventurer camp, from the game key
        `<tier>_landless_adventurer_camp`. Camp titles never take a landed tier word; '' when the
        key is missing.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        tier = ""
        for pfx, tv in L.TIER_KEY_OF_PREFIX.items():
            if key.startswith(pfx):
                tier = tv
                break
        if not tier:
            return ""
        v = L.loc(self.table, f"{tier}_landless_adventurer_camp")
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        return ""

    def title_by_key(self, key):
        if not key:
            return None
        return self._title_by_key.get(key)

    # ---- office names / prince titles ----

    _TIER_KEY = {"hegemon": "hegemon", "empire": "emperor", "kingdom": "king",
                 "duchy": "duke", "county": "count", "barony": "baron"}
    _TIER_RANK = {"h_": 6, "e_": 5, "k_": 4, "d_": 3, "c_": 2, "b_": 1}
    _RANK_TIER = {6: "hegemon", 5: "empire", 4: "kingdom", 3: "duchy",
                  2: "county", 1: "barony"}
    _CELESTIAL_LIKE_GOVS = {"celestial_government", "meritocratic_government",
                            "steppe_admin_government", "administrative_government"}
    # Office words for the Japanese ritsuryo government (japan_administrative_government), keyed by
    # the game's localization keys: the holder of e_japan is the regent, not an emperor, and the
    # throne is separate. This table applies only to ritsuryo; the soryo government has its own
    # `_JAPAN_SORYO_KEYS`.
    _JAPAN_OFFICE_KEYS = {
        "empire":  "emperor_administrative_male_japanese",   # regent
        "kingdom": "king_administrative_male_japanese",      # marshal
        "duchy":   "duke_administrative_male_japanese",      # provincial governor
        "county":  "count_administrative_male_japanese",     # provincial governor
        "barony":  "baron_administrative_male_japanese",     # district governor
    }
    # Fallback keys for the soryo government (japan_feudal_government), words taken from
    # dlc_tgp_cultural_titles_l_simp_chinese.yml; the male key is the house-head word.
    _JAPAN_SORYO_KEYS = {
        "county":  ("count_feudal_male_japanese", "count_feudal_female_japanese"),
        "duchy":   ("duke_feudal_male_japanese", "duke_feudal_female_japanese"),
        "kingdom": ("king_feudal_male_japanese", "king_feudal_female_japanese"),
    }
    _TENNO_TITLE_KEYS = {"k_chrysanthemum_throne"}  # holders of the throne title are the emperor
    # Office words for the Japanese top titles follow the government value, never the era: a CK3 run
    # is not history, so ritsuryo may be overthrown, restored, or never give way to a shogunate at
    # all. Same flavorization group as the game:
    #   japan_administrative_government -> e_japan: emperor_administrative_male_japanese (regent)
    #   japan_feudal_government -> e_japan: emperor_shogun_male_japanese, which the game gates on
    #     flag = shogun_flag; without that flag a feudal holder is the chancellor. Caches and melts
    #     store no character flags, so the feudal case uniformly uses the shogun word.
    #   k_chrysanthemum_throne -> king_tenno_male_japanese (emperor, government-independent)
    # Government order (see `_title_government` / `_gov_for_word`): the holder's dated history, then
    # the title's own history_government, then a generic word.
    _JAPAN_TOP_OFFICE_KEYS = {
        ("e_japan", "japan_administrative_government"): "emperor_administrative_male_japanese",
        ("e_japan", "japan_feudal_government"): "emperor_shogun_male_japanese",
        ("k_chrysanthemum_throne", "japan_administrative_government"): "king_tenno_male_japanese",
        ("k_chrysanthemum_throne", "japan_feudal_government"): "king_tenno_male_japanese",
    }
    # Office wording for the Japanese top titles uses a direct table of bare words, because the
    # flavorization chain cannot supply them: flag-gated entries (shogun, retired emperor) are marked
    # unsupported by the parser; `_dead_flavor_consistent` compares a key's middle as a government
    # prefix, so `shogun`/`joko` never equal `feudal`/`administrative` and the game's own baked word
    # is rejected; and flavorization.resolve's top_liege default lets the liege's government override
    # the holder's.
    # Table 1: baked flavor key -> bare word (the only reliable source for retired emperor and
    # shogun, because the key carries the flag information). Trusted only inside the death window,
    # since the key is baked from the state at death.
    _JAPAN_OFFICE_FROM_FLAVOR = {
        "emperor_shogun_male_japanese": "幕府将军",
        "emperor_shogun_female_japanese": "幕府将军",
        "emperor_shogun_male_japanese_feudal": "幕府将军",
        "emperor_shogun_female_japanese_feudal": "幕府将军",
        "emperor_joko_male_japanese": "上皇",
        "emperor_joko_female_japanese": "上皇",
        "emperor_administrative_male_japanese": "关白",
        "emperor_administrative_female_japanese": "关白",
        "emperor_daijo_daijin_male_japanese_feudal": "太政大臣",
        "emperor_daijo_daijin_female_japanese_feudal": "太政大臣",
        "emperor_tenno_male_japanese": "天皇",
        "emperor_tenno_female_japanese": "天皇",
        "emperor_tenno_male_japanese_flag": "天皇",
        "emperor_tenno_female_japanese_flag": "天皇",
        "king_tenno_male_japanese": "天皇",
        "king_tenno_female_japanese": "天皇",
    }
    # Table 2: (title key, government) -> bare word, used when there is no baked key (living
    # characters, early saves). A feudal title carrying `shogun_flag` gets the shogun word instead
    # (see `japan_top_office`).
    _JAPAN_TOP_OFFICE_WORD = {
        ("e_japan", "japan_administrative_government"): "关白",
        ("e_japan", "japan_feudal_government"): "太政大臣",
        ("k_chrysanthemum_throne", "japan_administrative_government"): "天皇",
        ("k_chrysanthemum_throne", "japan_feudal_government"): "天皇",
    }
    _JAPAN_OFFICE_SHOGUN = "幕府将军"
    _JAPAN_OFFICE_JOKO = "上皇"
    _SHOGUN_FLAG = "shogun_flag"
    # The Japanese top titles are the throne (k_chrysanthemum_throne) and e_japan. Neither name is
    # ever used as a prince/princess prefix: the game's prince word applies only to a living
    # emperor's children with special = ruler_child and the throne title, and e_japan's holder is a
    # regent or shogun whose children have no prince word at all. Japanese imperial titles come only
    # from _tenno_prince_word.
    _JAPAN_TOP_TITLE_KEYS = {"k_chrysanthemum_throne", "e_japan"}
    # An empty throne (landless = yes + figurehead = yes in the game, e.g. k_chrysanthemum_throne and
    # k_yongson_throne) has a position name, not a place name, so appending a tier word would produce
    # the game's mechanical string. Such titles therefore use the office word only (emperor / king).
    # The direct table has the same source as `_JAPAN_TOP_OFFICE_KEYS`; a throne has no government
    # distinction.
    _THRONE_TITLE_KEYS = {"k_chrysanthemum_throne", "k_yongson_throne"}
    _THRONE_OFFICE_KEYS = {
        "k_chrysanthemum_throne": "king_tenno_male_japanese",       # emperor
        "k_yongson_throne": "king_yongson_throne_male_korean",      # king
    }
    # Japanese imperial clan membership: the boundary between imperial and subject status is demotion
    # from the clan (being granted the Minamoto/Taira surname), not whether the father still reigns.
    # The game models this with `tgp_japan_imperial_branch_decision`
    # (game/common/decisions/dlc_decisions/tgp/tgp_japan_decisions.txt), which moves a character from
    # the imperial clan to Minamoto or Taira.
    _IMPERIAL_DYNASTY_KEYS = {"japanese_yamato"}
    _IMPERIAL_DYNASTY_NAMES = {"大和"}   # Simplified-Chinese name of dynn_Yamato in this project's table

    def _imperial_clan_state(self, cid):
        """Imperial clan status: 'imperial' (in the clan), 'subject' (demoted) or '' (unknown).

        Resolution order: the unified `dynasty_name` field in the cache (dated per save, so
        Minamoto/Taira/Fujiwara/Yamato are directly readable), then the dynasty key in the melt
        (`dynasties.dynasties[<id>].key` == japanese_yamato). '' makes the caller withhold the prince
        word rather than invent an imperial title.
        """
        nm = self.dynasty_name(cid) or ""
        if nm:
            return "imperial" if nm in self._IMPERIAL_DYNASTY_NAMES else "subject"
        did = self._dynasty_of_cid(cid)
        if did is None:
            return ""
        key = (((self.melt.get("dynasties") or {}).get("dynasties") or {})
               .get(str(did)) or {}).get("key") or ""
        if not key:
            return ""
        return "imperial" if key in self._IMPERIAL_DYNASTY_KEYS else "subject"

    def _ever_held_throne(self, cid, date=None):
        """True when the parent ever held the throne (abdicated or dead included): prince status is
        for life, so holding it at any point counts.
        """
        for tid, ivs in (self._hold_intervals(cid, date) or {}).items():
            if ((self._lt.get(str(tid)) or {}).get("key") or "") not in self._TENNO_TITLE_KEYS:
                continue
            for (g, _l, _lt) in ivs:
                if g:
                    return True
        return False

    def title_base_name(self, tid):
        """Base name of a title without tier or office word: dynamic name, custom, name, loc, key."""
        if tid is None:
            return ""
        specific = self._specific_name(tid)
        if specific:
            return specific
        t = self._lt.get(str(tid)) or {}
        tnd = t.get("title_name_data") or {}
        name = (tnd.get("custom") or "").strip() or (tnd.get("name") or "").strip()
        if not name:
            name = L.loc(self.table, t.get("key") or "")
        if not name:
            name = t.get("key") or ""
        return name

    def _primary_title(self, cid):
        """Primary title (tier, tid): the highest rank, and among equals the first in the domain
        list. (None, None) without a title."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        dom = (rec.get("landed") or {}).get("domain") or []
        if not dom:
            c = self._chars.get(str(cid)) or {}
            dom = (c.get("landed_data") or {}).get("domain") or []
        best_tid, best_rank = None, -1
        for tid in dom:
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            rank = self._TIER_RANK.get(key[:2], 0)
            if rank > 0 and rank > best_rank:
                best_tid, best_rank = tid, rank
        if best_tid is None:
            return None, None
        return self._RANK_TIER[best_rank], best_tid

    def _vassal_history(self, cid):
        """Per-save vassal history of the character, merged by date from this cache and the
        campaign's other subject caches.

        Each cache starts only at its own subject's accession, so an earlier vassal contract may
        exist only in another cache; the date merge is required because this cache may already hold
        an "independent" entry. Same-date entries prefer this cache. Entries are
        {date, liege, flags}, with liege None meaning not a vassal that day.
        """
        if cid is None:
            return []
        by_date = {}
        for src in list((self.campaign or {}).values()) + [self.cache]:
            if not isinstance(src, dict):
                continue
            for h in (src.get("char_vassal_history") or {}).get(str(cid)) or []:
                d = h.get("date")
                if d:
                    by_date[str(d)] = h
        return [by_date[k] for k in sorted(by_date, key=lambda x: cl.date_key(x))]

    def _vassal_entry_at(self, cid, date=None):
        """Vassal history entry at date; None without history or before its first point."""
        hist = self._vassal_history(cid)
        if not hist:
            return None
        if not date:
            return hist[-1]
        dk = cl.date_key(date)
        hit = None
        for h in hist:
            if h.get("date") and cl.date_key(h["date"]) <= dk:
                hit = h
            else:
                break
        return hit

    def _obligation_flags_at(self, cid, date=None):
        """Vassal contract obligation flags (celestial_province_*) at date; [] when independent or
        without history.

        For an ennoblement mid-year the next save's flags are used when it already shows vassalage,
        matching `_is_independent`'s lookahead.
        """
        ent = self._vassal_entry_at(cid, date)
        if (not ent or ent.get("liege") is None) and date:
            hist = self._vassal_history(cid)
            dk = cl.date_key(date)
            for h in hist:
                if h.get("date") and cl.date_key(h["date"]) > dk and h.get("liege") is not None:
                    if 0 < (_date_ord(h["date"]) - _date_ord(date)) <= 400:
                        return list(h.get("flags") or [])
                    break
        if not ent or ent.get("liege") is None:
            return []
        return list(ent.get("flags") or [])

    def _is_independent(self, cid, date=None):
        """Independence (not someone's vassal): with a date, from char_vassal_history; a date before
        the history starts returns None so the caller uses a generic word; without history the final
        save's vassal id set decides.
        """
        if cid is None:
            return True
        key = (int(cid), str(date or ""))
        if key in self._indep_cache:
            return self._indep_cache[key]
        hist = self._vassal_history(cid)
        v = None
        if hist and date:
            dk = cl.date_key(date)
            ent = self._vassal_entry_at(cid, date)
            nxt = None
            for h in hist:
                if h.get("date") and cl.date_key(h["date"]) > dk:
                    nxt = h
                    break
            # Ennobled mid-year: this save has no contract yet but the next one (within about a year)
            # shows vassalage, so the vassal word is used for that day.
            nxt_gap = (_date_ord(nxt.get("date")) - _date_ord(date)) if nxt else None
            if (ent is None or ent.get("liege") is None) \
                    and nxt is not None and nxt.get("liege") is not None \
                    and nxt_gap is not None and 0 < nxt_gap <= 400:
                v = False
            elif hist[0].get("date") and cl.date_key(hist[0]["date"]) > dk \
                    and ent is None:
                v = None
            else:
                v = True if (ent is None or ent.get("liege") is None) else False
        elif hist and not date:
            v = hist[-1].get("liege") is None
        else:
            v = int(cid) not in self._vassal_ids
        self._indep_cache[key] = v
        return v

    def _is_female(self, cid):
        """Sex: the cache's persisted `female` flag wins (it survives melt pruning), with the melt's
        character index as fallback for older caches. False for an invalid cid."""
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return False
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        v = rec.get("female")
        if v is not None:
            return bool(v)
        return bool((self._chars.get(str(cid)) or {}).get("female"))

    def is_spouse_pair(self, a, b):
        """True when a and b are spouses: b belongs to a's spouse set, former spouses and concubines
        included.

        The cache's accumulated `family.ever_spouses` (a cross-snapshot union that survives divorce
        or widowhood) wins; older caches fall back to the current family spouse keys. False for an
        invalid id.
        """
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return False
        if a == b:
            return False
        rec = (self.cache.get("characters") or {}).get(str(a)) or {}
        fam = rec.get("family") or {}
        ids = fam.get("ever_spouses")
        if not ids:
            ids = []
            for k in ("primary_spouse", "spouse", "former_spouses",
                      "concubine", "former_concubines"):
                ids += [x for x in (fam.get(k) or []) if isinstance(x, int)]
        return b in {int(x) for x in ids if isinstance(x, int)}

    def kin_word_gendered(self, subject, other, kind):
        """Gendered form of a spouse/consort kinship word, chosen by the subject's sex. kind is
        `spouse`, `former`, `concubine` or `f_concubine`, each with a male and a female form.

        When the sex cannot be determined (no `female` flag in the cache and no such character in the
        melt) a neutral word is used rather than guessing. The word forms live only here and are
        shared by the assassin-line helpers, so one person is never described two ways.
        """
        # sex undeterminable -> neutral word, reached only without a cache flag or melt record
        rec = (self.cache.get("characters") or {}).get(str(subject)) or {}
        v = rec.get("female")
        if v is None:
            v = (self._chars.get(str(subject)) or {}).get("female")
        if v is None:
            return "配偶" if kind in ("spouse", "former") else "情偶"
        fem = bool(v)
        if kind == "concubine":
            return "男宠" if fem else "妾"
        if kind == "f_concubine":
            return "前男宠" if fem else "前妾"
        if kind == "former":
            return "前夫" if fem else "前妻"
        return "夫" if fem else "妻"

    def _consort_word(self, owner, other):
        """Consort term of other relative to owner: wife, husband, concubine or lover.

        Needed because a stillbirth sentence must not call a concubine or a lover a wife. The cache's
        kinship sets decide: the concubine set first, then the spouse pair (via `is_spouse_pair`,
        which includes ever_spouses), otherwise lover. A female owner gets the husband word.
        """
        try:
            owner, other = int(owner), int(other)
        except (TypeError, ValueError):
            return ""
        fem = self._is_female(owner)
        rec = (self.cache.get("characters") or {}).get(str(owner)) or {}
        fam = rec.get("family") or {}
        conc = set()
        for k in ("concubine", "former_concubines"):
            conc |= {int(x) for x in (fam.get(k) or []) if isinstance(x, int)}
        if other in conc:
            return "夫" if fem else "妾"
        if self.is_spouse_pair(owner, other):
            return "夫" if fem else "妻"
        return "情人"

    # ---- marriage line: standard vs matrilineal (uxorilocal) ----

    def _common_children(self, a, b, after=None, before=None):
        """Ids of the children a and b have in common (the intersection of their child sets),
        filterable by a birth-date interval.

        `after` should be the wedding date: a child born before the marriage takes the mother's house
        and says nothing about the marriage line, so counting it would misread a marriage to a queen
        with an illegitimate child as matrilineal.
        """
        out = set()
        chars = self.cache.get("characters") or {}
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return out
        ka = {int(x) for x in (((chars.get(str(a)) or {}).get("family") or {})
                               .get("child") or []) if isinstance(x, int)}
        kb = {int(x) for x in (((chars.get(str(b)) or {}).get("family") or {})
                               .get("child") or []) if isinstance(x, int)}
        out = ka & kb
        if after or before:
            lo = cl.date_key(after) if after else None
            hi = cl.date_key(before) if before else None
            keep = set()
            for k in out:
                birth = cl.date_key((chars.get(str(k)) or {}).get("birth")
                                    or "0.0.0")
                if lo and birth <= lo:
                    continue
                if hi and birth > hi:
                    continue
                keep.add(k)
            out = keep
        return out

    def wedding_date(self, a, b):
        """Wedding date of a and b from a `married` memory in either cache record, else ''."""
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return ""
        chars = self.cache.get("characters") or {}
        for owner, other in ((a, b), (b, a)):
            for mem in ((chars.get(str(owner)) or {}).get("memories") or []):
                if str(mem.get("type") or "") != "married":
                    continue
                parts = mem.get("participants") or {}
                if parts.get("spouse") != other:
                    continue
                d = str(mem.get("creation_date") or "")
                if d:
                    return d
        return ""

    def _spouses_asof(self, cid, ids):
        """Trim a spouse id list to this biography's as_of.

        `family.primary_spouse` is the final save's state, so a decade biography would otherwise list
        a daughter's future husband. Spouses whose wedding date is unknown are kept.
        """
        ids = list(ids)
        if not self.as_of:
            return ids
        ao = cl.date_key(self.as_of)
        out = []
        for s in ids:
            wd = self.wedding_date(cid, s)
            if wd and cl.date_key(wd) > ao:
                continue
            out.append(s)
        return out

    # ---- end of a marriage: a decade biography lists only spouses still married in its window ----
    #
    # Every source records a marriage start but not its end: the cache's `family` is a per-save
    # union, the spouse latch keeps only `since`, and trimming tested only "wedding date <= as_of".
    # The only reliable dated end is a divorce line in the house-relations flow (day precision) while
    # death leaves no such line, though the death date is itself the end. Two traps: the engine also
    # writes a divorce line when a spouse dies, so a date equal to either death date is void; and
    # `family_data.former_spouses` unions divorce with widowhood without dates or types. Memories
    # carry no divorce entries at all.

    def _house_pair_flows(self):
        """Index of the house-relations flow by character pair: {frozenset({a,b}): [(date, raw), …]}.

        Source: the `change_reason` of `melt["house_relations"]["database"][*]["history"][*]`, a
        game-rendered whole sentence (marriage or divorce); the two ids are extracted with
        `_FEUD_CHAR_RE`. Scanned lazily once. Entries whose sentences cannot be parsed (no ids) are
        skipped, and the death date covers those cases.
        """
        cached = getattr(self, "_pair_flows_idx", None)
        if cached is not None:
            return cached
        idx = {}
        db = (self.melt.get("house_relations") or {}).get("database") or {}
        for r in db.values():
            if not isinstance(r, dict):
                continue
            for e in (r.get("history") or []):
                if not isinstance(e, dict):
                    continue
                raw = str(e.get("change_reason") or "")
                if "离婚" not in raw and "结婚" not in raw:
                    continue
                ids = [int(x) for x in _FEUD_CHAR_RE.findall(raw)]
                if len(ids) < 2 or ids[0] == ids[1]:
                    continue
                idx.setdefault(frozenset((ids[0], ids[1])), []).append(
                    (str(e.get("date") or ""), raw))
        self._pair_flows_idx = idx
        return idx

    def _char_death_date(self, cid):
        """Death date of the character: cache `characters[].death`, `player_death` for the subject,
        then `dead_data.date` from the three melt buckets.

        The melt fallback matters for the death-day divorce test, because one end of a divorce line is
        often absent from this subject's cache. An unknown date returns '' rather than a guess;
        results are memoized per id.
        """
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return ""
        memo = getattr(self, "_death_date_memo", None)
        if memo is None:
            memo = self._death_date_memo = {}
        if cid in memo:
            return memo[cid]
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        d = (rec.get("death") or {}).get("date")
        if not d and cid == self.cache.get("player_id"):
            d = (self.cache.get("player_death") or {}).get("date")
        if not d:
            for bucket in ((self.melt.get("living") or {}),
                           (self.melt.get("dead_unprunable") or {}),
                           ((self.melt.get("characters") or {}).get(
                               "dead_prunable") or {})):
                c = bucket.get(str(cid))
                if isinstance(c, dict):
                    dd = c.get("dead_data") or {}
                    if dd.get("date"):
                        d = dd.get("date")
                        break
        memo[cid] = str(d or "")
        return memo[cid]

    def is_widow_divorce(self, raw, date):
        """True when a house-relations divorce line is actually the engine's death-day divorce.

        The engine writes a divorce line on the day a spouse dies, so a line dated on either end's
        death date is not a divorce and must not be used on any display surface: the spouse list drops
        it through `spouse_end`'s death guard, and the feud and enemy sections drop it before
        rendering.
        """
        s = str(raw or "")
        if "离婚" not in s or not date:
            return False
        for _i in _FEUD_CHAR_RE.findall(s):
            try:
                cid = int(_i)
            except (TypeError, ValueError):
                continue
            d = self._char_death_date(cid)
            if d and cl.date_key(d) == cl.date_key(date):
                return True
        return False

    def spouse_end(self, pid, other):
        """End of the marriage between the subject and one spouse -> (date, kind, source, precision).

        kind is one of divorce, widowed (the spouse died) and player_end (the subject died or gave up
        the throne). The earliest of the divorce line, the spouse's death date and the subject's end
        date wins, with divorce preferred on the same day. All three missing returns empty strings, so
        the caller keeps an open interval. Divorce lines pass the death-day guard first.
        """
        try:
            pid, other = int(pid), int(other)
        except (TypeError, ValueError):
            return "", "", "", ""
        d_other = self._char_death_date(other)
        d_self = self._char_death_date(pid) or (self.cache.get("reign_end") or {}).get("date") or ""
        cands = []
        for date, raw in self._house_pair_flows().get(frozenset((pid, other)), []):
            if not date or "离婚" not in raw:
                continue
            if self.is_widow_divorce(raw, date):
                continue                       # trap: the engine also writes a divorce line for widowhood
            cands.append((cl.date_key(date), date, "divorce", "house_relations", "day"))
        # a `married` memory gives only a start date, so it cannot supply an end
        if d_other:
            cands.append((cl.date_key(d_other), d_other, "widowed", "death", "day"))
        if d_self:
            cands.append((cl.date_key(d_self), d_self, "player_end", "player_death", "day"))
        if not cands:
            return "", "", "", ""
        # divorce wins on the same day; the kind index keeps the sort stable across equal dates
        _ord = {"divorce": 0, "widowed": 1, "player_end": 2}
        cands.sort(key=lambda c: (c[0], _ord.get(c[2], 9)))
        _k, date, kind, src, prec = cands[0]
        return date, kind, src, prec

    def _bio_window_start(self):
        """Start of this biography's narrative window: for a decade biography, the previous decade's
        cutoff; otherwise the campaign start, which makes final and living biographies a no-op."""
        srcs = self.cache.get("sources") or []
        if not self.decade:
            return str(srcs[0]) if srcs else ""
        try:
            n = int(self.decade)
        except (TypeError, ValueError):
            return str(srcs[0]) if srcs else ""
        if n <= 1:
            return str(srcs[0]) if srcs else ""
        return self._decade_cutoff(n - 1) or (str(srcs[0]) if srcs else "")

    def spouse_active_in_window(self, other, win_start=None):
        """True when this spouse was still married to the subject inside this biography's window.

        The window is the half-open interval (win_start, as_of] and the marriage is [start, end): the
        start prefers `wedding_date` (an exact `married` memory) and falls back to the latched
        `since`; the end comes from `spouse_end` and is open when unknown. A spouse is kept when the
        start is at or before as_of and the end is missing or after win_start.
        """
        try:
            other = int(other)
        except (TypeError, ValueError):
            return True
        y0 = win_start if win_start is not None else self._bio_window_start()
        y1 = self.as_of or self.cache.get("last_date") or ""
        start = self.wedding_date(self.cache.get("player_id"), other)
        if not start:
            for r in self.spouse_latch_rows(self.as_of):
                if r.get("other") == other:
                    start = r.get("first_seen") or ""
                    break
        if start and y1 and cl.date_key(start) > cl.date_key(y1):
            return False                       # married after the window end
        end = self.spouse_end(self.cache.get("player_id"), other)[0]
        if end and y0 and cl.date_key(end) <= cl.date_key(y0):
            return False                       # already ended before the window starts
        return True

    def spouses_in_window(self, ids, win_start=None):
        """Filter a spouse id list to those still married inside this biography's window, keeping order."""
        if not ids:
            return []
        if win_start is None:
            win_start = self._bio_window_start()
        return [x for x in ids if self.spouse_active_in_window(x, win_start)]

    def _matrilineal_pairs_live(self):
        """Matrilineal pairs from the current melt's `relations.active_relations`, indexed lazily.

        The melt is the most complete source for marriages still in force, while the cache's
        `matrilineal_pairs` is per-save latched history that also covers marriages since ended.
        """
        memo = getattr(self, "_matri_live", None)
        if memo is None:
            memo = set()
            for e in (self.melt or {}).get("relations", {}).get(
                    "active_relations") or []:
                if not isinstance(e, dict) or "matrilineal" not in e:
                    continue
                a, b = e.get("first"), e.get("second")
                if isinstance(a, int) and isinstance(b, int) and a != b:
                    memo.add(cl.matrilineal_pair_key(a, b))
            self._matri_live = memo
        return memo

    def is_matrilineal(self, a, b, after=None, before=None):
        """True/False/None for whether the marriage is matrilineal, per the game rule that its children
        belong to the mother's house.

        Tests: the matrilineal flag in the melt's `relations.active_relations`; the same flag latched
        per save in `matrilineal_pairs` (the save entry disappears on divorce or widowhood); failing
        that, the houses of children born after the wedding. None when undeterminable.
        """
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return None
        if a == b:
            return None
        key = cl.matrilineal_pair_key(a, b)
        if key in self._matrilineal_pairs_live() \
                or key in (self.cache.get("matrilineal_pairs") or {}):
            return True
        kids = self._common_children(a, b, after=after, before=before)
        if not kids:
            return None
        ha, hb = self._house_of_cid(a), self._house_of_cid(b)
        if ha is None or hb is None or ha == hb:
            return None
        mom, dad = (a, b) if self._is_female(a) else (b, a)
        hm, hd = self._house_of_cid(mom), self._house_of_cid(dad)
        if hm is None or hd is None or hm == hd:
            return None
        n_mom = n_dad = n_other = 0
        for k in kids:
            hk = self._house_of_cid(k)
            if hk == hm:
                n_mom += 1
            elif hk == hd:
                n_dad += 1
            else:
                n_other += 1
        if n_mom and not n_dad and not n_other:
            return True
        if n_dad and not n_mom and not n_other:
            return False
        return None

    def marriage_lineality_note(self, a, b, wedding=None, before=None):
        """Lineage note for a verbless spouse list: the shortest matrilineal marker.

        Only the exceptional case is marked, matching the game UI's warning, which appears for
        matrilineal marriages alone; standard and undeterminable marriages return ''. Sentences with
        a verb use `marriage_verb` instead.

        `wedding` is the wedding date (looked up from `wedding_date` when omitted) and `before` is
        this biography's as_of, so children not yet born are not counted.
        """
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return ""
        if not wedding:
            wedding = self.wedding_date(a, b)
        if not self.is_matrilineal(a, b, after=wedding or None, before=before):
            return ""
        return "，入赘"

    def marriage_verb(self, a, b, wedding=None, before=None):
        """Verb of a wedding sentence: the matrilineal form for a matrilineal marriage and the plain
        wedding verb otherwise, with no separate lineage clause.

        Same test as `marriage_lineality_note`: only the matrilineal case differs, and an
        undeterminable marriage uses the standard verb.
        """
        try:
            a, b = int(a), int(b)
        except (TypeError, ValueError):
            return "成婚"
        if not wedding:
            wedding = self.wedding_date(a, b)
        if self.is_matrilineal(a, b, after=wedding or None, before=before):
            return "结入赘婚"
        return "成婚"

    def _office_word(self, tier, government, independent=False, female=False, tid=None,
                     cid=None, date=None):
        """Office word for (tier, government).

        The celestial, administrative and steppe-administrative governments share one set of words
        regardless of culture, and an independent celestial ruler uses an independent word rather than
        a vassal office word. The Japanese ritsuryo government has its own branch, and the Japanese
        top titles go through the `_JAPAN_TOP_OFFICE_KEYS` table, keyed by government rather than era.
        """
        gov = government or ""
        # Landless adventurer camps use the game's camp keys
        # (`duke_landless_adventurer_camp_<purpose>`, and the default key when the purpose is
        # unknown) instead of a feudal office word.
        if tid is not None and self.title_kind(tid) == "camp":
            w = self._camp_holder_word(cid, date) if cid is not None else ""
            if not w:
                w = self._camp_holder_word_default(female)
            return w if (w and not w.startswith(("$", "["))) else ""
        # Game flavorization wins: a culture-specific tier word outranks a generic government word.
        # When the government is unknown, an unconditional fallback entry such as duke/count counts as
        # a miss, or its priority would override the culture/government chain below and lose the
        # gendered form.
        fw_key = self._flavor_key("character", tier, cid, tid=tid,
                                  gender=("female" if female else "male"),
                                  gov=gov, date=date)
        if fw_key and not (not gov and FZ.is_unconditional(fw_key)):
            # The key's value may be a `[CHARACTER.Custom('GetActualDukeTheocracyTitle')]`
            # delegation (Christian theocratic office words), resolved by `_loc_or_custom_word`.
            v = self._loc_or_custom_word(fw_key, cid=cid, tid=tid, date=date)
            if v:
                return v
        if gov in ("japan_administrative_government", "japan_feudal_government"):
            tkey = (self._lt.get(str(tid)) or {}).get("key") or ""
            # The Japanese top titles (e_japan, the throne) consult the (title, government) table
            # first: regent, shogun or emperor, never the generic emperor word.
            key = self._JAPAN_TOP_OFFICE_KEYS.get((tkey, gov))
            if key is None:
                if gov == "japan_feudal_government":
                    # the soryo government has its own key table, split by sex
                    _pair = self._JAPAN_SORYO_KEYS.get(tier)
                    key = (_pair[1] if female else _pair[0]) if _pair else ""
                else:
                    key = self._JAPAN_OFFICE_KEYS.get(tier)
                if tkey in self._TENNO_TITLE_KEYS:
                    key = "king_tenno_male_japanese"
            if key:
                v = L.loc(self.table, key)
                if v and not v.startswith("$") and not v.startswith("["):
                    return v
        if gov in self._CELESTIAL_LIKE_GOVS:
            if independent:
                if tier == "hegemon":
                    # A female hegemon ruler gets the empress word directly: the game's
                    # `hegemon_celestial_female_chinese` is only a template reference to the male
                    # key, so the female key must be looked up explicitly.
                    key = "hegemon_celestial_female_chinese" if female \
                        else "hegemon_celestial_male_chinese"
                elif tier == "empire":
                    key = "emperor_celestial_male_chinese_independent"
                elif tier == "kingdom":
                    key = "king_female_chinese" if female else "king_male_chinese"
                elif tier == "duchy":
                    key = ("duke_female_chinese_independent"
                           if female else "duke_male_chinese_independent")
                elif tier == "county":
                    key = ("count_independent_female_feudal_chinese"
                           if female else "count_independent_male_feudal_chinese")
                else:
                    key = ("baron_female_feudal_chinese"
                           if female else "baron_male_feudal_chinese")
                v = L.loc(self.table, key)
                if v and not v.startswith("$") and not v.startswith("["):
                    return v
                v = L.loc(self.table, self._TIER_KEY[tier])
                if v and not v.startswith("$") and not v.startswith("["):
                    return v
                return L.GENERIC_TIER_ZH.get(tier, "")
            if tier == "hegemon":
                key = "hegemon_celestial_male_chinese"
            elif tier == "kingdom":
                key = "king_celestial_male_chinese_civilian_governor"
            elif tier == "empire":
                key = "emperor_celestial_male_chinese_civilian_governor"
            else:
                key = f"{self._TIER_KEY[tier]}_celestial_male_chinese_governor"
            v = L.loc(self.table, key)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        # Nomad/herder/tribal office words follow the game's flavorization keys:
        # <tier>_nomad_{male|female}_<heritage>, <tier>_tribal_{male|female} and
        # <tier>_herder_{male|female}. A nomad_government vassal matches the tribal key at the game's
        # own priority, while a non-Turkic culture has no nomad key; falling back to the feudal count
        # word would misname a nomad ruler.
        if gov in self._NOMAD_LIKE_GOVS:
            w = self._nomad_office_word(tier, gov, independent, female, cid)
            if w:
                return w
        # Culture title words (Chinese culture: king/duke/marquis/earl/general…): outside the
        # celestial governments the game addresses a ruler by culture, which the generic kingdom and
        # duchy words would not match.
        w = self._culture_office_word(cid, tier, independent, female)
        if w:
            return w
        prefix = re.sub(r"_government$", "", gov)
        # The sex belongs in the key: hard-coding the male form would degrade every female holder's
        # office word. Candidate order: government x sex, feudal x sex, tier x sex, then the plain
        # feudal male key for compatibility.
        g = "female" if female else "male"
        keys = ([f"{self._TIER_KEY[tier]}_{prefix}_{g}"] if prefix else []) \
            + [f"{self._TIER_KEY[tier]}_feudal_{g}",
               f"{self._TIER_KEY[tier]}_{g}",
               f"{self._TIER_KEY[tier]}_feudal_male"]
        for k in dict.fromkeys(keys):
            v = L.loc(self.table, k)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        # the generic fallback uses the sex-split office table (GENERIC_TIER_ZH holds title suffixes)
        pair = L.GENERIC_OFFICE_ZH.get(tier)
        if pair:
            return pair[1] if female else pair[0]
        return L.GENERIC_TIER_ZH.get(tier, "")

    # CK3 culture_titles word family (the `chinese` family in dlc_tgp_cultural_titles), using the
    # game's own key names for king, independent duke, feudal duke, feudal count, independent count
    # and feudal baron.
    _CULTURE_OFFICE_KEYS = {
        "hegemon": ("hegemon_male_chinese", None),
        "empire":  ("emperor_male_feudal_chinese", "emperor_female_feudal_chinese"),
        "kingdom": ("king_male_chinese", "king_female_chinese"),
        "duchy":   ("duke_independent_male_feudal_chinese",
                    "duke_independent_female_feudal_chinese"),
        "county":  ("count_independent_male_feudal_chinese",
                    "count_independent_female_feudal_chinese"),
        "barony":  ("baron_male_feudal_chinese", "baron_female_feudal_chinese"),
    }
    _CULTURE_OFFICE_KEYS_VASSAL = {
        "duchy":  ("duke_male_feudal_chinese", "duke_female_feudal_chinese"),
        "county": ("count_male_feudal_chinese", "count_female_feudal_chinese"),
    }

    def _culture_office_word(self, cid, tier, independent, female):
        """Look up a culture title word; usable only when the cid's culture maps to a word family."""
        if cid is None:
            return ""
        tpl = (self.culture_template(cid) or "").lower()
        fam = _CULTURE_TITLE_FAMILY.get(tpl)
        if fam != "chinese":
            return ""
        if tier == "hegemon":
            male, fem = self._CULTURE_OFFICE_KEYS[tier]
        elif independent:
            male, fem = self._CULTURE_OFFICE_KEYS.get(tier, (None, None))
        else:
            male, fem = (self._CULTURE_OFFICE_KEYS_VASSAL.get(tier)
                         or self._CULTURE_OFFICE_KEYS.get(tier, (None, None)))
        for k in (fem if female else male, male):
            if not k:
                continue
            v = L.loc(self.table, k)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        return ""

    # Nomad/herder/tribal governments (the flavorization family whose entries list nomad_government)
    _NOMAD_LIKE_GOVS = {"nomad_government", "herder_government",
                        "tribal_government", "wanua_government"}
    _NOMAD_TIER_KEY = {"hegemon": "emperor", "empire": "emperor",
                       "kingdom": "king", "duchy": "duke",
                       "county": "count", "barony": "baron"}

    # ---- game flavorization lookups (ruler address words / title name suffixes) ----
    # A culture-specific entry outranks a generic government entry by the game's own priority rules,
    # which is what flavorization.py implements.

    _FLAVOR_TIER = {"hegemon": "hegemony"}

    # ---- recovering a dead character's culture/faith: both are optional save keys ----
    # In a character record, `culture=` and `faith=` are optional once `dynasty_house` is written, and
    # the default is the house's value; the house record itself stores neither, so the value is the
    # first explicit one along the house leader chain (recent first), derived from `historical` plus
    # `head_of_house`. A missing culture on a dead character therefore means "the house's value",
    # which is how the game can always display it.
    def _house_of(self, cid):
        """House id of the character (cache first, melt character as fallback); None without a house."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        hid = rec.get("dynasty_house")
        if hid is None:
            hid = (self._chars.get(str(cid)) or {}).get("dynasty_house")
        try:
            return int(hid) if hid is not None else None
        except (TypeError, ValueError):
            return None

    def _house_default(self, cid, field):
        """House default per the game's rule: the first explicit `field` value along the house leader
        chain, recent first.

        field is 'culture' or 'faith'. The result is memoized per house, so the members share one
        resolution. None when unavailable.
        """
        hid = self._house_of(cid)
        if hid is None:
            return None
        memo = getattr(self, "_house_memo", None)
        if memo is None:
            memo = {}
            self._house_memo = memo
        per = memo.setdefault(field, {})
        if hid in per:
            return per[hid]
        houses = (self.melt.get("dynasties") or {}).get("dynasty_house") or {}
        h = houses.get(str(hid)) or {}
        leaders = []
        for x in (h.get("historical") or []):
            try:
                leaders.append(int(x))
            except (TypeError, ValueError):
                continue
        head = h.get("head_of_house")
        try:
            head = int(head) if head is not None else None
        except (TypeError, ValueError):
            head = None
        if head is not None and head not in leaders:
            leaders.append(head)
        val = None
        for lid in reversed(leaders):
            v = (self._chars.get(str(lid)) or {}).get(field)
            if v is not None:
                val = v
                break
        per[hid] = val
        return val

    def _culture_entry(self, cid, date=None):
        """The character's culture entry in culture_manager (with name_list and heritage).

        Resolution is dated and falls back to the house default: the culture history, then this
        cache's current value, then the melt character, then the house default. Reading only the
        cache's current value fails for dead characters, whose culture field the save prunes, which
        silently degrades flavorization to generic address words.
        """
        if cid is None:
            return {}
        cul = self._culture_id_at(cid, date)
        if cul is None:
            cul = (self._chars.get(str(cid)) or {}).get("culture")
        if cul is None:
            cul = self._house_default(cid, "culture")
        if cul is None:
            return {}
        e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
            .get(str(cul))
        return e if isinstance(e, dict) else {}

    def _faith_tags(self, cid, date=None):
        """Faith tags of the character as (faith tag, religion tag).

        Dated the same way as `_culture_entry` (faith history, current value, house default), because
        the save prunes `faith` on dead characters. The faith definition comes from `cl.faith_entry`,
        which reads the top-level `faiths.database` of newer saves and falls back to
        `religion.faiths` for older ones; reading only the old path would make every faith and
        religion gate fail.
        """
        fid = self._faith_id(cid, date) if cid is not None else None
        if fid is None:
            return "", ""
        e = cl.faith_entry(self.melt, fid)
        if not isinstance(e, dict) or not e:
            return "", ""
        ftag = str(e.get("faith_type") or e.get("tag") or "")
        rtag = ""
        rid = e.get("religion")
        if rid is not None:
            re_ = ((self.melt.get("religion") or {}).get("religions") or {}) \
                .get(str(rid))
            if isinstance(re_, dict):
                rtag = str(re_.get("tag") or re_.get("religion_type") or "")
        return ftag, rtag

    def _rite_type(self, cid, date=None):
        """`rite_type` key of the character's rite, used by the `rites` condition of flavorization.

        Read from `rites.database[<rid>].rite_type`. An older save without a rite database returns '',
        so entries with a `rites` condition never match, equivalent to the character having no rite.
        """
        rid = self._rite_id(cid, date)
        if rid is None:
            return ""
        return str(cl.rite_entry(self.melt, rid).get("rite_type") or "")

    def _top_liege_of(self, cid, tid):
        """Top liege along de_facto_liege; returns (cid, tid) when the character is already top."""
        seen = set()
        cur = str(tid) if tid is not None else ""
        holder, top_tid = cid, tid
        while cur and cur not in seen:
            seen.add(cur)
            t = self._lt.get(cur) or {}
            if not t:
                break
            h = t.get("holder")
            if isinstance(h, int):
                holder = h
            top_tid = t.get("title") or cur
            liege = t.get("de_facto_liege")
            cur = str(liege) if liege is not None else None
        try:
            top_tid = int(top_tid)
        except (TypeError, ValueError):
            top_tid = tid
        return holder, top_tid

    def _flavor_key(self, kind, tier, cid, tid=None, gender=None, gov=None,
                    date=None, special=None, independent=None):
        """Localization key chosen by flavorization, or '' when nothing matches.

        Government values for the character and his liege are taken at `date`, since the words differ
        between feudal and administrative periods. `special` is passed through to `FZ.resolve` (None
        means the holder class), and `independent` can override independence: the independent/vassal
        choice for a prince or princess word looks at the ruling parent, while `cid` is the landless
        child whose own independence is not determinable.
        """
        if not self._flavor or tier is None or cid is None:
            return ""
        tkey = self._FLAVOR_TIER.get(tier, tier)
        if gender is None:
            gender = "female" if self._is_female(cid) else "male"
        if gov is None:
            # The government is the holder's own: flavorization evaluates `governments` on the
            # Context Character (see `_gov_for_word`)
            gov = self._gov_for_word(cid, tid, date) if tid is not None else ""
        ce = self._culture_entry(cid, date)
        ftag, rtag = self._faith_tags(cid, date)
        rtype = self._rite_type(cid, date)
        title_key = ""
        if tid is not None:
            title_key = ((self._lt.get(str(tid)) or {}).get("key") or "")
        if independent is None:
            independent = self._is_independent(cid, date)
        if independent is None:
            independent = True
        # vassal: entries without an explicit top_liege = no are judged by the top liege (game default)
        top = None
        if not independent and tid is not None:
            lid, ltid = self._top_liege_of(cid, tid)
            if lid is not None and int(lid) != int(cid):
                lce = self._culture_entry(lid, date)
                lft, lrt = self._faith_tags(lid, date)
                top = {"government": (self._gov_for_word(lid, ltid, date)
                                      if ltid else ""),
                       "name_list": lce.get("name_list") or "",
                       "heritage": lce.get("heritage") or "",
                       "faith": lft, "religion": lrt,
                       "rite": self._rite_type(lid, date)}
        try:
            return FZ.resolve(
                kind, tkey, gender, government=gov or "",
                name_list=ce.get("name_list") or "",
                heritage=ce.get("heritage") or "",
                faith=ftag, religion=rtag, rite=rtype, title_key=title_key,
                independent=bool(independent), top=top,
                obligation_flags=self._obligation_flags_at(cid, date),
                special=(special or "holder"))
        except Exception:
            return ""

    def _prince_word_exists(self, ptier, government, independent, cid, tid, date,
                            owner=None):
        """Whether the game has a prince/princess word here, asked of the `special = ruler_child`
        entry table (`FZ.ruler_child_exists`). Tribal and nomad governments have no such entry at any
        tier, so their untitled children get none, while an undeterminable government passes the gate.
        A gate only: the wording comes from the existing tables.
        """
        if cid is None or ptier is None or not self._flavor:
            return True
        gov = (government or "").strip()
        if not gov and owner is not None:
            try:
                gov = (self._character_government_or_earliest(owner, date) or "")
            except Exception:
                gov = ""
        if not gov:
            return True
        ce = self._culture_entry(cid, date)
        ftag, rtag = self._faith_tags(cid, date)
        rtype = self._rite_type(cid, date)
        title_key = ((self._lt.get(str(tid)) or {}).get("key") or "") \
            if tid is not None else ""
        # vassal: entries without an explicit top_liege = no are judged by the top liege (as `_flavor_key`)
        top = None
        if not independent and tid is not None:
            lid, ltid = self._top_liege_of(cid, tid)
            if lid is not None and int(lid) != int(cid):
                lce = self._culture_entry(lid, date)
                lft, lrt = self._faith_tags(lid, date)
                top = {"government": (self._gov_for_word(lid, ltid, date)
                                      if ltid else ""),
                       "name_list": lce.get("name_list") or "",
                       "heritage": lce.get("heritage") or "",
                       "faith": lft, "religion": lrt,
                       "rite": self._rite_type(lid, date)}
        try:
            k = FZ.ruler_child_exists(
                self._FLAVOR_TIER.get(ptier, ptier),
                "female" if self._is_female(cid) else "male",
                government=gov,
                name_list=ce.get("name_list") or "",
                heritage=ce.get("heritage") or "",
                faith=ftag, religion=rtag, rite=rtype, title_key=title_key,
                independent=bool(independent), top=top,
                obligation_flags=self._obligation_flags_at(cid, date))
        except Exception:
            return True
        return bool(k)

    def _flavor_word(self, kind, tier, cid, tid=None, gender=None, gov=None,
                     date=None):
        """Localization word for a flavorization key; '' when unmapped or unresolved."""
        k = self._flavor_key(kind, tier, cid, tid=tid, gender=gender, gov=gov,
                             date=date)
        if not k:
            return ""
        v = L.loc(self.table, k)
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        return ""

    def _heritage_of(self, cid):
        """Culture heritage pillar (heritage_turkic and the like), used to pick a nomad office word by
        the game's priority."""
        if cid is None:
            return ""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        cul = rec.get("culture")
        if cul is None:
            cul = (self._chars.get(str(cid)) or {}).get("culture")
        if cul is None:
            return ""
        e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
            .get(str(cul)) or {}
        return (e.get("heritage") or "") if isinstance(e, dict) else ""

    def _nomad_office_word(self, tier, gov, independent, female, cid):
        """Nomad/herder/tribal ruler word, reproducing the game's flavorization order: the
        heritage-specific nomad word, then the generic tribal word, then the herder word. '' when none
        is found.
        """
        g = "female" if female else "male"
        tkey = self._NOMAD_TIER_KEY.get(tier)
        if not tkey:
            return ""
        heritage = (self._heritage_of(cid) or "").replace("heritage_", "")
        cands = []
        if gov == "nomad_government" and heritage:
            if independent and tier == "kingdom":
                cands.append(f"duke_independent_nomad_{g}_{heritage}")
            cands.append(f"{tkey}_nomad_{g}_{heritage}")
        if gov == "herder_government":
            cands.append(f"{tkey}_herder_{g}")
        cands.append(f"{tkey}_tribal_{g}")
        for k in cands:
            v = L.loc(self.table, k)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        return ""

    def _anchor_date(self, cid, date=None):
        """Date anchor for office and realm names: an explicit date, else the day before death for a
        character dead inside the biography window, else as_of.

        Titles pass to the heir on the death day, so the day before is used to keep the dead
        character's own titles, and a date at or after death folds there too. A character who died
        after as_of counts as living, so a later realm name cannot leak into an early decade.
        """
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        dd = (rec.get("death") or {}).get("date")
        if not dd and cid == self.cache.get("player_id"):
            dd = (self.cache.get("player_death") or {}).get("date")
        if date:
            if dd and cl.date_key(date) >= cl.date_key(dd):
                return _day_before(dd)          # a date at or after death -> standing at death
            return date
        if dd and (not self.as_of or cl.date_key(dd) <= cl.date_key(self.as_of)):
            return _day_before(dd)
        return self.as_of

    def _title_display_name(self, tid, date=None, cid=None):
        """Display name of a title: its name plus the tier word suffix, matching the game's
        TITLE_TIERED_NAME, so the label outlets and `title()` do not give one title two faces in the
        same material.

        Narrow by design: the suffix is appended only when the tier word comes from a
        `japan_feudal_government` flavorization entry. The ritsuryo title word and the office word
        would otherwise stack, and the effect on western and administrative titles has not been
        assessed.
        """
        if tid is None:
            return ""
        name = self._name_at_date(tid, date) or self.title_base_name(tid)
        if not name:
            return ""
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        tier = ""
        for pfx, tv in L.TIER_KEY_OF_PREFIX.items():
            if key.startswith(pfx):
                tier = tv
                break
        if not tier:
            return name
        if cid is None:
            cid = self._holder_at_or_now(self._lt.get(str(tid)) or {}, tid, date)
        if cid is None:
            return name
        gov = self._gov_for_word(cid, tid, date)
        fk = self._flavor_key("title", tier, cid, tid=tid, gov=gov, date=date)
        if not fk:
            return name
        e = (FZ.table().get("entries") or {}).get(fk) or {}
        if "japan_feudal_government" not in (e.get("governments") or []):
            return name
        v = L.loc(self.table, fk)
        if not v or v.startswith("$") or v.startswith("["):
            return name
        if _STATE_SUFFIX_RE.search(name):
            return name
        return f"{name}{v}"

    def _last_title_place(self, cid, fkey="", date=None):
        """Place name for a character's office word, since dead_data.flavor carries only the office
        word.

        Order: a title matching the office tier exactly, then the highest-tier title, then the most
        recently held one, then the titles in a dead character's `dead_data.domain` (which still holds
        his lands when title history has been pruned). The realm name is taken at the anchor date, so
        a dead character is named by the realm of his death. Returns a place name or ''.
        """
        anchor = self._anchor_date(cid, date)
        tier_want = None
        for pfx, rk in (("hegemon_", 6), ("emperor_", 5), ("king_", 4),
                        ("duke_", 3), ("count_", 2), ("baron_", 1)):
            if fkey and fkey.startswith(pfx):
                tier_want = rk
                break

        def _place_nm(tid):
            """Realm name of the title at the anchor date (a dead character's realm at death).

            House estates, camps and court offices are excluded: a family estate name is not a landed
            place name and must not be prefixed to an office word.
            """
            if tid is None:
                return ""
            if self._is_estate_title(tid):
                return ""
            t = self._lt.get(str(tid)) or {}
            key = t.get("key") or ""
            if not key or key.startswith(("x_", "e_minister_")):
                return ""
            # soryo titles carry their display-name suffix here too
            return self._title_display_name(tid, anchor, cid=cid) \
                or self._name_at_date(tid, anchor) or self.title_base_name(tid)

        # With several titles of the same tier, the primary title and the death save's liege_title win
        # over iteration order, so the result is stable and matches the game's display.
        if tier_want is not None:
            _pt, ptid = self._primary_title_at(cid, as_of=anchor)
            if ptid is not None and self._eff_rank(ptid) == tier_want:
                nm = _place_nm(ptid)
                if nm:
                    return nm
            drec = (self.cache.get("characters") or {}).get(str(cid)) or {}
            ltid = (drec.get("death") or {}).get("liege_title")
            if ltid is not None and int(ltid) != ptid and \
                    self._eff_rank(int(ltid)) == tier_want:
                nm = _place_nm(int(ltid))
                if nm:
                    return nm
        intervals = self._hold_intervals(cid)
        best_tier, best_tier_nm = -1, ""
        best_late, best_late_nm = None, ""
        for tid, ivs in intervals.items():
            t = self._lt.get(str(tid)) or {}
            key = t.get("key") or ""
            if not key or key.startswith(("x_", "e_minister_")) \
                    or self._is_estate_title(tid):
                continue
            rank = self._eff_rank(tid)
            for (gain, _loss, _lt) in ivs:
                if not gain:
                    continue
                # the realm name is the current one, not the accession day's; "current" means the
                # anchor date, so a dead character takes the realm of his death
                nm = self._title_display_name(tid, anchor, cid=cid) \
                    or self._name_at_date(tid, anchor) or self.title_base_name(tid)
                if not nm:
                    continue
                if tier_want is not None and rank == tier_want:
                    return nm  # exact tier match with the office tier: return directly
                if rank > best_tier:
                    best_tier, best_tier_nm = rank, nm
                dk = cl.date_key(gain)
                if best_late is None or dk > best_late[0]:
                    best_late = (dk, nm)
        if best_tier_nm:
            return best_tier_nm
        if best_late_nm:
            return best_late_nm
        # when title history is pruned, a dead character's dead_data.domain still carries the lands he
        # held at death; used here as the place-name fallback
        c = self._chars.get(str(cid)) or {}
        dd = c.get("dead_data") or {}
        ddom = dd.get("domain") or []
        if ddom:
            died = dd.get("date")
            for tid in ddom:
                t = self._lt.get(str(tid)) or {}
                key = t.get("key") or ""
                if not key or key.startswith(("x_", "e_minister_")) \
                        or self._is_estate_title(tid):
                    continue
                rank = self._eff_rank(tid)
                if tier_want is not None and rank == tier_want:
                    nm = self._name_at_date(tid, died)
                    if nm:
                        return nm
            # no exact tier match: take the highest-tier domain
            b_t, b_nm = -1, ""
            for tid in ddom:
                t = self._lt.get(str(tid)) or {}
                key = t.get("key") or ""
                if not key or key.startswith(("x_", "e_minister_")) \
                        or self._is_estate_title(tid):
                    continue
                rank = self._eff_rank(tid)
                nm = self._name_at_date(tid, died)
                if nm and rank > b_t:
                    b_t, b_nm = rank, nm
            return b_nm
        return ""

    # Faction-leader titles carry no place name and are no label on their own; the revolt section words them
    _FACTION_LEADER_FLAVORS = ("faction_leader", "faction_leader_male",
                               "faction_leader_female")
    # Tier-prefixed flavors hold ruler tier words, which need a place name to form a label; when no
    # place name resolves the whole word is dropped rather than emitted bare.
    _TIER_FLAVOR_PREFIXES = ("hegemon_", "emperor_", "king_", "duke_", "count_",
                             "baron_", "prince_", "princess_")

    def _has_current_landed_title(self, cid, anchor):
        """True when the character still holds a real landed title of county rank or above at the anchor
        (the test behind the "former" prefix for court offices). Camps, estates, court offices and
        baronies do not count.
        """
        for tid, ivs in (self._hold_intervals(cid, anchor) or {}).items():
            if not any(iv[1] is None for iv in ivs):
                continue
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            if key.startswith("e_minister_") or self._is_estate_title(tid):
                continue
            if self._TT_RANK.get(key[:2], 0) >= 2:
                return True
        return False

    def _ministry_office_at(self, cid, anchor, include_former=False):
        """Office word for a court post: the current word when still held, or with a "former" prefix
        when include_former is set and the post is gone. Among several posts the highest rank and then
        the latest gain win.

        The only source is the e_minister_* titles: the save's dead_data.flavor gives just the generic
        minister word, so the ministry name must come from the title.
        """
        best = None   # (rank, gain_key, word, still_held)
        for tid, ivs in (self._hold_intervals(cid, anchor) or {}).items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            if not key.startswith("e_minister_"):
                continue
            word = self._minister_office(tid)
            if not word:
                continue
            gains = [cl.date_key(iv[0]) for iv in ivs if iv and iv[0]]
            cand = (self._TT_RANK.get(key[:2], 0),
                    max(gains) if gains else (0, 0, 0), word,
                    any(iv[1] is None for iv in ivs))
            if best is None or (cand[0], cand[1]) > (best[0], best[1]):
                best = cand
        if best is None:
            return ""
        if best[3]:
            return best[2]
        return f"前{best[2]}" if include_former else ""

    # ---- office word for the head of a clerical province (holy see) ----
    # In the save a clerical province is a landed title with `landless = true`, a
    # `clerical_region = {…}` block and its own `title_name_data.name`, and the game treats it as a
    # duchy-level ecclesiastical title: `common/landed_titles/00_landed_titles.txt` marks it
    # `@never_primary_score` (affecting only AI primary-title choice) and
    # `common/flavorization/20_pam_flavorization.txt` gives it `special_title = clerical_region` with
    # `tier = duchy`. Ranking by key prefix would treat it as no real land and mislabel its holder, so
    # the word is produced here on the game's own terms.
    _HOLY_SEAT_KEYS = ("d_et_alexandria", "d_et_antioch", "d_et_aquileia",
                       "d_et_armenia", "d_et_jerusalem")     # patriarchal sees
    _METROPOLITANATE_KEYS = ("d_et_axum",)                  # metropolitanate
    _CR_WORD_TRIM = "区"        # trims the province suffix to leave the office word

    def _clerical_region_title(self, cid, date=None):
        """Id of the clerical-province title still held at date, else None."""
        if cid is None:
            return None
        ao = cl.date_key(date) if date else None
        for tid, ivs in (self._hold_intervals(cid, date) or {}).items():
            t = self._lt.get(str(tid)) or {}
            if not t.get("clerical_region"):
                continue
            held = False
            for iv in ivs or []:
                g, l = iv[0], (iv[1] if len(iv) > 1 else None)
                if ao is not None and g and cl.date_key(g) > ao:
                    continue
                if l and ao is not None and cl.date_key(l) <= ao:
                    continue
                held = True
            if held:
                return tid
        return None

    def _clerical_holder_word(self, cid, tid, date=None):
        """Office word for the head of a clerical province, from the game's `clerical_region_duchy_*`
        wording with its trailing province suffix removed.

        Variant per `common/flavorization/20_pam_flavorization.txt`: Orthodox or eastern-rite
        Christianity uses the orthodox key, while other Christianity and non-Christian faiths use the
        western-christian and fallback keys. The first hit wins, and a missing key drops the word.
        """
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if key in self._HOLY_SEAT_KEYS:
            lk = "clerical_region_duchy_patriarchate"
        elif key in self._METROPOLITANATE_KEYS:
            lk = "clerical_region_duchy_metropolitanate"
        else:
            _ftag, rtag = self._faith_tags(cid, date)
            if rtag == "christianity_religion":
                docs = []
                try:
                    docs = list(cl.rite_data(
                        self.melt, self._rite_id(cid, date)).get("doctrine") or [])
                except Exception:
                    docs = []
                east = ("special_doctrine_is_eastern_christian_faith" in docs
                        or _ftag == "orthodox")
                lk = "clerical_region_duchy_orthodox" if east \
                    else "clerical_region_duchy_west_christian"
            else:
                lk = "clerical_region_duchy_fallback"
        v = ""
        try:
            v = L.loc(self.table, lk) or ""
        except Exception:
            v = ""
        if not v or v.startswith(("$", "[")):
            return ""
        return v[:-1] if v.endswith(self._CR_WORD_TRIM) else v

    def clerical_region_word(self, cid, date=None):
        """Office word of a clerical province's head (place name plus ecclesiastical office word), else ''.

        Applies when the character holds a title with a non-empty `clerical_region` at date. The place
        name comes from `title()` and the office word from `_clerical_holder_word`.
        """
        tid = self._clerical_region_title(cid, date)
        if tid is None:
            return ""
        place = ""
        try:
            place = self.title(tid, date) or self._name_at_date(tid, date) \
                or self.title_base_name(tid) or ""
        except Exception:
            place = ""
        word = self._clerical_holder_word(cid, tid, date)
        if not word:
            return ""
        return f"{place}{word}" if place else word

    def _title_flags(self, tid, date=None):
        """Flag set of the title itself; the shogunate flag lands on e_japan this way.

        Only the current state is known, because the melt stores just the last save's `variables`, so a
        historic date returns an empty set rather than a guess.
        """
        if date is not None:
            last = self.cache.get("last_date")
            if last and cl.date_key(str(date)) < cl.date_key(str(last)):
                return set()
        t = self._lt.get(str(tid)) or {}
        return {str(v.get("flag"))
                for v in (((t.get("variables") or {}).get("data")) or [])
                if isinstance(v, dict) and v.get("flag")}

    def _char_flags(self, cid, date=None):
        """Flag set of the character himself, read from `alive_data.variables.data[].flag`.

        A dead character's save has its variables cleared, so an empty set is returned and the baked
        `dead_data.flavor` supplies the wording instead. Same "current state only" rule as
        `_title_flags`.
        """
        if date is not None:
            last = self.cache.get("last_date")
            if last and cl.date_key(str(date)) < cl.date_key(str(last)):
                return set()
        ad = (self._chars.get(str(cid)) or {}).get("alive_data") or {}
        return {str(v.get("flag"))
                for v in (((ad.get("variables") or {}).get("data")) or [])
                if isinstance(v, dict) and v.get("flag")}

    def japan_top_office(self, cid, date=None):
        """Bare office word of a holder of a Japanese top title, else ''.

        Order: the game's baked flavor key inside the death window (the only source for the retired
        emperor and the shogun); the (title, government) table, where a feudal title carrying
        `shogun_flag` gives the shogun word; then the character's own `shogun_flag` as a fallback when
        the title flag is missing. The word is returned bare, with no realm-name prefix.
        """
        if cid is None:
            return ""
        anchor = self._anchor_date(cid, date)
        _tier, tid = self._primary_title_at(cid, as_of=anchor)
        if not isinstance(tid, int):
            return ""
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if key not in self._JAPAN_TOP_TITLE_KEYS:
            return ""
        c = self._chars.get(str(cid)) or {}
        dd = c.get("dead_data") or {}
        fkey = dd.get("flavor") or ""
        if fkey and anchor and dd.get("date") \
                and abs(_date_ord(anchor) - _date_ord(dd["date"])) <= 1:
            w = self._JAPAN_OFFICE_FROM_FLAVOR.get(fkey)
            if w:
                return w
        gov = self._gov_for_word(cid, tid, anchor) or ""
        if not gov:
            gov = self._title_government_hist(tid, anchor) \
                or (self._lt.get(str(tid)) or {}).get("history_government") or ""
        if gov == "japan_feudal_government" \
                and self._SHOGUN_FLAG in self._title_flags(tid, anchor):
            return self._JAPAN_OFFICE_SHOGUN
        w = self._JAPAN_TOP_OFFICE_WORD.get((key, gov))
        if w:
            return w
        if self._SHOGUN_FLAG in self._char_flags(cid, anchor):
            return self._JAPAN_OFFICE_SHOGUN
        return ""

    def official_title(self, cid, date=None):
        """Role office name, "<title name><office word>".

        Dead characters read the save's baked `dead_data.flavor` word; `date` anchors the lookup
        (death date by default, `as_of` for the living) so a dynamic realm name lands right."""
        rhw = self.religious_head_word(cid)
        if rhw:
            return rhw
        # Japan's top titles (e_japan / 高御座) use the bare office word, with no
        # "日本政权/日本帝国" prefix (see `japan_top_office`).
        _jw = self.japan_top_office(cid, date)
        if _jw:
            return _jw
        anchor = self._anchor_date(cid, date)
        # Ministry offices come first: the save's flavor gives only the generic "尚书"
        # (minister_any_male) for the boards, so the board name must come from the title.
        mo = self._ministry_office_at(cid, anchor)
        if mo:
            return mo
        # Clerical province (圣职区) heads are landless theocratic titles whose key prefix
        # carries no tier, so `_has_current_landed_title` rejects them — check them before
        # the former-office fallback below.
        cr = self.clerical_region_word(cid, anchor)
        if cr:
            return cr
        if not self._has_current_landed_title(cid, anchor):
            mo = self._ministry_office_at(cid, anchor, include_former=True)
            if mo:
                return mo
        c = self._chars.get(str(cid)) or {}
        fkey = (c.get("dead_data") or {}).get("flavor")
        # `dead_data.flavor` is baked at death from the LAST government of the save, so it can
        # contradict an earlier date's government; accept it only when
        # `_dead_flavor_consistent` agrees with the anchor day.
        # Japan's top-office keys must come only from `japan_top_office`, which checks whether
        # the person really holds e_japan/高御座 that day — `_dead_flavor_consistent` merely
        # compares the government prefix.
        if fkey and fkey not in self._JAPAN_OFFICE_FROM_FLAVOR \
                and self._dead_flavor_consistent(fkey, cid, anchor):
            v = L.loc(self.table, fkey)
            if v and not v.startswith("$") and not v.startswith("["):
                if fkey.startswith(self._TIER_FLAVOR_PREFIXES):
                    # A tier word needs a place name; with none resolvable the bare word is
                    # not a title → "" and another branch renders the label.
                    place = self._last_title_place(cid, fkey, date=anchor)
                    if not place or v.startswith(place):
                        return ""
                    return f"{place}{v}"
                # Faction-leader flavors (领袖) name no place, so the bare word is not a
                # title — person_label's rebel branch renders it.
                if fkey in self._FACTION_LEADER_FLAVORS:
                    return ""
                return v
        tier, tid = self._primary_title_at(cid, as_of=anchor)
        if tid is None or tier is None:
            # Landless family estate titles (x_nf_*,「XX家族」): the holder word follows the
            # culture (Japan 当主, Korea 户长, otherwise 乡绅). Detected by `_is_estate_title`,
            # not by the x_nf_ prefix — Chinese clan estates use c_nf_/d_nf_ keys.
            if tid is not None:
                if self._is_estate_title(tid):
                    nm = self.title_base_name(tid) or ""
                    sq = self._estate_holder_word(cid)
                    return f"{nm}{sq}" if nm else sq
            return ""  # no title, or camp only (no office word)
        # Ministry office holder → office word (not "X皇帝/帝国")
        mo = self._minister_office(tid)
        if mo:
            return mo
        rn = self.realm_name(tid)
        if rn:
            return rn
        # 惣領制 titles carry "武士团" in the display name (see `_title_display_name`)
        name = self._title_display_name(tid, anchor, cid=cid) \
            or self._name_at_date(tid, anchor) or self.title_base_name(tid)
        # Government is resolved for the anchor day, not from the cache's last save.
        # `_gov_for_word` adds the title-side government (`de_facto_liege` up to the liege) and,
        # for the dead, `dead_data.government`; without them flavorization can fall back to the
        # unconditional `duke` entry and give one title two different words.
        gov = self._gov_for_word(cid, tid, anchor)
        if not gov:
            rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
            gov = (rec.get("landed") or {}).get("government") or ""
        if not gov:
            gov = (c.get("landed_data") or {}).get("government") or ""
        # For Japan's top title (天皇座/e_japan) also try the title-side government: a holder
        # whose government history starts after the cache window would otherwise get the
        # generic "皇帝".
        if ((self._lt.get(str(tid)) or {}).get("key") or "") in self._JAPAN_TOP_TITLE_KEYS:
            gov = self._gov_for_word(cid, tid, anchor) or gov
        _indep = self._is_independent(cid, anchor)
        word = self._office_word(tier, gov,
                                 independent=bool(_indep) if _indep is not None else True,
                                 female=self._is_female(cid),
                                 tid=tid, cid=cid, date=anchor)
        # A place-less title yields a bare office word — return it and let person_label fall
        # back to a display name. Cardinal titles (d_cd_*) are landless titular (see
        # `07_pam_ecclesiastical_titles.txt`), and the office word is already "枢机".
        if word and self._is_cardinal_title(tid):
            return word
        if name and word:
            return f"{name}{word}"
        return name or ""

    def _is_cardinal_title(self, tid):
        """Whether `tid` is a cardinal title (the 1.20 `d_cd_*` family).

        Judged by the save field `landed_titles[<tid>].clerical_elector`; `landless` is a static
        definition field that save title objects do not persist."""
        if tid is None:
            return False
        t = self._lt.get(str(tid)) or {}
        if not isinstance(t, dict):
            return False
        return t.get("clerical_elector") not in (None, "")

    # Ministry offices (e_minister_*) → localization keys (six boards + censorate +
    # privy council)
    _MINISTER_OFFICE_KEYS = {
        "e_minister_of_personnel": "minister_personnel",   # Board of Personnel
        "e_minister_of_revenue": "minister_revenue",       # Board of Revenue
        "e_minister_of_rites": "minister_rites",           # Board of Rites
        "e_minister_of_war": "minister_war",               # Board of War
        "e_minister_of_justice": "minister_justice",       # Board of Justice
        "e_minister_of_works": "minister_works",           # Board of Works
        "e_minister_censor": "minister_censor",            # Censorate
        "e_minister_grand_marshal": "minister_grand_marshal",  # Privy council
        "e_minister_chancellor": "minister_chancellor",    # Chancellor
    }
    # Fallback office words when a key is missing or unresolved (see _minister_office)
    _MINISTER_OFFICE_FALLBACKS = {
        "minister_revenue": ("councillor_steward_celestial_government_imperial",),
        "minister_rites": ("councillor_court_chaplain_celestial_government_imperial",),
        "minister_censor": ("minister_censor_male",),
        "minister_grand_marshal": ("minister_grand_marshal_male",),
        "minister_chancellor": ("minister_chancellor_male",),
    }

    # Feud events re-render both characters: the game's change_reason writes only
    # "国王/王" with no realm name, so both sides are looked up by the event date.
    def _feud_role_title(self, cid, date):
        """`<title name><name>` of a character in an event — person_label's `event` entry.

        The player goes through `event_name` (name only) to keep the feud log short."""
        if cid == self.cache.get("player_id"):
            return self.event_name(cid, date)
        return self.person_label(cid, date, "event")

    def _feud_other_house_phrase(self, cid, houses, fallback_label=""):
        """Opponent phrase for a self-referential feud line: "{other house}族人".

        The actor's house is always one of `houses`, so the opponent is the other one."""
        h = self._house_of_cid(cid)
        others = [x for x in (houses or []) if x != h]
        if h is None or len(others) != 1:
            return ""
        label = self._house_label(others[0]) or fallback_label or ""
        return f"{label}族人" if label else ""

    def _rerender_feud_event(self, raw, date, houses=None, other_label=""):
        """change_reason raw text → clean sentence with both sides re-rendered; '' when the
        result stays unreadable (rakaly sentinels, unresolved keys).

        `murder_attempt` and `cuckoldry` pass `TARGET_CHAR` as `root`, so both ends can bake to
        the same character; the second person is not in the save, so these degrade to a
        house-level opponent."""
        s = str(raw or "")
        if "\x15" not in s or "ONCLICK" not in s:
            return _clean_ck3_loc(s)
        ids = _FEUD_CHAR_RE.findall(s)
        self_ref = len(ids) >= 2 and len(set(ids)) == 1
        other_phrase = ""
        if self_ref:
            other_phrase = self._feud_other_house_phrase(int(ids[0]), houses,
                                                         other_label)
            if not other_phrase:
                return ""
        seen = [0]

        def _repl(m):
            seen[0] += 1
            cid = int(m.group(1))
            if self_ref and seen[0] == 2:
                return other_phrase
            return self._feud_role_title(cid, date)

        s2 = _FEUD_ROLE_RE.sub(_repl, s)
        return _clean_ck3_loc(s2)

    # Rebuild unreadable feud lines from the cached memories of that day
    _FEUD_MEMORY_TYPES = ("house_feud_started_memory", "house_feud_ended_memory")
    _FEUD_START_TPL = {
        "family_killed": "{other}因族人{victim}被杀，与{my}结为世仇。",
        "family_executed": "{other}因族人{victim}被处决，与{my}结为世仇。",
        "family_imprisoned": "{other}因族人{victim}被囚，与{my}结为世仇。",
        "family_tortured": "{other}因族人{victim}受刑，与{my}结为世仇。",
        "family_title_revoked": "{other}因族人{victim}被褫夺头衔，与{my}结为世仇。",
        "family_land_seized": "{other}因族人{victim}领地见夺，与{my}结为世仇。",
        "family_title_usurped": "{other}因族人{victim}头衔被篡，与{my}结为世仇。",
    }

    def _house_of_cid(self, cid):
        """Character's house id (cache first, then melt)."""
        if not isinstance(cid, int):
            return None
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        h = rec.get("dynasty_house")
        if isinstance(h, int):
            return h
        c = self._chars.get(str(cid)) or {}
        h = c.get("dynasty_house")
        return int(h) if isinstance(h, int) else None

    def _dynasty_of_cid(self, cid):
        """Character's dynasty id (via house); None when unknown."""
        hid = self._house_of_cid(cid)
        if hid is None:
            return None
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        did = rec.get("dynasty_id")
        if isinstance(did, int):
            return did
        return cl.dynasty_id_of(self.melt, hid)

    def _house_label(self, house_id):
        """House name → chronicle-style label ("程" → "程氏")."""
        nm = (cl.house_name_zh(self.melt, house_id) or "") if house_id is not None else ""
        if not nm:
            did = cl.dynasty_id_of(self.melt, house_id) if house_id is not None else None
            nm = (cl.dynasty_name_zh(self.melt, did) or "") if did is not None else ""
        if not nm:
            return ""
        return nm if nm.endswith(("氏", "家", "家族", "部")) else f"{nm}氏"

    def _house_label_at(self, cid, date=None):
        """House label of a character AS OF `date`: house history first, else the current
        house id. Has no call sites yet; kept for "属X氏" wording at a chapter cutoff."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        if rec.get("house_history"):
            h, dn = self._house_names_at(cid, date)
            nm = h or dn
        else:
            nm = self._house_label(self._house_of_cid(cid)) if self._house_of_cid(cid) else ""
        if not nm:
            return ""
        return nm if nm.endswith(("氏", "家", "家族", "部")) else f"{nm}氏"

    def _feud_event_fallback(self, my_houses, other_house, date, other_label):
        """Rebuild that day's feud sentence from cached memories when the raw text is unreadable.

        The feud starts when the memory's attacker is on our side and the victim on the other."""
        dk = str(date or "")
        my_house = None
        for h in my_houses:
            my_house = h
            break
        my_label = self._house_label(my_house) or "主角家族"
        other = other_label or self._house_label(other_house) or "对方家族"
        for _cid, rec in (self.cache.get("characters") or {}).items():
            if not isinstance(rec, dict):
                continue
            for mem in rec.get("memories") or []:
                if str(mem.get("creation_date") or "") != dk:
                    continue
                t = mem.get("type") or ""
                if t not in self._FEUD_MEMORY_TYPES:
                    continue
                parts = mem.get("participants") or {}
                attacker, victim = parts.get("attacker"), parts.get("victim")
                ah = self._house_of_cid(attacker)
                vh = self._house_of_cid(victim)
                if not ((ah in my_houses and vh == other_house)
                        or (vh in my_houses and ah == other_house)):
                    continue
                if t == "house_feud_ended_memory":
                    return f"{other}与{my_label}的世仇就此化解。"
                if ah not in my_houses:
                    continue                    # only our side's start of the feud
                # player name only, as in the other lines of the feud log
                an = self.event_name(attacker, dk) if attacker else ""
                vn = self.event_name(victim, dk) if victim else ""
                reason = ""
                for v in mem.get("vars") or []:
                    if v.get("flag") == "house_feud_reason":
                        reason = str(v.get("value") or "")
                        break
                tpl = self._FEUD_START_TPL.get(reason)
                if tpl and vn:
                    return tpl.format(other=other, victim=vn, my=my_label,
                                      attacker=an)
                if vn:
                    who = f"{vn}遭{an}加害" if an else f"族人{vn}受害"
                    return f"{other}因{who}，与{my_label}结为世仇。"
        # fallback: a rivalry memory between the two houses on that day
        for _cid, rec in (self.cache.get("characters") or {}).items():
            if not isinstance(rec, dict):
                continue
            for mem in rec.get("memories") or []:
                if str(mem.get("creation_date") or "") != dk:
                    continue
                if mem.get("type") not in ("became_rivals", "became_grudge",
                                           "became_nemesis"):
                    continue
                parts = mem.get("participants") or {}
                ids = [v for v in parts.values() if isinstance(v, int)]
                houses = [self._house_of_cid(v) for v in ids]
                if any(h in my_houses for h in houses) \
                        and any(h == other_house for h in houses):
                    try:
                        s = _mem_sentence(self, int(_cid), mem)
                    except (TypeError, ValueError):
                        s = ""
                    if s and loc_text_ok(s):
                        return s
        return ""

    # ------------------------------------------------------------------
    # Kinship labels — kin, lineage and in-laws all use "title + name"
    # ------------------------------------------------------------------
    # A former title is prefixed only when its tier is higher than the current one; the same
    # tid held now and then is not a former title.

    # Non-landed titles (ministry offices e_minister_*, landless camps and estates x_*):
    # never a prince/princess prefix and never a former title.
    _NON_LANDED_KEY_PREFIXES = ("e_minister_", "x_")

    def _is_landed_title(self, tid):
        """Whether `tid` is a landed title (h_/e_/k_/d_/c_/b_), not an office, camp or estate."""
        if tid is None:
            return False
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if not key:
            return False
        if any(key.startswith(p) for p in self._NON_LANDED_KEY_PREFIXES):
            return False
        return key[:2] in ("h_", "e_", "k_", "d_", "c_", "b_")

    def _current_title_tid(self, cid, date=None):
        """Current title tid, used to compare tiers against a former title.

        The dead and the dispossessed fall back to their most recent high title."""
        _tier, tid = self._primary_title_at(cid, as_of=date)
        if tid is not None:
            return tid
        return self._last_high_title_before(cid, date)

    def _former_high_title(self, cid, date=None, exclude_tid=None):
        """Highest-tier lost title tid other than the current one; None when there is none.

        Only landed titles count; camps, estates and offices are not former titles."""
        best_tid, best_rank, best_gain = None, 0, None
        for tid, ivs in self._hold_intervals(cid, date).items():
            if exclude_tid is not None and tid == exclude_tid:
                continue
            if not self._is_landed_title(tid):
                continue
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            rank = self._TT_RANK.get(key[:2], 0)
            if rank <= 0:
                continue
            for (g, _l, _lt) in ivs:
                if not g:
                    continue
                if rank > best_rank or (rank == best_rank
                                        and best_gain is not None
                                        and cl.date_key(g) > best_gain):
                    best_tid, best_rank, best_gain = tid, rank, cl.date_key(g)
                    break
        return best_tid

    def _former_title_text(self, cid, tid, date=None):
        """Chinese text of a former title: place name at the tenure midpoint plus the ruler word.

        Deliberately not the `title_history_names` display name, which stacks into "高昌王国国王"."""
        if tid is None:
            return ""
        gain = None
        loss = None
        for (g, l, _lt) in (self._hold_intervals(cid, date).get(tid) or []):
            gain, loss = g, l
            break
        end = date or self.as_of
        mid = self._span_mid(gain, end)
        nm = self._name_at_date(tid, mid) or self._name_at_date(
            tid, end) or self.title_base_name(tid)
        # The ruler word uses the midpoint's government too: a tenure's first day may still be
        # a landless adventurer government, which would flatten the word to the generic
        # "皇帝".
        w = self._ruler_word_at(cid, tid, self._span_mid(gain, loss or end))
        if nm and w and not nm.endswith(w):
            return f"{nm}{w}"
        return nm

    # ------------------------------------------------------------------
    # "title + name" assembly — the single place that produces person labels
    # ------------------------------------------------------------------
    # Placeholder names for unrecorded names — never used as a label
    _PLACEHOLDER_NAMES = ("某人", "一位人物", "（名讳不详）")
    # Uprising faction → label word, from the game's FACTION_*_TITLE_NAME keys
    _UPRISING_WORDS = {
        "peasant_faction": "农民叛乱",
        "escalated_peasant_faction": "农民起义",
        "populist_faction": "民粹暴动",
        "nomadic_faction": "游牧民叛乱",
    }

    def faction_word(self, cid):
        """Uprising name ("农民起义") when the character leads an uprising faction, else ''.

        Data comes from `cache["factions"]`; '' when that field is absent."""
        rec = (self.cache.get("factions") or {}).get(str(cid)) or {}
        return self._UPRISING_WORDS.get(rec.get("type") or "", "")

    def uprising_info(self, cid):
        """Uprising leader's rebellion info: {"base", "counties", "target", "word"} or {}.

        - base: county of the uprising title's `capital` — the only real data on where he is.
        - counties: number involved, from the faction title_members.
        - target: the object rebelled against (its realm name, else its label)."""
        rec = (self.cache.get("factions") or {}).get(str(cid)) or {}
        if not rec:
            return {}
        out = {}
        word = self._UPRISING_WORDS.get(rec.get("type") or "", "")
        if word:
            out["word"] = word
        base = rec.get("base") or {}
        nm = (base.get("county_name") or "").strip()
        if not nm and isinstance(base.get("county"), int):
            nm = self.title_base_name(base["county"]) or ""
            if nm.startswith(("c_", "b_", "x_")):
                nm = ""
        if nm:
            out["base"] = nm
        counties = rec.get("counties") or []
        if counties:
            out["counties"] = len(counties)
        tgt = rec.get("target")
        if isinstance(tgt, int):
            _t, tid = self._primary_title_at(tgt)
            rn = self.title(tid) if tid is not None else ""
            if rn and rn.startswith(("c_", "b_", "x_")):
                rn = ""
            out["target"] = rn or self.person_label(tgt, date=self.as_of, style="brief")
        return out

    # Cap on "乱连N州": larger counts are usually escalated revolts whose
    # title_members span the whole uprising rather than this leader's following, so
    # they are not written.
    _UPRISING_COUNT_CAP = 12

    def uprising_line(self, cid, name=None):
        """Uprising leader's standalone line: "丁文举起于渠州，乱连六州，反抗唐皇朝。"

        Same shape as the "X死于Y。" lines (standalone, no parenthetical apposition);
        '' when all three parts are missing."""
        info = self.uprising_info(cid)
        if not info:
            return ""
        who = name or self.name_with_regnal(cid) or self.name_or(cid)
        if not who:
            return ""
        parts = []
        if info.get("base"):
            parts.append(f"起于{info['base']}")
        n = info.get("counties") or 0
        if 2 <= n <= self._UPRISING_COUNT_CAP:
            parts.append(f"乱连{_count_zh(n)}州")
        if info.get("target"):
            parts.append(f"反抗{info['target']}")
        return f"{who}{'，'.join(parts)}。" if parts else ""

    @property
    def _name_logs(self):
        """Stack of active label loggers in this thread (nestable; see `log_names`)."""
        st = getattr(self._tls, "logs", None)
        if st is None:
            st = []
            self._tls.logs = st
        return st

    def log_names(self):
        """Open label logging for the current line (context manager, nestable).

        `f.index_names(text, lg)` then records the line with the (cid, label) pairs it used."""
        return _NameLog(self)

    def index_names(self, text, log, owner=None):
        """Register a line and the (cid, label) pairs it used into `name_index`.

        `owner` is the line's subject; the section pass uses it for kin attributes."""
        if text and log is not None and log.items:
            self.name_index[text] = [list(x) for x in log.items]
            if owner is not None:
                try:
                    self.line_owner[text] = int(owner)
                except (TypeError, ValueError):
                    pass
        return text

    def alias_line(self, old, new):
        """Copy a line's label registration onto its rewritten form.

        `name_index`, `line_owner` and `line_stated` are keyed by sentence body, so without the
        alias the section pass loses the line and its kin attributes."""
        if not old or not new or old == new:
            return
        for tbl in (self.name_index, self.line_owner, self.line_stated):
            if old in tbl and new not in tbl:
                tbl[new] = tbl[old]

    def _log_label(self, cid, label):
        """Record one entry in every active logger when `person_label` renders a label."""
        if not label or not self._name_logs:
            return
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return
        for lg in self._name_logs:
            lg.items.append((cid, label))

    # ---- Accolade (勋号) labels -------------------------------------------------
    # Accolades get no section and no line of their own: they are folded into the label exit
    # `person_label`, so an accolade always precedes its holder's name.
    # Save fields (melt["accolades"]["database"]): `name` is an already rendered string,
    # `acclaimed` the current knight, `history` the [{acclaimed, date}] tenure list; always
    # taken at `date`, so a later accolade never lands on an earlier person.
    def _accolade_index(self):
        """{character id: [(start date or None, accolade name), …]} — accolade tenure history,
        built once and cached."""
        if getattr(self, "_acc_idx", None) is not None:
            return self._acc_idx
        idx = {}
        db = (self.melt.get("accolades") or {}).get("database") or {}
        if isinstance(db, dict):
            for _aid, a in db.items():
                if not isinstance(a, dict):
                    continue
                nm = str(a.get("name") or "").strip()
                if not nm:
                    continue
                hist = []
                for h in (a.get("history") or []):
                    if not isinstance(h, dict):
                        continue
                    c, dd = h.get("acclaimed"), h.get("date")
                    if isinstance(c, int) and dd:
                        hist.append((str(dd), c))
                if not hist:
                    # no tenure history (old save / script grant): use `acclaimed` undated
                    c = a.get("acclaimed")
                    if isinstance(c, int):
                        idx.setdefault(c, []).append((None, nm))
                    continue
                hist.sort(key=lambda x: cl.date_key(x[0]))
                for dd, c in hist:
                    idx.setdefault(c, []).append((dd, nm))
        self._acc_idx = idx
        return idx

    def accolade_word_at(self, cid, date=None):
        """Accolade name the character wears at `date` ('' when none), for label prefixing."""
        if cid is None:
            return ""
        try:
            rows = self._accolade_index().get(int(cid)) or []
        except (TypeError, ValueError):
            return ""
        if not rows:
            return ""
        cut = date or self.as_of or self.cache.get("last_date")
        lim = cl.date_key(cut) if cut else None
        best, best_dk = "", None
        for dd, nm in rows:
            if dd is None:            # undated fallback row: only used if no dated row exists
                if best_dk is None:
                    best, best_dk = nm, (0, 0, 0)
                continue
            dk = cl.date_key(dd)
            if lim is not None and dk > lim:
                continue
            if best_dk is None or dk >= best_dk:
                best, best_dk = nm, dk
        return best

    def person_label(self, cid, date=None, style="full"):
        """Single entry point for person labels. `style`:
        - "full": household/lineage — "[former X,] current title Y name";
        - "brief": secrets/hooks/timeline — "current title Y name", no former title;
        - "event": feud events, office as of the event date;
        - "office": court rows, as brief (Eastern name order keeps the clan surname).

        A religious head gets "教宗X"; a landless uprising leader "农民起义领袖X"; an unrecorded
        name returns '' so the caller drops the line; an accolade precedes the name."""
        if cid is None:
            return ""
        key = (int(cid), date or "", style)
        if key in self._label_cache:
            out = self._label_cache[key]
            self._log_label(cid, out)
            return out
        out = self._person_label_uncached(cid, date, style)
        self._label_cache[key] = out
        self._log_label(cid, out)
        return out

    def _person_label_uncached(self, cid, date, style):
        nm = self.name_with_regnal(cid, date)
        if not nm or nm in self._PLACEHOLDER_NAMES:
            return ""
        # Timeline fact lines give the player the name only: the profile section already covers
        # his titles, and a full label on every line only costs attention. Everyone else still
        # uses the brief form (title + name) for recognition.
        if style == "timeline" and cid == self.cache.get("player_id"):
            return nm
        if self._tenno_prince_word(cid, date):
            return nm
        # The accolade sits alongside the office/title word instead of replacing it.
        acc = self.accolade_word_at(cid, date)
        pn = f"{acc}{nm}" if acc else nm
        # Antipope: full label for timeline/fact lines. Must come before
        # `official_title`, otherwise it falls into the former-office fallback
        # (`religious_head_word` is a generic word with no locating prefix).
        apw = self.antipope_label(cid, date)
        if apw:
            return f"{apw}{pn}"
        rhw = self.religious_head_word(cid)
        if rhw:
            return f"{rhw}{pn}"
        off = self._event_office(cid, date) if style == "event" \
            else self.official_title(cid, date)
        if not off:
            # No landed title: take a prince/princess word from the father's or
            # mother's title, as the profile section does
            off = self.prince_title(cid, date) or ""
        if not off:
            # Landless uprising leader: the uprising word serves as the title
            word = self.faction_word(cid)
            if word:
                off = f"{word}领袖"
        if style == "full":
            return self._full_label(cid, date, off, pn)
        return f"{off}{pn}" if off else pn

    def event_name(self, cid, date=None):
        """Subject name for timeline/fact lines: the name only for the player, a brief label
        for everyone else.

        The single exit for every name entering the timeline or the secret/feud streams."""
        if cid is None:
            return ""
        return self.person_label(cid, date, style="timeline") \
            or self.name_with_regnal(cid, date)

    def _event_office(self, cid, date):
        """The current office in a feud event, as "title name + office word" at the event date.

        The government is read from the title side: a character's landed data can be cleared for
        the dead or for that point in time, while the title's government stays."""
        tier, tid = self._primary_title_at(cid, as_of=date)
        if tid is None or tier is None:
            return ""
        tname = self._name_at_date(tid, date) or self.title_base_name(tid)
        if not tname:
            return ""
        _indep = self._is_independent(cid, date)
        word = self._office_word(tier, self._gov_for_word(cid, tid, date),
                                 independent=bool(_indep) if _indep is not None else True,
                                 female=self._is_female(cid), tid=tid, cid=cid,
                                 date=date)
        return f"{tname}{word}" if word else tname

    def _full_label(self, cid, date, cur, nm):
        """full-style label: a former title is prefixed only when its tier is higher than the
        current one; the same tid held now and then is not a former title.

        All three lookups share one anchor (`_anchor_date`, which folds post-death dates back),
        or a dead character would lose his current title in favour of a "former" one."""
        anchor = self._anchor_date(cid, date)
        # With no current office there is no current title, so the most recent high
        # title must not be excluded as if it were one (that would squeeze out a higher
        # former title in favour of a lower one).
        cur_tid = self._current_title_tid(cid, anchor) if cur else None
        cur_rank = 0
        if cur_tid is not None:
            key = (self._lt.get(str(cur_tid)) or {}).get("key") or ""
            cur_rank = self._TT_RANK.get(key[:2], 0)
        former_tid = self._former_high_title(cid, anchor, exclude_tid=cur_tid)
        f_rank = 0
        if former_tid is not None:
            key = (self._lt.get(str(former_tid)) or {}).get("key") or ""
            f_rank = self._TT_RANK.get(key[:2], 0)
        if cur and former_tid is not None and f_rank > cur_rank:
            ft = self._former_title_text(cid, former_tid, anchor)
            if ft and ft != cur:
                return f"前{ft}，{cur}{nm}"
            return f"{cur}{nm}"
        if cur:
            return f"{cur}{nm}"
        if former_tid is not None:
            ft = self._former_title_text(cid, former_tid, anchor)
            if ft:
                return f"前{ft}{nm}"
        pw = self.prince_title(cid, anchor)
        if pw:
            return f"{pw}{nm}"
        return nm

    def kin_label(self, cid, date=None):
        """Label for kin, lineage and in-laws — person_label's full entry point.

        `date` defaults to `self.as_of`, so office words follow the chapter's cutoff date."""
        return self.person_label(cid, date or self.as_of, "full")

    def _minister_office(self, tid):
        """Office word of an e_minister_* title; '' for other titles.

        Keys are tried as a candidate chain: minister_revenue and minister_rites have no
        localization entry, and the game shows those offices with the celestial council keys."""
        if tid is None:
            return ""
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if not key.startswith("e_minister_"):
            return ""
        loc_key = self._MINISTER_OFFICE_KEYS.get(key)
        cands = []
        if loc_key:
            cands.append(loc_key)
            cands.extend(self._MINISTER_OFFICE_FALLBACKS.get(loc_key, ()))
        for c in cands:
            v = L.loc(self.table, c)
            # reject unresolved references ($X$ / [X]) and English fallbacks (pure-ASCII words)
            if v and not v.startswith("$") and not v.startswith("[") \
                    and not re.search(r"[A-Za-z]{2,}", v):
                return v
        return self.title_base_name(tid) or "尚书"

    # Office word for holders of landless family estate titles (x_nf_*), chosen by
    # culture template (game localization keys: Japan 当主/女士, Korea 户长/夫人,
    # others 乡绅/夫人)
    _KOREAN_ESTATE_TPL = {"korean", "silla", "goryeo", "baekje",
                          "goguryeo", "balhae", "khitan"}

    def _estate_holder_word(self, cid):
        """Estate holder word, taken from the game's own text.

        The East Asian branches use their localization keys (Japan 当主/女士, Korea 户长/夫人,
        celestial 乡绅/夫人); everyone else uses `game_concept_house_head` = 家主."""
        female = self._is_female(cid)
        tpl = self.culture_template(cid) or ""
        if tpl == "japanese":
            key = "estate_holder_female_japanese" if female else "estate_holder_male_japanese"
        elif tpl in self._KOREAN_ESTATE_TPL:
            key = "estate_holder_female_korean" if female else "estate_holder_male_korean"
        elif tpl in self._EAST_ASIAN_ESTATE_TPL:
            key = "celestial_estate_holder_female" if female else "celestial_estate_holder_male"
        else:
            key = "game_concept_house_head"
        v = L.loc(self.table, key)
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        if key == "game_concept_house_head":
            return "家主"
        return "夫人" if female else "乡绅"

    def holder_at(self, tid, date=None):
        """Holder id of a title at `date` (last title-history entry at or before it); None
        with no record or after the title was destroyed. With `date` None, the melt's
        current holder."""
        if tid is None:
            return None
        if date is None:
            h = (self._lt.get(str(tid)) or {}).get("holder")
            return int(h) if isinstance(h, int) else None
        seq = self._title_seqs.get(int(tid)) or []
        if not seq:
            return self.holder_at(tid)
        dk = cl.date_key(date)
        holder = None
        for d, ev in seq:
            if cl.date_key(d) > dk:
                break
            entries = ev if isinstance(ev, list) else [ev]
            for e in entries:
                if isinstance(e, dict):
                    h, typ = e.get("holder"), e.get("type") or ""
                else:
                    h, typ = e, ""
                if typ == "destroyed":
                    holder = None
                    continue
                if h is None:
                    holder = None
                    continue
                try:
                    holder = int(h)
                except (TypeError, ValueError):
                    continue
        return holder

    def _my_realm_tids(self):
        """Title id set of the realm the player sits in: his primary title plus every title up
        its liege chain.

        A ministry office counts as his own only when its `de_facto_liege` is in this set, so
        other realms' offices never leak in."""
        pid = self.cache.get("player_id")
        if pid is None:
            return set()
        out = set()
        _tier, ptid = self._primary_title_at(pid)
        if ptid is None:
            cut = (self.as_of
                   or (self.cache.get("reign_end") or {}).get("date")   # abdication date
                   or (self.cache.get("player_death") or {}).get("date")
                   or self.cache.get("last_date"))
            if cut:
                _tier, ptid = self._primary_title_at(pid, held_through=cut)
        if ptid is not None:
            out.add(int(ptid))
            for tid, _h in self.liege_chain(ptid) or []:
                out.add(int(tid))
        if not out:
            # no title (landless adventurer etc.): take the player's camp/estate titles
            ld = ((self.cache.get("characters") or {}).get(str(pid)) or {}).get("landed") or {}
            for x in ld.get("domain") or []:
                if isinstance(x, int):
                    out.add(int(x))
        return out

    def _realm_title_set(self):
        """Compatibility alias for `_my_realm_tids`."""
        return self._my_realm_tids()

    def _ever_held_title(self, tid):
        """Whether this high title ever existed, by three checks:

        ① `history` is non-empty; ② it has a `holder` now; ③ a `realm_history` snapshot saw a
        non-empty holder. Title history gets pruned for destroyed titles, so ③ cannot be dropped.

        The de jure fallback (`_realm_facts._up_liege`) may only land on titles that existed,
        since the save gives `de_jure_liege` for never-created empty titles too."""
        if tid is None:
            return False
        t = self._lt.get(str(tid)) or {}
        if t.get("history") or t.get("holder") is not None:
            return True
        if getattr(self, "_rh_seen_tids", None) is None:
            seen = set()
            for h in (self._realm_snaps or []):
                for _t, _h in (h.get("holders") or {}).items():
                    if _h is None:
                        continue
                    try:
                        seen.add(int(_t))
                    except (TypeError, ValueError):
                        continue
            self._rh_seen_tids = seen
        try:
            return int(tid) in self._rh_seen_tids
        except (TypeError, ValueError):
            return False

    def legal_children(self, cid):
        """Set of cid's legal children: every child whose save `family` lists cid, including
        openly illegitimate ones.

        The field follows cid's own gender — a female cid compares her children's `mother` —
        and children of someone else's legal parentage belong to the wife's section."""
        out, _ = self.legal_children_ex(cid)
        return out

    def legal_children_ex(self, cid):
        """Same as `legal_children`, also returning whether genealogy data exists at all.

        Callers keep the original list when there is no data."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        kids = [k for k in (fam.get("child") or []) if isinstance(k, int)]
        if not kids:
            return set(), False
        # Female → compare the child's `mother` field; male → `father`. With no recorded
        # sex, compare both (a union is safer than dropping a child).
        female = self._is_female(cid)
        want = ["mother"] if female else ["father"]
        if not female and rec.get("female") is None:
            want = ["father", "mother"]
        out = set()
        for k in kids:
            kf = ((self.cache.get("characters") or {}).get(str(k)) or {}).get("family") or {}
            for w in want:
                if cid in [x for x in (kf.get(w) or []) if isinstance(x, int)]:
                    out.add(k)
                    break
        return out, True

    def wife_other_children(self, cid):
        """Children the spouse had with someone else, where cid is neither father nor mother.

        These are the household section's "spouse's children" and do not join cid's own list."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        legal, has = self.legal_children_ex(cid)
        if not has:
            return set()
        out = set()
        for sid in dict.fromkeys((fam.get("primary_spouse") or [])
                                 + (fam.get("spouse") or [])):
            if not isinstance(sid, int):
                continue
            srec = (self.cache.get("characters") or {}).get(str(sid)) or {}
            for k in (srec.get("family") or {}).get("child") or []:
                if isinstance(k, int) and k not in legal:
                    out.add(k)
        return out

    def wife_other_children_line(self, cid, kids=None):
        """Render the spouse's children by another parent as one ready-to-write sentence.

        Grouped by (mother, biological father) and stated per father, each child taking the
        biological father's house; '' when there is nothing to write."""
        chars = self.cache.get("characters") or {}
        kids = list(kids if kids is not None else self.wife_other_children(cid))
        if not kids:
            return ""
        # (mother, father) → [child ids], stably ordered by first appearance
        groups = {}
        order = []
        for k in sorted(kids, key=lambda x: str(x)):
            rec = chars.get(str(k)) or {}
            kf = rec.get("family") or {}
            mom = (kf.get("mother") or [None])[0]
            dad = (kf.get("real_father") or kf.get("father") or [None])[0]
            key = (mom, dad)
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append(k)
        parts = []
        total = 0
        _kids_all = []
        prev_mom = None
        for (mom, dad) in order:
            mname = self.kin_label(mom) if isinstance(mom, int) else ""
            dname = self.kin_label(dad) if isinstance(dad, int) else ""
            sons, daughters = [], []
            for k in groups[(mom, dad)]:
                if not self.name(k):
                    continue
                _kids_all.append(k)
                (daughters if self._is_female(k) else sons).append(self.kin_label(k))
            bits = []
            if sons:
                bits.append("子" + "、".join(sons))
            if daughters:
                bits.append("女" + "、".join(daughters))
            if not bits:
                continue
            body = "、".join(bits)
            total += len(sons) + len(daughters)
            if dname:
                if mname and mom == prev_mom:
                    lead = f"又与{dname}生"          # second partner of the same mother
                elif mname:
                    lead = f"{mname}与{dname}生"
                else:
                    lead = f"与{dname}生"
            else:
                lead = f"{mname}另育有" if mname else "另育有"
            parts.append(f"{lead}{body}")
            prev_mom = mom
        if not parts:
            return ""
        if total == 1:
            n = "此女" if self._is_female(_kids_all[0]) else "此子"
        elif total == 2:
            n = "此二人"
        elif total == 3:
            n = "此三人"
        else:
            n = f"此{total}人"
        return "；".join(parts) + f"。{n}各随生父之氏。"

    def _current_ministers(self, date=None):
        """Holders of the court ministries at `date` (default: the melt's save) as
        ['兵部尚书任清', …], for the court section.

        The office word comes first, with "department name：person" as a fallback, and holders
        are taken as of `date` so a later appointment never lands in an earlier decade.

        Only the player's own realm is collected (every `e_minister_*` would hang the Tang six
        boards on an unrelated prince's court); fail-closed when the realm is unknown."""
        d = date if date is not None else self.as_of
        mine = self._my_realm_tids()
        out = []
        for tid, t in self._lt.items():
            if not isinstance(t, dict):
                continue
            key = t.get("key") or ""
            if not key.startswith("e_minister_"):
                continue
            lc = t.get("de_facto_liege")
            if lc not in mine:      # empty `mine` ⇒ nothing is collected (fail-closed)
                continue
            holder = self.holder_at(int(tid), d)
            if not isinstance(holder, int):
                continue
            nm = self.name_or(holder)
            off = self._minister_office(int(tid))
            # no office word resolved: use "某职司" rather than the raw e_minister_ key
            base = self.title_base_name(int(tid)) or "某职司"
            if off and off != base:
                out.append(f"{off}{nm}")
            else:
                out.append(f"{base}：{nm}")
        return out

    def minister_ids(self, date=None):
        """Ids of the court ministry (e_minister_*) holders at `date`, used to source key
        officials' secrets.

        Same scope as `_current_ministers`, fail-closed."""
        d = date if date is not None else self.as_of
        mine = self._my_realm_tids()
        out = []
        for tid, t in self._lt.items():
            if not isinstance(t, dict):
                continue
            if not (t.get("key") or "").startswith("e_minister_"):
                continue
            lc = t.get("de_facto_liege")
            if lc not in mine:      # empty `mine` ⇒ nothing is collected (fail-closed)
                continue
            h = self.holder_at(int(tid), d)
            if isinstance(h, int) and h not in out:
                out.append(h)
        return out

    # ---- Secrets (隐事) ----

    def _secret_cut(self):
        """Cutoff for secret facts: `as_of` first, else the cache's last save date."""
        return self.as_of or self.cache.get("last_date")

    def secrets_owned_by(self, cid, date=None):
        """Secret records a person holds at `date`, ascending by first-seen date.

        Filter: matching owner + first_seen ≤ date + not yet lost (lost_at > date)."""
        if cid is None:
            return []
        cut = date or self._secret_cut()
        ck = cl.date_key(cut) if cut else None
        out = []
        for sid, rec in (self.cache.get("secrets_history") or {}).items():
            if not isinstance(rec, dict) or rec.get("owner") != cid:
                continue
            fs = rec.get("first_seen")
            if ck is not None and fs and cl.date_key(fs) > ck:
                continue
            la = rec.get("lost_at")
            if ck is not None and la and cl.date_key(la) <= ck:
                continue
            out.append(dict(rec, id=str(sid)))
        out.sort(key=lambda r: cl.date_key(r.get("first_seen") or "9999.9.9"))
        return out

    def _first_seen_note(self, rec):
        """Secret year phrase: "879年为外人所知"; '' when no year can be given.

        The wording stays inside the world (as `RULES["secret"]` asks) and avoids pipeline words
        such as 记载/见载/未载, which the model otherwise copies into scholarly filler."""
        fs = rec.get("first_seen")
        if not fs or rec.get("first"):
            return ""
        return f"{self._year_only(fs)}为外人所知"

    def _blood_kin(self, cid):
        """Set of cid's blood kin: parents, children and siblings.

        In-laws never count — incest is judged on blood only."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        out = set()
        for key in ("father", "mother", "child", "siblings"):
            for x in fam.get(key) or []:
                if isinstance(x, int) and x != cid:
                    out.add(x)
        # reverse relations where cid appears in another character's family fields (the
        # cache merges both directions; this also covers the melt side)
        for _cid, r in (self.cache.get("characters") or {}).items():
            rf = (r.get("family") or {})
            if cid in (rf.get("father") or []) or cid in (rf.get("mother") or []):
                try:
                    out.add(int(_cid))
                except (TypeError, ValueError):
                    continue
        return out

    def _sex_partner_mems(self, cid):
        """cid's sexual/romantic memories as [(date, other id)], ascending by date.

        Includes the Carnalitas `had_sex_*` family."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        out = []
        for m in rec.get("memories") or []:
            t = str(m.get("type") or "")
            if t not in _SEX_MEM_TYPES and not t.startswith(_SEX_MEM_PREFIX):
                continue
            parts = m.get("participants") or {}
            other = None
            for slot in _SEX_MEM_OTHER_KEYS:
                v = parts.get(slot)
                if isinstance(v, int) and v != cid:
                    other = v
                    break
            if other is None:
                # fallback: the single int participant other than cid
                cands = [v for v in parts.values()
                         if isinstance(v, int) and v != cid]
                if len(cands) == 1:
                    other = cands[0]
            if other is not None:
                out.append((str(m.get("creation_date") or ""), other))
        out.sort(key=lambda x: cl.date_key(x[0]) if x[0] else (0, 0, 0))
        return out

    def _secret_partner(self, rec):
        """Other party of a secret whose counterpart is not saved (incest and the like); None
        when undecidable.

        `secret_incest` has only the holder (`target` is empty), so the counterpart is blood kin
        ∩ sexual/romantic memories, earliest first; in-laws are excluded."""
        if not isinstance(rec, dict):
            return None
        owner = rec.get("owner")
        if not isinstance(owner, int):
            return None
        kin = self._blood_kin(owner)
        if not kin:
            return None
        for d, other in self._sex_partner_mems(owner):
            if other in kin:
                return other
        return None

    def _secret_partner_label(self, rec, self_cid=None):
        """Label of the other party (person_label brief; the record's own holder is "自己").

        "自己" follows the record's holder, not `self_cid`, so a family member's secret never
        calls the player "自己"."""
        o = self._secret_partner(rec)
        if o is None:
            return ""
        owner = rec.get("owner") if isinstance(rec, dict) else None
        if isinstance(owner, int) and o == owner:
            return "自己"
        return self.event_name(o, date=self.as_of) or ""

    def secret_topic(self, rec, self_cid=None):
        """Secret topic phrase without the holder: "在张朴主持的乡试中舞弊" / "谋害叠溪寋" /
        "与阿足私通"; unknown types fall back to the game's localization type name.

        Related characters carry their titles and the holder is written as "自己". Exam cheating
        states direction and level: `target` is the examiner who ran the exam."""
        if not isinstance(rec, dict):
            return ""
        tp = rec.get("type") or ""
        tgt = rec.get("target")
        owner = rec.get("owner")

        def _self_or(cid):
            """cid → "自己" (the holder himself) or the standard label."""
            if not isinstance(cid, int):
                return ""
            if isinstance(owner, int) and cid == owner:
                return "自己"
            return self.event_name(cid, date=self.as_of) or ""

        tname = _self_or(tgt) if isinstance(tgt, int) else ""
        if not tname and tp == "secret_incest":
            # For incest `target` is always empty (each side holds its own record), so the
            # counterpart comes from blood kin ∩ sexual memories (in-laws excluded); when
            # undecidable the plain "乱伦" form below is used — the program decides.
            tname = self._secret_partner_label(rec)
        if tp == "secret_exam_cheater":
            lvl = self._exam_level_for_secret(rec.get("owner"), rec.get("first_seen"))
            where = f"{tname}主持的{lvl}" if tname else (lvl or "科考")
            return f"在{where or '科考'}中舞弊" if (tname or lvl) else "科考舞弊"
        if tp in ("secret_disputed_heritage",
                  "secret_unmarried_illegitimate_child"):
            # Bloodline secrets must name the biological father, or the text cannot show that
            # the player's daughter married the player's own illegitimate son. The father comes
            # from the child's `real_father` (filled in by secret inference).
            tpl = SECRET_TOPICS.get(tp)
            if not tpl or not isinstance(tgt, int):
                return ""
            child = self.person_label(tgt, date=self.as_of, style="brief") or ""
            if not child:
                return ""
            crec = (self.cache.get("characters") or {}).get(str(tgt)) or {}
            rf = ((crec.get("family") or {}).get("real_father") or [None])[0]
            rn = _self_or(rf)
            if rn:
                return tpl.format(target=child, father=rn)
            # biological father unknown → short template without the father slot
            return SECRET_TOPICS_NO_FATHER.get(tp, "").format(target=child)
        tpl = SECRET_TOPICS.get(tp)
        if tpl:
            if "{target}" in tpl:
                if tname:
                    return tpl.format(target=tname)
                # counterpart not in the save and undecidable → the short form
                return SECRET_TOPICS_NO_TARGET.get(tp, "隐情")
            # Template without a target slot but a target exists: append it as a clause so
            # similar secrets stay distinguishable ("科举舞弊，事涉唐皇帝李漼")
            return f"{tpl}，事涉{tname}" if tname else tpl
        z = L.loc(self.table, tp) or ""
        if not z or re.search(r"[A-Za-z_]", z):
            return ""
        z = re.sub(r"者$", "", z)          # the type name is a noun ("考试舞弊者") — drop 者
        return f"{z}，事涉{tname}" if tname else z

    def _exam_level_for_secret(self, owner, first_seen):
        """Exam level of an exam-cheating secret, from the exam memory first seen in the same
        snapshot as the secret (nearest earlier one as fallback, else '')."""
        if owner is None:
            return ""
        keys = {"passed_child_exam_memory": "童子试",
                "passed_provincial_exam_memory": "乡试",
                "passed_metropolitan_exam_memory": "会试",
                "passed_palace_exam_memory": "殿试"}
        rec = (self.cache.get("characters") or {}).get(str(owner)) or {}
        exact, same_year, nearest = "", "", ""
        fs = str(first_seen or "")
        fs_year = fs.split(".")[0]
        best_dk = None
        for mem in rec.get("memories") or []:
            lvl = keys.get(mem.get("type") or "")
            if not lvl:
                continue
            seen = str(mem.get("first_seen") or "")
            if fs and seen == fs:
                exact = exact or lvl
            if fs_year and seen.split(".")[0] == fs_year:
                same_year = same_year or lvl
            if fs and seen and cl.date_key(seen) <= cl.date_key(fs):
                dk = cl.date_key(seen)
                if best_dk is None or dk > best_dk:
                    best_dk, nearest = dk, lvl
        return exact or same_year or nearest

    def secret_sentence(self, rec, owner_label=None, self_cid=None):
        """Secret sentence: "陆荣廷有一桩隐事：科举舞弊，事涉唐皇帝李漼，873年见于记载。"
        (no year for a secret present at the start of the data); target and year are clauses.

        Predicate-type topics (私通/乱伦/谋害/暗行巫术…) are written bare as "{owner}{topic}"."""
        if not isinstance(rec, dict):
            return ""
        topic = self.secret_topic(rec, self_cid=self_cid)
        if not topic:
            return ""
        owner = owner_label if owner_label is not None \
            else self.name_or(rec.get("owner"))
        if not owner:
            return ""
        if _style.secret_topic_is_predicate(rec.get("type")):
            s = f"{owner}{topic}"
        else:
            s = f"{owner}有一桩隐事：{topic}"
        note = self._first_seen_note(rec)
        if note:
            s += f"，{note}"
        return s + "。"

    def secret_knowers(self, rec, self_cid=None):
        """Knower phrase without the final period: "知情者：卢从度，同年；孙元忠，自873年起";
        '' when no third party knows. Knowers of the same year share one year.

        Knowers = known_by − holder − parties, since those necessarily knew already."""
        if not isinstance(rec, dict):
            return ""
        owner = rec.get("owner")
        parties = {x for x in (rec.get("participants") or []) if isinstance(x, int)}
        # For affair-type secrets the `target` is the other party (participants list only the
        # holder): exclude it too, or the line reads "…had an affair with Qiao, knowers: Qiao".
        if (rec.get("type") or "") in _SECRET_PARTY_TARGET_TYPES \
                and isinstance(rec.get("target"), int):
            parties.add(rec["target"])
        # The incest counterpart is not in `target` but has been determined from blood kin
        # ∩ sexual memories, so it is a party too and must not reappear as a knower.
        if (rec.get("type") or "") == "secret_incest":
            _p = self._secret_partner(rec)
            if isinstance(_p, int):
                parties.add(_p)
        seen = self._year_only(rec.get("first_seen")) if self._first_seen_note(rec) else ""
        groups = []            # [(year text or '', [names…])] — grouped by year
        index = {}
        total = 0
        for k in rec.get("known_by") or []:
            kid = k.get("id")
            if not isinstance(kid, int) or kid == owner or kid in parties:
                continue
            nm = self.name_with_regnal(kid) if kid == self_cid \
                else self.person_label(kid, date=self.as_of, style="brief")
            if not nm:
                continue
            frm = k.get("from")
            yr = self._year_only(frm) if (frm and not k.get("first")) else ""
            g = index.get(yr)
            if g is None:
                g = (yr, [])
                index[yr] = g
                groups.append(g)
            g[1].append(nm)
            total += 1
            if total >= 6:
                break
        if not groups:
            return ""
        # Sort by year with undated group first (otherwise "自875年起、自873年起" appears)
        groups.sort(key=lambda g: (1, cl.date_key(g[0])) if g[0] else (0, (0,)))
        parts = []
        for yr, names in groups:
            who = "、".join(names)
            if not yr:
                parts.append(who)
            elif seen and yr == seen:
                # the year is already written by the first-seen note, so write it once
                parts.append(f"{who}，同年")
            else:
                parts.append(f"{who}，自{yr}起")
        return "知情者：" + "；".join(parts)

    def note_line_stated(self, text, mem, owner_id=None):
        """A line whose wording already states the relation → register the counterpart so the
        section pass adds no kin attribute to it.

        Decided by memory type + participant slot, never by wording: the marriage, intercourse,
        widowhood, birth and stillbirth templates already name the relation."""
        mtype = str((mem or {}).get("type") or "")
        if not text or mtype not in _REL_STATED_TYPES:
            return
        slot = PARTICIPANT_SLOTS.get(mtype)
        oid = ((mem or {}).get("participants") or {}).get(slot) if slot else None
        if not isinstance(oid, int) or oid == owner_id:
            return
        # "同房" states a relation only for an actual spouse pair (others get "有私情")
        if mtype == "had_sex" and not self.is_spouse_pair(owner_id, oid):
            return
        self.line_stated[text] = [int(oid)]

    def secret_line(self, rec, owner_label=None, knowers=True, self_cid=None,
                    owner=None):
        """One secret line: "{owner}有一桩隐事：{topic}，事涉X，Y年见于记载；知情者：A，同年；B，自Z年起。"
        — secret and knowers in one sentence.

        `owner` is the secret holder's id (this line's subject)."""
        with self.log_names() as lg:
            out = self._secret_line_body(rec, owner_label=owner_label,
                                         knowers=knowers, self_cid=self_cid)
        return self.index_names(out, lg, owner=owner)

    def _secret_line_body(self, rec, owner_label=None, knowers=True, self_cid=None):
        s = self.secret_sentence(rec, owner_label=owner_label, self_cid=self_cid)
        if not s or not knowers:
            return s
        kl = self.secret_knowers(rec, self_cid=self_cid)
        return s[:-1] + "；" + kl + "。" if kl else s


    def secret_lines(self, recs, owner_label=None, self_cid=None, with_knowers=True,
                     owner=None):
        """Merge one holder's secrets into one line (saves tokens), e.g.
        "陆荣廷有隐事二桩：科举舞弊（涉及樊骥）；会试舞弊（涉及唐皇帝李漼，873年见载），
        知情者：卢从度（自875年起）。"

        Each secret keeps its own year and knowers; a single secret matches `secret_line`.
        Returns [str], [] when no topic is usable."""
        with self.log_names() as lg:
            out = self._secret_lines_body(recs, owner_label=owner_label,
                                          self_cid=self_cid,
                                          with_knowers=with_knowers, owner=owner)
        for ln in (out or []):
            self.index_names(ln, lg, owner=owner)
        return out

    def _secret_lines_body(self, recs, owner_label=None, self_cid=None,
                           with_knowers=True, owner=None):
        items = [r for r in (recs or []) if isinstance(r, dict)]
        if not items:
            return []
        owner = owner_label
        if owner is None:
            owner = self.name_or(items[0].get("owner"))
        if not owner:
            return []
        if len(items) == 1:
            ln = self.secret_line(items[0], owner_label=owner, self_cid=self_cid,
                                  knowers=with_knowers, owner=owner)
            return [ln] if ln else []
        # Predicate-type topics each become their own sentence ("X与Y私通，1072年见于记载。"),
        # while noun-type ones still merge into "X有隐事N桩：…" — mixing the two
        # half-sentences reads badly.
        blocks = []          # [(is_predicate, [rec…])] in original (date-sorted) order
        for r in items:
            pred = _style.secret_topic_is_predicate(r.get("type"))
            if blocks and blocks[-1][0] == pred:
                blocks[-1][1].append(r)
            else:
                blocks.append((pred, [r]))
        out = []
        for pred, group in blocks:
            if pred:
                for r in group:
                    ln = self.secret_line(r, owner_label=owner, self_cid=self_cid,
                                          knowers=with_knowers, owner=owner)
                    if ln:
                        out.append(ln)
                continue
            clauses = []
            for r in group:
                topic = self.secret_topic(r, self_cid=self_cid)
                if not topic:
                    continue
                note = self._first_seen_note(r)
                if note:
                    # the first-seen year becomes a clause after the topic, not a
                    # parenthetical
                    topic += f"，{note}"
                kn = self.secret_knowers(r, self_cid=self_cid) if with_knowers else ""
                if kn:
                    topic += "，" + kn
                clauses.append(topic)
            if clauses:
                out.append(f"{owner}有隐事{_count_zh(len(clauses))}桩："
                           + "；".join(clauses) + "。")
        return out

    def secrets_known_by(self, cid, date=None):
        """Secret records cid knows about but does not own (the leverage dimension)."""
        cut = date or self._secret_cut()
        ck = cl.date_key(cut) if cut else None
        out = []
        for sid, rec in (self.cache.get("secrets_history") or {}).items():
            if not isinstance(rec, dict) or rec.get("owner") == cid:
                continue
            for k in rec.get("known_by") or []:
                if k.get("id") != cid:
                    continue
                fs = k.get("from")
                if ck is not None and fs and cl.date_key(fs) > ck:
                    continue
                out.append(dict(rec, id=str(sid)))
                break
        return out

    # ------------------------------------------------------------------
    # Court identity / consort affairs / hooks / domain-title folding
    # ------------------------------------------------------------------

    def court_service_phrase(self, cid, actor_label=None):
        """Court identity phrase: "主角廷中骑士，自869年6月4日在廷".

        Source is `court_data` (cache key `court`), emitted only when the employer is the player."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        ct = rec.get("court") or {}
        pid = self.cache.get("player_id")
        if not ct or pid is None or ct.get("employer") != pid:
            return ""
        who = actor_label or "主角"
        key = "court_knight" if ct.get("knight") else "court_member"
        word = _FACT_WORDING[key].format(actor=who)
        jd = ct.get("join_court_date")
        if jd:
            since = _FACT_WORDING["affair_joined_court"].format(date=self.date(jd))
            return f"{word}，{since}"
        return word

    def domain_titles(self, dom):
        """Fold domain titles: returns (kept ids, folded ids).

        A county's capital barony is implied by that county (listing both writes one holding as
        two places), and baronies never enter the list.

        Kept = the top tier plus actually held counties, since only counties can be worked
        directly; a family estate (x_nf_*) stays only when there is no county at all."""
        ids = [int(t) for t in (dom or []) if isinstance(t, int)]
        held = set(ids)

        def _rank(tid):
            return self._TT_RANK.get(
                ((self._lt.get(str(tid)) or {}).get("key") or "")[:2], 0)

        keep, folded = [], set()
        for tid in ids:
            t = self._lt.get(str(tid)) or {}
            if _rank(tid) == 1:      # baronies are implied by the county they belong to
                folded.add(tid)
                continue
            cap = t.get("capital")
            if t.get("capital_barony") and isinstance(cap, int) \
                    and cap != tid and cap in held:
                folded.add(tid)
                continue
            keep.append(tid)
        # keep only the top tier + counties (an estate stays only when no county exists)
        top = max((_rank(t) for t in keep), default=0)
        has_county = any(_rank(t) == 2 for t in keep)
        out = []
        for tid in keep:
            rank = _rank(tid)
            if rank == 2 or rank == top:
                out.append(tid)
            elif rank == 0 and not has_county:
                out.append(tid)      # pure clan: the estate is all the land it has
            else:
                folded.add(tid)
        return out, folded

    def consort_affairs(self, cid, spouses=None):
        """Consort affair threads: [{spouse, spouse_label, partner, identity, arc}].

        One entry per lover, the arc aggregated from cached memories by person; the identity
        phrase comes from `court_service_phrase`."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        pid = self.cache.get("player_id")
        if spouses is None:
            spouses = []
            for k in ("primary_spouse", "spouse", "former_spouses",
                      "concubine", "former_concubines"):
                spouses += [x for x in (fam.get(k) or []) if isinstance(x, int)]
        ao = cl.date_key(self.as_of) if self.as_of else None
        out = []
        for sid in dict.fromkeys(spouses):
            if sid == cid:
                continue
            srec = (self.cache.get("characters") or {}).get(str(sid)) or {}
            groups = {}
            for mem in srec.get("memories") or []:
                tp = mem.get("type")
                slot = _AFFAIR_SLOTS.get(tp)
                if not slot:
                    continue
                d = mem.get("creation_date")
                if ao is not None and d and cl.date_key(d) > ao:
                    continue
                other = (mem.get("participants") or {}).get(slot)
                if not isinstance(other, int) or other in (sid, pid, cid):
                    continue
                groups.setdefault(other, []).append((str(d or ""), tp))
            for partner, mems in groups.items():
                mems.sort(key=lambda x: cl.date_key(x[0]))
                parts = []
                seen_first = set()
                repeats = []
                for d, tp in mems:
                    if tp == "had_sex" and "had_sex" in seen_first:
                        repeats.append(str(d).split(".")[0])
                        continue
                    seen_first.add(tp)
                    key = {"had_sex": "affair_entry",
                           "became_lovers": "affair_lovers",
                           "became_soulmates": "affair_soulmates",
                           "broke_up_lovers": "affair_broke_up",
                           "lover_died": "affair_lover_died"}.get(tp)
                    if not key:
                        continue
                    parts.append(_FACT_WORDING[key].format(date=self.date(d)))
                if repeats:
                    yrs = "、".join(f"{y}年" for y in repeats[:4])
                    parts.append(_FACT_WORDING["affair_repeat"].format(years=yrs))
                if not parts:
                    continue
                out.append({
                    "spouse": sid,
                    "spouse_label": self.person_label(sid, date=self.as_of, style="brief")
                                    or self.name_or(sid),
                    "partner": partner,
                    "identity": self.court_service_phrase(partner),
                    "arc": "，".join(parts),
                })
        out.sort(key=lambda e: (e["spouse"], str(e["arc"])))
        return out

    def _hook_meta(self, tp):
        return (L.hook_type_table().get("hook_types") or {}).get(tp or "") or {}

    def _hook_name(self, tp):
        """Quoted hook name, e.g. 「干了我老婆」; '' when the localization is missing."""
        nm = L.hook_type(self.table, tp or "")
        return f"「{nm}」" if nm else ""

    def _hook_since(self, rec):
        if rec.get("first") or not rec.get("first_seen"):
            return ""
        return _FACT_WORDING["hook_since"].format(
            year=self._year_only(rec["first_seen"]))

    # House-head hooks never reach the fact layer: `house_head_hook` comes with the house-head
    # identity itself, not from a narrative deed, so it would only fill the secrets section
    # (cache_lib skips them on ingest, see `hook_type_kept`; this also guards older caches).
    # Only whitelisted types are emitted — see `style.hook_type_kept`.
    def _hook_kept(self, tp):
        return _style.hook_type_kept(tp)

    def hook_lines(self):
        """Hook facts: {"held": [hooks the player holds], "over": [hooks others hold over him]}.

        Direction comes from the cache's resolved `holder`/`target`; strength is `strong` in
        `common/hook_types`; hooks of one type merge into one line.

        Types pass the `style.hook_type_kept` whitelist, and only hooks seen before as_of and
        still held then are emitted."""
        pid = self.cache.get("player_id")
        if pid is None:
            return {}
        ao = cl.date_key(self.as_of) if self.as_of else None
        # the player gets the name only (event_name); the profile names his titles once
        plabel = self.event_name(pid, self.as_of) or "主角"
        recs = []
        for rec in (self.cache.get("hooks") or {}).values():
            if not isinstance(rec, dict):
                continue
            if not self._hook_kept(rec.get("type")):
                continue
            fs, la = rec.get("first_seen"), rec.get("lost_at")
            if ao is not None and fs and cl.date_key(fs) > ao:
                continue
            if ao is not None and la and cl.date_key(la) <= ao:
                continue
            if not isinstance(rec.get("holder"), int) \
                    or not isinstance(rec.get("target"), int):
                continue
            recs.append(rec)
        out = {}
        for direction, mine in (("held", True), ("over", False)):
            sel = [r for r in recs if (r["holder"] == pid) == mine]
            groups = {}
            for r in sel:
                groups.setdefault(
                    (r.get("type"), bool(self._hook_meta(r.get("type")).get("strong"))),
                    []).append(r)
            lines = []
            for (tp, strong), rs in groups.items():
                name = self._hook_name(tp)
                word = _FACT_WORDING["hook_strong_word"] if strong else ""
                if len(rs) > 1:
                    # merged line: the counterpart depends on direction (player holds →
                    # target; others over player → holder)
                    ids = [(r["target"] if mine else r["holder"]) for r in rs]
                    names = "、".join(
                        (self.person_label(i, date=self.as_of, style="brief") or "某人")
                        for i in list(dict.fromkeys(ids))[:3])
                    tpl = _FACT_WORDING[
                        "hook_group_held" if mine else "hook_group_over"]
                    lines.append(tpl.format(actor=plabel, names=names, strength=word,
                                            name=name, n=len(rs)))
                    continue
                r = rs[0]
                other = self.person_label(r["target"], date=self.as_of, style="brief") or "某人"
                tpl = _FACT_WORDING[
                    "hook_held_strong" if (mine and strong) else
                    "hook_held_weak" if mine else
                    "hook_over_actor_strong" if strong else
                    "hook_over_actor_weak"]
                since = self._hook_since(r)
                exp = r.get("expiration")
                if exp and str(exp) not in ("9999.1.1", "none"):
                    since = _FACT_WORDING["hook_expires"].format(date=self.date(exp))
                if mine:
                    lines.append(tpl.format(actor=plabel, target=other,
                                            name=name, since=since))
                else:
                    holder = self.person_label(r["holder"], date=self.as_of, style="brief") or "某人"
                    lines.append(tpl.format(actor=plabel, holder=holder,
                                            name=name, since=since))
            if lines:
                out[direction] = lines
        return out

    def _is_slave_of(self, slave, owner=None, date=None):
        """Whether `slave` is a slave of `owner` (default: the player) at `date`, per the
        per-save diff record: first_seen ≤ date and (no lost_at, or lost_at > date)."""
        pid = self.cache.get("player_id")
        owner = pid if owner is None else owner
        if slave is None or owner is None:
            return False
        rec = (self.cache.get("enslavements") or {}).get(f"{owner}>{slave}")
        if not isinstance(rec, dict):
            return False
        dk = cl.date_key(date) if date else (
            cl.date_key(self.as_of) if self.as_of else None)
        fs, la = rec.get("first_seen"), rec.get("lost_at")
        if dk is not None and fs and cl.date_key(fs) > dk:
            return False
        if dk is not None and la and cl.date_key(la) <= dk:
            return False
        return True

    def enslaved_lines(self):
        """Slavery facts: the people the player owns as slaves.

        Carnalitas enslaves an imprisoned person and releases him from prison in the same
        instant, so only the scripted relation
        (`opinions.active_opinions[*].scripted_relations.slave`, cache `enslavements`) separates
        "enslaved" from "captured and freed".

        Returns {"lines": [one line per current slave, merged above three], "former": [relations
        the player has lost, closed by the cache diff as resold, freed or unknown]}."""
        pid = self.cache.get("player_id")
        if pid is None:
            return {}
        ao = cl.date_key(self.as_of) if self.as_of else None
        recs = []
        former = []
        for key, rec in (self.cache.get("enslavements") or {}).items():
            if not isinstance(rec, dict):
                continue
            # only relations where the player was SOME owner (a resold slave stays cached)
            owners = [rec.get("owner")] + list(rec.get("prev_owners") or [])
            if pid not in owners:
                continue
            fs, la = rec.get("first_seen"), rec.get("lost_at")
            if ao is not None and fs and cl.date_key(fs) > ao:
                continue
            if not isinstance(rec.get("slave"), int):
                continue
            if ao is not None and la and cl.date_key(la) <= ao:
                # relation already ended before as_of → formerly owned by the player
                former.append(rec)
                continue
            recs.append(rec)
        recs.sort(key=lambda r: cl.date_key(r.get("first_seen") or "9999.9.9"))
        former.sort(key=lambda r: cl.date_key(r.get("lost_at") or "9999.9.9"))
        W = _FACT_WORDING
        # the player gets the name only (event_name); the profile names his titles once
        plabel = self.event_name(pid, self.as_of) or "主角"
        names = []
        for r in recs:
            nm = self.person_label(r["slave"], date=self.as_of, style="brief") or ""
            if nm:
                names.append((r, nm))
        fnames = []
        for r in former:
            nm = self.person_label(r["slave"], date=self.as_of, style="brief") or ""
            if nm:
                fnames.append((r, nm))
        if not names and not fnames:
            return {}
        out = []
        if len(names) > 3:
            first = names[0][0]
            shown = "、".join(nm for _r, nm in names[:3])
            extra = W["enslaved_group_extra"].format(n=len(names))
            out.append(W["enslaved_group"].format(
                actor=plabel, names=shown, extra=extra,
                year=self._year_only(first.get("first_seen"))))
        else:
            for r, nm in names:
                fs = r.get("first_seen")
                if r.get("first") or not fs:
                    # present at the data start: the year is unknown, so write the deed only
                    out.append(W["enslaved_line"].format(
                        slave=nm, actor=plabel))
                else:
                    out.append(W["enslaved_line_since"].format(
                        slave=nm, actor=plabel,
                        year=self._year_only(fs)))
        fout = []
        for r, nm in fnames[:8]:
            fs, la = r.get("first_seen"), r.get("lost_at")
            # the start year is an initial adverbial ("自874年起，X没为Y的奴隶，至881年…"),
            # not a parenthetical
            since = "" if (r.get("first") or not fs) \
                else "自{}起，".format(self._year_only(fs))
            end_y = self._year_only(la) if la else ""
            buyer = r.get("end_owner")
            bname = self.person_label(buyer, date=self.as_of, style="brief") \
                if isinstance(buyer, int) else ""
            if bname:
                fout.append(W["enslaved_former_sold"].format(
                    slave=nm, actor=plabel, since=since, year=end_y,
                    buyer=bname))
            elif r.get("freed"):
                fout.append(W["enslaved_former_freed"].format(
                    slave=nm, actor=plabel, since=since, year=end_y))
            else:
                fout.append(W["enslaved_former_lost"].format(
                    slave=nm, actor=plabel, since=since, year=end_y))
        return {"lines": out, "former": fout}

    def harm_lines(self):
        """Fact lines for forced / half-consented acts — an intentional empty implementation
        (always returns []).

        Sexual matters live only in the friend and enemy chapters now; kept as the restore point
        should such facts be wanted in a dedicated block again."""
        return []

    def std_lines(self):
        """Fact lines for disease transmission; only parties inside the related set.

        Returns ["{date}，{source}把{disease}传染给了{target}。"], or "{target}染上{disease}。"
        with no source."""
        related = _related_ids(self)
        out = []
        for when, text, src, tgt in _std_index(self):
            if not when:
                continue
            if not (tgt in related or (isinstance(src, int) and src in related)):
                continue
            out.append(f"{self.date(when)}，{text}")
        return out

    def carnal_opinion_lines(self):
        """Carnalitas event opinion → clean Chinese sentence.

        Source is `cache["carnal_opinions"]` (per-save diff with the game's own `start` date);
        each localization is an assessment of the other person ("曾强奸我" …), stated as
        "{owner}自{year}起视{target}为{word}。". Keys without a localization are dropped.

        Off by default via `carnal_opinions` in `config.json`: the entries give only judgements,
        with no place, act or day."""
        if not self._show_carnal_opinions:
            return {}
        pid = self.cache.get("player_id")
        if pid is None:
            return {}
        ao = cl.date_key(self.as_of) if self.as_of else None
        out = []
        for rec in (self.cache.get("carnal_opinions") or {}).values():
            if not isinstance(rec, dict):
                continue
            owner, target = rec.get("owner"), rec.get("target")
            if not isinstance(owner, int) or not isinstance(target, int):
                continue
            fs = rec.get("start") or rec.get("first_seen")
            if ao is not None and fs and cl.date_key(fs) > ao:
                continue
            word = L.loc(self.table, str(rec.get("modifier") or ""))
            if not word or not loc_text_ok(word):
                continue
            she = self.person_label(owner, date=self.as_of, style="brief") or ""
            the = self.person_label(target, date=self.as_of, style="brief") or ""
            if not she or not the:
                continue
            year = self._year_only(fs) if fs else ""
            # the start year is an adverbial inside the sentence ("X自874年起视Y为…")
            since = f"自{year}起" if (year and not rec.get("first")) else ""
            out.append(f"{she}{since}视{the}为{word}。")
        if not out:
            return {}
        return {"lines": sorted(set(out))[:10]}

    def carnal_victim_line(self):
        """Closing line for "recently raped" on the player himself, from the per-save diff of
        the character modifier `carn_recently_raped` (5 years, health −0.25).

        The modifier corroborates the sexual memories: the act was handled as forced and still
        counts as recent."""
        pid = self.cache.get("player_id")
        if pid is None:
            return ""
        rec = (self.cache.get("carnal_modifiers") or {}).get(
            f"{pid}>carn_recently_raped")
        if not isinstance(rec, dict):
            return ""
        ao = cl.date_key(self.as_of) if self.as_of else None
        fs, la = rec.get("first_seen"), rec.get("lost_at")
        if ao is not None and fs and cl.date_key(fs) > ao:
            return ""
        if ao is not None and la and cl.date_key(la) <= ao:
            return ""
        return _FACT_WORDING["carnal_recently_raped"]

    def forced_concubine_lines(self):
        """Forced-concubinage facts, one line each: "880年1月1日，主角强纳戈迪娜·迭戈斯为妾。".

        Source is `start_date` of `forced_me_concubine_marriage_opinion` in
        `cache["opinions"]` (owner = the woman taken, target = the one acting). The game grants
        it to an imprisoned or chaste person and releases her from prison in the same block, so
        a matching `released_from_prison_memory` adds "同日自狱中释出" and fixes the order."""
        pid = self.cache.get("player_id")
        if pid is None:
            return []
        ao = cl.date_key(self.as_of) if self.as_of else None
        W = _FACT_WORDING
        out = []
        for rec in (self.cache.get("opinions") or {}).values():
            if not isinstance(rec, dict):
                continue
            if rec.get("modifier") != "forced_me_concubine_marriage_opinion":
                continue
            owner, target = rec.get("owner"), rec.get("target")
            if not isinstance(owner, int) or not isinstance(target, int):
                continue
            fs, la = rec.get("first_seen"), rec.get("lost_at")
            if ao is not None and fs and cl.date_key(fs) > ao:
                continue
            if ao is not None and la and cl.date_key(la) <= ao:
                continue
            start = rec.get("start") or fs
            if not start:
                continue
            name = self.person_label(owner, date=self.as_of, style="brief") or ""
            if not name:
                continue
            actor = "主角" if target == pid \
                else (self.person_label(target, date=self.as_of, style="brief") or "某人")
            # released the same day (the script's release_from_prison = yes) — that is why
            # she left prison
            paroled = False
            for m in (((self.cache.get("characters") or {}).get(str(owner))
                       or {}).get("memories") or []):
                if m.get("type") != "released_from_prison_memory":
                    continue
                if str(m.get("creation_date")) != str(start):
                    continue
                if (m.get("participants") or {}).get("imprisoner") == target:
                    paroled = True
                    break
            tpl = W["concubine_forced_paroled"] if paroled else W["concubine_forced"]
            out.append(tpl.format(date=self.date(start), actor=actor, name=name))
        return sorted(set(out))

    def concubine_divorce_lines(self):
        """Facts about a concubine's existing marriage being broken, one line each: e.g.
        "879年9月1日，希尔德加德原为萨洛蒙之妻，主角强纳为妾而离异。".

        Source is `forced_spouse_concubine_marriage_opinion` in `cache["opinions"]` (owner = the
        divorced spouse, target = the one taking the concubine); the game grants it with
        `divorce = scope:recipient`, so without the line the woman's marriage gets invented."""
        pid = self.cache.get("player_id")
        if pid is None:
            return []
        ao = cl.date_key(self.as_of) if self.as_of else None
        W = _FACT_WORDING
        out = []
        for rec in (self.cache.get("opinions") or {}).values():
            if not isinstance(rec, dict):
                continue
            if rec.get("modifier") != "forced_spouse_concubine_marriage_opinion":
                continue
            owner, target = rec.get("owner"), rec.get("target")
            if not isinstance(owner, int) or not isinstance(target, int):
                continue
            fs, la = rec.get("first_seen"), rec.get("lost_at")
            if ao is not None and fs and cl.date_key(fs) > ao:
                continue
            if ao is not None and la and cl.date_key(la) <= ao:
                continue
            start = rec.get("start") or fs
            if not start:
                continue
            ex_name = self.person_label(owner, date=self.as_of, style="brief") or ""
            if not ex_name:
                continue
            # the woman taken = the spouse's ex in this save (the only former spouse in the
            # cache's kinship set)
            sp_name = ""
            for x in (((self.cache.get("characters") or {}).get(str(owner)) or {})
                      .get("family") or {}).get("former_spouses") or []:
                if isinstance(x, int) and x != pid:
                    sp_name = self.person_label(x, date=self.as_of, style="brief") or ""
                    break
            if not sp_name:
                continue
            actor = "主角" if target == pid \
                else (self.person_label(target, date=self.as_of, style="brief") or "某人")
            out.append(W["concubine_divorced"].format(
                date=self.date(start), actor=actor, name=sp_name, ex=ex_name))
        return sorted(set(out))

    def hook_notable(self):
        """Whether there is a hook worthy of the secrets section.

        The bar is the `style.hook_type_kept` whitelist: identity-borne and generic hooks
        (house-head, filial piety, favours, obligations) get no section of their own."""
        pid = self.cache.get("player_id")
        for rec in (self.cache.get("hooks") or {}).values():
            if not isinstance(rec, dict):
                continue
            if not _style.hook_type_kept(rec.get("type")):
                continue
            if pid in (rec.get("holder"), rec.get("target")):
                return True
        return False

    # Dramatic facts — short-lived empires/dynasties (lost or destroyed within 30 days)
    DRAMATIC_TENURE_DAYS = 30

    def dramatic_facts(self, pid):
        """Highlighted dramatic events: short-lived realms (an h_/e_ title held and then lost or
        destroyed within 30 days).

        Villain chains are computed by `_villain_chains` and merged in build_facts."""
        out = []
        if pid is None:
            return out
        intervals = self._hold_intervals(pid)
        for tid, ivs in intervals.items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            if not key.startswith(("h_", "e_")):
                continue
            # The six boards are landless government-office titles granted to ministers the
            # day they are created, so the "reign" lasts zero days — not a short-lived
            # realm.
            if key.startswith("e_minister_"):
                continue
            for (gain, loss, ltype) in ivs:
                if not gain or not loss:
                    continue
                span = _daynum(loss) - _daynum(gain)
                if span < 0 or span > self.DRAMATIC_TENURE_DAYS:
                    continue
                tname = self._title_name_at(tid, gain, pid)
                if not tname:
                    continue  # with no title name available, never emit the raw key
                verb = "被毁" if ltype == "destroyed" else "失去"
                out.append(f"{self.date(gain)}承袭{tname}，"
                           f"{self.date(loss)}{verb}，在位仅{span}日")
        return out

    def _prince_word(self, ptier, government, independent, female,
                     child=None, ptid=None, date=None, owner=None):
        """Prince word by the parent's title tier × government × independent/vassal × sex.

        Celestial: empire → 皇子/皇女, independent kingdom → 王子/郡主, vassal kingdom → 公子/公女;
        feudal: 王子/公主.

        A combination missing from the game's `special = ruler_child` table (`_prince_word_exists`)
        grants no title in the game either, so '' is returned; with `child`/`ptid` omitted the
        gate is skipped."""
        if child is not None and not self._prince_word_exists(
                ptier, government, independent, child, ptid, date, owner=owner):
            return ""
        gov = government or ""
        if gov in self._CELESTIAL_LIKE_GOVS:
            if ptier in ("hegemon", "empire"):
                key = "princess_female_celestial_chinese" if female else "prince_male_celestial_chinese"
            elif independent:
                key = ("princess_kingdom_celestial_chinese_independent" if female
                       else "prince_kingdom_celestial_chinese_independent")
            else:
                key = ("princess_kingdom_celestial_chinese" if female
                       else "prince_kingdom_celestial_chinese")
            v = L.loc(self.table, key)
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        key = ("princess_kingdom_feudal_chinese" if female
               else "prince_kingdom_feudal_chinese")
        # A feudal kingdom's daughter is "郡主" in the localization table, but a Western
        # kingdom's or empire's daughter is always written "公主" in the biography; the
        # celestial 皇女/郡主/公女 are deliberate East Asian flavour and are not overridden.
        v = _PRINCE_WORD_OVERRIDE.get(key) or L.loc(self.table, key)
        if v and not v.startswith("$") and not v.startswith("["):
            return v
        return "公主" if female else "王子"

    def _parents_of_cid(self, cid):
        """Parent ids of a character (cache `family`, then the melt's `family_data`)."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        parents = []
        for k in ("father", "mother"):
            parents.extend((rec.get("family") or {}).get(k) or [])
        if not parents:
            c = self._chars.get(str(cid)) or {}
            fd = c.get("family_data") or {}
            for k in ("father", "mother"):
                v = fd.get(k)
                if v is not None:
                    parents.extend(v if isinstance(v, list) else [v])
        return [int(x) for x in parents if isinstance(x, int) or str(x).isdigit()]

    def _tenno_prince_word(self, cid, date=None):
        """Prince/princess word for children of the Chrysanthemum Throne (天皇座)
        → '亲王'/'内亲王'; '' when not applicable.

        Prince/princess ('親王'/'内親王') is a lifetime status, so a parent who ever held the throne
        counts even after death or abdication, while a child who left the imperial clan
        (源/平 surname) gets nothing. The word only exists for
        `special = ruler_child` + `titles = { k_chrysanthemum_throne }`
        (game/common/flavorization/10_tgp_japan_flavorization.txt)."""
        try:
            tier0, _ = self._primary_title_at(cid, as_of=date)
            if tier0 is not None:
                return ""  # already has a title, not applicable
        except Exception:
            return ""
        if self._imperial_clan_state(cid) != "imperial":
            return ""      # left the imperial clan (源/平/藤原…) or clan unknown
        for pid2 in self._parents_of_cid(cid):
            try:
                _t, ptid = self._primary_title_at(pid2, as_of=date)
            except Exception:
                ptid = None
            on_throne = bool(ptid) and \
                ((self._lt.get(str(ptid)) or {}).get("key") in self._TENNO_TITLE_KEYS)
            if not on_throne:
                # parent dead or abdicated: the status lasts a lifetime, so accept ever-held
                try:
                    on_throne = self._ever_held_throne(pid2, date)
                except Exception:
                    on_throne = False
            if not on_throne:
                continue
            female = self._is_female(cid)
            key = ("princess_tenno_female_japanese" if female
                   else "prince_tenno_male_japanese")
            w = L.loc(self.table, key)
            if not w or w.startswith("$") or w.startswith("["):
                return ""
            return w
        return ""

    def _tenno_prince_name(self, cid, date=None):
        """Full name of a throne child, given name + prince/princess word ('利永亲王'), no clan
        surname; '' when there is no given name or the style does not apply."""
        word = self._tenno_prince_word(cid, date)
        if not word:
            return ""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        given = rec.get("name_zh") or ""
        if not given:
            c = self._chars.get(str(cid)) or {}
            given = cl.name_zh(c) or ""
        if not given:
            return ""
        return given + word

    def prince_title(self, cid, date=None):
        """Prince/princess style for a character with no landed title whose parent held kingdom
        tier or above (highest parent wins; also covers a sibling who is the reigning emperor).

        `date` evaluates the parent's title as of that date — used by list data such as the
        assassin record so the style does not drift across time. Throne children return '' because
        their word is already part of the display name."""
        if self._tenno_prince_word(cid, date):
            return ""
        tier0, _ = self._primary_title_at(cid, as_of=date)
        if tier0 is not None:
            return ""  # already has a title, not applicable
        style = self._parent_prince_style(cid, date)
        if style:
            return style
        return self._emperor_sibling_style(cid, date)

    _EMPEROR_TIERS = ("hegemon", "empire")

    def _style_parent_title(self, parent, date):
        """(tier, tid) of the parent's title used to style the children: the currently held title
        first, else the parent's highest ever held title, so a dead or deposed parent still styles."""
        t, tid = self._primary_title_at(parent, as_of=date)
        if t is not None and self._is_landed_title(tid):
            return t, tid
        ftid = self._former_high_title(parent, date)
        if ftid is None:
            return None, None
        key = (self._lt.get(str(ftid)) or {}).get("key") or ""
        rank = self._TT_RANK.get(key[:2], 0)
        tier = self._RANK_TIER.get(rank) if rank >= 1 else None
        return (tier, ftid) if tier else (None, None)

    def _prince_style_from_title(self, ptier, ptid, date, child, owner):
        """(tier, title) + holder → prefix + prince word; '' when there is no base name.
        Government comes from the title, independence from the holder.

        The prefix is the title's own name, never a tier word. Two exceptions: a dynasty-named
        empire (`dynn_title_*` history name, e.g. 汉/晋/隋/唐/宋) is prefixed '大', while
        short titles (`definite_form = yes`) and names already carrying a state word stay as they
        are. Japan's top titles (天皇座/日本帝国) are excluded — `_tenno_prince_word` owns them."""
        if ((self._lt.get(str(ptid)) or {}).get("key") or "") in self._JAPAN_TOP_TITLE_KEYS:
            return ""
        pgov = self._title_government(ptid, date)
        pbase = self._name_at_date(ptid, date or self.as_of) or self.title_base_name(ptid)
        if not pbase:
            return ""
        independent = self._is_independent(owner, date)
        if independent is None:
            independent = True
        rn = self.realm_name(ptid)
        if rn:
            prefix = rn
        elif ptier == "hegemon" and pgov in self._CELESTIAL_LIKE_GOVS \
                and not self._is_short_title(ptid) \
                and not _STATE_SUFFIX_RE.search(pbase) \
                and self._name_source_key(ptid, date).startswith("dynn_"):
            # Chinese dynasty: the state name follows the dynasty (唐/宋/秦…) → 大唐 / 大宋
            prefix = pbase if pbase.startswith("大") else f"大{pbase}"
        else:
            # no tier word is appended (国/路/皇朝/王国/帝国); a short title uses its own name
            prefix = pbase
        word = self._prince_word(ptier, pgov, independent, self._is_female(child),
                                 child=child, ptid=ptid, date=date, owner=owner)
        # the game gives no word here (gate missed) → drop the whole style, so it never
        # degrades into a bare prefix
        if not word:
            return ""
        # do not stack a prefix when the word is already part of the display name
        # (nickname '时尚王子' + father's realm), same guard as `_tenno_prince_word`
        if word in (self.name_with_regnal(child, date) or ""):
            return ""
        return prefix + word

    def _parent_prince_style(self, cid, date):
        """Child style when a parent rules kingdom tier or above (highest-ranking parent wins).
        Japan's top titles are skipped here, so the other parent can still style the child."""
        best = None  # (rank, ptier, ptid, parent_cid)
        for pid2 in self._parents_of_cid(cid):
            t, tid = self._style_parent_title(int(pid2), date)
            if ((self._lt.get(str(tid)) or {}).get("key") or "") in self._JAPAN_TOP_TITLE_KEYS:
                continue
            rank = {"hegemon": 6, "empire": 5, "kingdom": 4}.get(t, 0)
            if rank > 0 and (best is None or rank > best[0]):
                best = (rank, t, tid, int(pid2))
        if best is None:
            return ""
        _rank, ptier, ptid, pparent = best
        return self._prince_style_from_title(ptier, ptid, date, cid, pparent)

    def _emperor_sibling_style(self, cid, date):
        """Prince/princess style when a sibling is the reigning emperor and the father was also
        an emperor; both conditions are required so mere imperial half-brothers are not styled."""
        fam = ((self.cache.get("characters") or {}).get(str(cid)) or {}).get("family") or {}
        sibs = [int(x) for x in (fam.get("siblings") or []) if isinstance(x, int)]
        fathers = [int(x) for x in (fam.get("father") or []) if isinstance(x, int)]
        if not sibs or not fathers:
            return ""
        father_ok = False
        for f2 in fathers:
            t, _tid = self._style_parent_title(f2, date)
            if t in self._EMPEROR_TIERS:
                father_ok = True
                break
        if not father_ok:
            return ""
        for b in sibs:
            t, tid = self._primary_title_at(b, as_of=date)
            if t in self._EMPEROR_TIERS and self._is_landed_title(tid):
                return self._prince_style_from_title(t, tid, date, cid, b)
        return ""

    # ---- house feuds (house_relations) / artifact records (artifacts) ----

    # Release reason, read straight from the melt (no extra cache field).
    # Direction: `add_opinion = { target = scope:actor }` inside the prisoner's scope means the
    # prisoner holds that opinion, so owner = prisoner and target = releaser; only
    # `ransomed_from_prison` targets the payer (possibly a third-party relative), hence the extra
    # owner-based lookup.
    # Lifetime: all release opinions are years=10 / decaying (`ransomed_from_prison` is scripted to
    # 1 year) and disappear from the save the moment the holder dies; when unreadable the fallback
    # is "获释", and the per-save cache["prison_manners"] keeps old releases readable in the final
    # volume.
    # `demanded_hook` is worded neutrally as "以人情获释": it and `favor_hook` come from the same
    # two interactions and leave identical save fields, so a ransom cannot be told from a favour.
    _PRISON_MANNER_MODS = {
        "released_from_prison":            ("released",  "获释"),
        "merciful_opinion":                ("released",  "获释"),
        "ransomed_from_prison":            ("ransomed",  "纳赎获释"),
        "demanded_my_conversion_opinion":  ("converted", "改信获释"),
        "compelled_me_to_convert_opinion": ("converted", "改信获释"),
        "demanded_hook":                   ("hook",      "以人情获释"),
        "demanded_claim_renouncement":     ("claim",     "被迫放弃宣称获释"),
        "banished_me":                     ("banished",  "遭驱逐"),
        "demanded_recruitment":            ("recruit",   "遭强征入仕"),
        "demanded_taking_vows":            ("vows",      "被迫出家获释"),
    }
    # Kind word for folded rows: ending family → phrase used in the count row; multi-person
    # clusters carry no duration while a single prisoner row keeps "3日后 / 1个月后".
    _PRISON_KIND_WORD = {
        "released": "获释", "converted": "改信获释", "hook": "以人情获释",
        "claim": "放弃宣称获释", "ransomed": "纳赎获释", "banished": "遭驱逐",
        "recruit": "遭强征入仕", "vows": "被迫出家获释", "escape": "越狱脱身",
        "enslaved": "没为奴隶", "punished": "受刑获释", "executed": "处决",
        "died_in_prison": "死于狱中",
        # eaten during imprisonment: same death family as `executed` but proven by the
        # `devoured_by` field; worded like the death roll's "被其吃掉".
        "devoured": "被吃掉",
        # The bound is supplied by the caller: a decade volume passes its own cutoff date, the
        # final volume the last save (see `_prison_bound`).
        "held": "至{bound}仍在押",
    }

    def prison_death_clause(self, victim, date=None):
        """Death record for the closing sentence → {date, reason, killer} or {}.

        Cache first; when the cache holds no death (the victim died past the cache's last save)
        fall back to the melt's `dead_data`."""
        rec = ((self.cache.get("characters") or {}).get(str(victim)) or {})
        dd = rec.get("death") or {}
        if dd.get("date"):
            return dd
        for seg in ("living", "dead_unprunable"):
            c = (self.melt.get(seg) or {}).get(str(victim))
            if isinstance(c, dict) and (c.get("dead_data") or {}).get("date"):
                return c["dead_data"]
        return {}

    def _death_int(self, v):
        """Integer field of a death record; the sentinel 4294967295 / 0xFFFFFFFF means absent → int|None."""
        if not isinstance(v, int) or v < 0 or v >= 4294967295:
            return None
        return v

    # ------------------------------------------------------------------
    # Single decision point for how an imprisonment ended.
    # ------------------------------------------------------------------
    # `prison_history.from/to` is only the per-save observation window (see cache_lib): a closed
    # interval can mean release, execution or death in prison, so release must never be inferred
    # from it alone.
    #
    # Decision order:
    #   ① release / escape memory (same jailer, date ≥ entry) — most accurate;
    #   ② enslaved during the stay (Carnalitas creates slavery at the same instant as release,
    #      so this precedes any release verdict);
    #   ③ death record (death ≥ entry; killer == jailer ⇒ judicial killing; `devoured_by` proof
    #      wins);
    #   ④ prison_history interval close ⇒ left prison (an observation bound, not an asserted
    #      release date);
    #   ⑤ none of the above ⇒ held.
    def prison_exit(self, victim, jailer, entry_date):
        """How an imprisonment ended → {"kind", "date", "manner", "source", "reason"}.

        kind ∈ escape / <release_manner variants> / released / enslaved /
               executed / died_in_prison / devoured / held
        date = day of release or death (empty for held); manner = release-reason wording."""
        out = {"kind": "held", "date": "", "manner": "", "source": "none",
               "reason": ""}
        if not isinstance(victim, int) or not entry_date:
            return out
        rec = (self.cache.get("characters") or {}).get(str(victim)) or {}
        dk0 = cl.date_key(str(entry_date))
        # Acceptable releasers — includes the jailer's successor after a handover, recorded as a
        # `from_imprisoner`/`imprisoner` pair in prison_history. Without it a released prisoner
        # would read as still held in the last save.
        _jailers = {jailer} if isinstance(jailer, int) else set()
        for iv in rec.get("prison_history") or []:
            if isinstance(iv.get("from_imprisoner"), int) \
                    and iv.get("from_imprisoner") == jailer \
                    and isinstance(iv.get("imprisoner"), int):
                _jailers.add(iv["imprisoner"])
        # Jailers of *other* imprisonments: a releaser who is not this jailer only counts as a
        # successor if it never imprisoned this person. The handover record lives only in the
        # previous protagonist's cache, so this fallback is required.
        _other_jailers = set()
        for m in rec.get("memories") or []:
            if (m.get("type") or "") != "imprisoned":
                continue
            j2 = (m.get("participants") or {}).get("imprisoner")
            if isinstance(j2, int) and j2 != jailer:
                _other_jailers.add(j2)
        # ① release / escape memory (earliest one matching this jailer)
        rel = None
        for m in rec.get("memories") or []:
            t = m.get("type") or ""
            if t not in ("released_from_prison_memory",
                         "escaped_from_prison_memory"):
                continue
            d = str(m.get("creation_date") or "")
            if not d or cl.date_key(d) < dk0:
                continue
            j = (m.get("participants") or {}).get("imprisoner")
            if isinstance(j, int) and _jailers and j not in _jailers \
                    and j in _other_jailers:
                continue          # this release memory belongs to another imprisonment
            if rel is None or cl.date_key(d) < cl.date_key(rel[0]):
                rel = (d, t)
        # the prison-history close date is computed first because it also caps the death verdict:
        # a close earlier than the death means the person left prison and died later, so that
        # death does not belong to this imprisonment.
        hist_to = ""
        for iv in rec.get("prison_history") or []:
            to = str(iv.get("to") or "")
            if to and cl.date_key(to) >= dk0 \
                    and (not hist_to or cl.date_key(to) < cl.date_key(hist_to)):
                hist_to = to
        # death first, to gate ① with "not later than the death" (contradictory data: death wins)
        dd = self.prison_death_clause(victim) or {}
        ddate = str(dd.get("date") or "")
        if ddate and cl.date_key(ddate) < dk0:
            dd, ddate = {}, ""
        if ddate and hist_to and cl.date_key(ddate) > cl.date_key(hist_to):
            dd, ddate = {}, ""
        _esc = bool(rel) and rel[1] == "escaped_from_prison_memory"
        # enslaved during the stay (an escaper is excluded — he really did get away)
        if not _esc:
            _own = _enslaved_in_span(self, victim, jailer, entry_date,
                                     (ddate or (rel[0] if rel else "")) or None)
            if _own is not None:
                return {"kind": "enslaved", "date": ddate or (rel[0] if rel else ""),
                        "manner": "", "source": "enslavement", "reason": ""}
        if rel is not None:
            d, t = rel
            if not ddate or cl.date_key(d) <= cl.date_key(ddate):
                if t == "escaped_from_prison_memory":
                    return {"kind": "escape", "date": d, "manner": "",
                            "source": "memory", "reason": ""}
                mk, mw = self.release_manner(victim, jailer, d)
                return {"kind": mk or "released", "date": d, "manner": mw,
                        "source": "memory", "reason": ""}
        if ddate:
            killer = self._death_int(dd.get("killer"))
            jail = self._death_int(jailer)
            _exec = (dd.get("reason") in _PRISON_EXEC_REASONS
                     or (killer is not None and jail is not None
                         and killer == jail))
            reason = str(dd.get("reason") or "")
            if _exec and jail is not None and self.devoured_by(jail, victim):
                return {"kind": "devoured", "date": ddate, "manner": "",
                        "source": "death", "reason": reason}
            return {"kind": "executed" if _exec else "died_in_prison",
                    "date": ddate, "manner": "", "source": "death",
                    "reason": reason}
        # prison-history interval close: an observation bound ("not held from save X on"), never
        # asserted as the release date
        if hist_to:
            return {"kind": "released", "date": hist_to, "manner": "",
                    "source": "history", "reason": ""}
        return out

    def prison_capture_head(self, victim, jailer, date, cluster_n=1):
        """Opening clause of a prison row (who captured whom, with hard evidence for the manner).

        A manner word is written only on hard evidence (`Facts.capture_manner`: diarchy 摄政拘押 /
        raid 劫掠中掳走 / battle 战阵俘获 / batch 群体拘押); otherwise a bare
        "{jailer}囚禁{victim}" carries no manner, leaving the model no place to invent a scene.
        The minor-age caveat is only used by the chronology, where the age is known."""
        W = _style.FACT_WORDING
        jn = self._feud_role_title(jailer, date) if isinstance(jailer, int) else ""
        vn = self._feud_role_title(victim, date) if isinstance(victim, int) else ""
        if not vn:
            return ""
        if not jn:
            return W["prison_held"].format(victim=vn)
        try:
            cm, _note = self.capture_manner(victim, jailer, date,
                                            cluster_n=cluster_n)
        except Exception:
            cm = "unknown"
        if cm == "diarchy":
            return W["prison_captured_diarch"].format(jailer=jn, victim=vn)
        if cm in ("battle", "battle_poi"):
            return W["prison_captured_battle"].format(jailer=jn, victim=vn)
        if cm == "raid":
            return W["prison_raid_captured"].format(jailer=jn, victim=vn)
        if cm == "batch":
            return W["prison_batch_seized"].format(jailer=jn, victim=vn)
        return W["prison_jailed"].format(jailer=jn, victim=vn)

    def prison_tail(self, victim, jailer, entry_date, ex=None, purge=False):
        """Closing clause of a prison row (leading '，') → `(tail, kind, span)`.

        Every verdict comes from `prison_exit`; wording is 当日 / N日后 / N个月后 / N年后, stating
        the duration instead of asserting the observation bound as a release date."""
        W = _style.FACT_WORDING
        ex = ex or self.prison_exit(victim, jailer, entry_date)
        kind = ex.get("kind") or "held"
        ddate = str(ex.get("date") or "")
        span = _prison_span(entry_date, ddate) if ddate else ""
        same = bool(span) and span == W["prison_same_day"]
        if kind == "held":
            tail = W["prison_still_held"].format(bound=self._prison_bound())
            tail += self.prison_handover_clause(victim, date=entry_date)
            return (tail, "held", "")
        if kind == "enslaved":
            return (W["prison_enslaved"], "enslaved", span)
        if kind == "escape":
            if same:
                t = W["prison_escape_same_day"]
            elif span:
                t = W["prison_escaped"].format(span=span)
            else:
                t = W["prison_escape_on"].format(date=self.date(ddate))
            return (t, "escape", span)
        if kind in ("executed", "died_in_prison", "devoured"):
            key = {"executed": "prison_died_executed",
                   "died_in_prison": "prison_died_in_prison",
                   "devoured": "prison_died_devoured"}[kind]
            sp = (W["prison_same_day"] if same
                  else (f"{span}后" if span else f"至{self.date(ddate)}"))
            return (W[key].format(sp=sp), kind, span)
        # release family: released / converted / hook / claim / ransomed / recruit / vows /
        # punished — a purge day always reads 遭驱逐
        if purge:
            return ("，遭驱逐", "banished", span)
        mw = str(ex.get("manner") or "")
        if mw:
            if same:
                t = f"{W['prison_same_day']}{mw}"
            elif span:
                t = f"{span}后{mw}"
            elif ddate:
                t = f"{self.date(ddate)}{mw}"
            else:
                t = mw
            return (t if t.startswith("，") else "，" + t, kind, span)
        if same:
            return (W["prison_released_same_day"], "released", span)
        if span:
            return (W["prison_released"].format(span=span), "released", span)
        return (W["prison_release_on"].format(date=self.date(ddate)), "released", span)

    def spouse_latch_rows(self, as_of=None):
        """Protagonist's spouse latch records → [{other, kind, first_seen}], sorted by sighting date.

        Source `cache["spouse_latch"]`, which latches marriage back-pointers found in every
        character's `family_data` (see `cache_lib._latch_spouses`). The protagonist's own
        `family_data` is cleared in the save where they die, so this table is the only
        cross-save-reliable record of the spouses taken in a lifetime."""
        pid = self.cache.get("player_id")
        if pid is None:
            return []
        ck = cl.date_key(as_of) if as_of else None
        out = []
        for key, rec in (self.cache.get("spouse_latch") or {}).items():
            if not isinstance(rec, dict):
                continue
            if rec.get("player") != pid:
                continue
            other = rec.get("other")
            if not isinstance(other, int):
                continue
            fs = rec.get("first_seen")
            st = rec.get("since") or fs
            # `since` can precede the first sighting (naming opinions carry a start_date), and the
            # decade gate uses it so an 879 marriage is not counted in the second decade
            if ck is not None and st and cl.date_key(st) > ck:
                continue
            out.append({"other": other, "kind": str(rec.get("kind") or ""),
                        "first_seen": st or fs})
        out.sort(key=lambda r: (cl.date_key(r["first_seen"] or ""), r["other"]))
        return out

    def merge_spouse_latch(self, fam, as_of=None):
        """Merge the spouse latches into the relatives set in place and return `fam`.

        Ranks map onto the five keys `primary_spouse` / `spouse` / `concubine` / `former_spouses`
        / `former_concubines`, isomorphic to the game's `family_data`, so downstream needs no
        second vocabulary. Add-only: values present in this save win, the latch fills gaps."""
        rows = self.spouse_latch_rows(as_of)
        if not rows:
            return fam
        fam = fam if isinstance(fam, dict) else {}
        for key in ("primary_spouse", "spouse", "concubine",
                    "former_spouses", "former_concubines"):
            fam.setdefault(key, [])
        # rank can evolve across saves (concubine → wife): keep the strongest (rank in cache_lib)
        rank = cl._SPOUSE_KIND_RANK
        best = {}
        for r in rows:
            k = r["kind"]
            if k not in rank:
                continue
            if r["other"] not in best or rank[k] < rank[best[r["other"]]]:
                best[r["other"]] = k
        for other, k in best.items():
            slot = {"primary_spouse": "primary_spouse", "spouse": "spouse",
                    "concubine": "concubine", "former_spouse": "former_spouses",
                    "former_concubine": "former_concubines"}[k]
            if other not in fam[slot]:
                fam[slot].append(other)
        # a formal wife/consort is no longer listed as concubine: with one person in both fields
        # `_consort_word` prefers 妾 and would read a wife as a concubine
        _formal = set(fam.get("primary_spouse") or []) | set(fam.get("spouse") or [])
        if _formal:
            fam["concubine"] = [x for x in fam.get("concubine") or []
                                if x not in _formal]
            fam["former_concubines"] = [x for x in fam.get("former_concubines") or []
                                        if x not in _formal]
        ever = set(fam.get("ever_spouses") or [])
        for key in ("primary_spouse", "spouse", "former_spouses",
                    "concubine", "former_concubines"):
            ever.update(int(x) for x in (fam.get(key) or []))
        if ever:
            fam["ever_spouses"] = sorted(ever)
        return fam

    def _prison_bound(self):
        """Observation bound for the prison closing clause → "{date}末档" or "末档".

        A decade volume is bounded by its own cutoff date, the final volume by the cache's last
        save. The literal 末档 must stay — a bare date would be read as the release date."""
        last = self.cache.get("last_date")
        cut = self.as_of or last
        if not cut:
            return "末档"
        if last and str(cut) == str(last):
            return "末档"
        d = self.date(cut)
        return f"{d}末档" if d else "末档"

    def prison_handover_clause(self, victim, date=None):
        """Jailer-handover clause for this prisoner → "，881年1月1日转归埃尔梅辛达"; '' when there
        is no handover or it falls after this volume's cutoff.

        Two sources: ① a `from_imprisoner` change observed within the same cache (the jailer
        changed while the protagonist still lived); ② `cache["prison_succession"]`, latched from
        later saves of the same campaign by `cache_lib._latch_prison_succession` for imprisonments
        that passed to a successor after the protagonist's death."""
        try:
            victim = int(victim)
        except (TypeError, ValueError):
            return ""
        cut = self.as_of or self.cache.get("last_date")
        ck = cl.date_key(cut) if cut else None
        rec = (self.cache.get("prison_succession") or {}).get(str(victim)) or {}
        nxt = rec.get("to") if isinstance(rec.get("to"), int) else None
        when = rec.get("first_seen") or rec.get("since") or ""
        if nxt is None:
            for iv in (((self.cache.get("characters") or {}).get(str(victim)) or {})
                       .get("prison_history") or []):
                if isinstance(iv, dict) and isinstance(iv.get("from_imprisoner"), int) \
                        and isinstance(iv.get("imprisoner"), int):
                    nxt = iv["imprisoner"]
                    when = iv.get("from") or ""
                    break
        if nxt is None:
            return ""
        if date and ck is not None and cl.date_key(date) > ck:
            return ""
        name = self.event_name(nxt, date=self.as_of) or self.name_or(nxt, "")
        if not name:
            return ""
        d = self.date(when) if when else ""
        return f"，{d}转归{name}" if d else f"，转归{name}"

    def _mem_holder_index(self):
        """{memory id: holder id}, inverted from each character's `alive_data/dead_data.memories`
        (lazy).

        A memory object carries no `owner` field — ownership is recorded in the character's
        `memories` list — while memory ids share the id pool with character ids, so treating the
        memory id as the holder returns a different character's id."""
        cached = getattr(self, "_mem_holder", None)
        if cached is not None:
            return cached
        out = {}
        for bucket in (self.melt.get("living") or {},
                       self.melt.get("dead_unprunable") or {},
                       (self.melt.get("characters") or {}).get("dead_prunable") or {}):
            for cid, c in bucket.items():
                if not isinstance(c, dict):
                    continue
                ad = c.get("alive_data") or c.get("dead_data") or {}
                for mid in (ad.get("memories") or []):
                    try:
                        out[int(mid)] = int(cid)
                    except (TypeError, ValueError):
                        continue
        self._mem_holder = out
        return out

    def _battle_by_date(self):
        """{date: [(type, loser, winner, owner)]} over every battle/war memory in this save (lazy).

        Source `character_memory_manager.database`, from any holder, so it does not depend on the
        protagonist being present. Only `battle_*_memory` means "a battle was fought that day";
        `war_won` / `war_lost` are war-end memories, so `capture_manner` takes only the `battle_`
        prefix. The holder is the subject: holder of `*_won` = winner (participants carry only
        `loser`), holder of `*_lost` = loser (participants carry `winner`)."""
        cached = getattr(self, "_battle_idx", None)
        if cached is not None:
            return cached
        out = {}
        holder = self._mem_holder_index()
        db = (self.melt.get("character_memory_manager") or {}).get("database") or {}
        for mid, e in db.items():
            if not isinstance(e, dict):
                continue
            t = e.get("type") or ""
            if t not in ("battle_won_memory", "battle_lost_memory",
                         "war_won", "war_lost"):
                continue
            parts = e.get("participants") or {}
            owner = e.get("owner")
            if owner is None:
                try:
                    owner = holder.get(int(mid))
                except (TypeError, ValueError):
                    owner = None
            d = e.get("creation_date")
            if not d:
                continue
            out.setdefault(str(d), []).append(
                (t, parts.get("loser"), parts.get("winner"), owner))
        self._battle_idx = out
        return out

    @staticmethod
    def _battle_winner(rec):
        """Battle/war memory → (loser, winner); a missing winner is filled from the holder."""
        t, loser, winner, owner = rec
        if winner is None:
            # the holder of `*_won` is the winner; `*_lost` should carry winner in participants
            if t.endswith("_won") or "won" in t:
                winner = owner
        return loser, winner

    def _var_flags(self, cid):
        """Set of flag names in a character's `alive_data.variables` (`dead_data` for the dead)."""
        chars = self.melt.get("living") or {}
        if str(cid) not in chars:
            chars = self.melt.get("dead_unprunable") or {}
        if str(cid) not in chars:
            chars = (self.melt.get("characters") or {}).get("dead_prunable") or {}
        ad = (chars.get(str(cid)) or {}).get("alive_data") \
            or (chars.get(str(cid)) or {}).get("dead_data") or {}
        vs = ad.get("variables")
        items = vs.get("data") if isinstance(vs, dict) else vs
        out = set()
        for it in (items or []):
            if isinstance(it, dict) and it.get("flag"):
                out.add(str(it["flag"]))
        return out

    def _char_var(self, cid, flag):
        """`variables.data[flag].data.identity` of a character, or None when the variable is absent.

        A `value` variable (e.g. `pam_papabile_score`, fixed point ×100000) returns the raw value;
        a `char` variable (e.g. `pam_papabile_leaning_target`) returns a character id. Values come
        from `self._chars` = `cl.all_characters(melt)`, the same three buckets the renderer uses."""
        rec = self._chars.get(str(cid)) or {}
        vs = (rec.get("alive_data") or {}).get("variables")
        items = vs.get("data") if isinstance(vs, dict) else vs
        for it in (items or []):
            if isinstance(it, dict) and str(it.get("flag")) == flag:
                d = it.get("data")
                if isinstance(d, dict) and isinstance(d.get("identity"), (int, float)):
                    return d["identity"]
                return None
        return None

    def _battle_poi_hits(self, jailer, date, victim=None):
        """Battle point-of-interest hits → province ids.

        Province variables `battle_poi_winner` / `battle_poi_loser` /
        `battle_poi_date_{year,month,day}` / `battle_poi_enemy_commander_imprisoned`
        (events/war_events/combat_events.txt) come from an event fired by the same on_action as the
        imprisoning one (common/on_action/combat_on_actions.txt), so both describe one battle; date
        values are stored ×100000. Coverage is very narrow but a hit is conclusive, and a hit
        requires `loser == victim` because another battle may share the province and day."""
        cached = getattr(self, "_poi_idx", None)
        if cached is None:
            cached = {}
            provs = self.melt.get("provinces") or {}
            for pid, p in provs.items():
                if not isinstance(p, dict):
                    continue
                vs = (p.get("variables") or {})
                items = vs.get("data") if isinstance(vs, dict) else vs
                flags = {}
                for it in (items or []):
                    if isinstance(it, dict) and it.get("flag"):
                        d = it.get("data") or {}
                        flags[str(it["flag"])] = d.get("identity")
                if not flags.get("battle_poi_enemy_commander_imprisoned"):
                    continue
                def _div(name):
                    v = flags.get(name)
                    try:
                        return int(v) // 100000
                    except (TypeError, ValueError):
                        return None
                cached[str(pid)] = {
                    "winner": flags.get("battle_poi_winner"),
                    "loser": flags.get("battle_poi_loser"),
                    "year": _div("battle_poi_date_year"),
                    "month": _div("battle_poi_date_month"),
                    "day": _div("battle_poi_date_day"),
                }
            self._poi_idx = cached
        try:
            y, mo, d = (int(x) for x in str(date).split(".")[:3])
        except (TypeError, ValueError):
            return []
        return [pid for pid, v in cached.items()
                if v.get("winner") == jailer and v.get("year") == y
                and v.get("month") == mo and v.get("day") == d
                and (victim is None or v.get("loser") == victim)]

    def imprison_batch_sizes(self):
        """{(date, jailer): headcount} — how many people one jailer imprisoned in one day (lazy).

        Two sources, the larger value wins: ① the event side (`_pm["n"]` in
        `_pair_imprisonments`); ② the jailer's own `imprisoned_other` memories, the more durable
        count — a prisoner's `imprisoned` memory is reclaimed with them when they die, while the
        jailer's survive (1350-year memory span), so the jailer's side counts group captures."""
        cached = getattr(self, "_batch_sizes", None)
        if cached is not None:
            return cached
        out = {}
        holder = self._mem_holder_index()
        db = (self.melt.get("character_memory_manager") or {}).get("database") or {}
        for mid, e in db.items():
            if not isinstance(e, dict) or e.get("type") != "imprisoned_other":
                continue
            try:
                jailer = holder.get(int(mid))
            except (TypeError, ValueError):
                jailer = None
            if jailer is None:
                continue
            key = (str(e.get("creation_date")), jailer)
            out[key] = out.get(key, 0) + 1
        self._batch_sizes = out
        return out

    def _age_at(self, cid, date):
        """Age of the character on `date` (int|None); None when the birth year is unknown."""
        cy = _audit_year(self, cid)
        if cy is None or not date:
            return None
        try:
            y = int(str(date).split(".")[0])
        except (TypeError, ValueError):
            return None
        return y - cy

    def _last_raid_on(self, jailer, date):
        """Whether the jailer was raiding that day → the raw `last_raid` value or None.

        The game stores the most recent raid date in `landed_data.last_raid`. Being the last and
        not the full history, it can only prove a raid: equal to the entry date ⇒ the person was
        taken while raiding; different ⇒ nothing is ruled out, since a later raid overwrites it."""
        if jailer is None or not date:
            return None
        for bucket in (self.melt.get("living") or {},
                       self.melt.get("dead_unprunable") or {},
                       (self.melt.get("characters") or {}).get("dead_prunable") or {}):
            c = bucket.get(str(jailer))
            if isinstance(c, dict):
                lr = (c.get("landed_data") or {}).get("last_raid")
                if lr and str(lr) == str(date):
                    return str(lr)
                break
        return None

    def _house_raid_index(self):
        """Index of raid entries in the house-relation log → {date: [(raider, target, raw)…]}
        (lazy, single scan).

        The save holds no raid memory type at all, so the only per-day raid trace is
        `house_relations.database[*].history[*].change_reason`, written by `on_raid_action_completion`
        (`common/on_action/army_on_actions.txt`) on the day a raid completes, ordered
        (CHAR, TARGET_CHAR) = (raider, raided holder). `raided_estate` / `raided_estate_attempt`
        entries are collected too — equally positive proof of raiding that person that day.

        Not a full history: it is written only when a raid moved a house relation, so it can prove
        a raid but never rule one out."""
        cached = getattr(self, "_house_raid_idx", None)
        if cached is not None:
            return cached
        idx = {}
        db = (self.melt.get("house_relations") or {}).get("database") or {}
        for r in db.values():
            if not isinstance(r, dict):
                continue
            for e in (r.get("history") or []):
                if not isinstance(e, dict):
                    continue
                raw = str(e.get("change_reason") or "")
                if not any(k in raw for k in _RAID_WORDS):
                    continue
                ids = [int(x) for x in _FEUD_CHAR_RE.findall(raw)]
                if len(ids) < 2:
                    continue
                idx.setdefault(str(e.get("date")), []).append((ids[0], ids[1], raw))
        self._house_raid_idx = idx
        return idx

    def _house_raid_on(self, jailer, victim, date):
        """Whether the jailer's raid log for that day names the prisoner or their house →
        `'own'` / `'house'` / None.

        Both verdicts require log order (raider = jailer, raided = …): `'own'` means the second end
        is the prisoner themself (hard proof), `'house'` that it is of the prisoner's house (weaker,
        house-level). Unlike `_last_raid_on`, which reads only the single latest raid from
        `landed_data.last_raid`, this reads the per-day house log, covering days it overwrote."""
        if not date or jailer is None or victim is None:
            return None
        try:
            jailer = int(jailer)
            victim = int(victim)
        except (TypeError, ValueError):
            return None
        vhouse = None
        for raider, target, _raw in self._house_raid_index().get(str(date), []):
            if raider != jailer:
                continue
            if target == victim:
                return "own"
            if vhouse is None:
                vhouse = self._house_of_cid(victim)
            if vhouse is not None and self._house_of_cid(target) == vhouse:
                return "house"
        return None

    def house_flow_on(self, house_a, house_b, date):
        """House-relation log entries for exactly that day → [rendered sentence, …].

        Same source as the house-feud record (`house_relations.database[*].history`); sentences run
        through `_rerender_feud_event`, which re-renders both characters as of the event date. Used
        to add the proximate cause in `relation_cause_lines` ④; [] when nothing renders."""
        if house_a is None or house_b is None or not date:
            return []
        db = (self.melt.get("house_relations") or {}).get("database") or {}
        out = []
        for r in db.values():
            if not isinstance(r, dict):
                continue
            hs = r.get("houses") or []
            if house_a not in hs or house_b not in hs:
                continue
            for e in (r.get("history") or []):
                if not isinstance(e, dict) or str(e.get("date")) != str(date):
                    continue
                raw = str(e.get("change_reason") or "")
                # a divorce written on the death day (the engine also records 离婚 for a widowing)
                # is not a feud cause
                if self.is_widow_divorce(raw, str(e.get("date") or "")):
                    continue
                txt = self._rerender_feud_event(raw, date, houses=hs)
                if txt and txt not in out:
                    out.append(txt)
        return out

    def house_feud_reason_clause(self, house_a, house_b, date):
        """Cause row of a house feud → a causal sentence; '' when there is no such entry.

        That row is written on the day the feud escalates, not on the day of the deed, so reading it
        as a same-day event narrates the deed a second time. This renders a causal phrase instead
        and adds the real date taken from the event-style entry with the same victim in the same
        relation record; with no such entry only the causal phrase is written."""
        if house_a is None or house_b is None or not date:
            return ""
        db = (self.melt.get("house_relations") or {}).get("database") or {}
        for r in db.values():
            if not isinstance(r, dict):
                continue
            hs = r.get("houses") or []
            if house_a not in hs or house_b not in hs:
                continue
            hist = [e for e in (r.get("history") or []) if isinstance(e, dict)]
            for e in hist:
                if str(e.get("date")) != str(date):
                    continue
                raw = str(e.get("change_reason") or "")
                row = _feud_head_kind(raw)
                if not row:
                    continue
                ids = [int(x) for x in _FEUD_CHAR_RE.findall(raw)]
                if len(ids) < 2:
                    continue
                victim, actor = ids[0], ids[1]
                vn = self._feud_role_title(victim, date) or ""
                an = self._feud_role_title(actor, date) or ""
                if not vn or not an:
                    continue
                # real deed date = earliest event-style entry in the same record, same victim
                real = ""
                for e2 in hist:
                    raw2 = str(e2.get("change_reason") or "")
                    if not raw2 or row[2] not in raw2 or _feud_head_kind(raw2):
                        continue
                    ids2 = [int(x) for x in _FEUD_CHAR_RE.findall(raw2)]
                    if len(ids2) < 2 or ids2[1] != victim:
                        continue
                    d2 = str(e2.get("date") or "")
                    if d2 and (not real or cl.date_key(d2) < cl.date_key(real)):
                        real = d2
                phrase = row[3].format(j=an)
                if real:
                    return f"{vn}于{self.date(real)}{phrase}，两族由此决裂"
                return f"{vn}{phrase}，两族由此决裂"
        return ""

    def _prison_type_fresh(self, cid, date):
        """Cell grade of *this* imprisonment → 'dungeon' / 'house_arrest' / None.

        `prison_data.type` is usable only when three dates agree
        (`date == pd["date"] == pd["imprison_type_date"]`): `date` is the start of the current
        imprisonment, so a mismatch means the person was jailed again (or released) since, while
        `imprison_type_date` is the day the grade was set by `change_prison_type`, so a mismatch
        means the original grade was overwritten — then None rather than a guess. A battle capture
        always writes `type = house_arrest` (combat_events.txt), so `dungeon` rules one out."""
        if cid is None or not date:
            return None
        for bucket in ((self.melt.get("living") or {}),
                       (self.melt.get("dead_unprunable") or {}),
                       ((self.melt.get("characters") or {}).get("dead_prunable") or {})):
            c = bucket.get(str(cid))
            if not isinstance(c, dict):
                continue
            pd = ((c.get("alive_data") or {}).get("prison_data")
                  or (c.get("dead_data") or {}).get("prison_data"))
            if not isinstance(pd, dict):
                return None
            if str(pd.get("date")) != str(date) \
                    or str(pd.get("imprison_type_date")) != str(date):
                return None
            t = pd.get("type")
            return str(t) if t else None
        return None

    def _same_day_imprisoned(self, jailer, date):
        """Memory ids of everyone imprisoned by (jailer, date) → [mid, …] (lazy cache).

        One such cluster is a single action, so cluster-level demographics (whether minors are
        present, for instance) must be judged over the whole cluster, not the current row alone.
        Prisoner ids come from `_mem_holder_index()`, since a memory object carries no owner."""
        key = (jailer, str(date))
        cache = getattr(self, "_same_day_cache", None)
        if cache is None:
            cache = {}
            self._same_day_cache = cache
        if key in cache:
            return cache[key]
        out = []
        if jailer is not None:
            db = (self.melt.get("character_memory_manager") or {}).get("database") or {}
            for mid, e in db.items():
                if not isinstance(e, dict) or e.get("type") != "imprisoned":
                    continue
                if str(e.get("creation_date")) != str(date):
                    continue
                if (e.get("participants") or {}).get("imprisoner") != jailer:
                    continue
                try:
                    out.append(int(mid))
                except (TypeError, ValueError):
                    continue
        cache[key] = out
        return out

    def _has_minor_victim(self, jailer, date, victim):
        """Whether the jailer's prison cluster that day includes a minor (the prisoner included)."""
        a = self._age_at(victim, date)
        if a is not None and a < 16:
            return True
        holder = self._mem_holder_index()
        for mid in self._same_day_imprisoned(jailer, date):
            v = holder.get(mid)
            if v is None or v == victim:
                continue
            av = self._age_at(v, date)
            if av is not None and av < 16:
                return True
        return False

    def capture_manner(self, victim, jailer, date, cluster_n=1):
        """How this imprisonment was made → (tag, note); note serves logs/asserts only.

        The save cannot distinguish a city-fall capture from a defeat capture: battle, siege and
        raid captures all end in a bare `imprison` with identical fields, and `melt["sieges"]` keeps
        only sieges still running at save time. Tags therefore come only from hard evidence, and
        everything else is `unknown`, whose wording carries no manner word at all:

          | tag | evidence |
          | --- | --- |
          | `diarchy` | prisoner carries `imprisoned_by_diarch` (its only set point) |
          | `raid` | jailer raided that day: `landed_data.last_raid` equals the entry date, or a same-day house-relation raid row with raider = jailer and target = prisoner or their house. Ordered before `batch` — hard evidence beats a heuristic |
          | `batch` | ≥3 people jailed by the same jailer that day ⇒ group capture, so a defeat capture is out |
          | `battle_poi` | province battle point of interest matching jailer, prisoner as loser and date (conclusive, narrow) |
          | `battle` | a real `battle_*_memory` that day with prisoner = loser and jailer = winner |
          | `not_battle` | prisoner is under 16, or the cluster contains a minor ⇒ defeat capture is out |
          | `unknown` | none of the above → no manner word is written |

        `battle` and `battle_poi` are switched off when the fresh cell grade is `dungeon`, because
        a battle capture always writes `type = house_arrest` while a bare `imprison` defaults to
        `dungeon`; that only refutes, never proves (house_arrest does not imply a battle), and
        `raid` is unaffected. Age is the one reliable refutation of a defeat capture: its pool is
        adult combatants (the losers' primary commander plus knights) whereas a city fall takes
        barony holders and courts — and female prisoners do occur among battle captures."""
        try:
            victim = int(victim)
            jailer = int(jailer) if jailer is not None else None
        except (TypeError, ValueError):
            return ("unknown", "")
        if victim is None or not date:
            return ("unknown", "")
        # diarchy regent abduction (conclusive)
        if "imprisoned_by_diarch" in self._var_flags(victim):
            return ("diarchy", "imprisoned_by_diarch")
        # raiding proven; either test suffices:
        #   ②a the jailer's `landed_data.last_raid` equals the entry date (last raid only, narrow);
        #   ②b a same-day house-relation raid row with raider = jailer and target = the prisoner or
        #       their house (accumulates day by day, covering days ②a has overwritten).
        #   Ordered before `batch`, which only emits a manner-less 拘押: a raid has save proof,
        #   and hard evidence beats a heuristic.
        if self._last_raid_on(jailer, date):
            return ("raid", f"last_raid={date}")
        _hk = self._house_raid_on(jailer, victim, date)
        if _hk:
            return ("raid", f"house_relation_raid/{_hk}")
        # ≥3 people jailed by the same jailer that day = group capture ⇒ a defeat capture is out:
        # that pool is the losers' primary commander plus knights taken one by one, whereas these
        # clusters are children and unrelated courtiers. `cluster_n` comes from the caller because a
        # prisoner's own `imprisoned` memory is reclaimed with them when they die.
        if cluster_n >= 3:
            return ("batch", f"{cluster_n}人同日")
        # cell-grade refutation: `dungeon` with all three dates equal ⇒ no battle capture, since a
        # battle capture always writes `type = house_arrest` while a bare `imprison` defaults to
        # dungeon. It only refutes — raid (②) is unaffected.
        _no_battle = self._prison_type_fresh(victim, date) == "dungeon"
        # province battle point of interest (conclusive, narrow; winner + loser + date must agree)
        if jailer is not None and not _no_battle:
            hits = self._battle_poi_hits(jailer, date, victim=victim)
            if hits:
                return ("battle_poi", f"province={hits[0]}")
        # same-day real battle memory (only `battle_*_memory`) with the prisoner as loser and, when
        # the jailer is known, as winner too — several battles can share one day. `war_won` /
        # `war_lost` are war-end memories and are excluded, so such days fall back to a bare 囚禁
        # instead of claiming a battle capture.
        for rec in (() if _no_battle else self._battle_by_date().get(str(date), [])):
            if not str(rec[0]).startswith("battle_"):
                continue
            loser, winner = self._battle_winner(rec)
            _ok = (loser == victim) and (winner == jailer if jailer is not None
                                         else True)
            if _ok:
                return ("battle", f"{rec[0]} loser={loser} winner={winner}")
        # prisoner is a minor, or the cluster contains one ⇒ no defeat capture (that pool is adult
        # combatants only, while a city fall also takes court and family)
        _age = self._age_at(victim, date)
        if _age is not None and _age < 16:
            return ("not_battle", f"{_age}岁")
        if self._has_minor_victim(jailer, date, victim):
            return ("not_battle", "同簇含未成年人")
        return ("unknown", "")

    def sex_mem_lines(self, cid, as_of=None, player=None):
        """Forced / semi-forced sexual memories involving this character → ["date，sentence"].

        The only outlets are the friend and enemy biographies; the character profile and the public
        chronology carry no sexual matter, so this is the single exit, attached by
        `biography._subject_facts`.

        Two sources are unioned and deduped by (date, act, consent, partner): ① memories the character
        holds themself — a `giving`/`receiving` key name gives the direction, and the victim's record
        yields "X被Y强迫…" directly; ② the same memory held by the protagonist (`sex_partner == cid`),
        which is the durable copy because a victim's memory is reclaimed by the engine when they die;
        that path renders from the victim's point of view so the direction is never reversed. Only
        `noncon` / `dubcon` are kept, and nothing after `as_of`."""
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return []
        try:
            player = int(player) if player is not None else None
        except (TypeError, ValueError):
            player = None
        db = (self.melt.get("character_memory_manager") or {}).get("database") or {}
        holder = self._mem_holder_index()
        out = {}
        for mid, e in db.items():
            if not isinstance(e, dict):
                continue
            t = str(e.get("type") or "")
            info = sex_mem_info(t)
            if info is None or not info["kept"]:
                continue
            parts = e.get("participants") or {}
            other = parts.get(_SEX_PARTNER_SLOT)
            if not isinstance(other, int):
                continue
            try:
                h = holder.get(int(mid))
            except (TypeError, ValueError):
                h = None
            if h == cid and other != cid:
                s = _sex_mem_sentence(self, cid, e, info)
                key_other = other
            elif player is not None and h == player and other == cid:
                # protagonist-side lookup: the entry records the protagonist giving, but the
                # sentence must take the victim's side
                act = info["act"] or "base"
                w = _style.SEX_MEM_WORDING["victim_noncon" if info["consent"] == "noncon"
                                           else "victim_dubcon"]
                nm = self.event_name(cid, date=e.get("creation_date"))
                om = self.event_name(player, date=e.get("creation_date"))
                s = w.get(act, w["base"]).format(name=nm, other=om) if (nm and om) else ""
                # dedup key uses the other party from the character's own point of view, otherwise
                # the character's entry (sex_partner = protagonist) and the protagonist's entry
                # (sex_partner = character) count as two and the same sentence appears twice
                key_other = player
            else:
                continue
            if not s:
                continue
            _md = self.mem_date(cid, e)
            if as_of and _md and cl.date_key(_md) > cl.date_key(as_of):
                continue
            out[(_md, info["act"], info["consent"], key_other)] = \
                f"{self.date(_md)}，{s}"
        return [out[k] for k in sorted(out, key=lambda x: cl.date_key(str(x[0])))]

    def _prison_opinion_index(self):
        """{(owner, target): [(modifier, start_date)]} plus a fallback index by owner (lazy)."""
        cached = getattr(self, "_prison_opinions", None)
        if cached is not None:
            return cached
        by_pair, by_owner = {}, {}
        for o in (self.melt.get("opinions") or {}).get("active_opinions") or []:
            if not isinstance(o, dict):
                continue
            ow, tg = o.get("owner"), o.get("target")
            if not isinstance(ow, int) or not isinstance(tg, int):
                continue
            for v in cl._opinion_values(o):
                mod = str(v.get("modifier") or "")
                if mod not in self._PRISON_MANNER_MODS:
                    continue
                st = str(v.get("start_date") or "")
                by_pair.setdefault((ow, tg), []).append((mod, st))
                by_owner.setdefault(ow, []).append((mod, st))
        self._prison_opinions = (by_pair, by_owner)
        return self._prison_opinions

    def release_manner(self, victim, jailer, out_date):
        """Release reason as of `out_date` → (ending family, wording); ('', '') when undecidable.

        Evidence is a release-type opinion modifier newly gained by the prisoner on that very day —
        the save carries its `start_date`, which is more precise than differencing saves. Family
        purge endings are decided elsewhere (`family_purge_victims` / `_purge_dates`). When the melt
        shows nothing this falls back to `cache["prison_manners"]` (latched per save), because these
        opinions decay over 10 years and vanish with their holder while the final volume loads only
        the last save's melt."""
        if victim is None or not out_date:
            return ("", "")
        d = str(out_date)
        by_pair, by_owner = self._prison_opinion_index()
        rows = list(by_pair.get((int(victim), int(jailer)), [])) \
            if isinstance(jailer, int) else []
        if not any(st == d for _m, st in rows):
            rows += by_owner.get(int(victim), [])
        for mod, st in rows:
            if st == d:
                return self._PRISON_MANNER_MODS[mod]
        return self._latch_manner(victim, jailer, d)

    def _latch_manner(self, victim, jailer, date):
        """Cache fallback for the release reason — reads `cache["prison_manners"]`.

        A latch record (see `cache_lib._latch_prison_manners`) has two shapes of `kind`: an opinion
        source stores the modifier name (demanded_hook / ransomed_from_prison …), a hook source
        stores the ending-family name (hook = the favor_hook / indebted_hook branch of a ransom)."""
        if not isinstance(jailer, int):
            return ("", "")
        rec = (self.cache.get("prison_manners") or {}).get(
            f"{int(victim)}>{int(jailer)}>{date}")
        if not isinstance(rec, dict):
            return ("", "")
        kind = str(rec.get("kind") or "")
        if kind in self._PRISON_MANNER_MODS:
            return self._PRISON_MANNER_MODS[kind]
        if kind in self._PRISON_KIND_WORD:
            return (kind, self._PRISON_KIND_WORD[kind])
        return ("", "")

    def is_purge_prisoner(self, victim, jailer, date):
        """Whether this imprisonment belongs to a family purge.

        Two candidate tests exist: ① the victim is on `family_purge_victims(jailer)`; ② the date is
        a purge day of `purged_houses(jailer)` and the victim's house is the house purged that day.
        This method creates a house-level row, so a dateless ① would drag later events back to the
        imprisonment year — only ②, which carries a date, is used here. A jailer of the
        protagonist's own house counts too (several generations of one house)."""
        if jailer is None or not date or victim is None:
            return False
        houses = self.purged_houses(jailer).get(str(date))
        if not houses:
            return False
        try:
            hid = self._house_of_cid(int(victim))
        except (TypeError, ValueError):
            return False
        return hid is not None and hid in houses

    def house_purge_pairs(self, house_id, my_houses):
        """(date, executioner) pairs for this house's executions on purge days.

        Same source as the purge test in `_house_prison_nodes` (`purged_houses`): some houses were
        not jailed on their purge day (members jailed on one day, the head executed on another), so
        prison nodes alone would miss their house-level row."""
        out = set()
        for cid, c in self._chars.items():
            if not isinstance(c, dict) or c.get("dynasty_house") != house_id:
                continue
            dd = c.get("dead_data") or {}
            if dd.get("reason") != "death_execution":
                continue
            k = dd.get("killer")
            d = str(dd.get("date") or "")
            if not isinstance(k, int) or not d:
                continue
            k = int(k)
            if k not in my_houses and self._house_of_cid(k) not in my_houses:
                continue
            if house_id in self.purged_houses(k).get(d, ()):
                out.add((d, k))
        return out

    def house_purge_line(self, killer, house_id, date, house_label=""):
        """House-level purge row: "924年3月25日，X诛灭裴氏满门，处决家主N人，余族尽数流放".

        Closing wording: everyone landed is executed and the exiled are landless remnants who are
        not named; the head count N is the number of this house executed that day."""
        if killer is None or not date:
            return ""
        d = str(date)
        house_label = house_label or self._house_label(house_id) or ""
        if not house_label:
            return ""
        n = 0
        for cid, c in self._chars.items():
            if not isinstance(c, dict):
                continue
            dd = c.get("dead_data") or {}
            if dd.get("reason") != "death_execution" or dd.get("killer") != int(killer):
                continue
            if str(dd.get("date") or "") != d:
                continue
            if c.get("dynasty_house") != house_id:
                continue
            n += 1
        jn = self._feud_role_title(killer, d) or "主角"
        head = f"{jn}诛灭{house_label}满门"
        if n:
            head += f"，处决家主{n}人"
        return head + "，余族尽数流放"

    def _house_prison_nodes(self, other_house, my_houses, as_of,
                            raw_entries=None):
        """Prison nodes between two houses (both directions).

        Returns [{"date", "victim", "jailer", "vn", "jn", "text", "kind", "sp", "purge",
        "from_history"}]. Direction is resolved per node so that both "our house jailed theirs"
        and "theirs jailed ours" produce rows. Every verdict goes through the single exits
        `prison_exit` / `prison_tail`, the opening clause through `prison_capture_head`.
        `raw_entries` are house-feud log entries containing a prison word: a later protagonist's
        cache often no longer holds the victim's `imprisoned` memory, so the log text plus the
        cached death record still yields a node."""
        cache = self.cache
        chars = cache.get("characters") or {}
        W = _style.FACT_WORDING
        out = []

        def _house(cid):
            return self._house_of_cid(cid)

        def _in_span(d):
            return not (as_of and d and cl.date_key(d) > cl.date_key(as_of))

        def _direction(vh, jh):
            """Direction of this node; None when it does not belong to this feud."""
            if vh == other_house and jh in my_houses:
                return "fwd"          # our house jailed theirs
            if vh in my_houses and jh == other_house:
                return "rev"          # theirs jailed ours
            return None

        def _build(victim, jailer, d, purge, from_history):
            head = self.prison_capture_head(victim, jailer, d, cluster_n=1)
            if not head:
                return None
            tail, kind, sp = self.prison_tail(victim, jailer, d, purge=purge)
            return {"date": d, "victim": victim, "jailer": jailer,
                    "vn": self._feud_role_title(victim, d),
                    "jn": self._feud_role_title(jailer, d),
                    "text": head + tail, "kind": kind, "sp": sp,
                    "purge": purge, "from_history": from_history}

        out = []
        _seen = set()
        for cid_s, rec in chars.items():
            try:
                cid = int(cid_s)
            except (TypeError, ValueError):
                continue
            vh = _house(cid)
            if vh != other_house and vh not in my_houses:
                continue
            for m in rec.get("memories") or []:
                if (m.get("type") or "") != "imprisoned":
                    continue
                jailer = (m.get("participants") or {}).get("imprisoner")
                if not isinstance(jailer, int):
                    continue
                if _direction(vh, _house(jailer)) is None:
                    continue
                d = str(m.get("creation_date") or "")
                if not _in_span(d):
                    continue
                # duplicates: the same person jailed by the same jailer on the same day is one node
                if (d, cid, jailer) in _seen:
                    continue
                _seen.add((d, cid, jailer))
                node = _build(cid, jailer, d,
                              self.is_purge_prisoner(cid, jailer, d), False)
                if node:
                    out.append(node)
        # log-text fallback: build a node only when (date, victim) has no memory node yet
        for ent in (raw_entries or []):
            d = str(ent.get("date") or "")
            if not d or not _in_span(d):
                continue
            ids = [i for i in (ent.get("ids") or []) if isinstance(i, int)]
            if len(ids) < 2:
                continue
            # a feud-cause prison row ("A被B无理由囚禁", ids ordered victim then actor, dated to the
            # day the feud escalated) builds no node — that imprisonment has its own event-style row
            _rawtxt = ent.get("raw") or ent.get("text") or ""
            if _is_feud_reason_prison(_rawtxt):
                continue
            # event-style rows always read "[actor]囚禁了[target]"
            # (house_relations_l_simp_chinese.yml), so the id order is (jailer, victim); roles must
            # not be assigned by house membership, since in a reverse row the actor is the other house
            victim = jailer = None
            _a, _b = ids[0], ids[1]
            _ah, _bh = _house(_a), _house(_b)
            if _ah in my_houses and _bh == other_house:
                jailer, victim = _a, _b
            elif _ah == other_house and _bh in my_houses:
                jailer, victim = _a, _b
            if victim is None or jailer is None:
                continue
            if (d, victim, jailer) in _seen or \
                    any(n["date"] == d and n["victim"] == victim for n in out):
                continue
            node = _build(victim, jailer, d,
                          self.is_purge_prisoner(victim, jailer, d), True)
            if node:
                out.append(node)
        return out

    def _fold_house_prison_nodes(self, nodes):
        """Collapse nodes jailed on the same day by the same jailer.

        Naming follows the existing rule (title rank descending → reign start ascending → first 5
        people + 等N人). The closing clause goes through `_prison_fold_tail`, the same as the
        chronology: counts are keyed by (ending family, duration) with the duration written as
        "N年后" rather than the day the imprisonment ended, so clusters containing executions or
        deaths in prison fold as well."""
        W = _style.FACT_WORDING
        groups, order = {}, []
        for n in nodes:
            key = (str(n.get("date") or ""), n.get("jailer"))
            if key not in groups:
                groups[key] = []
                order.append(key)
            groups[key].append(n)
        out = []
        for key in order:
            rows = groups[key]
            d, jailer = key
            if len(rows) < 2:
                n = rows[0]
                out.append((n["date"], n["text"]))
                continue
            ranked = []
            for n in rows:
                rank, since = self.title_rank_since_at(n["victim"], d)
                ranked.append((rank, since, n))
            ranked.sort(key=lambda r: (-r[0],
                                       cl.date_key(r[1]) if r[1] else _DATE_KEY_MAX,
                                       r[2]["victim"]))
            names = [r[2].get("vn") or "" for r in ranked]
            names = [x for x in names if x]
            if not names:
                continue
            shown = "、".join(names[:5])
            if len(names) > 5:
                shown += f"等{len(names)}人"
            jn = rows[0].get("jn") or ""
            body = W["prison_jailed"].format(jailer=jn, victim=shown) if jn \
                else W["prison_held"].format(victim=shown)
            body += _prison_fold_tail(
                [{"o": r.get("kind") or "released", "sp": r.get("sp") or ""}
                 for r in rows], self)
            out.append((d, body))
        return out

    def _house_war_nodes(self, other_house, my_houses, as_of):
        """War causality nodes between two houses → [(date, sentence)].

        `house_relations.history` records only the moments a relation value moved (the imprisonment
        on the day a feud began), while war outcomes and conquests live in cached memories; without
        this the model would read a siege capture as the cause of the feud. Four node kinds are
        computed straight from memories: declaration, victory, title lost, and falling to a
        landless adventurer."""
        cache = self.cache
        pid = cache.get("player_id")
        if pid is None:
            return []
        chars = cache.get("characters") or {}
        out = []

        def _house(cid):
            return self._house_of_cid(cid)

        def _nm(cid, date=None):
            # the protagonist appears by name only (no title) in these rows
            return self.event_name(cid, date) if cid else ""

        def _in_span(d):
            return not (as_of and d and cl.date_key(d) > cl.date_key(as_of))

        # ---- ① protagonist's declarations of war on, and wins over, that house's members ----
        prec = chars.get(str(pid)) or {}
        for m in prec.get("memories") or []:
            t = m.get("type") or ""
            if t not in ("offensive_war", "war_won"):
                continue
            d = m.get("creation_date") or ""
            if not _in_span(d):
                continue
            parts = m.get("participants") or {}
            other = parts.get("other_party") if t == "offensive_war" \
                else parts.get("loser")
            if not isinstance(other, int) or _house(other) != other_house:
                continue
            onm = _nm(other, d)
            if t == "offensive_war":
                cb = ""
                for v in m.get("vars") or []:
                    if v.get("flag") == "war_cb":
                        cb = str(v.get("value") or "")
                        break
                kind = "征服战" if "conquest" in cb else "开战"
                # the protagonist appears by name only here (not the event-style full title)
                out.append((d, f"{self.event_name(pid, d)}向{onm}"
                               f"发动{kind}"))
            else:
                out.append((d, f"{self.event_name(pid, d)}战胜{onm}"))
        # ---- ② imprisonments of that house by our house live in `_house_prison_nodes`, which owns
        # the verdicts and wording, so no per-person prison sentence is emitted here ----
        # ---- ③ titles the other side lost ----
        lost_titles = []
        for cid, rec in chars.items():
            if _house(int(cid)) != other_house:
                continue
            for m in rec.get("memories") or []:
                if (m.get("type") or "") != "lost_title_memory":
                    continue
                # the loss date comes from the title-history event; the memory date is usually a day late
                d = self.mem_date(int(cid), m)
                if not _in_span(d):
                    continue
                parts = m.get("participants") or {}
                if parts.get("new_holder") != pid:
                    continue
                tid = None
                for v in m.get("vars") or []:
                    if v.get("flag") == "landed_title" and v.get("identity"):
                        tid = v.get("identity")
                        break
                tname = self.title(tid) if tid else ""
                nm = _nm(int(cid), d)
                out.append((d, f"{nm}失守{tname}" if tname else f"{nm}失守领地"))
                lost_titles.append((d, int(cid), tname))
        # ---- the other side ends up a landless adventurer (the key to why they resent it) ----
        seen_cid = None
        for d, cid, tname in sorted(lost_titles, key=lambda x: cl.date_key(x[0])):
            if self._title_kind_landless(cid, d):
                nm = _nm(cid)
                if nm and cid != seen_cid:
                    out.append((d, f"{nm}自此沦为无地冒险者"))
                    seen_cid = cid
                break
        out.sort(key=lambda x: cl.date_key(x[0]))
        return out

    def _title_kind_landless(self, cid, date):
        """Whether the character holds no landed title on `date` (a landless adventurer)."""
        try:
            tier, tid = self._primary_title_at(cid, as_of=date)
        except Exception:
            return False
        if tid is None:
            return True
        return self.title_kind(tid) in ("camp", "estate", "none")

    def house_feuds(self):
        """Houses at quarrel / rivalry / feud level with the protagonist's house.
        Returns [{house, level, events:[date, event…]}], most events first."""
        cache = self.cache
        pid = cache.get("player_id")
        if pid is None:
            return []
        prec = (cache.get("characters") or {}).get(str(pid)) or {}
        my_houses = set()
        h0 = prec.get("dynasty_house")
        if isinstance(h0, int):
            my_houses.add(h0)
        did = cache.get("dynasty_id")
        dh = (self.melt.get("dynasties") or {}).get("dynasty_house") or {}
        if did is not None:
            for hid, e in dh.items():
                if isinstance(e, dict) and e.get("dynasty") == did:
                    my_houses.add(int(hid))
        if not my_houses:
            return []
        db = (self.melt.get("house_relations") or {}).get("database") or {}
        NEG = {"default_house_relation_level_feud",
               "default_house_relation_level_rivalry",
               "default_house_relation_level_quarrel"}
        # A decade volume lists only the feud flow inside those ten years; the final and
        # living-subject volumes (no decade) use the whole life. A house whose current level is
        # neutral but which has negative flow in the window still qualifies, and its level word
        # reads 旧怨.
        _lo = None
        if getattr(self, "decade", None) and self.as_of:
            try:
                _lo = _decade_lower_bound(self)
            except Exception:
                _lo = None
        _lok = cl.date_key(_lo) if _lo else None
        _hikey = cl.date_key(str(self.as_of)) if self.as_of else None

        def _in_window(d):
            if not d:
                return False
            k = cl.date_key(d)
            if _lok is not None and k < _lok:
                return False
            if _hikey is not None and k > _hikey:
                return False
            return True

        out = []
        for _k, r in db.items():
            if not isinstance(r, dict):
                continue
            hs = r.get("houses") or []
            if not any(h in my_houses for h in hs):
                continue
            lvl = r.get("level") or ""
            _neg_in_win = any(_in_window(str(e.get("date") or ""))
                              and (e.get("amount") or 0) < 0
                              # a divorce on the death day is not a grievance and does not pull a
                              # house into the record
                              and not self.is_widow_divorce(
                                  e.get("change_reason") or "",
                                  str(e.get("date") or ""))
                              for e in (r.get("history") or []))
            if lvl not in NEG and not _neg_in_win:
                continue
            other = [h for h in hs if h not in my_houses]
            if not other:
                continue
            # fall back to the dynasty name, then to 某家族, so a house id is never leaked
            _hname = cl.house_name_zh(self.melt, other[0]) or ""
            if not _hname:
                _did = cl.dynasty_id_of(self.melt, other[0])
                if _did is not None:
                    _hname = cl.dynasty_name_zh(self.melt, _did) or ""
            _hlabel_raw = _hname or "某家族"
            _hlabel = self._house_label(other[0]) or _hlabel_raw
            events = []
            _raw_ids = {}      # (date, sentence) -> character ids in that log row (both ends)
            _raw_prison = []   # log rows containing a prison word {date, ids, text}, node fallback
            for e in (r.get("history") or []):
                d = str(e.get("date") or "")
                # as_of cut: a decade biography lists only events up to that date
                if self.as_of and d and cl.date_key(d) > cl.date_key(self.as_of):
                    continue
                if _lok is not None and d and cl.date_key(d) < _lok:
                    continue
                # both ends are re-rendered as of the event date to add realm names (the game text
                # writes only 国王/王); the house ids and the other house's label make a
                # self-referential row fall back to "{other house}族人"
                _raw = e.get("change_reason") or ""
                # a divorce written on the day one spouse died (see `is_widow_divorce`) is dropped
                # entirely: no event, no node fallback, no bearing on the negative-flow test
                if self.is_widow_divorce(_raw, d):
                    continue
                # a feud-cause prison row (passive, ids reversed, dated to the feud's escalation) is
                # dropped entirely — the imprisonment has its own event-style row
                if _is_feud_reason_prison(_raw):
                    continue
                txt = self._rerender_feud_event(_raw, d,
                                                houses=hs, other_label=_hlabel)
                if not txt:
                    # unreadable game text (rakaly sentinel string / unresolved key) → rebuild from
                    # cached memories
                    txt = self._feud_event_fallback(my_houses, other[0], d, _hlabel)
                if not txt:
                    continue
                _ids = []
                for _i in _FEUD_CHAR_RE.findall(str(_raw)):
                    try:
                        _ic = int(_i)
                    except (TypeError, ValueError):
                        continue
                    # both ends are collected: pairing and same-day suppression need our own side's
                    # id as well. Order of appearance must be preserved, because the prison template
                    # reads "[actor]囚禁了[target]", i.e. (jailer, victim) — sorting would destroy it.
                    if self._house_of_cid(_ic) is not None and _ic not in _ids:
                        _ids.append(_ic)
                _raw_ids[(d, txt)] = set(_ids)
                if any(_k in txt for _k in _PRISON_KIND_WORDS):
                    _raw_prison.append({"date": d, "ids": list(_ids),
                                        "text": txt, "raw": _raw})
                events.append((d, txt))
            # War causality nodes supplement the flow: the flow's "向X宣战" carries no war type and
            # "成为X的仇敌" only the outcome, so a same-day war sentence from the flow is replaced by
            # the more informative node. Nodes added by this loop coexist on the same day (a victory
            # and a lost title are two facts of one war).
            _hist_events = list(events)
            _node_events = []
            for d, txt in self._house_war_nodes(other[0], my_houses, self.as_of):
                _hist_events = [
                    (ed, et) for ed, et in _hist_events
                    if str(ed) != str(d)
                    or not any(k in et for k in
                               _WAR_KIND_WORDS + _PRISON_KIND_WORDS)]
                if (str(d), txt) not in {(str(ed), et) for ed, et in
                                         _hist_events + _node_events}:
                    _node_events.append((d, txt))
            # the prison side is carried by structured nodes: ① a purge day's whole cluster becomes
            # one house-level row; ② remaining same-day, same-jailer clusters fold into one row;
            # ③ flow rows already covered by a node are dropped, and rows with no evidence keep the
            # game text. Both directions produce nodes, and `raw_entries` lets a later protagonist's
            # cache fall back to the log text plus the cached death/release record when the victim's
            # `imprisoned` memory has been reclaimed by the engine.
            _nodes = self._house_prison_nodes(other[0], my_houses, self.as_of,
                                              raw_entries=_raw_prison)
            # house-level rows cover purge days on which this house was jailed ∪ executed; both
            # tests share one source
            _pairs = {(n["date"], n["jailer"]) for n in _nodes if n["purge"]}
            _pairs |= self.house_purge_pairs(other[0], my_houses)
            _purge_days = {d for d, _k in _pairs}
            _node_keys = {(n["date"], n["victim"]) for n in _nodes}
            # Sort weight counts the per-person events *before* folding: folding merges a whole
            # cluster into one row, and folded counts would push a purged great house out of the top
            # five.
            _weight = len(_hist_events) + len(_node_events) + len(_nodes)
            if _purge_days:
                # one house-level row per (date, executioner) — never a cross product, which would
                # credit a purge to a successor not yet in power
                for _d, _killer in sorted(_pairs, key=lambda x: cl.date_key(x[0])):
                    _line = self.house_purge_line(_killer, other[0], _d, _hlabel)
                    if _line:
                        _node_events.append((_d, _line))
                # the purge day's per-person prison nodes and flow rows (including per-person
                # execution sentences) are suppressed: those appear in the annals and the assassin
                # record, while this record uses the house-level row
                _hist_events = [
                    (ed, et) for ed, et in _hist_events
                    if not (str(ed) in _purge_days
                            and any(k in et for k in
                                    _PRISON_KIND_WORDS + ("处决了",)))]
                _nodes = [n for n in _nodes if not n["purge"]]
            # ③ flow rows already covered by a same-day, same-person node are dropped — a verbatim
            #    duplicate beside the more informative node adds nothing — while rows with no
            #    evidence keep the game text. Execution sentences are included, since they and a
            #    single-person execution node are two spellings of one event; the test remains "a
            #    node exists for that person on that same day", so executions without one stay.
            _hist_events = [
                (ed, et) for ed, et in _hist_events
                if not (any(k in et for k in
                            _PRISON_KIND_WORDS + _EXEC_KIND_WORDS)
                        and _raw_ids.get((ed, et))
                        and any((str(ed), _v) in _node_keys
                                for _v in _raw_ids[(ed, et)]))]
            _node_events.extend(self._fold_house_prison_nodes(_nodes))
            events = _hist_events + _node_events
            if not events:
                continue
            events.sort(key=lambda x: cl.date_key(x[0]))
            # localize the relation level, falling back to natural words instead of the raw key;
            # a house now neutral but with negative flow in the window reads 旧怨
            _lvl = L.loc(self.table, lvl) or {
                "default_house_relation_level_feud": "世仇",
                "default_house_relation_level_rivalry": "敌对",
                "default_house_relation_level_quarrel": "争吵",
            }.get(lvl, "")
            if lvl not in NEG:
                _lvl = "旧怨"
            if not _lvl:
                continue
            out.append({
                "house": _hlabel_raw,
                # historiographic house name (程氏) used by the "家族：程氏，两族为世仇" row
                "house_label": _hlabel,
                "level": _lvl,
                # internal: (game date, rendered sentence) pairs, so merging, sorting and deduping
                # use game date keys instead of re-parsing the rendered "924年3月25日"
                "pairs": [(d, f"{self.date(d)}，{t}") for d, t in events],
                "weight": _weight,
            })
        return self._merge_and_cap_feuds(out)

    # The house-feud record shows at most five houses, merging same-surname houses first: one
    # surname can map to several house ids, and without merging the same surname appears as several
    # blocks. Order: level descending (世仇 → 敌对 → 争吵) → event count descending → first event
    # date ascending → surname.
    HOUSE_FEUDS_MAX = 5

    def _merge_and_cap_feuds(self, rows):
        """Merge same-name houses, sort by level and event count, keep the first HOUSE_FEUDS_MAX.

        Input rows carry `pairs` = [(game date, rendered sentence)]; output rows carry
        `events` = [rendered sentence]."""
        rank = {"世仇": 3, "敌对": 2, "争吵": 1}
        merged = {}
        order = []
        for r in rows:
            key = r.get("house_label") or r.get("house") or ""
            if not key:
                continue
            cur = merged.get(key)
            if cur is None:
                merged[key] = {"house": r.get("house") or key,
                               "house_label": r.get("house_label") or key,
                               "level": r.get("level") or "",
                               "pairs": list(r.get("pairs") or []),
                               "weight": int(r.get("weight") or 0)}
                order.append(key)
                continue
            # keep the heaviest level; the event union dedupes by (date, sentence), since the flow
            # can hold verbatim duplicate "囚禁了X" rows for one person on one day
            if rank.get(r.get("level") or "", 0) > rank.get(cur["level"], 0):
                cur["level"] = r.get("level") or cur["level"]
            cur["weight"] += int(r.get("weight") or 0)
            cur["pairs"].extend(r.get("pairs") or [])
        out = []
        for key in order:
            r = merged[key]
            seen, pairs = set(), []
            for d, txt in r["pairs"]:
                if (str(d), txt) in seen:
                    continue
                seen.add((str(d), txt))
                pairs.append((d, txt))
            pairs.sort(key=lambda x: cl.date_key(str(x[0])))
            out.append({"house": r["house"], "house_label": r["house_label"],
                        "level": r["level"],
                        "events": [txt for _d, txt in pairs],
                        "_first": cl.date_key(str(pairs[0][0])) if pairs else _DATE_KEY_MAX,
                        "_w": r["weight"], "_n": len(pairs)})
        out.sort(key=lambda x: (-rank.get(x.get("level") or "", 0),
                                -x["_w"], -x["_n"], x["_first"],
                                x.get("house_label") or ""))
        out = out[:self.HOUSE_FEUDS_MAX]
        for r in out:
            r.pop("_first", None)
            r.pop("_w", None)
            r.pop("_n", None)
        return out

    # The artifact record keeps only rare treasures, at the game's top grade 名望级 (illustrious):
    # neither the save nor the game defines a legendary grade, so a legendary filter would always be
    # empty. Hunting trophies (hides, horns, skulls) are dropped as filler even when rare, and the
    # list is capped to 20 items to keep the prompt small.
    ARTIFACT_RARITY = ("illustrious",)
    # Part artifacts (made from a body) are kept only at green or above. Grade order
    # common(白) < masterwork(绿) < famed(蓝) < illustrious(紫), from
    # `game/common/customizable_localization/ledger_custom_loc.txt` (Chinese names in
    # `game/localization/simp_chinese/inventory/inventory_l_simp_chinese.yml`). The "devouring" mod
    # maps a bone's rarity to the eaten person's title — empire illustrious / kingdom famed / duke
    # masterwork / everyone else common (`workshop/<CK3_appid>/3802979803/common/scripted_effects/
    # devour_effects.txt`) — so this threshold equals "bones of dukes and above".
    ARTIFACT_PART_RARITY = ("masterwork", "famed", "illustrious")
    ARTIFACT_FILLER_TYPES = {
        "animal_hide", "animal_hide_big", "animal_trinket",
        "animal_skull", "VIET_clutter",
    }
    ARTIFACT_MAX = 20
    # A separate quota for part artifacts (bones): they are a different kind of item from the rare
    # treasures above, and one shared cap let a "mass devouring" campaign push out imperial crowns
    # and seals. Part artifacts are taken in creation-date order up to this quota.
    ARTIFACT_PART_MAX = 30
    # Artifact transfer rows → whose hands the artifact is in *after* that row. For conquest the
    # actor is the loser and recipient the new holder; inherited / given / purchased / prize_* /
    # stolen / created / taken_in_siege put the new holder in recipient (created falls back to actor
    # on older saves), while taken_in_battle uses actor. `claimed_by_house` is absent because
    # neither slot matches (recipient is always null): such rows are skipped, and an earlier row
    # with an owner decides.
    ARTIFACT_HOLDER_SLOT = {
        "conquest": "recipient",
        "inherited": "recipient",
        "given": "recipient",
        "purchased": "recipient",
        "prize_awarded": "recipient",
        "prize_created": "recipient",
        "stolen": "recipient",
        "taken_in_battle": "actor",
        "taken_in_siege": "recipient",
        "discovered": "actor",
        "created": "recipient",
    }

    # Character-part artifacts — items made from a human body: a human-skull stand from executing a
    # prisoner (guaranteed when the prisoner is a nemesis) and a skull goblet when a nemesis dies
    # (Friends & Foes). Both are common/masterwork grade, which is why part artifacts have their own
    # rarity list instead of the 名望级-only threshold.
    ARTIFACT_PART_VISUALS = {"skull_goblet", "human_skull", "devour_bone_visual"}
    ARTIFACT_PART_WORDS = ("头骨", "头颅", "颅骨", "头盖骨", "乳牙",
                           "之骨", "剩的骨头", "被吃掉了")

    # Data-function blocks inside an artifact description: \x15ONCLICK:CHARACTER,id \x15TOOLTIP:… \x15L name\x15!\x15!\x15!
    _ARTIFACT_REF_RE = re.compile(
        r"\x15ONCLICK:([A-Z_]+),([^\s\x15]+)"
        r"(?:\s*\x15TOOLTIP:[^\s\x15]+)?"
        r"\s*\x15L;?\s*(.*?)\x15!\x15!\x15!", re.S)

    def _artifact_material(self, raw, date=None):
        """Artifact description → a clean Chinese material sentence; '' when unreadable.

        Embedded data-function blocks (`\\x15ONCLICK:CHARACTER,id … \\x15L name\\x15!\\x15!\\x15!`) are
        resolved: a CHARACTER block is re-rendered by this project's `event_name` as of the date,
        giving a full title and name instead of the game's baked short name, while other blocks keep
        the game's rendered Chinese. Residual format codes are stripped in place rather than through
        `_clean_ck3_loc`, whose "title，name" comma rule would also eat the ordinary commas of a
        description; bare keys and sentinel strings fail `loc_text_ok` and yield ''."""
        s = str(raw or "")
        if not s:
            return ""

        # The mod's bone text is "[eaten]被吃掉了，这是[他/她]被吃剩的骨头。", whose pronoun reads
        # oddly inside a factual sentence. `ONCLICK:CHARACTER,<id>` is that pronoun's referent, so the
        # pronoun is replaced by this project's own designation and the text becomes one sentence.
        _vic = None
        _m0 = re.search(r"ONCLICK:CHARACTER,(\d+)", s)
        if _m0:
            _vic = int(_m0.group(1))
        _ta = "她" if (_vic is not None and self._is_female(_vic)) else "他"

        def _repl(m):
            kind, key, text = m.group(1), m.group(2), (m.group(3) or "").strip()
            if kind == "CHARACTER" and str(key).isdigit():
                nm = self.event_name(int(key), date) or ""
                if nm:
                    return nm
            return text

        s = self._ARTIFACT_REF_RE.sub(_repl, s)
        s = s.replace("\x15", "")
        s = re.sub(r"ONCLICK:[A-Z_]+,[^\s]+", "", s)
        s = re.sub(r"TOOLTIP:[A-Z_]+,[^\s]+", "", s)
        s = re.sub(r"(?<![A-Za-z])L(?=[;\s])", "", s)
        s = re.sub(r"high\s*", "", s)
        s = s.replace("!", "").replace(";", "")
        s = re.sub(r"\s{2,}", " ", s).strip()
        # Stripping spaces treats a middle dot as Chinese context too: baked mod bone names read
        # "妮克· 阿利尔‑獾" with a space after the dot, which a CJK-CJK-only rule would leave in place.
        s = re.sub(r"(?<=[\u4e00-\u9fff·]) (?=[\u4e00-\u9fff·])", "", s)
        if _vic is not None:
            vn = self.event_name(_vic, date) or ""
            if vn:
                s = s.replace("被吃掉了", "被吃掉")
                s = s.replace(f"这是{_ta}被吃剩的骨头",
                              f"这是被吃剩的骨头")
                s = s.replace(f"这是{_ta}", "这是")
                s = re.sub(r"这是[他她](?=被)", "这是", s)
        return s.rstrip("。") if loc_text_ok(s) else ""

    def _artifact_text(self, raw, date=None):
        """Artifact name or description → clean Chinese.

        Same cleaning as `_artifact_material`, but through one entry point: a name used to go in raw
        (`a.get("name")`) even though artifact names also carry data-function blocks and baked short
        names, so `\\x15high …\\x15!` fragments — modifiers, not character references — are stripped
        in place instead of reaching the prompt."""
        return self._artifact_material(raw, date)

    def _artifact_name(self, raw, date=None):
        """Artifact name → clean Chinese.

        Same cleaning as `_artifact_material` plus one rule valid for names only: the game renders
        "title + name" with a full-width comma after the title
        (`devour_bone_name = "[bone_victim.GetUINameNoTooltip]之骨"`, mod 3802979803), so in the
        prompt's "宝物：{name}，{rarity}" the model read the title as the artifact's name. Names
        therefore drop the comma between title and name (the rule `_clean_ck3_loc` shares); a material
        sentence keeps its commas, which are ordinary prose."""
        s = self._artifact_material(raw, date)
        if not s:
            return ""
        # drop the comma between a title (≤5 CJK chars) and the CJK text that follows it
        return re.sub(r"([\u4e00-\u9fff]{1,5})，(?=[\u4e00-\u9fff])", r"\1", s)

    def _is_part_artifact(self, a, desc=""):
        """Whether the artifact is made from a character part: a matching visual type, or a word hit in
        the name or description.

        `devour_bone_visual` and the words 之骨 / 剩的骨头 / 被吃掉了 cover the devouring mod's bones
        (`devour_bone_name` = `[…]之骨`, `devour_bone_desc` = "…被吃掉了，这是…被吃剩的骨头。"),
        which does not clash with `ARTIFACT_FILLER_TYPES`' `animal_skull`: animal bone is filler,
        human bone is this category."""
        vis = ((a.get("visuals") or {}).get("type") or "")
        if vis in self.ARTIFACT_PART_VISUALS:
            return True
        blob = f"{a.get('name') or ''}{desc}"
        return any(w in blob for w in self.ARTIFACT_PART_WORDS)

    def _artifact_ever_own_player(self, hist):
        """Whether the transfer history *ever* put the artifact in the protagonist's own hands.

        The test uses `player_id`, not the dynasty: a dynasty-wide test pulls in bones held by another
        protagonist of the same dynasty while the material names no current owner, and the model then
        attributed those bones to the protagonist."""
        pid = self.cache.get("player_id")
        if not isinstance(pid, int):
            return False
        for e in hist:
            if not isinstance(e, dict):
                continue
            for key in ("actor", "recipient"):
                if e.get(key) == pid:
                    return True
        return False

    def _artifact_owner_at(self, hist, as_of=None, fallback=None):
        """Owner id of the artifact as of `as_of` — the source of the "current owner" row.

        With no `as_of` (final or living-subject volume) the save's own `owner` field is used: the game
        writes the current holder, and the last transfer row need not reach the latest handover. With
        an `as_of` (decade volume) the last transfer at or before it wins (slot from
        `ARTIFACT_HOLDER_SLOT`, `created` falling back to actor); rows are unordered, so the latest
        date decides, then `fallback`."""
        if not as_of and isinstance(fallback, int):
            return fallback
        best_dk, cid = None, None
        ao = cl.date_key(as_of) if as_of else None
        for e in hist:
            if not isinstance(e, dict):
                continue
            t = e.get("type") or ""
            slot = self.ARTIFACT_HOLDER_SLOT.get(t)
            if not slot:
                continue
            d = e.get("date")
            if ao is not None and (not d or cl.date_key(d) > ao):
                continue
            v = e.get(slot)
            if not isinstance(v, int) and t == "created":
                v = e.get("actor")
            if not isinstance(v, int):
                continue
            dk = cl.date_key(d) if d else None
            if best_dk is None or (dk is not None and dk >= best_dk):
                best_dk, cid = dk, v
        if cid is not None:
            return cid
        return fallback if isinstance(fallback, int) else None

    def _capital_title_at(self, date=None):
        """Capital title id of the protagonist at `date`: per-save `capital_history`, else the last
        save's `landed.realm_capital`; None when unavailable.

        Same source as `_capital_province_at`, but it keeps the title id because the caller wants the
        place name rendered through `title()`, matching the profile's 治所 wording."""
        want = None
        ch = self.cache.get("capital_history") or []
        if ch and date:
            dk = cl.date_key(str(date))
            for pt in ch:
                d = pt.get("date")
                if d and cl.date_key(str(d)) <= dk:
                    want = pt.get("title")
                elif d:
                    break
        if want is None:
            pid = self.cache.get("player_id")
            rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
            want = (rec.get("landed") or {}).get("realm_capital")
        return want if isinstance(want, int) else None

    def artifact_home(self, cid, date=None):
        """Where the artifact is kept: for a settled ruler the place name of their capital at the time
        (the same exit as the profile's 治所); '' for landless/nomad or when unavailable.

        Per the game a settled ruler's artifacts sit in the current capital, so this is the storage
        place; a transfer row's `location` is where that particular move happened (the holder's
        itinerary when travelling) and serves only as a caller-side fallback."""
        if not isinstance(cid, int):
            return ""
        tid = None
        if cid == self.cache.get("player_id"):
            tid = self._capital_title_at(date)
        if tid is None:
            c = self._chars.get(str(cid)) or {}
            ld = c.get("landed_data") or {}
            tid = ld.get("realm_capital")
            if not isinstance(tid, int):
                # the dead: when the save has cleared `landed_data`, use the first domain entry at death
                dom = (c.get("dead_data") or {}).get("domain") or []
                tid = dom[0] if dom else None
        if not isinstance(tid, int):
            return ""
        nm = self.title(tid, date=date) or ""
        return nm

    def _artifact_cross_dyn(self, hist, pid, my_dyn):
        """Whether the transfer history ever had a holder outside this dynasty.

        An unknown dynasty counts as foreign: the plain `d != my_dyn` test treated a holder whose
        dynasty cannot be looked up as our own, so artifacts passing through lowborn or pruned
        characters lost their whole "left the family" record. The protagonist themself never counts,
        and when the protagonist has no dynasty (`my_dyn is None`) any other holder is foreign."""
        for e in hist:
            if not isinstance(e, dict):
                continue
            for key in ("actor", "recipient"):
                cid = e.get(key)
                if not isinstance(cid, int) or cid == pid:
                    continue
                if my_dyn is None or self._artifact_dyn_of(cid) != my_dyn:
                    return True
        return False

    def _artifact_dyn_of(self, cid):
        """Dynasty id of a character (melt `dynasty_house` → `dynasty`); None when unknown.

        Separate from `_dynasty_of_cid`, which reads the cache and falls back to `dynasty_id_of`; this
        melt-only index is what the cross-dynasty test uses."""
        if not isinstance(cid, int):
            return None
        dh = (self.melt.get("dynasties") or {}).get("dynasty_house") or {}
        c = (self.melt.get("living") or {}).get(str(cid)) \
            or (self.melt.get("dead_unprunable") or {}).get(str(cid)) or {}
        h = c.get("dynasty_house")
        return (dh.get(str(h)) or {}).get("dynasty") if isinstance(h, int) else None

    def _artifact_candidates(self, as_of):
        """Artifact selection for the record → [(aid, kind, a, hist)], already cut at `as_of`.

        Two kinds: "relic" — a top-grade treasure that was once held outside the dynasty; "part" — an
        artifact made from a body part and held by our line, at green or above
        (`ARTIFACT_PART_RARITY`), and not required to have left the family (a self-made skull goblet
        is a trophy). Ownership is judged as of `as_of` so a decade volume cannot look ahead, and it
        is judged for the protagonist themself rather than the dynasty."""

        my_dyn = self.cache.get("dynasty_id")
        my_pid = self.cache.get("player_id")

        def _held_asof(hist, as_of):
            """Whether the artifact was already in the protagonist's own hands by `as_of`;
            no such judgement is made when `as_of` is empty (final volume)."""
            if not as_of:
                return True
            ao = cl.date_key(as_of)
            for e in hist:
                d = e.get("date")
                if not d or cl.date_key(d) > ao:
                    continue
                t = e.get("type") or ""
                slot = self.ARTIFACT_HOLDER_SLOT.get(t)
                if not slot:
                    continue
                cid = e.get(slot)
                if not isinstance(cid, int) and t == "created":
                    cid = e.get("actor")
                if isinstance(cid, int) and cid == my_pid:
                    return True
            return False

        art = (self.melt.get("artifacts") or {}).get("artifacts") or {}
        out = []
        for aid, a in art.items():
            if not isinstance(a, dict):
                continue
            if (a.get("type") or "") in self.ARTIFACT_FILLER_TYPES:
                continue
            hist = (a.get("history") or {}).get("entries") or []
            # ownership as of the date: an artifact not yet in the protagonist's own hands is dropped
            if not _held_asof(hist, as_of):
                continue
            if not (self._artifact_ever_own_player(hist)
                    or (as_of is None and a.get("owner") == my_pid)):
                continue
            kind = ""
            if a.get("rarity") in self.ARTIFACT_RARITY:
                if self._artifact_cross_dyn(hist, my_pid, my_dyn):
                    kind = "relic"
            # part artifacts pass the rarity gate first and only then the part test; the gate first
            # also avoids the description-cleaning cost for common bones
            if not kind and a.get("rarity") in self.ARTIFACT_PART_RARITY:
                desc = self._artifact_material(a.get("description"), as_of
                                               or self.as_of)
                if self._is_part_artifact(a, desc):
                    kind = "part"
            if kind:
                out.append((aid, kind, a, hist))
        return out

    def _decade_cutoff(self, decade):
        """Data cutoff date of decade number `decade` — the start of year (start + decade×10), capped at
        the last save; same formula as `pipeline._decade_cutoff`, reused for cross-volume dedup."""
        srcs = self.cache.get("sources") or []
        last = self.cache.get("last_date")
        if not srcs:
            return last
        try:
            sy = int(str(srcs[0]).split(".")[0])
            end = f"{sy + decade * 10}.1.1"
        except Exception:
            return last
        if last and cl.date_key(last) < cl.date_key(end):
            return last
        return end

    def _artifacts_written_before(self):
        """Ids of artifacts already written by earlier decade volumes.

        The union of re-running the same selection at every earlier cutoff, so no "used artifacts"
        ledger is stored and reruns, --force and concurrent writes cannot drift. A final volume (no
        decade) takes the full set and excludes nothing."""
        if not self.decade or not self.as_of:
            return set()
        out = set()
        for k in range(1, int(self.decade)):
            cut = self._decade_cutoff(k)
            if not cut:
                continue
            try:
                out |= {c[0] for c in self._artifact_candidates(cut)}
            except Exception:
                continue
        return out

    def family_artifacts(self):
        """Artifact record data source: top-grade treasures plus character-part artifacts (green or
        above). Returns [multi-line text] (name / rarity / material / transfer history).

        A decade volume judges ownership as of its own cutoff, so it never carries a treasure the
        protagonist won later, and it excludes artifacts earlier decade volumes already wrote."""
        rarity_zh = {"common": "常见", "famed": "著名", "masterwork": "大师级",
                     "illustrious": "名望级", "legendary": "传奇级"}
        written = self._artifacts_written_before()
        rows = []
        for aid, kind, a, hist in self._artifact_candidates(self.as_of):
            if aid in written:
                continue
            # the name is cleaned too: a saved artifact name carries `\x15high …\x15!` data-function
            # blocks and baked short names
            # the name goes through `_artifact_name`, which additionally drops the "title，name"
            # comma so the model cannot read the title as the artifact's name
            name = self._artifact_name(a.get("name"), self.as_of) or "一件宝物"
            rarity = rarity_zh.get(a.get("rarity")) or a.get("rarity") or ""
            # rarity as a comma apposition (宝物：X，名望级), not a parenthetical
            lines = [f"宝物：{name}，{rarity}"]
            # "current owner / current home" lines: the material otherwise never says whether the
            # artifact is still in the protagonist's hands, which the program can state
            # deterministically. The owner is the holder as of the cutoff, marked when it is not the
            # protagonist; the home is the holder's capital at the time, falling back to a transfer
            # row's `location` only when the holder is landless/nomad or the capital is unknown.
            _own = self._artifact_owner_at(hist, self.as_of, fallback=a.get("owner"))
            _onm = self.name_or(_own, "") if isinstance(_own, int) else ""
            if _onm:
                lines.append(f"现主：{_onm}" if _own == self.cache.get("player_id")
                             else f"现主：{_onm}，非传主")
            _hname = self.artifact_home(_own, self.as_of)
            if not _hname:
                _loc = None
                _ldk = None
                for e in hist:
                    if not isinstance(e, dict) or not isinstance(e.get("location"), int):
                        continue
                    _d = e.get("date")
                    if self.as_of and (not _d or cl.date_key(_d) > cl.date_key(self.as_of)):
                        continue
                    _dk = cl.date_key(_d) if _d else None
                    if _ldk is None or (_dk is not None and _dk >= _ldk):
                        _ldk, _loc = _dk, e.get("location")
                if _loc is not None:
                    _ctid = self.county_at_province(_loc)
                    if _ctid is not None:
                        _hname = self.title(_ctid, self.as_of) or ""
            if _hname:
                lines.append(f"现藏：{_hname}")
            if kind == "part":
                mat = self._artifact_material(a.get("description"), self.as_of)
                if mat:
                    lines.append(f"材质：{mat}")
            _is_bone = self._is_devour_bone(a)
            entries = []
            for e in reversed(hist):
                # as_of cut: a decade volume lists only transfers up to that date
                if self.as_of and e.get("date") \
                        and cl.date_key(e.get("date")) > cl.date_key(self.as_of):
                    continue
                t = e.get("type") or ""
                d = self.date(e.get("date")) if e.get("date") else ""
                actor = self.name_or(e.get("actor"), "") if isinstance(e.get("actor"), int) else ""
                rec2 = self.name_or(e.get("recipient"), "") if isinstance(e.get("recipient"), int) else ""
                if t == "created" and _is_bone and actor and rec2:
                    # in a bone's creation row the actor is the person who was eaten (the mod sets
                    # `creator = $VICTIM$`), so the generic wording would read "X forged this"; this
                    # sentence states both the eater and the victim
                    entries.append(f"{d}，{rec2}吃掉{actor}，遗骨成此宝")
                elif t == "created" and actor:
                    entries.append(f"{d}，{actor}锻造此宝")
                elif t == "created":
                    entries.append(f"{d}，创制")
                elif t == "inherited" and rec2:
                    entries.append(f"{d}，传于{rec2}")
                elif t == "taken_in_battle" and actor:
                    entries.append(f"{d}，{actor}自战场夺得")
                elif t == "taken_in_siege" and actor:
                    entries.append(f"{d}，{actor}围攻中夺得")
                elif t == "conquest":
                    # naming both ends (actor = loser, recipient = new holder, see
                    # `ARTIFACT_HOLDER_SLOT`) avoids a two-character coinage plus 所得 being read as
                    # a person's name; the row is dropped when neither end has a name
                    _win = self.name_or(e.get("recipient"), "") \
                        if isinstance(e.get("recipient"), int) else ""
                    _lose = self.name_or(e.get("actor"), "") \
                        if isinstance(e.get("actor"), int) else ""
                    if _win and _lose:
                        entries.append(f"{d}，{_win}自{_lose}处夺得")
                    elif _win:
                        entries.append(f"{d}，{_win}夺得")
                    elif _lose:
                        entries.append(f"{d}，{_lose}处宝物易主")
                elif t == "created_before_history":
                    # no row: a creation predating the history is left out rather than becoming an
                    # editor's note about missing material
                    pass
                # stolen: actor = loser, recipient = taker
                elif t == "stolen" and actor and rec2:
                    entries.append(f"{d}，{rec2}自{actor}处窃得")
                elif t == "stolen" and actor:
                    entries.append(f"{d}，{actor}处宝物遭窃")
                elif t == "stolen":
                    entries.append(f"{d}，宝物遭窃")
                # an unknown transfer type is omitted rather than leaking its raw key
            if entries:
                lines.append("流转：" + "；".join(entries))
            # relics first, part artifacts second; within a category by richness of transfer history
            # (row = (category, sort weight, artifact id, artifact object, text lines); parts are
            # re-sorted by creation date)
            rows.append((0 if kind == "relic" else 1, -len(lines), aid, a, lines))
        rows.sort(key=lambda x: (x[0], x[1], x[2]))
        # the two categories have separate caps (see the ARTIFACT_PART_MAX comment); within the part
        # category, creation date ascending (the order they were eaten), then transfer richness
        relics = [r for r in rows if r[0] == 0][: self.ARTIFACT_MAX]
        parts = [r for r in rows if r[0] == 1]
        parts.sort(key=lambda r: (self._artifact_created_key(r[3]), r[1], r[2]))
        return ["\n".join(r[4]) for r in relics + parts[: self.ARTIFACT_PART_MAX]]

    def _is_devour_bone(self, a):
        """Whether this is a "leftover bones" artifact from devouring."""
        return ((a.get("visuals") or {}).get("type") or "") == self._DEVOUR_VISUAL

    def _artifact_created_key(self, a):
        """Artifact creation date → sort key (largest key when there is no `created` row)."""
        for e in ((a.get("history") or {}).get("entries") or []):
            if isinstance(e, dict) and e.get("type") == "created" and e.get("date"):
                return cl.date_key(e["date"])
        return (9999, 0, 0)

    # ---- dynamic realm names for Islamic rulers (game rules reproduced) ----

    _ISLAM_RELIGIONS = {"islam_religion", "sunni_religion",
                        "shia_religion", "ibadi_religion"}
    _NO_RELIGIOUS_HEAD = 4294967295  # 0xFFFFFFFF = no religious head

    def _faith_id(self, cid, date=None):
        """Faith id of a character: faith history at `date` → cached current value → melt character
        object → rite lookup → house default.

        `faith` and `culture` are optional keys in the save (absent = the house's faith) and are often
        pruned from a dead character's record, so reading only the current value would miss a dead
        character's faith in flavorization conditions and void doctrine checks. From 1.20 characters
        carry `rite` rather than `faith`, so the faith is looked up through
        `rites.database[rite].faith` (`cl.faith_id_of_char`)."""
        if cid is None:
            return None
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fid = _hist_value_at(rec.get("faith_history"), date, "faith")
        if fid is None:
            fid = rec.get("faith")
        if fid is None:
            fid = cl.faith_id_of_char(self.melt, self._chars.get(str(cid)))
        if fid is None:
            fid = cl.faith_id_of_rite(self.melt, self._rite_id(cid, date))
        if fid is None:
            fid = self._house_default(cid, "faith")
        return fid

    def _rite_id(self, cid, date=None):
        """Rite id of a character: rite history at `date` → cached current value → melt character object.

        Characters carry `rite` from 1.20 on; older saves have no such field, giving None so the caller
        falls back to the faith."""
        if cid is None:
            return None
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        rid = _hist_value_at(rec.get("rite_history"), date, "rite")
        if rid is None:
            rid = rec.get("rite")
        if rid is None:
            rid = cl.rite_id_of_char(self._chars.get(str(cid)))
        return rid

    def rite_name(self, cid, date=None):
        """Chinese name of the rite this character holds at `date` (the save stores it, e.g. 罗马礼).

        Older (1.19) saves have no rite database, so the faith name is used instead: 1.20's state
        religion is the former State Faith renamed State Rite, keeping the wording continuous."""
        rid = self._rite_id(cid, date)
        if rid is not None:
            nm = cl.rite_name_of(self.melt, rid)
            if nm:
                return nm
        return self._faith_name(self._faith_id(cid, date))

    # =====================================================================
    # Rite record / church record material (CK3 1.20's new religion system)
    # =====================================================================
    # Data sources, all verified against saves:
    #   · rite definition  rites.database[<rid>] (data.name/adjective/desc/fervor/tenets/doctrine)
    #   · head of rite     rites.database[<rid>].head_of_rite (a character id)
    #   · tenet status     data.tenets[].status ∈ core/permitted/prohibited/known/unknown
    #   · tenet name key   `<tenet key>_name` (e.g. tenet_be_fruitful_and_multiply_name)
    #   · personal tenets  characters.<id>.playable_data.tenets (plus a per-save change history)
    #   · spiritual fulfillment  playable_data.current_spiritual_fulfillment (a plain float; the
    #                            number itself is not sent to the model)
    #   · church context   situation_manager / situation_sub_region_manager / …participant_group_manager


    def rite_tenets(self, rid):
        """Tenets of a rite grouped by status (in 1.20 the tenet status lives on the rite)."""
        out = {}
        for e in (cl.rite_data(self.melt, rid).get("tenets") or []):
            if not isinstance(e, dict) or not e.get("tenet"):
                continue
            out.setdefault(str(e.get("status") or "known"), []).append(str(e["tenet"]))
        for v in out.values():
            v.sort()
        return out

    def tenet_name(self, key, rid=None):
        """Tenet key → Chinese name. In 1.20 the localization key is `<tenet key>_name`
        (`tenet_be_fruitful_and_multiply_name` = 你们要生育繁殖), with per-rite `_<rite>_name`
        variants tried first; '' when none resolve."""
        if not key:
            return ""
        k = str(key)
        cands = []
        if rid is not None:
            rt = str(cl.rite_entry(self.melt, rid).get("rite_type") or "")
            if rt:
                cands.append(f"{k}_{rt}_name")
        cands.append(f"{k}_name")
        for c in cands:
            v = L.loc(self.table, c)
            if v and v != c:
                return v
        return ""

    def _spiritual_fulfillment(self, cid, date=None):
        """Current spiritual fulfillment as of the date (the cutoff wins); None when unknown."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        hist = rec.get("sf_history") or []
        if hist and date:
            ao = cl.date_key(date)
            val = None
            for h in hist:
                if cl.date_key(h.get("from") or "0.0.0") <= ao:
                    val = h.get("value")
            if val is not None:
                return float(val)
        v = rec.get("spiritual_fulfillment")
        return float(v) if isinstance(v, (int, float)) else None

    def _sf_level_word(self, cid, sf, date=None):
        """Spiritual fulfillment value → the game's official level name.

        The bands are defined in `localization.build_spiritual_fulfillment`: the set depends on the
        character's religion family (7 bands "诅咒之人…蒙恩之人" for `christianity_religion`, 5 bands
        "茫然无措…从心所欲" otherwise), and the highest band whose threshold the value meets wins. A
        missing table or key falls back to the locally coined `_sf_word`."""
        if sf is None:
            return ""
        _ftag, rtag = self._faith_tags(cid, date)
        ty = L.sf_type_for(self._sf_types or {}, rtag)
        lv = ty.get("levels") or []
        if not lv:
            return _sf_word(sf)
        key = "%s_level_%d" % (ty.get("key"), L.sf_level_index(lv, sf))
        v = ""
        try:
            v = L.loc(self.table, key) or ""
        except Exception:
            v = ""
        return v if v and not v.startswith(("$", "[")) else _sf_word(sf)

    def _tenet_change_points(self, cid, date=None):
        """Change points of the personal tenets → [(date, set(tenet keys))], date ascending.

        The precise source is the cache's `personal_tenets_history` (per-save change points, see
        cache_lib). Without that field the points are inferred from the adoption history plus the
        current set: a tenet missing from the current set counts as abandoned at the next history date
        after it, or at the last save date when there is none. [] when unknown."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        psh = [h for h in (rec.get("personal_tenets_history") or [])
               if isinstance(h, dict) and h.get("from")
               and isinstance(h.get("tenets"), list)]
        ao = cl.date_key(date) if date else None
        if psh:
            out = []
            for h in psh:
                if ao is not None and cl.date_key(h["from"]) > ao:
                    break
                out.append((str(h["from"]), {str(t) for t in h["tenets"]}))
            return out
        hist = [h for h in (rec.get("personal_tenet_history") or [])
                if isinstance(h, dict) and h.get("tenet") and h.get("from")]
        if not hist:
            return []
        final = {str(x) for x in (rec.get("personal_tenets") or [])}
        by_date = {}
        for h in hist:
            by_date.setdefault(str(h["from"]), []).append(str(h["tenet"]))
        dates = sorted(by_date, key=cl.date_key)
        rows, running = [], set()
        for i, d in enumerate(dates):
            if ao is not None and cl.date_key(d) > ao:
                break
            add = set(by_date[d])
            # a drop = a tenet held before but absent from the current set (the history records
            # additions only, so drops are inferred here)
            drop = {t for t in running if t not in final}
            running = (running - drop) | add
            rows.append((d, set(running)))
        # tail after the last point: a tenet adopted in the last history entry yet absent from the
        # current set is dropped without a replacement
        if ao is None and dates:
            tail = {t for t in by_date[dates[-1]] if t not in final}
            end = str(self.cache.get("last_date") or "")
            if tail and end and cl.date_key(end) > cl.date_key(dates[-1]):
                rows.append((end, set(running) - tail))
        return rows

    def _personal_tenets(self, cid, date=None):
        """Personal tenet keys held by the character at `date`.

        Personal tenets have a slot limit (growing with piety, traits and dynasty perks; 1–3 observed),
        so "at that date" is a set — returning every history entry up to the date would count
        abandoned tenets as still held."""
        pts = self._tenet_change_points(cid, date)
        if pts:
            return sorted(pts[-1][1])
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        return [str(x) for x in (rec.get("personal_tenets") or [])]

    def rite_profile_lines(self, cid, date=None):
        """Opening lines of the rite record: rite held / origin / rite head / core tenets / fervor /
        spiritual fulfillment / personal tenets; [] when the character has no rite.

        The rite head and core tenets are read at `date` through `_rite_point_at` (the cache's per-save
        latch point), so a decade volume cannot show a head or tenets installed later."""
        rid = self._rite_id(cid, date)
        if rid is None:
            return []
        ent = cl.rite_entry(self.melt, rid)
        d = cl.rite_data(self.melt, rid)
        # the rite's latch point at the cutoff — shared source for the rite-head and core-tenet rows
        _pt = self._rite_point_at(rid, date) or {}
        _ten = _pt.get("tenets") or None
        rows = []
        nm = self.rite_name(cid, date)
        if nm:
            rows.append(f"所奉礼仪：{nm}。")
        origin = ent.get("origin_rite")
        if isinstance(origin, int) and origin != rid:
            onm = cl.rite_name_of(self.melt, origin)
            if onm:
                rows.append(f"源自{onm}。")
        _h = _pt.get("head")
        head = _h if isinstance(_h, int) else cl.head_of_rite(self.melt, rid)
        if head is not None:
            # a renamed holder (a pope's regnal name) gets the birth name appended; the note uses a
            # comma because factual-layer parentheses are always turned into natural language
            _hl = "本人。" if head == cid else f"{self.event_name(head, date=date)}。"
            if head != cid:
                _hl = self.label_with_birth_name(head, _hl.rstrip("。"), date) + "。"
            rows.append("礼仪领袖：" + _hl)
        # the head of this faith's opposing side (antipope): recognizing only `head_of_rite` would
        # drop the one installed by the player. Wording lives in `antipope_lines`.
        rows.extend(self.antipope_lines(cid, date))
        st = _ten or self.rite_tenets(rid)
        core = st.get("core") or []
        cnames = [self.tenet_name(k, rid) for k in core]
        cnames = [n for n in cnames if n]
        if cnames:
            # tenet and holy-order names carry no 〈〉 brackets, matching the "、" enumeration used
            # elsewhere in the project
            rows.append("核心教义：" + "、".join(cnames) + "。")
        fv = d.get("fervor")
        if isinstance(fv, (int, float)):
            rows.append(f"宗教热情：{_fervor_word(float(fv))}。")
        sf = self._spiritual_fulfillment(cid, date)
        if sf is not None:
            rows.append(f"灵性满足：{self._sf_level_word(cid, sf, date)}。")
        pt = self._personal_tenets(cid, date)
        if pt:
            names = [self.tenet_name(k, rid) or k for k in pt]
            rows.append("个人教义：" + "、".join(names) + "。")
        return rows

    @staticmethod
    def _join_sentences(lines):
        """Several already-punctuated short sentences → one sentence (trailing 。 stripped, joined with
        "；", a final "。" appended).

        `personal_tenet_lines` gives each clause its own period, so a plain "；".join would read
        "…。；…"."""
        parts = [str(x).strip().rstrip("。") for x in (lines or []) if str(x).strip()]
        return "；".join(parts) + "。" if parts else ""

    def _holy_order_chain(self, tid):
        """Chain [(tid, holder, key)] walking up a holy order title's capital county via `de_facto_liege`.

        The capital is `landed_titles[<order title>].capital`, the game's `leader.capital_county`
        (`common/scripted_effects/00_holy_order_effects.txt`); the holders and tiers along the chain say
        whose realm the order sits in and who is its protector."""
        cur = ((self._lt.get(str(tid)) or {}).get("capital"))
        out, seen = [], set()
        while isinstance(cur, int) and cur not in seen:
            seen.add(cur)
            t = self._lt.get(str(cur)) or {}
            out.append((cur, t.get("holder"), str(t.get("key") or "")))
            cur = t.get("de_facto_liege")
        return out

    def _title_holder_since(self, tid, holder, date=None):
        """Date the title was last granted to `holder` at or before `date` ('' when unknown)."""
        hist = ((self._lt.get(str(tid)) or {}).get("history"))
        if not isinstance(hist, dict):
            return ""
        ao = cl.date_key(date) if date else None
        best = ""
        for d, hv in hist.items():
            if not isinstance(hv, dict) or hv.get("holder") != holder:
                continue
            if ao is not None and cl.date_key(d) > ao:
                continue
            if not best or cl.date_key(d) > cl.date_key(best):
                best = str(d)
        return best

    def _title_holder_at(self, tid, date=None):
        """Holder of the title on `date` (None when unknown).

        Needed because an antipope row's `sponsor` is the sponsor's *title* id, so naming the installer
        requires looking the holder up. `landed_titles[].history` values occur in two shapes — a bare
        character id or a `{type, holder}` dict — and both must be accepted, or the lookup returns the
        previous holder."""
        hist = ((self._lt.get(str(tid)) or {}).get("history"))
        ao = cl.date_key(date) if date else None
        best, best_dk = None, None
        if isinstance(hist, dict):
            for d, hv in hist.items():
                if isinstance(hv, dict):
                    h = hv.get("holder")
                elif isinstance(hv, int):
                    h = hv
                else:
                    continue
                if not isinstance(h, int):
                    continue
                try:
                    dk = cl.date_key(d)
                except Exception:                             # noqa: BLE001
                    continue
                if ao is not None and dk > ao:
                    continue
                if best_dk is None or dk >= best_dk:
                    best, best_dk = h, dk
        if isinstance(best, int):
            return best
        t = self._lt.get(str(tid)) or {}
        h = t.get("holder")
        return h if isinstance(h, int) else None

    def antipope_lines(self, cid, date=None):
        """One row per antipope (religious head challenger) of the protagonist's faith in place at
        `date`; [] when the faith has none, or none is installed or still standing.

        Recognizing only `rites.database[rite].head_of_rite` (the canonical head) would drop the one a
        player installed through a decision. The label comes from `antipope_label`, and the row states
        the sponsor (its `sponsor` field is a title id, so the holder is looked up) and the start date."""
        if cid is None:
            return []
        fid = self._faith_id(cid, date)
        if fid is None:
            return []
        want = self._antipope_challenger_ids(fid)
        if not want:
            return []                       # this faith registers no challenger (code can drop the list)
        rows, seen = [], set()
        for tid in sorted(want):
            holder = self._title_holder_at(tid, date)
            if not isinstance(holder, int) or holder in seen:
                continue
            seen.add(holder)
            lbl = self.antipope_label(holder, date) or self._ANTIPOPE_WORD
            since = self._title_holder_since(tid, holder, date)
            seg = f"{lbl}，{since}起" if since else lbl
            sponsor = None
            for row in (cl.faith_entry(self.melt, fid)
                        .get("religious_head_challengers") or []):
                if isinstance(row, dict) and row.get("religious_head_challenger") == tid:
                    s_tid = row.get("sponsor")
                    if isinstance(s_tid, int):
                        sponsor = self._title_holder_at(s_tid, date)
                    break
            if isinstance(sponsor, int):
                snm = self.event_name(sponsor, date=date) or ""
                if snm:
                    seg += f"，由{snm}扶立"
            rows.append("对立教宗：" + seg + "。")
        return rows

    def holy_order_lines(self, cid, date=None):
        """Holy orders founded by, protected by, or standing inside the protagonist's realm (rite record
        opening).

        Source `holy_orders.holy_orders[<id>]` =
        {rite, title, titles[], founder, worldliness, holy_order_type, tenet}. An order qualifies when
        `founder == cid`, or when it shares the protagonist's faith and the protagonist appears on the
        `de_facto_liege` chain up from its capital county — i.e. the patron is the protagonist or one of
        their (sub)vassals. The game's `holy_order_patron` is derived at runtime and never saved, so the
        patron is the nearest chain holder at duke tier or above (`PATRON_MIN_TIER = 3`,
        `common/defines/00_defines.txt`). Truncation uses the founding date = the earliest key of
        `landed_titles[<title>].history` (a title's `date` is its last change), falling back to `date`
        when there is no history. Members and `worldliness` are not written; names come from
        `self.title()`."""
        if cid is None:
            return []
        ho = (self.melt.get("holy_orders") or {}).get("holy_orders") or {}
        if not ho:
            return []
        ao = cl.date_key(date) if date else None
        my_rite = self._rite_id(cid, date)
        my_faith = self._faith_id(cid, date)
        rows = []
        for _hid, h in ho.items():
            if not isinstance(h, dict):
                continue
            tid = h.get("title")
            if not isinstance(tid, int):
                continue
            is_founder = h.get("founder") == cid
            rid = h.get("rite")
            ofaith = cl.faith_id_of_rite(self.melt, rid) \
                if isinstance(rid, int) else None
            chain = self._holy_order_chain(tid)
            holders = [x[1] for x in chain]
            in_realm = cid in holders
            patron = None
            for _t2, _hold, _key in chain:
                if isinstance(_hold, int) and self._TT_RANK.get(_key[:2], 0) >= 3:
                    patron = _hold
                    break
            same_faith = (my_faith is not None and ofaith is not None
                          and my_faith == ofaith)
            if not (is_founder or (same_faith and in_realm)):
                continue
            lt = self._lt.get(str(tid)) or {}
            # founding date = the earliest key of `history`, never `landed_titles[].date`: the latter is
            # the title's last change and moves whenever the holder changes, so using it as the "not yet
            # founded" test cuts an old order out of a decade volume entirely. `date` is a fallback for
            # titles without history.
            fdate = ""
            _hist = lt.get("history")
            if isinstance(_hist, dict) and _hist:
                fdate = min(_hist, key=cl.date_key)
            if not fdate:
                fdate = lt.get("date")
            if ao is not None and (not fdate or cl.date_key(fdate) > ao):
                continue          # not founded yet: a decade volume does not look ahead
            name = self.title(tid, date) or ""
            if not name:
                continue
            year = self._year_only(fdate) if fdate else ""
            if is_founder:
                head = f"{year}，他立{name}" if year else f"他立{name}"
            elif patron == cid:
                head = f"{year}，他是{name}的庇护者" if year \
                    else f"他是{name}的庇护者"
            else:
                head = f"{year}，{name}在其领地之内" if year \
                    else f"{name}在其领地之内"
            bits = []
            rname = cl.rite_name_of(self.melt, rid) if isinstance(rid, int) else ""
            if rname and (my_rite is None or rid != my_rite):
                bits.append(f"其礼为{rname}")
            ten = h.get("tenet")
            if ten:
                tn = self.tenet_name(ten, rid if isinstance(rid, int) else None)
                if tn:
                    bits.append(f"会规：{tn}")
            lands = [self.title(t, date) for t in (h.get("titles") or [])
                     if isinstance(t, int)]
            lands = [x for x in lands if x]
            if lands:
                shown = "、".join(lands[:2])
                bits.append(f"领{shown}等{len(lands)}处教堂领地"
                            if len(lands) > 2 else f"领{'、'.join(lands)}")
            if patron is not None and patron != cid:
                pn = self.event_name(patron, date=date)
                if pn:
                    bits.append(f"庇护者是{pn}")
            cur = lt.get("holder")
            if isinstance(cur, int):
                cn = self.event_name(cur, date=date)
                hd = self._title_holder_since(tid, cur, date)
                if cn:
                    # no parenthetical note here (same rule as `rite_tenet_changes`)
                    bits.append("现任之长" + cn
                                + (f"，{self._year_num(hd)}年起在任" if hd else ""))
            rows.append(head + ("，" + "，".join(bits) if bits else "") + "。")
        return rows

    @staticmethod
    def _year_num(d):
        """Date string → year number ('' for an empty input)."""
        s = str(d or "").split(".")[0]
        return s if s.isdigit() else ""

    def _rite_point_at(self, rid, date):
        """Latching point of this rite at `date`: `{from, tenets, head}` (None if no history).

        Takes the last point with `from <= date`; a date before the first point yields the first
        one (same convention as `_hist_value_at`). An empty history yields None, so callers fall
        back to the current value. `rite_tenets_history` latches only on a core-tenets tier
        change, so a rite-head-only change brackets to the previous latch point. Returns the
        whole point including `head`, so the leader and tenets rows draw from one source."""
        hist = ((self.cache.get("rite_tenets_history") or {}).get(str(rid)) or [])
        if not hist:
            return None
        dk = cl.date_key(date) if date else None
        pick = None
        for h in hist:
            if not isinstance(h, dict) or not h.get("from"):
                continue
            if pick is None:
                pick = h
                continue
            if dk is None or cl.date_key(h["from"]) <= dk:
                pick = h
            else:
                break
        return pick or None

    def rite_tenet_changes(self, cid, date=None):
        """Sentences for changes of this rite's own core tenets (《礼仪志》 chronicle).

        Source: cached `rite_tenets_history[<rid>]` (latched per tier, see
        `cache_lib.extract_snapshot`), truncated at `date` and diffed tier by tier. The game
        keeps only current state, so exact dates bracket to the snapshot interval, as with every
        `*_history` key. Only the rite's `head_of_rite` can change its tenets, so that tier's
        leader is named (the clause is dropped when the name is unknown). The first known tier
        is a baseline and emits nothing. Returns the sentences."""
        rid = self._rite_id(cid, date)
        if rid is None:
            return []
        hist = ((self.cache.get("rite_tenets_history") or {}).get(str(rid)) or [])
        if not hist:
            return []
        ao = cl.date_key(date) if date else None
        rows, prev = [], None
        for h in hist:
            d = h.get("from")
            if not d:
                continue
            if ao is not None and cl.date_key(d) > ao:
                break
            core = sorted(str(x) for x in
                          ((h.get("tenets") or {}).get("core") or []))
            if not core:
                continue
            names = [self.tenet_name(k, rid) or k for k in core]
            year = int(str(d).split(".")[0]) if str(d).split(".")[0].isdigit() \
                else self._year_only(d)
            if prev is not None and set(core) != set(prev):
                out = [self.tenet_name(k, rid) or k for k in prev if k not in core]
                inn = [self.tenet_name(k, rid) or k for k in core if k not in prev]
                # No parenthetical apposition of the 「名词（名词）」 kind, and the current three tenets are
                # already given by the opening 「核心教义」 line, so they are not repeated here.
                if out and inn:
                    rows.append(f"{year}年起，{self._leader_clause(h, d)}"
                                f"改礼仪核心教义：{'、'.join(out)}换成"
                                f"{'、'.join(inn)}。")
                elif inn:
                    rows.append(f"{year}年起，{self._leader_clause(h, d)}"
                                f"为礼仪增定{'、'.join(inn)}。")
                else:
                    rows.append(f"{year}年起，礼仪核心教义去{'、'.join(out)}。")
            prev = core
        return rows

    def _leader_clause(self, h, d):
        """The 「礼仪领袖X」 clause from this tier's `head_of_rite`; '' when no name is known."""
        head = h.get("head")
        if not isinstance(head, int):
            return ""
        nm = self.event_name(head, date=d)
        return f"礼仪领袖{nm}" if nm else ""

    def rite_history_lines(self, cid, date=None):
        """Rite-succession sentences (《礼仪志》): the change points of the rite axis.

        Per-tier diff of `faith_rite_history`, merged with the game's own
        `converted_rite_memory` (old_rite/new_rite + creation_date): the cache covers only the
        tiers of the reigning character, so diffing alone loses conversions earlier than the
        first tier. Only the rite value is used and adjacent equal rites are merged (a faith
        change without a rite change is not a conversion). Truncated at `date`, untruncated when
        omitted; fewer than two points returns []. The first entry is worded as 「奉」 and not
        「改奉」, and a same-year pair collapses to a single year."""
        hist = []
        for d, _fid, rid in self.faith_rite_history(cid):
            if rid is None:
                continue
            if hist and hist[-1][1] == rid:
                continue
            hist.append((d, rid))
        if len(hist) < 2:
            return []
        ao = cl.date_key(date) if date else None
        rows = []
        for i, (d, rid) in enumerate(hist):
            dk = cl.date_key(d)
            if ao is not None and dk > ao:
                break
            nm = cl.rite_name_of(self.melt, rid)
            if not nm:
                continue
            start = int(str(d).split(".")[0])
            nxt = hist[i + 1][0] if i + 1 < len(hist) else None
            if nxt is not None and (ao is None or cl.date_key(nxt) <= ao):
                end = int(str(nxt).split(".")[0]) - 1
                rows.append(f"{start}年奉{nm}" if end <= start
                            else f"{start}年至{end}年奉{nm}")
            else:
                rows.append(f"自{start}年起奉{nm}" if i == 0
                            else f"自{start}年起改奉{nm}")
        return rows

    def personal_tenet_lines(self, cid, date=None):
        """Succession sentences for personal tenets: one line per change point.

        Tenets are diffed as sets, so 「自N年起，奉〈X〉」 lines cannot read as several tenets
        held at once. Change points come from `_tenet_change_points` (exact history first,
        otherwise inferred from the added-tenet history plus the current value)."""
        pts = self._tenet_change_points(cid, date)
        if not pts:
            return []
        rid = self._rite_id(cid, date)
        rows, prev = [], set()
        for d, cur in pts:
            year = int(str(d).split(".")[0])
            add = [t for t in sorted(cur - prev) if self.tenet_name(t, rid)]
            drop = [t for t in sorted(prev - cur) if self.tenet_name(t, rid)]
            _n = lambda ks: "、".join(  # noqa: E731
                self.tenet_name(k, rid) for k in ks)
            if add and drop:
                rows.append(f"{year}年起，放弃{_n(drop)}，"
                            f"改奉{_n(add)}为个人教义。")
            elif add:
                rows.append(f"自{year}年起，奉{_n(add)}为个人教义。")
            elif drop:
                rows.append(f"{year}年起，不复奉{_n(drop)}为个人教义。")
            prev = set(cur)
        return rows

    def faith_doctrines(self, cid):
        """Doctrine keys of the character's faith, [] when unknown.

        One doctrine is stored as a bare string rather than a list."""
        fid = self._faith_id(cid)
        if fid is None:
            return []
        d = cl.faith_entry(self.melt, fid).get("doctrine")
        if isinstance(d, str):
            return [d]
        return [x for x in (d or []) if isinstance(x, str)]

    def _sacrifice_faith(self, cid):
        """Whether the character's faith permits human sacrifice (doctrine grants
        `human_sacrifice_active`)."""
        docs = self.faith_doctrines(cid)
        if not docs:
            return False
        return bool(set(docs) & self._sacrifice_doctrines)

    def is_islamic(self, cid):
        """Whether the character is an Islamic ruler: faith → religion → religion_type in the
        Islamic set."""
        fid = self._faith_id(cid)
        if fid is None:
            return False
        fe = cl.faith_entry(self.melt, fid)
        if not fe:
            return False
        rid = fe.get("religion")
        if not isinstance(rid, int):
            return False
        religions = (self.melt.get("religion") or {}).get("religions") or {}
        re = religions.get(str(rid))
        return (isinstance(re, dict)
                and (re.get("religion_type") or "") in self._ISLAM_RELIGIONS)

    def is_caliph(self, cid):
        """Whether the character is also caliph: current holder of the faith's religious head
        title (faith.religious_head, e.g. d_sunni) is the character himself.

        In 1.20 `faith.religious_head` is empty and the leader is recorded in
        `rites.database[rite].head_of_rite`, so a fallback also accepts "head of own rite" while
        additionally requiring an Islamic religion (this keeps the pope out)."""
        fid = self._faith_id(cid)
        if fid is None:
            return False
        fe = cl.faith_entry(self.melt, fid)
        rh = fe.get("religious_head")
        if isinstance(rh, int) and rh != self._NO_RELIGIOUS_HEAD:
            t = self._lt.get(str(rh)) or {}
            if isinstance(t, dict) and t.get("holder") == cid:
                return True
        rid = self._rite_id(cid)
        if rid is not None and cl.head_of_rite(self.melt, rid) == cid:
            return self.is_islamic(cid)
        return False

    def _holds_head_seat(self, cid):
        """Whether the character holds a papal-seat title (k_papal_state / d_papacy …)."""
        for tid in (self._hold_intervals(cid) or {}):
            tkey = (self._lt.get(str(tid)) or {}).get("key") or ""
            if "papal" in tkey or "papacy" in tkey:
                return True
        return False

    # =====================================================================
    # Antipope (religious head challenger)
    # =====================================================================
    # Mechanism, cited from the game files:
    #   · The office is a dynamically created landless title (`create_dynamic_title` +
    #     `set_landless_title`) carrying the title variable `pam_antipope_office`; its name is
    #     `<capital barony name>` + the faith's `ReligiousHeadTitleName`.
    #   · Register: `faiths.database[<fid>].religious_head_challengers` holds entries
    #     `{religious_head_challenger: <title id>, sponsor: <title id>}` — both fields are title
    #     ids, so resolve people through `landed_titles[<id>].holder`.
    #   · That list can be empty (dropped by code when the rite leaves the faith,
    #     pam_antipope_effects.txt), hence the title variable is the primary test and the list
    #     only cross-checks.
    #   · Do not use `antipope_flag` (the flag is only added on inheritance at kingdom tier,
    #     title_on_actions.txt) or `head_of_rite` (installing an antipope never touches it).
    #   · Title word comes from the flavorization `antipope_male/female` ⇒ 中文「对立教宗」;
    #     the lookup key is `game_concept_antipope`.
    _ANTIPOPE_FLAG = "pam_antipope_office"
    _ANTIPOPE_WORD = "对立教宗"        # fallback when the localization table lacks the key

    def _antipope_office_ids(self):
        """All antipope-office title ids in the save (lazily scanned once, keyed on the variable)."""
        if getattr(self, "_antipope_ids", None) is None:
            ids = set()
            for tid, t in (self._lt or {}).items():
                if not isinstance(t, dict):
                    continue
                for v in ((t.get("variables") or {}).get("data") or []):
                    if isinstance(v, dict) and str(v.get("flag") or "") == self._ANTIPOPE_FLAG:
                        try:
                            ids.add(int(tid))
                        except (TypeError, ValueError):
                            pass
                        break
            self._antipope_ids = ids
        return self._antipope_ids

    def _title_destroyed_date(self, tid):
        """Earliest `destroyed` event date in this title's history ('' if none).

        Used to tell that an office title has ended: an antipope's office title is destroyed when
        he is promoted (or the challenge ends), while the last tier still keeps a holder."""
        hist = (self._lt.get(str(tid)) or {}).get("history")
        if not isinstance(hist, dict):
            return ""
        out = ""
        for d, v in hist.items():
            for e in (v if isinstance(v, list) else [v]):
                if not isinstance(e, dict) or e.get("type") != "destroyed":
                    continue
                ds = str(d)
                if not out or cl.date_key(ds) < cl.date_key(out):
                    out = ds
        return out

    def antipope_office_at(self, cid, date=None):
        """Id of the antipope title the character holds at `date` (None if none).

        Holding is resolved through `_hold_intervals` (truncated at `date`; `abdication` counts
        as a transfer of office, consistent with the project's existing convention).

        Titles already `destroyed` are excluded: destroying the office title leaves the old
        `holder` in the last tier, so `_hold_intervals` alone would report a promoted antipope as
        still in office for the rest of the save."""
        if cid is None:
            return None
        pos = self._antipope_office_ids()
        if not pos:
            return None
        ivs = self._hold_intervals(cid, date) or {}
        best = None
        for tid in sorted(pos):
            rng = ivs.get(tid)
            if not rng:
                continue
            _dd = self._title_destroyed_date(tid)
            if _dd and (not date or cl.date_key(str(date)) >= cl.date_key(_dd)):
                continue
            if best is None:
                best = tid
        return best

    def _antipope_challenger_ids(self, fid):
        """Title ids of the antipopes registered for this faith (empty when the save lists none)."""
        e = cl.faith_entry(self.melt, fid) if fid is not None else {}
        out = set()
        for row in (e.get("religious_head_challengers") or []):
            if not isinstance(row, dict):
                continue
            tid = row.get("religious_head_challenger")
            if isinstance(tid, int):
                out.add(tid)
        return out

    # Tail words of religious-seat title names, used only to locate a dynamic religious title
    _SEAT_TAILS = ("教廷", "教宗国")

    def _title_short_name(self, tid, date=None):
        """Bare title name used as a location word: seat or base name without tier words.

        Lookup order by reliability: ① capital barony/county name from
        `title_name_data.name`, the same source as the game's `PAM_ANTIPOPE_TITLE_NAME` reading
        `pam_antipope_capital`; ② this title's base `title_name_data.name` (save-baked name);
        ③ `_name_at_date(date)` for dynamic/generated names, with the seat tail word stripped;
        ④ title key, keeping a trailing number as a last resort."""
        t = self._lt.get(str(tid)) or {}
        cap = t.get("capital")
        if isinstance(cap, int):
            ct = self._lt.get(str(cap)) or {}
            nm = ((ct.get("title_name_data") or {}).get("name") or "").strip()
            if nm:
                return nm
        base = ((t.get("title_name_data") or {}).get("name") or "").strip()
        if base:
            return base
        nm = ""
        try:
            nm = self._name_at_date(tid, date) or ""
        except Exception:                                     # noqa: BLE001
            nm = ""
        if not nm:
            try:
                nm = self.title(tid, date) or ""
            except Exception:                                 # noqa: BLE001
                nm = ""
        for tail in self._SEAT_TAILS:
            if nm.endswith(tail) and len(nm) > len(tail):
                nm = nm[:-len(tail)]
                break
        if not nm:
            key = str(t.get("key") or "")
            m = re.match(r"^[a-z]+_(?:script|d_laamp)_(\d+)$", key)
            if m:
                nm = m.group(1)
        return nm

    def _antipope_location_word(self, tid, date=None):
        """Location word of an antipope title: its bare name (「京兆教廷」→「京兆」)."""
        return self._title_short_name(tid, date)

    def _highest_held_title(self, cid, date=None):
        """Highest-tier title the character holds at `date` (None if none); ties go to the
        latest acquisition.

        An antipope office is a landless `x_` title (tier 0), so once the holder also gains a
        real title the location word switches to that title."""
        best, best_rank, best_key = None, -1, None
        for tid, ivs in (self._hold_intervals(cid, date) or {}).items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            rank = self._TT_RANK.get(key[:2], 0)
            gains = [cl.date_key(iv[0]) for iv in (ivs or []) if iv and iv[0]]
            gk = max(gains) if gains else (0, 0, 0)
            if rank > best_rank or (rank == best_rank and best_key is not None
                                    and gk > best_key):
                best, best_rank, best_key = tid, rank, gk
        return best

    def antipope_label(self, cid, date=None):
        """Role appellation of an antipope: `对立教宗` prefixed with a location word.

        The prefix is the bare name of the character's highest title when he holds one above the
        office, otherwise the office title's location name (e.g. 「日本对立教宗」). '' when he is
        not an antipope."""
        off = self.antipope_office_at(cid, date)
        if off is None:
            return ""
        concept = ""
        try:
            concept = L.loc(self.table, "game_concept_antipope") or ""
        except Exception:                                     # noqa: BLE001
            concept = ""
        if not concept or concept.startswith(("$", "[")):
            concept = self._ANTIPOPE_WORD
        top = self._highest_held_title(cid, date)
        loc = ""
        if top is not None and top != off:
            loc = self._title_short_name(top, date)
        if not loc:
            loc = self._antipope_location_word(off, date)
        return f"{loc}{concept}" if loc else concept

    def religious_head_word(self, cid):
        """Religious leader appellation: the word for the character when he is the religious head
        of his faith (holder of a faith.religious_head title such as the Papal State), else ''.

        Only holders of a religious-head title qualify; ordinary theocratic rulers keep their
        generic title word instead of being styled 「国王主教」. In 1.20
        `faith.religious_head` is empty, so the test goes through `rites.head_of_rite` and then the
        papal-seat title. An antipope matches neither, so a final clause detects him; otherwise he
        would fall back to `official_title`."""
        rid0 = self._rite_id(cid)
        fid = self._faith_id(cid)
        if fid is None and rid0 is None:
            return ""
        rh = cl.faith_entry(self.melt, fid).get("religious_head") \
            if fid is not None else None
        if isinstance(rh, int) and rh != self._NO_RELIGIOUS_HEAD:
            t = self._lt.get(str(rh)) or {}
            # Tenure interval (title history, already truncated at as_of — dead and former
            # popes count); the current holder is a fallback only when as_of leaves no gap, so a
            # decade biography cannot leak a later pope into an earlier decade
            held_rh = rh in (self._hold_intervals(cid) or {})
            melt_date = (self.melt.get("date") or "")
            no_gap = not (self.as_of and cl.date_key(self.as_of) < cl.date_key(melt_date))
            if not held_rh and not (no_gap and isinstance(t, dict)
                                    and t.get("holder") == cid):
                return ""
            # Only papal-seat titles (k_papal_state / d_papacy) qualify here; other religious
            # heads (caliphs and the like) keep the realm_name path and are not styled 教宗.
            tkey = t.get("key") or ""
            if "papal" not in tkey and "papacy" not in tkey:
                return ""
            v = L.loc(self.table, "religiousheadname_pope")
            if v and not v.startswith("$") and not v.startswith("["):
                return v
            return ""
        # In 1.20 the leader is recorded on the rite: head of this rite and holder of a
        # papal-seat title
        rid = rid0
        if rid is not None and cl.head_of_rite(self.melt, rid) == cid \
                and self._holds_head_seat(cid):
            v = L.loc(self.table, "religiousheadname_pope")
            if v and not v.startswith("$") and not v.startswith("["):
                return v
        # Antipope (the sponsor heads a rival rite). This function is the generic religious-head
        # word — callers add realm or title context to its result — so only the bare concept word
        # is returned here; the prefixed full appellation comes from `antipope_label`.
        return self._ANTIPOPE_WORD if self.antipope_office_at(cid) is not None else ""

    # ---- College of cardinals and papal election ----
    # Save fields used:
    #   · Seats = titles carrying `clerical_elector = <fid>`; the seat name comes from
    #     `title_name_data.name` (already localized in the save) and holders from `.holder`.
    #   · Filled vs vacant = `faiths.database[<fid>].active_clerical_electors` /
    #     `inactive_clerical_electors`.
    #   · Papabile score = character variable `pam_papabile_score` (fixed point ×100000, and the
    #     variable keeps no history).
    #   · Next-election nominees and votes = the papal-seat title's
    #     `succession_election{nominations[], candidate_sources[]}` — votes are `strength` summed
    #     per candidate, which reproduces the title's `heir` order; faction key comes from
    #     `candidate_sources[].key`.
    #   · Reigning pope = `k_papal_state` `.holder` (empty means the see is vacant).
    #   · Canvassing = cardinal variable `pam_papabile_leaning_target` (a 20-year timer);
    #     pressure = `pam_forced_papal_vote_target`.
    # Not emitted: election odds (engine-internal, absent from the save) and per-tier score
    # curves (the score variable has no history).
    _CARDINAL_LIST_MAX = 12          # max vassals listed individually as cardinals
    _PAPAL_FACTION_WORDS = (
        ("theocratic_elective_pious", "虔诚派"),
        ("theocratic_elective_populist", "大众派"),
        ("theocratic_elective_powerful", "权势派"),
    )

    def _cardinal_word(self):
        """The word for 「枢机」 (concept-key lookup, else the literal fallback)."""
        for key in ("game_concept_cardinal", "cardinal_male"):
            try:
                v = L.loc(self.table, key) or ""
            except Exception:                                     # noqa: BLE001
                v = ""
            if v and not v.startswith(("$", "[")):
                return v
        return "枢机"

    def _cardinal_seats(self, fid=None):
        """Cardinal seats `{tid: {"fid", "name", "holder"}}` (whole `landed_titles` scan, lazily
        once).

        A seat is any `landed_titles` entry with a non-empty `clerical_elector`; when `fid` is
        given only that faith's seats are kept."""
        memo = getattr(self, "_cardinal_seats_memo", None)
        if memo is None:
            memo = {}
            for tid, t in self._lt.items():
                if not isinstance(t, dict):
                    continue
                _f = t.get("clerical_elector")
                if _f is None:
                    continue
                memo[str(tid)] = {
                    "fid": _f if isinstance(_f, int) else None,
                    "name": str(((t.get("title_name_data") or {}).get("name")) or ""),
                    "holder": t.get("holder") if isinstance(t.get("holder"), int) else None,
                }
            self._cardinal_seats_memo = memo
        if fid is None:
            return dict(memo)
        return {k: v for k, v in memo.items() if v.get("fid") == fid}

    def _seat_in_realm_of(self, tid, cid):
        """Whether `cid`'s title appears on this seat title's `de_facto_liege` chain.

        The save holds no per-tier vassal hierarchy, only the current de_facto chain (as of the
        same instant as this block's time gate), so this serves only present-state sections (see
        the time gate in `papal_election_lines`)."""
        seen = set()
        cur = (self._lt.get(str(tid)) or {}).get("de_facto_liege")
        for _ in range(20):
            if not isinstance(cur, int) or cur in seen:
                return False
            seen.add(cur)
            t = self._lt.get(str(cur)) or {}
            if not isinstance(t, dict):
                return False
            if t.get("holder") == cid:
                return True
            cur = t.get("de_facto_liege")
        return False

    def _papal_seat_tid(self):
        """Papal-seat title id (`k_papal_state`; None when absent); memoized."""
        memo = getattr(self, "_papal_seat_tid_memo", None)
        if memo is not None:
            return memo
        tid = None
        for _tid, t in self._lt.items():
            if isinstance(t, dict) and t.get("key") == "k_papal_state":
                tid = int(_tid) if str(_tid).isdigit() else _tid
                break
        self._papal_seat_tid_memo = tid
        return tid

    def _papal_vote_tally(self, tid=None):
        """Papal election → (elector count, [(candidate cid, votes)] by votes desc,
        {candidate cid: faction key}).

        Votes are `succession_election.nominations[].strength` summed per candidate, which matches
        the title's `heir` order entry by entry; missing data yields (0, [], {})."""
        if tid is None:
            tid = self._papal_seat_tid()
        t = self._lt.get(str(tid)) or {}
        se = t.get("succession_election") if isinstance(t, dict) else None
        if not isinstance(se, dict):
            return 0, [], {}
        tally = {}
        for n in (se.get("nominations") or []):
            if not isinstance(n, dict) or not isinstance(n.get("candidate"), int):
                continue
            try:
                tally[n["candidate"]] = tally.get(n["candidate"], 0.0) \
                    + float(n.get("strength") or 0)
            except (TypeError, ValueError):
                continue
        fac = {}
        for cs in (se.get("candidate_sources") or []):
            if isinstance(cs, dict) and isinstance(cs.get("character"), int):
                fac[cs["character"]] = str(cs.get("key") or "")
        rows = sorted(tally.items(), key=lambda kv: (-kv[1], kv[0]))
        return len(se.get("electors") or []), rows, fac

    def _papal_score(self, cid):
        """Papal-candidate prestige (`pam_papabile_score`, fixed point ×100000) as a number, or
        None.

        Only cardinals are meaningful here: the pope carries the variable too but no
        `cardinal_flag`."""
        v = self._char_var(cid, "pam_papabile_score")
        return (v / 100000.0) if isinstance(v, (int, float)) else None

    def papal_election_lines(self, cid=None, date=None):
        """Fact lines for the third 《礼仪志》 block: college of cardinals and papal election.

        Three gates must hold at once: ① present state — `date` is not earlier than
        `cache.last_date`, because election data has no history (`succession_election` and the
        papabile score are current fields only), so an earlier decade emits nothing instead of a
        later shortlist; ② the faith of the rite the subject follows that year owns this college;
        ③ either a vassal of the subject sits in it or the subject is a cardinal himself.
        Rows: seat count, vassal cardinals (seat name + name + papabile score), reigning pope and
        since when, next nominees with votes, factions, canvassing."""
        pid = int(cid) if isinstance(cid, int) else self.cache.get("player_id")
        if pid is None:
            return []
        last = self.cache.get("last_date")
        if date and last and cl.date_key(str(date)) < cl.date_key(str(last)):
            return []
        fid = self._faith_id(pid, date)
        if fid is None:
            return []
        seats = self._cardinal_seats(fid)
        if not seats:
            return []
        mine = {tid: s for tid, s in seats.items()
                if isinstance(s.get("holder"), int)
                and s["holder"] != pid
                and self._seat_in_realm_of(tid, pid)}
        if not mine and not any(s.get("holder") == pid for s in seats.values()):
            return []
        rows = []
        entry = cl.faith_entry(self.melt, fid)
        act = [x for x in (entry.get("active_clerical_electors") or [])]
        ina = [x for x in (entry.get("inactive_clerical_electors") or [])]
        n_act = len(act) or len([s for s in seats.values()
                                 if isinstance(s.get("holder"), int)])
        rows.append(f"枢机团：在位枢机 {n_act} 席"
                    + (f"，虚悬 {len(ina)} 席。" if ina else "。"))
        if mine:
            word = self._cardinal_word()
            parts = []
            for tid, s in sorted(mine.items(), key=lambda kv: int(kv[0])
                                 if str(kv[0]).isdigit() else 0)[:self._CARDINAL_LIST_MAX]:
                h = s["holder"]
                # Seat name + 「枢机」 + bare name: `event_name` already carries title words such
                # as 「枢机」, so concatenating its result would duplicate them.
                nm = self.name_or(h) or self.event_name(h, date=date) or ""
                seat = s.get("name") or self.title(tid) or ""
                seg = f"{seat}{word}{nm}" if seat else f"{word}{nm}"
                sc = self._papal_score(h)
                if sc is not None:
                    # the score is written in natural language, never as a parenthetical
                    seg += f"，教宗候选声望 {_num_word(sc)}"
                parts.append(seg)
            rows.append(f"本朝封臣入枢机者 {len(mine)} 人："
                        + "；".join(parts) + "。")
        pap = self._papal_seat_tid()
        holder = (self._lt.get(str(pap)) or {}).get("holder") if pap is not None else None
        if isinstance(holder, int):
            # The reigning pope is written with a bare name: his `event_name` still carries the
            # antipope appellation after a promotion, which contradicts his current office.
            nm = self.name_with_regnal(holder, date=date) or self.name(holder, date=date) or ""
            since = self._title_holder_since(pap, holder, date)
            _tail = (f"自{self.date(since)}起" if since else "")
            _b = self.regnal_birth_name(holder, date)
            _note = "，".join(x for x in ((f"本名{_b}" if _b else ""), _tail) if x)
            rows.append(f"现任教宗：{nm}" + (f"，{_note}" if _note else "") + "。")
        else:
            rows.append("现任教宗：宗座出缺。")
        n_el, tally, fac = self._papal_vote_tally(pap)
        if tally:
            def _nm(_c):
                return self.event_name(_c, date=date) or self.name_or(_c)

            seg = "、".join(f"{_nm(c)} {_num_word(v)} 票" for c, v in tally)
            rows.append(f"下届选举：{n_el or '全'} 位枢机推举 {len(tally)} 人 —— {seg}；"
                        f"第一顺位为{_nm(tally[0][0])}。")
            _fw = dict(self._PAPAL_FACTION_WORDS)
            fparts = [f"{_nm(c)}属{_fw[k]}" for c, _v in tally
                      if (k := fac.get(c)) and k in _fw]
            if fparts:
                rows.append("派别：" + "，".join(fparts) + "。")
            # canvassing: cardinals leaning towards one candidate; only ≥2 are written so a
            # single cardinal does not produce noise
            lean = {}
            for s in seats.values():
                h = s.get("holder")
                if not isinstance(h, int):
                    continue
                tgt = self._char_var(h, "pam_papabile_leaning_target")
                if isinstance(tgt, int):
                    lean[tgt] = lean.get(tgt, 0) + 1
            for tgt, n in sorted(lean.items(), key=lambda kv: (-kv[1], kv[0])):
                if n >= 2 and tgt in dict(tally):
                    rows.append(f"奔走：{n} 位枢机在替{_nm(tgt)}奔走。")
                    break
        return rows

    # ---- execution method (approximates the send_option list of execute_prisoner_interaction) ----

    def execution_method(self, killer_id, victim_id, date=None):
        """Execution method: one send_option available to the executioner at the time.

        The save stores only `death_execution`, never the method, so availability is approximated from the
        executioner's state as of the yearly snapshot. Deterministically forced: 连坐处死 (a same-day mass
        execution across houses, a `purged_*` opinion or a purge-catalyst hit) and devouring. Otherwise the
        pool holds 斩首 (East Asian heritage pillar, or the same faith as the victim; an unknown culture
        defaults to it), 烧死 (non-East-Asian culture), 做成神秘的肉 (landless adventurer government plus
        `fear_tax_perk`), 犬决 (`kennelperson_camp_officer` employed), 食人 (`cannibal` trait or
        `secret_cannibal`) and 献祭 (a doctrine granting `human_sacrifice_active`, whose keys live in
        `religion.faiths[fid].doctrine`). A stable pseudo-random pick is made from that pool. Returns
        (key, Chinese phrase), or ('', '') when the killer is missing or nothing is available."""
        if killer_id is None:
            return "", ""
        # Devouring hard evidence first: a 「…之骨」 bone relic under the victim's name whose
        # creation recipient is this executioner means the man was eaten. The cause of death is
        # then deterministic and stays out of the random pool.
        if victim_id is not None and self.devoured_by(int(killer_id), int(victim_id)):
            return _style.EXECUTION_DEVOUR_BONE
        # Deaths hit by a house purge are always recorded as 连坐处死, outside the random pool.
        if victim_id is not None and self.is_family_purge(killer_id, victim_id, date):
            return _style.EXECUTION_PURGE
        tpl = (self.culture_template(killer_id) or "").lower()
        asian = (not tpl) or tpl in _ASIAN_HERITAGE_TPL
        kf = self._faith_id(killer_id)
        same_faith = kf is not None and kf == self._faith_id(victim_id)
        avail = []
        if asian or same_faith:
            avail.append("beheaded")
        if not asian:
            avail.append("burned")
        # 做成神秘的肉: landless adventurer with the fear-tax perk (camp provisions are
        # transient and never reach the biography)
        c = self._chars.get(str(killer_id)) or {}
        gov = (self.cache.get("characters") or {}).get(str(killer_id), {}) \
            .get("landed") or {}
        gv = gov.get("government") or (c.get("landed_data") or {}).get("government") or ""
        if gv == "landless_adventurer_government" and \
                "fear_tax_perk" in ((c.get("alive_data") or {}).get("perk") or []):
            avail.append("provisions")
        # 犬决: employs a kennelperson courtier
        cpd = (self.melt.get("court_positions") or {}).get("database") or {}
        if any(isinstance(e, dict) and e.get("employer") == killer_id
               and e.get("court_position") == "kennelperson_camp_officer"
               for e in cpd.values()):
            avail.append("kennel")
        # 食人: the cannibal trait (dated through trait_history, current value for older caches)
        # or a secret
        if self._has_trait_at(killer_id, "cannibal", date) or \
                self._has_secret(killer_id, "secret_cannibal"):
            avail.append("devour")
        # 献祭: the faith's doctrines grant human_sacrifice_active (the save keeps the doctrine
        # key list in religion.faiths[fid].doctrine; parameter names are generated by
        # localization.doctrines_granting from doctrine_types parameters)
        if self._sacrifice_faith(killer_id):
            avail.append("sacrifice")
        if not avail:
            return "", ""
        avail.sort(key=lambda k: _EXECUTION_ORDER.get(k, 99))
        seed = int(hashlib.md5(
            f"exec::{killer_id}:{victim_id}:{date or ''}".encode("utf-8")
        ).hexdigest()[:12], 16)
        key = random.Random(seed).choice(avail)
        zh = dict(_EXECUTION_OPTIONS).get(key, "")
        return key, zh

    _PURGE_OPINION = ("purged_banishment_opinion", "purged_execution_opinion")
    # The two day-level channels below no longer serve as criteria now that the test is narrowed
    # to house level: the catalyst entry (`catalyst_tyrannical_extinguish_noble_family`, written by
    # event `tgp_east_asia_interaction_events.2000` through `10_tgp_interactions.txt`) and "3+ houses
    # executed in one day" both carry no house information, so naming people off them would again
    # mark everyone executed that same day. The constants are kept only for reference.
    _PURGE_CATALYST = "catalyst_tyrannical_extinguish_noble_family"
    _PURGE_HOUSE_THRESHOLD = 3
    # Hard `is_shown` gate of the `celestial_extinguish_noble_family` interaction: the game's
    # `10_tgp_interactions.txt` requires `government_has_flag = government_is_celestial`, and in
    # `00_government_types.txt` that flag appears only inside the `celestial_government` block.
    # Only this one government counts: administrative, meritocratic and steppe_admin do not carry
    # the flag and have their own family-extinction interactions, which never write the purge
    # catalyst.
    _PURGE_GOVS = {"celestial_government"}

    def _dynastic_cycle_history_entries(self):
        """History entries of the `dynastic_cycle` situation (empty when absent)."""
        sm = (self.melt.get("situation_manager") or {}).get("database") or {}
        for v in sm.values():
            if isinstance(v, dict) and v.get("type") == "dynastic_cycle":
                hist = v.get("history") or []
                if isinstance(hist, list):
                    return hist
        return []

    def purged_houses(self, killer_id):
        """Houses purged by this executioner, as **{date: frozenset(house id)}**.

        All criteria are settled at house level:
          · Primary — the interaction in `10_tgp_interactions.txt` destroys every
            `is_noble_family_title` holding (noble-family estate `_nf_`) of the victim and kills only him
            and close kin of the same house, so a house counts when its `_nf_` estate was destroyed on a
            day and that estate's holder was executed by this executioner on the same day.
          · Fallback, when no estate entry exists — `purged_*` opinions owned by the executioner whose
            target's house is among the houses executed by him that day (the only trace exiles leave).
          · Mechanism gate — his government that day must be `celestial_government`, matching the
            interaction's `government_has_flag = government_is_celestial` (see `_PURGE_GOVS`).
          · Devouring excluded — days with `devour_bone_visual` evidence are dropped (see `_devour_bones`).

        An empty dict means no determinable purge for this executioner."""
        if killer_id is None:
            return {}
        kid = int(killer_id)
        cached = self._purge_houses_map.get(kid)
        if cached is not None:
            return cached
        # victims executed by this executioner per day: {date: [(cid, house_id)]}
        victims_by_day = {}
        for cid, c in self._chars.items():
            if not isinstance(c, dict):
                continue
            dd = c.get("dead_data") or {}
            if dd.get("reason") != "death_execution" or dd.get("killer") != kid:
                continue
            d = str(dd.get("date") or "")
            if not d:
                continue
            victims_by_day.setdefault(d, []).append((int(cid), c.get("dynasty_house")))
        if not victims_by_day:
            self._purge_houses_map[kid] = {}
            return {}
        out = {}
        # primary criterion: an estate destroyed that day whose holder was executed that day
        for tid, t in self._lt.items():
            if not isinstance(t, dict) or not self._is_estate_title(tid):
                continue
            hist = t.get("history") or {}
            if not isinstance(hist, dict):
                continue
            for _hd, v in hist.items():
                for e in (v if isinstance(v, list) else [v]):
                    if not isinstance(e, dict) or e.get("type") != "destroyed":
                        continue
                    d = str(_hd)
                    h = e.get("holder")
                    if not isinstance(h, int):
                        continue
                    rows = victims_by_day.get(d)
                    if not rows or h not in {c for c, _hh in rows}:
                        continue
                    hid = self._house_of_cid(h)
                    if hid is not None:
                        out.setdefault(d, set()).add(hid)
        # fallback: houses of purged_* opinion targets owned by the executioner, intersected with
        # the houses executed that day
        for d, houses in self._purge_opinion_houses(kid).items():
            vhouses = {hh for _c, hh in (victims_by_day.get(d) or [])
                       if hh is not None}
            hit = {hh for hh in houses if hh in vhouses}
            if hit:
                out.setdefault(d, set()).update(hit)
        # mechanism gate + devouring exclusion
        devoured = {d for d, _rec, _vid in self._devour_bones().values()}
        self._purge_houses_map[kid] = {
            d: frozenset(hs) for d, hs in out.items()
            if hs and d not in devoured and self._purge_gov_ok(kid, d)}
        return self._purge_houses_map[kid]

    def _purge_dates(self, killer_id):
        """Purge dates — the date projection of `purged_houses`, for verification scripts only.

        It carries no house information, so filtering names by day through it would again mark
        everyone executed that day; criteria always go through `purged_houses` /
        `is_family_purge`."""
        return set(self.purged_houses(killer_id))

    def _purge_opinion_houses(self, killer_id):
        """This executioner's `purged_*` opinions → {date: {target house}} (fallback path).

        Direction: the event `tgp_east_asia_interaction_events.txt` writes them through
        `reverse_add_opinion = { target = root }`, so owner = executioner and target = the purged
        man's house. Both `purged_*` modifiers last 25 years with `decaying = yes`
        (`common/opinion_modifiers/00_crime_and_prison_opinions.txt`) and vanish the moment either
        side dies, so the executed man's entry is never found and only a living exile's survives."""
        out = {}
        for o in (self.melt.get("opinions") or {}).get("active_opinions") or []:
            if not isinstance(o, dict) or o.get("owner") != killer_id:
                continue
            tgt = o.get("target")
            if not isinstance(tgt, int):
                continue
            hid = self._house_of_cid(tgt)
            if hid is None:
                continue
            for v in cl._opinion_values(o):
                if v.get("modifier") in self._PURGE_OPINION and v.get("start_date"):
                    out.setdefault(str(v["start_date"]), set()).add(hid)
        return out

    def _purge_opinion_dates(self, killer_id):
        """Date projection of `purged_*` opinions involving this executioner; the actual criteria
        stay at house level (see `_purge_opinion_houses`)."""
        return set(self._purge_opinion_houses(killer_id))

    def _purge_gov_ok(self, killer_id, date):
        """Whether the executioner's government on `date` can perform a house purge.

        An unknown government returns True: the conservative direction here is not to change the
        verdict, so executions earlier than the start of the per-tier government history still take
        part and the positive evidence does the narrowing. Only a government known to be different
        (e.g. `tribal_government`) blanks the whole day."""
        gov = self._character_government(killer_id, date)
        return (not gov) or gov in self._PURGE_GOVS

    # Hard evidence index for devouring: the mod's `devour_bone_visual` artifact. Eating a character
    # creates a 「…之骨」 bone relic for him at the same instant, and the `created` entry of
    # `history.entries` names the eater in `recipient`. The cause of death itself only says
    # `death_execution` (the same key as an execution), so this relic is the only physical proof in the
    # save that a man was eaten; without it a pseudo-random method pool would hand the deed to 斩首,
    # 烧死, 献祭 or drowning instead.
    _DEVOUR_VISUAL = "devour_bone_visual"

    def _devour_bones(self):
        """Hard devouring evidence: {artifact id: (creation date, eaten character id)}.

        Keeps only relics whose `visuals.type == devour_bone_visual` and whose `created` entry
        carries a `recipient`. The eaten character id is that entry's `actor` (the victim himself,
        the same source as `ONCLICK:CHARACTER,id` in the description), falling back to the
        creator."""
        memo = getattr(self, "_devour_bones_map", None)
        if memo is not None:
            return memo
        out = {}
        art = (self.melt.get("artifacts") or {}).get("artifacts") or {}
        for aid, a in art.items():
            if not isinstance(a, dict):
                continue
            if ((a.get("visuals") or {}).get("type") or "") != self._DEVOUR_VISUAL:
                continue
            for e in ((a.get("history") or {}).get("entries") or []):
                if not isinstance(e, dict) or e.get("type") != "created":
                    continue
                rec = e.get("recipient")
                if not isinstance(rec, int):
                    continue
                vid = e.get("actor")
                if not isinstance(vid, int):
                    vid = self._artifact_actor_from_name(a.get("description"))
                out[str(aid)] = (str(e.get("date") or ""), rec, vid)
                break
        self._devour_bones_map = out
        return out

    def devoured_by(self, killer_id, victim_id=None):
        """What this executioner ate: {eaten character id: relic creation date}, or with
        `victim_id` the creation date of that one man.

        Shares `_devour_bones`: only "the creation recipient is this person" counts, because the
        mod lets relics be gifted or inherited and the last tier's owner has long changed."""
        out = {}
        for _aid, (date, rec, vid) in (self._devour_bones() or {}).items():
            if rec != killer_id:
                continue
            if vid is None:
                continue
            out[int(vid)] = date
        if victim_id is None:
            return out
        return out.get(int(victim_id), "")

    def _artifact_actor_from_name(self, raw):
        """Eaten character id read from `ONCLICK:CHARACTER,<id>` in a relic description (None when
        not found)."""
        m = self._ARTIFACT_REF_RE.search(str(raw or ""))
        if not m or m.group(1) != "CHARACTER":
            return None
        key = m.group(2)
        return int(key) if str(key).isdigit() else None

    def is_family_purge(self, killer_id, victim_id, date=None):
        """Whether this single execution is a house purge.

        Criterion: the victim's house is among the houses purged that day (see `purged_houses`).
        The date alone is not enough, since then every man this executioner executed that day
        would be recorded as 连坐处死."""
        if killer_id is None or victim_id is None or not date:
            return False
        houses = self.purged_houses(killer_id).get(str(date))
        if not houses:
            return False
        try:
            hid = self._house_of_cid(int(victim_id))
        except (TypeError, ValueError):
            return False
        return hid is not None and hid in houses

    def family_purge_victims(self, killer_id):
        """Ids involved in a house purge: those executed and those banished from the purged houses.

        The interaction `celestial_extinguish_noble_family_interaction` (and event
        `tgp_east_asia_interaction_events.2000`) first imprisons every close and extended family member and
        every spouse of the recipient with `imprison = { type = house_arrest }`, then executes the recipient
        and banishes the rest, leaving `purged_banishment_opinion` in the save; one such event yields dozens
        of executions and imprisonments at once, which would flood a per-person chronicle.

        Each person is checked against the houses purged that day: executed victims by the house set,
        banished survivors (including foreign spouses) by the `purged_*` opinion targets owned by the
        executioner that day — that interaction is their only source (see `_purge_opinion_houses`)."""
        killer_houses = self.purged_houses(killer_id)
        if not killer_houses:
            return set()
        kid = int(killer_id)
        out = set()
        for cid, c in self._chars.items():
            if not isinstance(c, dict):
                continue
            dd = c.get("dead_data") or {}
            if dd.get("reason") != "death_execution" or dd.get("killer") != kid:
                continue
            houses = killer_houses.get(str(dd.get("date") or ""))
            if houses and c.get("dynasty_house") in houses:
                out.add(int(cid))
        for o in (self.melt.get("opinions") or {}).get("active_opinions") or []:
            if not isinstance(o, dict) or o.get("owner") != kid:
                continue
            tgt = o.get("target")
            if not isinstance(tgt, int) or tgt == kid:
                continue
            for v in cl._opinion_values(o):
                if v.get("modifier") in self._PURGE_OPINION \
                        and str(v.get("start_date") or "") in killer_houses:
                    out.add(tgt)
                    break
        return out

    def family_purge_events(self, killer_id):
        """House-level fact lines for house purges, as `[{"date", "text"}]`.

        Shared by two callers: the chronicle insertion (one line for the whole event) and the
        summary before the 《刺客列传》 roster. Banished people are not named one by one: the
        interaction executes everyone landed, so the exiled are landless remnants and listing them
        is pure noise. Only victims of the houses purged that day are counted."""
        killer_houses = self.purged_houses(killer_id)
        if not killer_houses:
            return []
        kid = int(killer_id)
        by_day = {}
        for cid, c in self._chars.items():
            if not isinstance(c, dict):
                continue
            dd = c.get("dead_data") or {}
            if dd.get("reason") != "death_execution" or dd.get("killer") != kid:
                continue
            d = str(dd.get("date") or "")
            houses = killer_houses.get(d)
            hid = c.get("dynasty_house")
            if not houses or hid is None or hid not in houses:
                continue
            by_day.setdefault(d, []).append((int(cid), hid))
        out = []
        for d in sorted(by_day, key=lambda x: cl.date_key(x)):
            items = by_day[d]
            houses, seen = [], set()
            for _cid, hid in items:
                if hid is None or hid in seen:
                    continue
                seen.add(hid)
                label = self._house_label(hid)
                if label:
                    houses.append(label)
            n = len(seen) or len(items)
            shown = "、".join(houses[:6])
            if n > 6 and shown:
                shown += "等"
            head = f"诛灭{shown} {n} 族" if shown else f"诛灭世族 {n} 族"
            out.append({"date": d,
                        "text": f"{head}，处死家主 {len(items)} 人，剩余残党被流放"})
        return out

    def family_purge_summaries(self, killer_id):
        """House-level summary texts (used before the 《刺客列传》 roster), see
        `family_purge_events`.

        Each already starts with its date, because this caller does not go through the chronicle's
        date prefixing."""
        return [f"{self.date(e['date'])}{e['text']}"
                for e in self.family_purge_events(killer_id)]

    _CYCLE_ERA = {
        "situation_dynastic_cycle_phase_stability_expansion":
            ("开疆拓土", "治世"),
        "situation_dynastic_cycle_phase_stability_advancement":
            ("政通人和", "治世"),
        "situation_dynastic_cycle_phase_stability":
            ("国局稳定", "治世"),
        "situation_dynastic_cycle_phase_instability":
            ("局势紧张", "危世"),
        "situation_dynastic_cycle_phase_instability_conquest":
            ("新朝征服", "危世"),
        "situation_dynastic_cycle_phase_chaos":
            ("群雄割据", "乱世"),
    }

    def dynastic_cycle_line(self, date=None):
        """The Mandate-of-Heaven line, e.g. 「天命：新朝征服，世属危世，自919年8月2日」.

        `dynastic_cycle` is the game's world-unique situation (`is_unique = yes` in
        `common/situation/situations/tgp_dynastic_cycle.txt`) acting on the China core sub-region
        (the same file adds `h_china` to that sub-region, by de jure title and by realm). It is
        emitted only when the subject's government at that time belongs to the celestial chain
        (celestial / meritocratic / steppe_admin), so a feudal ruler's file never claims the
        Mandate; an unknown government withholds the line."""
        pid = self.cache.get("player_id")
        gov = self._character_government_or_earliest(pid, date) \
            if pid is not None else ""
        if gov not in self._CELESTIAL_CHAIN_GOVS:
            return ""
        hist = self.cache.get("dynastic_cycle_history") or []
        rec = None
        if hist:
            dk = cl.date_key(date) if date else None
            for h in hist:
                if not h.get("date"):
                    continue
                if dk is None or cl.date_key(h["date"]) <= dk:
                    rec = h
                else:
                    break
        if rec is None:
            cur = cl.dynastic_cycle_phase(self.melt)
            if cur:
                rec = {"phase": cur.get("phase"),
                       "start": cur.get("start") or date}
        if not rec:
            return ""
        phase = rec.get("phase") or ""
        pair = self._CYCLE_ERA.get(phase)
        if not pair:
            zh = L.loc(self.table, phase)
            if not zh or zh.startswith(("$", "[")) or re.search(r"[A-Za-z_]", zh):
                return ""
            name, era = zh, ""
        else:
            name, era = pair
        start = rec.get("start") or rec.get("date") or ""
        when = self.date(start) if start else ""
        # the era type is a parallel clause, never a parenthetical
        era_clause = f"，世属{era}" if era else ""
        if when:
            return f"天命：{name}{era_clause}，自{when}"
        return f"天命：{name}{era_clause}"

    def assassination_method(self, killer_id, victim_id, date=None, reason_key=None,
                             name_date=None):
        """Assassination method: one concrete method drawn from a pool for a generic cause of death.

        Availability gates (see `_METHOD_REASON_TAGS` / `_ASSASSINATION_GAME_KEYS` /
        `_ASSASSINATION_HISTORY`): the method's tags must be a subset of those allowed for the
        cause (mysterious death / disappearance / murder / poisoning); the killer's or the victim's
        culture selects the eastern or the western pool, with `any` entries in both; a victim under
        8 at death only gets child-safe entries; palace-coup, throne and triumph methods need the
        victim to be kingdom tier or above at death. Returns (key, Chinese phrase), or ('', '')
        when the cause has no pool or the pool is empty."""
        if killer_id is None or not reason_key:
            return "", ""
        tags = _METHOD_REASON_TAGS.get(reason_key)
        if not tags:
            return "", ""
        tpl_k = (self.culture_template(killer_id) or "").lower()
        tpl_v = (self.culture_template(victim_id) or "").lower()
        east = (tpl_k in _ASIAN_HERITAGE_TPL) or (tpl_v in _ASIAN_HERITAGE_TPL)
        sphere = "east" if east else "west"
        # The killer's appellation must match the rest of the text: `_death_sentence` performs the
        # 「缩为其」 substitution through it, so both places have to agree.
        # `name_date` gives the day of the deed, so the appellation is taken at that date: in a
        # chronicle line about an earlier year the killer cannot already carry a title he only
        # gained later.
        kname = self.event_name(killer_id, date=name_date or self.as_of) \
            or self.name_or(killer_id, "某人")
        age = self._age_at_death(victim_id, date)
        child = age is not None and age < 8
        high = self._is_high_rank_at(victim_id, date)
        avail = []
        for loc_key, mtags, msphere, child_ok in _ASSASSINATION_GAME_KEYS:
            if not mtags <= tags or msphere not in ("any", sphere):
                continue
            if child and not child_ok:
                continue
            if loc_key in _METHOD_HIGH_RANK and not high:
                continue
            text = _render_killer_loc(self.table, loc_key, kname)
            if text:
                avail.append((loc_key, text))
        for mkey, tmpl, mtags, msphere, child_ok in _ASSASSINATION_HISTORY:
            if not mtags <= tags or msphere not in ("any", sphere):
                continue
            if child and not child_ok:
                continue
            avail.append((mkey, tmpl.format(k=kname)))
        if not avail:
            return "", ""
        seed = int(hashlib.md5(
            f"assassin::{killer_id}:{victim_id}:{date or ''}:{reason_key}"
            .encode("utf-8")
        ).hexdigest()[:12], 16)
        return random.Random(seed).choice(avail)

    def _age_at_death(self, cid, date=None):
        """The character's age in whole years at death; None when birth or death is unknown."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        c = self._chars.get(str(cid)) or {}
        birth = rec.get("birth") or c.get("birth")
        death = date or (rec.get("death") or {}).get("date") \
            or (c.get("dead_data") or {}).get("date")
        if not birth or not death:
            return None
        try:
            return int(str(death).split(".")[0]) - int(str(birth).split(".")[0])
        except Exception:
            return None

    def _is_high_rank_at(self, cid, date=None):
        """Whether the victim was kingdom tier (k_) or above at death — used by palace-coup and
        throne methods."""
        try:
            tier, tid = self._primary_title_at(cid, as_of=date)
        except Exception:
            return False
        if tid is None:
            return False
        rank = self._TT_RANK.get((self._lt.get(str(tid)) or {}).get("key", "")[:2], 0)
        return rank >= 4

    def imprison_duration(self, cid, date=None):
        """Length of imprisonment when the character was still in prison at death, rendered as
        「N年M个月」; '' when under a year, already released, or unrecorded.

        Source: the victim's own `imprisoned` / `released_from_prison_memory` memories, with the
        player's `imprisoned_other` as fallback. Takes the last imprisonment before the death date
        and ignores it when a release follows. Only months are resolved although game dates are
        day-granular."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        if not date:
            date = (rec.get("death") or {}).get("date")
        if not date:
            return ""
        pid = self.cache.get("player_id")

        def _prison_mems(owner):
            ore = (self.cache.get("characters") or {}).get(str(owner)) or {}
            return ore.get("memories") or []

        ins, outs = [], []
        for m in _prison_mems(cid):
            t = m.get("type")
            d = m.get("creation_date")
            if not d:
                continue
            if t == "imprisoned":
                ins.append(d)
            elif t in ("released_from_prison_memory",
                       "escaped_from_prison_memory"):
                outs.append(d)  # escaping also ends imprisonment, so an escapee is not still held
        if not ins and pid is not None:
            # when the victim's memories were pruned, the player's 「囚禁他人」 memory is a fallback
            for m in _prison_mems(pid):
                if m.get("type") != "imprisoned_other":
                    continue
                parts = m.get("participants") or {}
                if parts.get("imprisoned") == cid and m.get("creation_date"):
                    ins.append(m["creation_date"])
        if not ins:
            return ""
        dk = cl.date_key(str(date))
        start = None
        for d in sorted(ins, key=lambda x: cl.date_key(str(x))):
            if cl.date_key(str(d)) <= dk:
                start = d
        if not start:
            return ""
        if any(cl.date_key(str(o)) > cl.date_key(str(start))
               and cl.date_key(str(o)) <= dk for o in outs):
            return ""  # released before death
        try:
            y0, m0, d0 = (int(x) for x in str(start).split(".")[:3])
            y1, m1, d1 = (int(x) for x in str(date).split(".")[:3])
        except Exception:
            return ""
        months = (y1 - y0) * 12 + (m1 - m0)
        if d1 < d0:
            months -= 1
        if months < 12:
            return ""
        y, m = divmod(months, 12)
        return f"{y}年" + (f"{m}个月" if m else "")

    def killer_is_public(self, cid):
        """Whether this character's killer is publicly known: the save flag `dead_data.killer_known`
        (written by `set_killer_public` on the murder/exposure chain) or a cause of death that is public by
        nature (`public_knowledge = yes`, see `_PUBLIC_DEATH_REASONS`).

        `dead_data.know_of_killer` is not a criterion: it lists who knows the killer privately, so the
        player's own entry only means the killer knows himself. Read from the melt, because the cached
        `death` is latched once (`cache_lib.py`) and never updated when `on_expose` rewrites the cause
        through `set_death_reason` (`00_secret_types.txt`)."""
        if cid is None:
            return False
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return False
        memo = getattr(self, "_kp_cache", None)
        if memo is None:
            memo = self._kp_cache = {}
        if cid in memo:
            return memo[cid]
        dd = ((self._chars.get(str(cid)) or {}).get("dead_data") or {})
        if dd:
            val = bool(dd.get("killer_known")) \
                or str(dd.get("reason") or "") in _PUBLIC_DEATH_REASONS
        else:                 # not in the melt (pruned in an early tier): use the cached cause
            rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
            val = str((rec.get("death") or {}).get("reason") or "") \
                in _PUBLIC_DEATH_REASONS
        memo[cid] = val
        return val

    def killer_hidden(self, cid, killer):
        """Whether a public text hides this killer: the killer is the subject and the killing is not
        public.

        This is the only gate — third-party killers are still named, and the subject's already
        public killings (an exposed plot, a public execution, an exposed estate raid) are named
        too."""
        try:
            killer = int(killer)
        except (TypeError, ValueError):
            return False
        pid = self.cache.get("player_id")
        if pid is None or killer != int(pid):
            return False
        return not self.killer_is_public(cid)

    def death_clause(self, cid, date=None, reason=None, killer=None, imprison=False,
                     insider=False, killer_date=None):
        """Cause-of-death clause including the agent: executions draw on the execution-method pool,
        assassinations on the assassination-method pool, everything else on the generic text.

        Explicitly passed `date`/`reason`/`killer` win, which serves the melt fallback when the
        victim is absent from the cache. With `imprison=True` a character imprisoned for a full year
        at death is prefixed with 「囚禁N年后」, so imprisonment reaches the biography. `insider=True`
        returns the inside story (naming the killer and using the assassination pool) and belongs to
        the assassin chapter only; the default is the public version, which never names the subject
        as an unpublished killer (see `Facts.killer_hidden`)."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        d = rec.get("death") or {}
        if reason is None:
            reason = d.get("reason")
        if killer is None:
            killer = d.get("killer")
        if date is None:
            date = d.get("date")
        # A public text hides the subject's role as killer: the clause falls back to the game's
        # public wording (mysterious death / murdered / vanished) without inside detail.
        # insider=True belongs to the assassin chapter, which always puts the subject in the
        # killer's slot (see killer_pronoun on the biography side).
        _public = False
        if killer is not None and not insider and self.killer_hidden(cid, killer):
            killer = None
            _public = True
        # Epidemic causes of death use the game's own contemporary disease name
        # (「染丘陵热而亡」); the static period-flavoured word (「染斑疹伤寒而亡」) applies only when
        # no epidemic can be resolved.
        if reason in _DEATH_DISEASE_REASON and killer is None:
            _dyn = _disease_dynamic_name(
                self, cid, _DEATH_DISEASE_REASON[reason], _year_of(date))
            if _dyn:
                return f"染{_dyn}而亡"
        out = ""
        if killer is None:
            out = _death_clause(self.table, reason, None, lambda k: "",
                                public=_public)
        else:
            # The agent uses the unified appellation through `event_name` (bare name for the
            # subject), matching the rest of the text; the assassin chapter's killer_pronoun
            # substitution must draw on the same source.
            # `killer_date` can pin the day of the deed, so a chronicle line about an earlier year
            # does not name the killer by a title he gained later.
            _kdate = killer_date or self.as_of
            kname = self.event_name(killer, date=_kdate) \
                or self.name_or(killer, "某人")
            if reason == "death_execution":
                _k, zh = self.execution_method(killer, cid, date)
                if zh:
                    out = f"被{kname}{zh}"
            if not out:
                _mkey, mzh = self.assassination_method(killer, cid, date, reason,
                                                       name_date=_kdate)
                if mzh:
                    out = mzh
            if not out:
                out = _death_clause(self.table, reason, killer,
                                    lambda k: self.event_name(k, date=_kdate)
                                    or self.name_or(k, "某人"))
        if imprison and out:
            dur = self.imprison_duration(cid, date)
            if dur:
                # When the cause already ends in 「…后」, append 「，囚禁X」 instead of prefixing,
                # so the two do not stack as 「囚禁X后…后…」; otherwise prefix 「囚禁X后」.
                if "后" in out:
                    out = f"{out}，囚禁{dur}"
                else:
                    out = f"囚禁{dur}后{out}"
        return out

    def _has_trait_at(self, cid, trait_key, date=None):
        """Whether the character holds the trait on a date, from the cached `trait_history`
        interval (`from ≤ date < to`); with no history (older caches) the current traits are used."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        th = rec.get("trait_history") or {}
        ivs = th.get(trait_key)
        dk = cl.date_key(date) if date else \
            (cl.date_key(self.as_of) if self.as_of else None)
        if ivs:
            for iv in ivs:
                frm, to = iv.get("from"), iv.get("to")
                if frm and dk is not None and cl.date_key(frm) > dk:
                    continue
                if to and dk is not None and cl.date_key(to) <= dk:
                    continue
                return True
            return False
        for t in rec.get("traits") or []:
            if isinstance(t, int) and 0 <= t < len(self._tl) \
                    and self._tl[t] == trait_key:
                return True
        return False

    def _has_secret(self, cid, secret_type):
        """Whether the character holds this secret (e.g. `secret_cannibal`): an owner match in
        `melt.secrets.secrets`."""
        try:
            secs = (self.melt.get("secrets") or {}).get("secrets") or {}
            return any(isinstance(e, dict) and e.get("owner") == cid
                       and e.get("type") == secret_type for e in secs.values())
        except Exception:
            return False

    # ---- the game's own relation reasons (opinions.active_opinions) ----
    # The game records `scripted_relations.reason` for each pair (e.g. rival_murderer =
    # 「X杀害了Y的亲近之人」) and localization resolves every one of them, so the reason for a feud
    # or a friendship is read from game data instead of being guessed by the model.
    _REL_REASON_KINDS = {
        "rival": ("became_rivals",), "grudge": ("became_grudge",),
        "nemesis": ("became_nemesis",),
        "friend": ("became_friends",), "best_friend": ("became_friends", "became_soulmates"),
        "soulmate": ("became_soulmates",), "blood_brother": ("became_blood_brother",),
        "lover": ("became_lovers", "had_sex"),
    }

    def _player_opinion_index(self):
        """Lazy index of `opinions.active_opinions`: {(owner, target): scripted_relations}.

        Keeps only pairs involving the subject; the one scan over roughly 70k pairs stays well under
        a second."""
        if self._opinion_index is not None:
            return self._opinion_index
        pid = self.cache.get("player_id")
        idx = {}
        if pid is not None:
            for o in (self.melt.get("opinions") or {}).get("active_opinions") or []:
                if not isinstance(o, dict):
                    continue
                ow, tg = o.get("owner"), o.get("target")
                if ow == pid or tg == pid:
                    sr = o.get("scripted_relations")
                    if isinstance(sr, dict):
                        idx[(ow, tg)] = sr
        self._opinion_index = idx
        return idx

    def _cached_opinion_index(self):
        """Relation reasons taken from the cache, shaped like `_player_opinion_index`:
        `{(owner, target): {kind: {"reason":…, "involved_character":…}}}`.

        Source: `cache["relation_reasons"]`, latched per tier by
        `cache_lib._latch_relation_reasons` under key `"<owner>|<target>|<kind>"`. The game writes
        `scripted_relations.<kind>.reason` only while the relation lasts, and the entry disappears
        together with its reason once one side dies or the relation ends, so the newest melt — the
        only one used for generation — cannot show why an early feud started. Built lazily and only
        for entries involving the subject."""
        if self._cached_opinion_idx is not None:
            return self._cached_opinion_idx
        idx = {}
        for rec in (self.cache.get("relation_reasons") or {}).values():
            if not isinstance(rec, dict):
                continue
            owner, target, kind = rec.get("owner"), rec.get("target"), rec.get("kind")
            reason = rec.get("reason")
            if not isinstance(owner, int) or not isinstance(target, int) \
                    or not kind or not reason:
                continue
            idx.setdefault((owner, target), {})[kind] = {
                "reason": reason,
                "involved_character": rec.get("involved"),
                "province": rec.get("province"),
                "_first_seen": rec.get("first_seen"),
            }
        self._cached_opinion_idx = idx
        return idx

    def _any_opinion_index(self):
        """All-pairs index of `melt.opinions.active_opinions`.

        Same source as `_player_opinion_index` but not filtered by the subject, so third-party
        pairs are included too. Only entries carrying `scripted_relations` are kept (about 56k
        across a save), which keeps the index small; scanned lazily once. Needed because relation
        memories such as `became_lovers` must be explained from the memory's own participants
        rather than from the subject."""
        if self._any_opinion_idx is not None:
            return self._any_opinion_idx
        idx = {}
        for o in (self.melt.get("opinions") or {}).get("active_opinions") or []:
            if not isinstance(o, dict):
                continue
            ow, tg = o.get("owner"), o.get("target")
            if not isinstance(ow, int) or not isinstance(tg, int):
                continue
            sr = o.get("scripted_relations")
            if isinstance(sr, dict) and sr:
                idx[(ow, tg)] = sr
        self._any_opinion_idx = idx
        return idx

    def _rel_mem_date(self, cid, mem_types, base=None):
        """Earliest memory date of one relation kind between the subject and `cid` (≤ as_of), used
        as the time gate for the game's reason text so a decade never leaks a relation formed after
        as_of.

        `base` sets the reference person (the subject by default), because a third-party pair must
        also be tested for existence before as_of."""
        cache = self.cache
        pid = base if base is not None else self.cache.get("player_id")
        if pid is None or cid is None:
            return None
        chars = cache.get("characters") or {}
        best = None
        ao = cl.date_key(self.as_of) if self.as_of else None
        for cid0, rec in ((pid, chars.get(str(pid)) or {}),
                          (cid, chars.get(str(cid)) or {})):
            for m in rec.get("memories") or []:
                if m.get("type") not in mem_types:
                    continue
                parts = m.get("participants") or {}
                if not any(isinstance(v, int) and v in (pid, cid) and v != cid0
                           for v in parts.values()):
                    continue
                d = m.get("creation_date")
                if not d:
                    continue
                if ao is not None and cl.date_key(d) > ao:
                    continue
                if best is None or cl.date_key(d) < cl.date_key(best):
                    best = d
        return best

    def relation_reasons(self, cid, kinds):
        """Game reason sentences: `scripted_relations.reason` for the subject and `cid`, localized with name
        placeholders substituted. `kinds` is the set of relation kinds (rival/grudge/nemesis/friend/
        soulmate/...); returns deduplicated sentences. Rendered only when a memory of that relation is
        ≤ as_of, which prevents leakage into earlier decades.

        Fallback: when the melt has no entry for the pair, the per-tier latched `cache["relation_reasons"]`
        supplies it — the game clears the entry with its reason once one side dies or the relation ends, and
        generation uses only the newest melt, so an early feud would stay unexplained. A reason the melt
        carries for the same kind wins; the latch only fills gaps."""
        if cid == self.cache.get("player_id"):
            return []
        idx = self._player_opinion_index()
        cached = self._cached_opinion_index()
        pid = self.cache.get("player_id")
        out = []
        seen = set()
        for pair in ((cid, pid), (pid, cid)):
            # Melt first: any kind it carries a reason for wins (the key order is preserved too);
            # the latch fills in kinds the melt lacks or entries without a reason
            merged = {}
            for kind, v in (idx.get(pair) or {}).items():
                if kind in kinds and isinstance(v, dict) and v.get("reason"):
                    merged[kind] = v
            for kind, v in (cached.get(pair) or {}).items():
                if kind in kinds and isinstance(v, dict) and kind not in merged:
                    merged[kind] = v
            for kind, v in merged.items():
                reason = v.get("reason")
                if not reason:
                    continue
                mtypes = self._REL_REASON_KINDS.get(kind)
                if mtypes and not self._rel_mem_date(cid, mtypes):
                    continue  # relation did not exist before as_of → not rendered
                tpl = L.relation_templates().get(reason)
                if not tpl:
                    continue  # older localization tables carry no template; cause/memory sentences fill in
                extra = v.get("involved_character")
                if not isinstance(extra, int):
                    extra = None
                s = _sub_relation_loc(self, tpl, pair[0], pair[1], extra,
                                      province=v.get("province"))
                s = s.strip("。") + "。" if s else ""
                if s and s not in seen:
                    seen.add(s)
                    out.append(s)
        return out

    def relation_reason_for_pair(self, a, b, kinds, styled=False):
        """Game reason sentences for any pair — same conventions as `relation_reasons` but with a
        reference person other than the subject, for pairs where neither side is the subject.

        Source: the all-pairs melt index (`_any_opinion_index`) plus the per-tier latched
        `cache["relation_reasons"]`. Time gate as in `relation_reasons` (the relation must exist
        before as_of). Returns rendered sentences, melt first with the latch filling gaps (same key
        order conventions). With `styled=True` all three appellations go through `event_name`,
        matching the rest of the fact layer."""
        if not isinstance(a, int) or not isinstance(b, int) or a == b:
            return []
        melt_idx = self._any_opinion_index()
        cached = self._cached_opinion_index()
        out, seen = [], set()
        for pair in ((a, b), (b, a)):
            merged = {}
            for kind, v in (melt_idx.get(pair) or {}).items():
                if kind in kinds and isinstance(v, dict) and v.get("reason"):
                    merged[kind] = v
            for kind, v in (cached.get(pair) or {}).items():
                if kind in kinds and isinstance(v, dict) and kind not in merged:
                    merged[kind] = v
            for kind, v in merged.items():
                reason = v.get("reason")
                if not reason:
                    continue
                mtypes = self._REL_REASON_KINDS.get(kind)
                if mtypes and not self._rel_mem_date(b, mtypes, base=a):
                    continue      # relation did not exist before as_of → not rendered
                tpl = L.relation_templates().get(reason)
                if not tpl:
                    continue
                extra = v.get("involved_character")
                if not isinstance(extra, int):
                    extra = None
                _names = None
                if styled:
                    _names = [
                        self.event_name(pair[0], date=self.as_of) or self.name_or(pair[0]),
                        self.event_name(pair[1], date=self.as_of) or self.name_or(pair[1]),
                        (self.event_name(extra, date=self.as_of) or self.name_or(extra))
                        if isinstance(extra, int) else "",
                    ]
                s = _sub_relation_loc(self, tpl, pair[0], pair[1], extra,
                                      province=v.get("province"), names=_names)
                s = s.strip("。") + "。" if s else ""
                if s and s not in seen:
                    seen.add(s)
                    out.append(s)
        return out

    def dynasty_name(self, cid):
        """Dynasty name of the character (used for Muslim realm names: the game names such realms
        after the dynasty, e.g. 图伦苏丹国): cached dynasty_name → house_name → `dynasty_house`
        resolved through the melt."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        if rec.get("dynasty_name"):
            return rec["dynasty_name"]
        if rec.get("house_name"):
            return rec["house_name"]
        c = self._chars.get(str(cid)) or {}
        hid = c.get("dynasty_house")
        if isinstance(hid, int):
            did = cl.dynasty_id_of(self.melt, hid)
            if did is not None:
                return cl.dynasty_name_zh(self.melt, did) or ""
            return cl.house_name_zh(self.melt, hid)
        return ""

    def realm_name(self, tid):
        """Realm name of an Islamic ruler: k_ → {dynasty}苏丹国; e_/h_ → {dynasty}哈里发国 when he is
        also caliph, else {dynasty}帝国.

        Returns '' for non-Islamic, non-kingdom/empire tier or missing dynasty name, which then take
        the regular rendering. Nomad government does not qualify: it uses
        `uses_culture_and_house_head_named_realms`, so its realms are dynamic culture + house + tribe
        titles rather than an Islamic special name."""
        t = self._lt.get(str(tid)) or {}
        key = t.get("key") or ""
        holder = t.get("holder")
        if not key.startswith(("k_", "e_", "h_")) or not isinstance(holder, int):
            return ""
        if self._title_government(tid, self.as_of) == "nomad_government":
            return ""
        if not self.is_islamic(holder):
            return ""
        dyn = self.dynasty_name(holder)
        if not dyn:
            return ""
        if key.startswith("k_"):
            return f"{dyn}苏丹国"
        if self.is_caliph(holder):
            return f"{dyn}哈里发国"
        return f"{dyn}帝国"

    # ---- culture / faith / traits / government ----
    def culture_template(self, cid):
        """The character's culture template name (norse/han/balhae…): cached culture id → melt
        `culture_manager`.

        When both cache and melt lack the culture (cleared after death, or a save version without
        the field) it is inferred from the kinship chain and then from language. The kinship chain
        outranks the language lookup because one language is often shared by several cultures
        (language_tai alone covers several), and taking whichever candidate comes first would
        misjudge a patrilineal culture. CK3 children inherit culture from the father, so the order is
        self → paternal line → siblings → dynasty → mother → language."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        cul = rec.get("culture")
        if cul is None:
            c = self._chars.get(str(cid)) or {}
            cul = c.get("culture")
        if cul is not None:
            e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
                .get(str(cul))
            tpl = (e or {}).get("culture_template") if isinstance(e, dict) else None
            if tpl:
                return tpl
        # The kinship chain comes first (its last step inside `cl._culture_template_of` is itself the
        # language lookup). chars/memo are passed in so the full character index is not rebuilt on
        # every call within one build_facts run.
        tpl = cl._culture_template_of(self.cache, cid, self.melt,
                                      chars=self._chars, memo=self._tpl_memo)
        if tpl:
            return tpl
        # Language lookup, the last resort when the kinship chain is empty: known languages →
        # `culture_manager.language` → culture template. When several cultures share one language the
        # template with patronym rules wins (language_norse → norse rather than norman).
        for lg in self._languages_of(cid):
            cands = self._lang_to_tpl.get(lg) or []
            if not cands:
                continue
            for tpl in cands:
                if tpl in _patronym_rules():
                    return tpl
            return cands[0]
        return None

    def _languages_of(self, cid):
        """Language ids of the character: those captured in the cache (kept across years) first, else
        the newest melt's alive_data."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        langs = rec.get("languages") or []
        if not langs:
            c = self._chars.get(str(cid)) or {}
            langs = (c.get("alive_data") or {}).get("languages") or []
        return [str(x) for x in langs]

    def languages(self, cid):
        """Chinese names of the character's languages: language_norse → language_norse_name → 诺斯语."""
        out = []
        for lg in self._languages_of(cid):
            v = L.loc(self.table, f"{lg}_name") or L.loc(self.table, lg) or ""
            if v:
                out.append(v)
        return out

    # ---- language flavour (mother tongue / additional languages / mutual understanding) ----
    def _culture_language_id(self, cid, date=None):
        """Language id of the character's culture (language_japonic…); derived from the culture
        template when the culture is missing."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        # the culture id follows the history at `date`, so the mother tongue of an early chapter
        # matches its ethnicity
        cul = self._culture_id_at(cid, date)
        if cul is None:
            cul = (self._chars.get(str(cid)) or {}).get("culture")
        if cul is not None:
            e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
                .get(str(cul))
            if isinstance(e, dict) and e.get("language"):
                return str(e["language"])
        # culture id cleared (player or dead): derive the language from the culture template
        tpl = self.culture_template(cid)
        if tpl:
            lg = self._tpl_to_lang.get(tpl)
            if lg:
                return str(lg)
        return ""

    def mother_language(self, cid, date=None):
        """Chinese name of the mother tongue: culture → language → localization; '' when unknown.

        CK3's language list always contains the native tongue and the rest are learned (Royal Court
        language system). When the culture is untraceable and the character knows exactly one
        language, that one is his mother tongue."""
        lg = self._culture_language_id(cid, date)
        if lg:
            v = L.loc(self.table, f"{lg}_name") or L.loc(self.table, lg) or ""
            if v:
                return v
        langs = self.languages(cid)
        if len(langs) == 1:
            return langs[0]
        return ""

    def language_sentence(self, cid, date=None):
        """Language fact sentence, e.g. 「母语日琉语，兼通乌古尔语。」 or 「通日琉语、乌古尔语。」 when the
        mother tongue cannot be determined; '' when no language is recorded.

        The mother tongue follows `date`, so an early chapter does not use the mother tongue of a
        later ethnicity."""
        langs = self.languages(cid)
        if not langs:
            return ""
        ml = self.mother_language(cid, date)
        if ml and ml in langs:
            others = [x for x in langs if x != ml]
            if others:
                return f"母语{ml}，兼通{'、'.join(others)}。"
            return f"母语{ml}。"
        return f"通{'、'.join(langs)}。"

    def language_relation_line(self, a, b):
        """Language relation sentence for two people: only 「不通」 is stated — when they share no
        common language it lists both language sets and concludes that an interpreter is needed
        (mutual understanding inside a family is common knowledge and is never written).

        Returns '' when a common language exists or either side has no language record."""
        la = self.languages(a)
        lb = self.languages(b)
        if not la or not lb:
            return ""
        # appellations match the rest of the text (person_label: office or title plus name)
        na = self.person_label(a, date=self.as_of, style="brief") or self.name_or(a)
        nb = self.person_label(b, date=self.as_of, style="brief") or self.name_or(b)
        if not na or not nb:
            return ""
        if set(la) & set(lb):
            return ""            # a shared language is common knowledge and is never emitted
        # The language lists are parallel clauses rather than a parenthetical apposition
        # (「与X（奥伊通俗拉丁语）无共通语」 breaks the fact-layer style), so both sides' languages are
        # stated directly.
        return (f"{na}通{'、'.join(la)}，{nb}通{'、'.join(lb)}，"
                f"二者无共通语，交谈须借通译或以手势、习语往来。")

    def language_relation_lines(self, cid):
        """Language relation sentences between the subject and his spouses/children: only those with
        no common language are listed, grouped by the other side's language. Mutual understanding is
        never written."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        ids = list(dict.fromkeys(
            (fam.get("primary_spouse") or []) + (fam.get("spouse") or [])
            + (fam.get("child") or [])))
        pl = self.languages(cid)
        if not pl:
            return []
        # appellations for the subject and his family match the rest of the text (person_label /
        # kin_label)
        na = self.person_label(cid, date=self.as_of, style="brief") or self.name_or(cid)
        groups = {}   # the other side's language tuple -> [id]
        for x in ids:
            try:
                x = int(x)
            except Exception:
                continue
            lx = self.languages(x)
            if not lx:
                continue
            if set(pl) & set(lx):
                continue          # a shared language means no sentence
            groups.setdefault(tuple(lx), []).append(x)
        out = []
        for key, members in groups.items():
            names = "、".join(self.person_label(m, date=self.as_of, style="brief") or self.name_or(m)
                             for m in members)
            if not names:
                continue
            out.append(f"{na}通{'、'.join(pl)}，{names}通{'、'.join(key)}，"
                       f"二者无共通语，交谈须借通译或以手势、习语往来。")
        return out[:4]

    def language_bridge_line(self, cid):
        """Language relations between the subject and his spouses/children, listing only those with no
        common language; '' otherwise.

        Kept as a compatibility exit; prompts use `language_relation_lines`, which also states shared
        languages. The label 「妻室子女言语」 spells out in-laws and children because a looser label was
        read as the subject's origin."""
        pl = set(self.languages(cid))
        if not pl:
            return ""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fam = rec.get("family") or {}
        ids = list(dict.fromkeys(
            (fam.get("primary_spouse") or []) + (fam.get("spouse") or [])
            + (fam.get("child") or [])))
        bits = []
        for x in ids:
            try:
                x = int(x)
            except Exception:
                continue
            lang = self.languages(x)
            if not lang or set(lang) & pl:
                continue
            nm = self.kin_label(x)
            bits.append(f"{nm}通{'、'.join(lang)}")
            if len(bits) >= 5:
                break
        if not bits:
            return ""
        return "妻室子女言语：" + "；".join(bits) + "。"

    def name_zh_of(self, cid):
        """Name of the character without family name or title, used to compose patronymics."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        nm = rec.get("name_zh")
        if not nm:
            c = self._chars.get(str(cid)) or {}
            nm = c.get("first_name")
        return nm or ""

    def _father_id(self, cid):
        """Father id of the character; None when unknown."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        parents = (rec.get("family") or {}).get("father") or []
        if not parents:
            c = self._chars.get(str(cid)) or {}
            v = (c.get("family_data") or {}).get("father")
            if v is not None:
                parents = v if isinstance(v, list) else [v]
        return int(parents[0]) if parents else None

    def patronym(self, cid):
        """Patronymic (middle name): for patronymic cultures with a known father, prefix + father's
        name + suffix (Norse -son/-dóttir, Welsh ap-, Irish mac-/nic-, Iberian -ez, Slavic -ovich,
        English -son …). Empty when the father is unknown or the culture has no patronym rules.

        Resolution goes through `cache_lib._patronym_of`, which infers the culture template from the
        kinship chain and so also covers the player and the dead."""
        return cl._patronym_of(self.cache, cid, self.melt, self.names_path,
                               chars=self._chars)

    def _culture_id_at(self, cid, date=None):
        """Culture id of the character at `date`: the history point wins, else the last tier's value.

        Same convention as `_character_government` — a decade travelling into early years must not
        pick up the last tier's culture. The value lookup is shared with the faith history through
        `_hist_value_at`."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        cul = _hist_value_at(rec.get("culture_history"), date, "culture")
        if cul is not None:
            return cul
        return rec.get("culture")

    def culture(self, cid, date=None):
        """Culture of the character, rendered as 「X人」: cached/melt culture id → language inference →
        localization.

        Returns '' when nothing supports a name, so the caller drops the whole clause instead of
        writing a note such as 「族属不详」. `date` (the chapter's cut-off day) selects the value from
        the culture history, so an early chapter does not use the last tier's culture."""
        cul = self._culture_id_at(cid, date)
        if cul is not None:
            e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
                .get(str(cul))
            tpl = (e or {}).get("culture_template") if isinstance(e, dict) else None
            if tpl:
                name = L.loc(self.table, tpl) or CULTURE_TEMPLATE_ZH.get(tpl) or ""
                if name:
                    return name if name.endswith("人") else f"{name}人"
        tpl = self.culture_template(cid) or ""
        name = L.loc(self.table, tpl) or CULTURE_TEMPLATE_ZH.get(tpl) or ""
        if name:
            # ethnic names use 「X人」 (诺斯人/汉人), never 「X族」; a name already ending in 「人」 stays
            return name if name.endswith("人") else f"{name}人"
        # nothing supports a name → '', so the caller drops the clause instead of writing a note
        return ""

    def _faith_name(self, fid):
        """Faith id → Chinese name ('' when unknown).

        In 1.20 the faith name is already localized in the save (`faiths.database[fid].name`) and is
        used directly; older saves lack the field and go through `faith_type` → localization table /
        FAITH_TYPE_ZH."""
        if fid is None:
            return ""
        nm = cl.faith_name_of(self.melt, fid)
        if nm:
            return nm
        ft = (cl.faith_entry(self.melt, fid) or {}).get("faith_type") or ""
        return L.loc(self.table, ft) or FAITH_TYPE_ZH.get(ft) or ""

    # =====================================================================
    # Exact change points of faith and rite conversion
    # =====================================================================
    # Per-tier cache diffs (`faith_history` / `rite_history`) cover only the tiers in which this
    # character reigned, so every conversion earlier than the first tier is invisible. The game does
    # keep memories (save memory_manager, each with a creation_date and vars):
    #   · converted_faith_memory: new_faith / old_faith / new_rite
    #   · converted_rite_memory:  new_rite / old_rite
    # The cache stores `characters.<id>.memories` together with those vars, so day-exact change
    # points need no re-melt; a tier diff can only notice the change on the following snapshot's
    # 1 January.
    _CONV_MEM_TYPES = ("converted_faith_memory", "converted_rite_memory")

    def conversion_points(self, cid):
        """Exact change points of faith and rite conversion: {date: (faith id|None, rite id|None)}.

        Source: the character's `converted_faith_memory` / `converted_rite_memory` memories (see the block
        comment above); two entries on one day merge into one pair, each filling the other's gap.

        A conversion memory carrying only `new_rite` inherits the character's most recent known faith
        instead of looking up which faith that rite belongs to now, because a rite's faith affiliation
        changes when the game founds a new faith. {} when there are no such memories."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        raw = {}
        for m in (rec.get("memories") or []):
            if not isinstance(m, dict) or m.get("type") not in self._CONV_MEM_TYPES:
                continue
            d = str(m.get("creation_date") or "")
            if not d:
                continue
            v = {}
            for x in (m.get("vars") or []):
                if isinstance(x, dict) and x.get("flag"):
                    v[str(x["flag"])] = x.get("identity")
            fid, rid = v.get("new_faith"), v.get("new_rite")
            fid = fid if isinstance(fid, int) else None
            rid = rid if isinstance(rid, int) else None
            if fid is None and rid is None:
                continue
            prev = raw.get(d) or (None, None)
            raw[d] = (fid if fid is not None else prev[0],
                      rid if rid is not None else prev[1])
        # carry forward in date order: a rite-only change keeps the previous faith, and the first
        # point takes the earliest cached history tier
        out, prev_fid, prev_rid = {}, None, None
        for d in sorted(raw, key=cl.date_key):
            fid, rid = raw[d]
            if fid is None and rid is not None:
                fid = prev_fid if prev_fid is not None \
                    else self._faith_baseline(cid)
            if rid is None:
                rid = prev_rid
            if fid is None and rid is None:
                continue
            out[d] = (fid, rid)
            if fid is not None:
                prev_fid = fid
            if rid is not None:
                prev_rid = rid
        return out

    def _faith_baseline(self, cid):
        """Faith id of the earliest tier in the cached history (None when unknown).

        Used when a rite-conversion memory carries only `new_rite` and its date precedes every faith
        change point: a character who never changed faith keeps his faith, so the earliest known value
        is taken rather than the rite's current affiliation in the melt (a rite's faith affiliation
        changes when the game founds a new faith)."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fh = [h for h in (rec.get("faith_history") or []) if h.get("from")]
        if fh:
            first = min(fh, key=lambda h: cl.date_key(h["from"]))
            fid = first.get("faith")
            if isinstance(fid, int):
                return fid
        return None


    def faith_rite_history(self, cid):
        """History points of faith and rite: [(date, faith id, rite id)], ascending, adjacent equal
        values merged.

        Three sources combine: cached `faith_history` / `rite_history` (per-tier diffs, dated on the
        snapshot day 1 January when the change was noticed) and `conversion_points` (memories, exact
        to the day); the exact memory value wins when both exist on one day. The other axis is read
        with `_hist_value_at` on that same day, so faith and rite are one pair at one instant — a
        rite's owning faith can change when the game founds a new faith, so the same rite name in
        different tiers need not belong to the same religion."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        fh = [h for h in (rec.get("faith_history") or []) if h.get("from")]
        rh = [h for h in (rec.get("rite_history") or []) if h.get("from")]
        mem = self.conversion_points(cid)
        dates = set(mem)
        dates.update(str(h["from"]) for h in fh)
        dates.update(str(h["from"]) for h in rh)
        pts = []
        for d in sorted(dates, key=cl.date_key):
            if d in mem:
                fid, rid = mem[d]
            else:
                fid = _hist_value_at(fh, d, "faith")
                rid = _hist_value_at(rh, d, "rite")
            if pts and pts[-1][1] == fid and pts[-1][2] == rid:
                continue
            pts.append((d, fid, rid))
        return pts

    def _faith_rite_label(self, fid, rid):
        """Full name of a faith: religion + rite, e.g. 「迦克墩基督教拜上帝会」.

        In CK3 1.20 the faith is only the religion family name while the rite is the denomination
        actually followed, and the religion alone cannot tell denominations apart. Writes whichever
        name exists when the two are equal or only one is known; '' when neither."""
        nm = self._faith_name(fid)
        rn = cl.rite_name_of(self.melt, rid) if rid is not None else ""
        if rn and rn != nm:
            return f"{nm}{rn}" if nm else rn
        return nm

    def faith(self, cid, date=None):
        """Full current faith of the character: religion + rite (「迦克墩基督教拜上帝会」).

        Cache first, as with culture; '' when nothing supports a name. Rite and faith are resolved
        together (an older save without a rite writes the faith alone) and always by date — the
        default is this chapter's cut-off `self.as_of`, the same convention as the faith history, so a
        chapter cut off in 915 does not name a denomination adopted in 916. `_faith_id` / `_rite_id`
        carry their own date semantics (history → current value → melt → family default) and are
        reused here."""
        d = date or self.as_of
        if d:
            return self._faith_rite_label(self._faith_id(cid, d),
                                          self._rite_id(cid, d))
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        c = self._chars.get(str(cid)) or {}
        fid = rec.get("faith")
        if fid is None:
            fid = c.get("faith")
        if fid is None:
            fid = cl.faith_id_of_char(self.melt, c)
        rid = rec.get("rite")
        if rid is None:
            rid = cl.rite_id_of_char(c)
        return self._faith_rite_label(fid, rid)

    def faith_history_lines(self, cid):
        """Faith history, built on the three-source `faith_rite_history`.

        e.g. ['885年至893年信迦克墩基督教拜上帝会', '894年信儒家经学',
        '自895年起改信迦克墩基督教拜上帝会']. Dates are rendered as years only: diff points are dated
        on the snapshot day 1 January although the conversion happened between two tiers, and memory
        points are day-exact but reduced to their year as well. Truncated at as_of; fewer than two
        points returns []."""
        pts = self.faith_rite_history(cid)
        if len(pts) < 2:
            return []
        ao = cl.date_key(self.as_of) if self.as_of else None
        rows = []
        for i, (d, fid, rid) in enumerate(pts):
            if ao is not None and cl.date_key(d) > ao:
                break
            nm = self._faith_rite_label(fid, rid)
            if not nm:
                continue
            start = int(str(d).split(".")[0])
            # History entries are full clauses rather than a parenthetical list; the caller joins
            # them with 「；」
            nxt = pts[i + 1][0] if i + 1 < len(pts) else None
            if nxt is not None and (ao is None or cl.date_key(nxt) <= ao):
                end = int(str(nxt).split(".")[0]) - 1
                # two changes in one year (day-exact memory points) collapse into a single year
                # instead of 「894年至894年」
                rows.append(f"{start}年信{nm}" if end <= start
                            else f"{start}年至{end}年信{nm}")
            else:
                rows.append(f"自{start}年起改信{nm}" if i else f"自{start}年起信{nm}")
        # With only one entry (no second change before as_of) nothing is emitted: the name sentence
        # already states the current faith and a single-entry history would only repeat it.
        return rows if len(rows) >= 2 else []

    def _culture_name_of_id(self, cul):
        """Culture id → 「X人」 without a character record (used by the ethnicity-change sentence)."""
        if cul is None:
            return ""
        tpl = cl._template_of_culture(self.melt, cul)
        name = L.loc(self.table, tpl) or CULTURE_TEMPLATE_ZH.get(tpl) or ""
        if name:
            return name if name.endswith("人") else f"{name}人"
        return ""

    def culture_history_lines(self, cid):
        """Ethnicity change sentence, e.g. ['族属：原为哥特人，871年起为诺斯人。'].

        Source: the cached `culture_history` (per-tier diff in cache_lib, same shape as
        `faith_history`). Fewer than two points after truncating at as_of returns []."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        hist = [h for h in (rec.get("culture_history") or []) if h.get("from")]
        if len(hist) < 2:
            return []
        ao = cl.date_key(self.as_of) if self.as_of else None
        pts = []
        for h in hist:
            if ao is not None and cl.date_key(h["from"]) > ao:
                break
            nm = self._culture_name_of_id(h.get("culture"))
            if nm:
                pts.append((int(str(h["from"]).split(".")[0]), nm))
        if len(pts) < 2:
            return []
        out = [f"原为{pts[0][1]}"]
        for y, nm in pts[1:]:
            out.append(f"{y}年起为{nm}")
        return ["族属：" + "，".join(out) + "。"]

    def traits(self, cid):
        """Chinese names of the character's current traits (unknown traits skipped).

        Truncated at as_of: only traits held before as_of and not yet lost are kept, so a decade never
        leaks a later illness."""
        return [z for _k, z in self.trait_pairs(cid)]

    def trait_xp_map(self, cid):
        """Per-track XP of the character at as_of: `{trait key: {track key: value}}`.

        Source: cached `rec["trait_xp"]` samples (`[{from, traits, xp}]`, aligned with that tier's
        `traits` order); the last sample with `from ≤ as_of` is used. Older caches without samples
        yield `{}`, and the renderer falls back to base names. Track definitions live in
        `data/trait_tracks.json`."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        samples = rec.get("trait_xp") or []
        if not samples:
            return {}
        ao = cl.date_key(self.as_of) if self.as_of else None
        pick = None
        for s in samples:
            if not isinstance(s, dict):
                continue
            if ao is not None and cl.date_key(str(s.get("from"))) > ao:
                break
            pick = s
        if pick is None:
            return {}
        tracks = (L.trait_track_table().get("tracks") or {})
        traits = pick.get("traits") or []
        xp = pick.get("xp") or []
        out, cur = {}, 0
        for t in traits:
            if not isinstance(t, int) or t < 0 or t >= len(self._tl):
                continue
            key = self._tl[t]
            rows = tracks.get(key)
            if not rows:
                continue
            m = {}
            for r in rows:
                if cur < len(xp):
                    m[r["track"]] = xp[cur]
                cur += 1
            if m:
                out[key] = m
        return out

    def _trait_display(self, key, z, xpmap):
        """Trait name plus a parenthetical of its sub-tracks: 「不法之徒（强盗、窃贼、掠夺者）」.

        Only tracks already entered are listed (XP ≥ the first threshold); a track with no level yet is
        omitted, so a trait holder does not drag a list of unentered tracks behind him. Single-track
        traits get no parentheses, because the track name and the trait name are the same word. Level
        ordinals such as 「一阶」 are never written — the game has no such terminology (only trait
        routes and trait experience), and the year span plus the tier-renamed trait carries the level."""
        if not z:
            return z
        m = (xpmap or {}).get(key) or {}
        rows = (L.trait_track_table().get("tracks") or {}).get(key) or []
        if len(rows) <= 1:
            return z
        bits = []
        for r in rows:
            v = m.get(r["track"])
            if v is None:
                continue
            lv = 0
            for th in (r.get("levels") or []):
                if v >= th:
                    lv += 1
            if lv <= 0:
                continue
            nm = L.loc(self.table, "trait_track_" + str(r["track"])) or ""
            if not nm:
                continue
            bits.append(nm)
        if not bits:
            return z
        return f"{z}（{'、'.join(bits)}）"

    def trait_pairs(self, cid):
        """[(trait key, Chinese name)] for currently held traits (as_of truncation as in `traits`).

        Keys come along because the 「为人」 clause groups traits by the game's `category`."""
        if self.as_of:
            return self._trait_pairs_at(cid)
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        ids = rec.get("traits") or []
        xpmap = self.trait_xp_map(cid)
        out = []
        for t in ids:
            if not isinstance(t, int) or t < 0 or t >= len(self._tl):
                continue
            key = self._tl[t]
            z = _trait_name(self.table, key, xp=(xpmap.get(key) or {}))
            if z:
                out.append((key, z))
        return out

    def _trait_pairs_at(self, cid):
        """Traits held at as_of, as [(key, name)], from the `trait_history` intervals
        (`from ≤ as_of < to`).

        Names take the tier name for that instant's track XP; older caches without XP samples fall back
        to the base name."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        th = rec.get("trait_history") or {}
        ao = cl.date_key(self.as_of)
        xpmap = self.trait_xp_map(cid)
        out = []
        seen = set()
        for key in sorted(th):
            for iv in th[key]:
                frm = iv.get("from")
                to = iv.get("to")
                if frm and cl.date_key(frm) > ao:
                    continue
                if to and cl.date_key(to) <= ao:
                    continue
                z = _trait_name(self.table, key, xp=(xpmap.get(key) or {}))
                if z and key not in seen:
                    seen.add(key)
                    out.append((key, z))
        return out

    def _traits_at(self, cid):
        """Compatibility exit: Chinese names of the traits held at as_of (for older call sites)."""
        return [z for _k, z in self._trait_pairs_at(cid)]

    def trait_groups(self, cid, public=False):
        """Trait grouping for the 「为人」 sentence: [(category word, [trait names], truncated), …].

        Categories come from the game's `common/traits` `category` (tabulated in localization.py)
        rather than from the prompt. A group over `_TRAIT_GROUP_LIMIT` entries keeps the first few and
        appends 「等」, because an unbroken run of a dozen trait names reads as a recitation; the order
        follows `_TRAIT_GROUP_ORDER`. Trait names may carry a sub-track parenthesis. With
        `public=True` fertility traits (`_FERTILITY_TRAITS`) are hidden — a court historian sees
        children around a ruler, not the body's private detail."""
        cats = (L.trait_names().get("categories") or {})
        xpmap = self.trait_xp_map(cid)
        buckets = {}
        for key, z in self.trait_pairs(cid):
            if public and key in _FERTILITY_TRAITS:
                continue
            buckets.setdefault(cats.get(key, ""), []).append(
                self._trait_display(key, z, xpmap))
        out = []
        for cat in list(_TRAIT_GROUP_ORDER) + sorted(
                set(buckets) - set(_TRAIT_GROUP_ORDER)):
            names = buckets.get(cat) or []
            if not names:
                continue
            word = _TRAIT_GROUP_WORDS.get(cat, "")
            if len(names) > _TRAIT_GROUP_LIMIT:
                out.append((word, names[:_TRAIT_GROUP_LIMIT], True))
            else:
                out.append((word, names, False))
        return out

    def traits_sentence(self, cid, public=False):
        """Text of the 「为人」 sentence by category: 「性情野心勃勃、专断；禀赋眉清目秀」; '' with no
        traits.

        Categories without a word are listed directly (mod-defined categories). `public=True` gives the
        public version (fertility traits hidden, see `trait_groups`)."""
        parts = []
        for word, names, truncated in self.trait_groups(cid, public=public):
            body = "、".join(names) + ("等" if truncated else "")
            parts.append(f"{word}{body}" if word else body)
        return "；".join(parts)

    def trait_history_lines(self, cid):
        """Trait history: each entry reads 「<trait>（自X年起获得 / 自X年后消失…）」.

        Truncated at as_of, so intervals gained later are dropped, and intervals present at first sight
        (`first=True`, existing before the data start) are omitted because the trait still appears in the
        「为人」 list. Transient condition traits (pregnancy/illness/injury) are excluded: births are carried
        by the 「添丁进口」 memory, so the history keeps only traits that constitute a record. Dates keep the
        year only, since snapshot diff dates are all 1 January. Disease traits use the game's contemporary
        epidemic name (`epidemics.database[*].name`, e.g. 「平原热」 rather than a static 「伤寒」), preferring
        an epidemic touching the character's realm or county and then the latest starting one, so two bouts
        of one disease in different places do not read as a single sentence."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        th = rec.get("trait_history") or {}
        ao = cl.date_key(self.as_of) if self.as_of else None
        lines = []
        for key in sorted(th):
            if key in _TRANSIENT_TRAITS:
                continue
            z = _trait_name(self.table, key)
            if not z or z == key:
                continue
            spans = []
            for iv in th[key]:
                if ao is not None and iv.get("from") and cl.date_key(iv.get("from")) > ao:
                    continue
                if iv.get("first"):
                    continue  # present at first sight — carries no information
                d_from = self._year_only(iv.get("from"))
                d_to = self._year_only(iv.get("to"))
                # Disease traits use the contemporary epidemic name; the name is swapped only at the
                # first occurrence so one line never mixes two disease names.
                _dyn = ""
                if key in _DISEASE_TRAITS and iv.get("from"):
                    _dyn = _disease_dynamic_name(
                        self, cid, key, _year_of(iv.get("from")))
                if iv.get("from") and not iv.get("to"):
                    spans.append(f"自{d_from}起获得")
                elif iv.get("from") and iv.get("to"):
                    spans.append(f"自{d_from}起获得，自{d_to}后消失")
                elif iv.get("to"):
                    spans.append(f"至{d_to}后消失")
                if _dyn:
                    z = _dyn
            if spans:
                # no parentheses: 「诗人自921年起获得」 rather than 「诗人（自921年起获得）」
                lines.append(z + "；".join(spans))
        # track level-ups: 「不法之徒·强盗（自872年起）」
        lines.extend(self.trait_level_history(cid))
        return lines

    def _trait_base_name(self, key):
        """Base trait name without tier words, used by history lines so they do not mix with the tier
        names of the 「为人」 sentence."""
        mapped = (L.trait_names().get("traits") or {}).get(key)
        for cand in (mapped, f"trait_{key}", key):
            if not cand:
                continue
            v = L.loc(self.table, cand)
            if v and not v.startswith(("$", "[")):
                return v
        return TRAIT_ZH.get(key, "")

    def trait_level_history(self, cid):
        """Track level-up history: 「<trait>·<track>（自X年起，Y年益进）」.

        Diffs the `rec["trait_xp"]` samples: a track crossing its next threshold is recorded once, with
        as_of truncation. Same source as the trait history and likewise year-only, since yearly
        snapshots carry no intra-day detail. Level ordinals such as 「进至N阶」 are never written — the
        game has no such terminology."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        samples = [s for s in (rec.get("trait_xp") or []) if isinstance(s, dict)]
        if not samples:
            return []
        tracks = (L.trait_track_table().get("tracks") or {})
        if not tracks:
            return []
        lv_of = {k: [r.get("levels") or [] for r in rows]
                 for k, rows in tracks.items()}
        ao = cl.date_key(self.as_of) if self.as_of else None
        prev = {}
        out = []
        for s in samples:
            if ao is not None and cl.date_key(str(s.get("from"))) > ao:
                break
            xp = s.get("xp") or []
            cur = 0
            for t in (s.get("traits") or []):
                if not isinstance(t, int) or t < 0 or t >= len(self._tl):
                    continue
                key = self._tl[t]
                rows = tracks.get(key)
                if not rows:
                    continue
                for ri, r in enumerate(rows):
                    if cur >= len(xp):
                        cur += 1
                        continue
                    v = xp[cur]
                    cur += 1
                    lv = 0
                    for th in (lv_of.get(key) or [[]])[ri]:
                        if v >= th:
                            lv += 1
                    if lv > prev.get((key, r["track"]), 0):
                        out.append((key, r["track"], lv, s.get("from")))
                    prev[(key, r["track"])] = lv
        lines = []
        grouped = {}      # (trait, track) -> [(level, from), …], order preserved
        for key, tk, lv, frm in out:
            grouped.setdefault((key, tk), []).append((lv, frm))
        for (key, tk), rows in grouped.items():
            base = self._trait_base_name(key)
            tn = L.loc(self.table, "trait_track_" + str(tk)) or ""
            if not base or not tn:
                continue
            steps = []
            for i, (lv, frm) in enumerate(rows):
                yr = self._year_only(frm)
                # only the entry year is recorded, never a level ordinal such as 「进至一阶」
                steps.append(f"自{yr}起" if i == 0 else f"{yr}益进")
            # A single-track trait's track name equals its trait name (「老练的旅行者·老练的旅行者」),
            # so it is not repeated.
            name = f"{base}·{tn}" if len(tracks.get(key) or []) > 1 else base
            # no parentheses: 「不法之徒·强盗自921年起，924年益进」
            lines.append(name + "，".join(steps))
        return lines

    @staticmethod
    def _year_only(d):
        """Reduce a snapshot date to its year: '871.1.1' → '871年'."""
        if not d:
            return ""
        s = str(d)
        return s.split(".")[0] + "年"

    def government(self, cid, date=None):
        """Government display name, resolved by `date` because government is not constant (a character
        can be feudal for years and administrative afterwards, and reading the last tier would label
        his adventurer or feudal years administrative too).

        '' when nothing supports a name."""
        g = self._character_government(cid, date or self.as_of)
        if not g and int(self.cache.get("schema") or 1) < 2:
            # older caches (schema<2) have no per-tier government history: fall back to the last tier
            rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
            g = (rec.get("landed") or {}).get("government") or ""
        return self._government_zh(g)

    def motto(self):
        """Chinese motto of the player's house ('' when unset)."""
        mot = self.cache.get("house_motto")
        if not mot:
            return ""
        return render_motto(mot, self.table)

    def _office_name(self, cid):
        """Office plus name, e.g. 「交州刺史应偁」 — the office entry point of person_label."""
        return self.person_label(cid, date=self.as_of, style="office")

    def _council_scope(self):
        """(Government, is-empire) for picking council seat words; empire = independent and top
        title ≥ e_."""
        pid = self.cache.get("player_id")
        rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
        gov = (rec.get("landed") or {}).get("government") or ""
        return gov, (self._top_rank_now(pid) >= 5
                     and bool(self._is_independent(pid, self.as_of)))

    def _top_rank_now(self, cid, date=None):
        """Highest tier among the titles held now (or at `date`) (barony=1…empire=5).

        `_primary_title_at` alone would return 0 when the character holds only a noble-family estate or
        a camp (an `x_` title); in the game such a title still counts as barony tier, and the office and
        council variant decisions need a tier. So the highest tier among all titles not yet lost is
        taken, with an `x_` estate or yurt counting as 1, matching the game's barony treatment."""
        if cid is None:
            return 0
        best = 0
        for tid, ivs in (self._hold_intervals(cid, date) or {}).items():
            if not ivs or ivs[-1][1] is not None:
                continue
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            rank = self._TT_RANK.get(key[:2], 0)
            if rank == 0 and key.startswith("x_"):
                rank = 1 if self.title_kind(tid) else 0
            best = max(best, rank)
        return best

    def council_line(self):
        """Council seats with their dynamic office words and holders, e.g.
        「御前会议六席：长史（某人）、司户（某人）…」.

        Resolved from `council_task_manager` + `council_tasks` (a celestial empire uses
        宰相/户部尚书/御史大夫/大将军/礼部尚书; a non-imperial celestial realm 长史/司户/察事/司马/博士;
        feudal 掌玺大臣/财政总管…). The save stores only task ids, so a seat name comes from
        `council_tasks.position` plus the government variant key; when no seat can be resolved the
        result is '' rather than a constant 「御前会议六席」 string."""
        pid = self.cache.get("player_id")
        if pid is None:
            return ""
        rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
        seats = (rec.get("landed") or {}).get("council") or []
        if not seats:
            return ""
        gov, imperial = self._council_scope()
        act = (self.melt.get("council_task_manager") or {}).get("active") or {}
        parts = []
        for sid in seats:
            e = act.get(str(sid)) or {}
            if not isinstance(e, dict):
                continue
            owner = e.get("court_owner")
            if isinstance(owner, int) and owner != pid:
                continue          # someone else's council, including a spouse's seat
            word = L.council_seat_word(self.table, self._council_tasks,
                                       e.get("type") or "", gov, imperial)
            who = e.get("owner")
            nm = self.person_label(who, date=self.as_of, style="brief") if isinstance(who, int) else ""
            # The court-chaplain seat carries a clerical appellation (the game displays
            # 「宫廷司祭佛罗伦萨主教卡利斯托」). For a temporal-theocracy faith or a pagan religion the
            # game delegates the whole seat-name chain to `actual_bishop_title`
            # (`00_council_positions.txt`), and then the seat name *is* the clerical word — so it
            # replaces the seat word and yields 「日本和尚忠盛」 rather than 「宫廷司祭日本和尚忠盛」.
            if (e.get("type") or "") in self._CHAPLAIN_SEAT_TASKS \
                    and isinstance(who, int):
                _ct = self.chaplain_title(who, date=self.as_of)
                if _ct:
                    if self._chaplain_seat_is_bishop_title(e, who):
                        word = ""
                    nm = f"{_ct}{nm}" if nm else _ct
            if word and nm:
                # The office is written directly against the holder's name (「长史延寿」) rather than
                # as a parenthetical apposition, which matches modern Chinese usage
                # (「宰相吴全略」).
                # When the holder's appellation already carries the same office it is written once:
                # the brief form reads 「御史大夫欺诈者崔克勤」, so joining it to the seat word would
                # repeat 「御史大夫」 twice.
                nm2 = nm[len(word):] if nm.startswith(word) else nm
                parts.append(f"{word}{nm2}")
            elif word:
                parts.append(f"{word}虚悬")
            elif nm:
                parts.append(nm)
        if not parts:
            return ""
        return f"御前会议{_count_zh(len(parts))}席：" + "、".join(parts)

    def council_seat_word(self, task_type):
        """One council task → its seat office word (public exit used by regression scripts)."""
        gov, imperial = self._council_scope()
        return L.council_seat_word(self.table, self._council_tasks, task_type,
                                   gov, imperial)

    def _chaplain_seat_is_bishop_title(self, seat, who=None):
        """Whether the game delegates this chaplain seat's *name* to `actual_bishop_title`.

        Criterion: resolve the `name = { first_valid = … }` arm list in `common/council_positions` and
        check whether the first matching arm's desc equals `actual_bishop_title` (the name chain in
        `00_council_positions.txt` and its delegating arm, whose condition is a temporal-theocracy
        faith `doctrine_theocracy_temporal` or a pagan religion `rf_pagan`)."""
        pos = ((self._council_tasks or {}).get("tasks") or {}) \
            .get(seat.get("type") or "") or ""
        if not pos or not self._council_names:
            return False
        liege = seat.get("court_owner")
        if not isinstance(liege, int):
            liege = self.cache.get("player_id")
        if not isinstance(liege, int):
            return False
        scope = self._bishop_scope(liege, who, self.as_of)
        return L.council_name_desc(self._council_names, pos, scope) \
            == "actual_bishop_title"

    # ---- court chaplain (realm priest) clerical appellation ----
    #
    # The game composes the chaplain's appellation as "clerical word + name" (for a Catholic duchy the
    # word is 主教). The word comes from `GetActualBishopTitle` in
    # `common/customizable_localization/00_divinity_custom_loc.txt`, selected by religion group × the
    # liege's highest title tier; the Chinese words live in
    # `localization/simp_chinese/council_l_simp_chinese.yml` under
    # `councillor_court_chaplain_<religion group>_{county,duchy,kingdom,empire}` (Catholic: 伯爵级 =
    # 隶属主教, 公国级 = 主教, 王国级 = 总主教, 帝国级 = 牧首). The place name is the liege's primary
    # title name, which together with the council seat word yields
    # 「宫廷司祭托斯卡纳主教卡利斯托」.
    _CHAPLAIN_SEAT_TASKS = ("task_religious_relations",)
    _CHAPLAIN_WORD_RE = re.compile(
        r"^councillor_court_chaplain_(?P<rel>.+?)_"
        r"(?P<tier>county|duchy|kingdom|empire)(?P<fem>_female)?$")
    # religion group id/tag → prefix used in localization keys (the game mixes both spellings, so the
    # candidates are tried in turn)
    _CHAPLAIN_REL_ALIASES = {
        "christianity_religion": "christian",
        "christianity": "christian",
        "islam_religion": "islam",
        "judaism_religion": "judaism",
        "buddhism": "buddhism_religion",
        "taoism": "taoism_religion",
        "hellenism": "hellenism_religion",
        "paganism_religion": "paganism_religion",
    }

    def _chaplain_words(self):
        """Localization table → {religion group prefix: {tier: (neutral word, female word)}} (built
        once, lazily)."""
        idx = getattr(self, "_chaplain_words_index", None)
        if idx is not None:
            return idx
        idx = {}
        for k, v in (self.table or {}).items():
            if not isinstance(v, str) or not v or "$" in v or "[" in v:
                continue
            m = self._CHAPLAIN_WORD_RE.match(k)
            if not m:
                continue
            rel = m.group("rel")
            tier = m.group("tier")
            slot = idx.setdefault(rel, {}).setdefault(tier, ["", ""])
            slot[1 if m.group("fem") else 0] = v
        self._chaplain_words_index = idx
        return idx

    def _chaplain_word(self, rel_id, rel_tag, tier, female=False):
        """Religion group × liege tier → clerical word (falls back to the `theocrat` entry)."""
        idx = self._chaplain_words()
        cands = []
        for r in (rel_id, rel_tag):
            s = str(r or "")
            if not s:
                continue
            for c in (s, s.replace("_religion", ""),
                      self._CHAPLAIN_REL_ALIASES.get(s, "")):
                if c and c not in cands:
                    cands.append(c)
        cands.append("theocrat")
        for c in cands:
            slot = (idx.get(c) or {}).get(tier)
            if not slot:
                continue
            w = slot[1] if (female and slot[1]) else slot[0]
            if w:
                return w
        return ""

    def _bishop_scope(self, liege, who=None, date=None):
        """Evaluation scope for the bishop arm table and the council seat name chain.

        Holds the slots the game's triggers use: `highest_held_title_tier` (liege tier),
        `culture = { has_cultural_pillar = … }` (cultural pillars), `government_has_flag`,
        `religion = religion:x` / `faith.religion = faith:y.religion` (religion keys),
        `religion = { is_in_family = rf_z }` (religion family), `has_doctrine`, and the chaplain's sex
        (`NOT = { cp:councillor_court_chaplain ?= { is_female = yes } }`)."""
        d = date or self.as_of
        scope = {"tier": self._top_rank_now(liege, d),
                 "chaplain_female": (bool(self._is_female(who))
                                     if who is not None else False)}
        rec = (self.cache.get("characters") or {}).get(str(liege)) or {}
        # `culture = { has_cultural_pillar = X }` may name any of heritage_/language_/ethos_/
        # tradition_ (the game's Japanese arm uses `language_japonic`), so all four pillar kinds are
        # merged into `pillars`; heritage stays separate for older callers.
        ce = self._culture_entry(liege, d)
        heritage = str(ce.get("heritage") or "")
        pillars = set()
        for _v in (ce.get("heritage"), ce.get("language"), ce.get("ethos")):
            if isinstance(_v, str) and _v:
                pillars.add(_v)
        for _t in (ce.get("traditions") or []):
            if isinstance(_t, str) and _t:
                pillars.add(_t)
        scope["heritage"] = heritage
        scope["pillars"] = pillars
        scope["gov_flag"] = L.government_prefix(
            (rec.get("landed") or {}).get("government") or "")
        maps = self._bishop_titles or {}
        faiths_map = maps.get("faiths") or {}
        rel = self.melt.get("religion") or {}
        fid = self._faith_id(liege, d)
        fe = (rel.get("faiths") or {}).get(str(fid)) or {}
        re_ = (rel.get("religions") or {}).get(str(fe.get("religion"))) or {}
        fkey = str(fe.get("key") or fe.get("tag") or "")
        rkey = str(re_.get("religion_type") or re_.get("tag") or "")
        if fkey and fkey in faiths_map:
            # the faith key is folded into its religion key first, matching the game's faith.religion
            rkey = faiths_map[fkey]
        scope["religion"] = rkey
        scope["religion_family"] = str((maps.get("religions") or {}).get(rkey)
                                       or re_.get("family") or "")
        try:
            scope["doctrines"] = list(self.faith_doctrines(liege) or [])
        except Exception:
            scope["doctrines"] = []
        return scope

    def _held_title_scope_entries(self, cid, date=None):
        """Titles the character still holds at `date`, as a small table for condition evaluation.

        Each entry is {tier, clerical_region, clerical_elector, landless, key}, serving the two kinds
        of leaf: `any_held_title = { tier = tier_duchy has_clerical_region = yes }` and
        `has_title = title:X`. Holding intervals are filtered as in `_primary_title_at` (gained on or
        before `date` and not lost before it)."""
        if cid is None:
            return []
        ao = cl.date_key(date) if date else None
        out = []
        for tid, ivs in (self._hold_intervals(cid, date) or {}).items():
            held = None
            for (g, l, _lt) in ivs:
                if ao is not None and g and cl.date_key(g) > ao:
                    continue
                if l and ao is not None and cl.date_key(l) <= ao:
                    continue
                held = (g, l)
            if held is None:
                continue
            t = self._lt.get(str(tid)) or {}
            out.append({
                "tier": self._scope_tier(tid),
                "clerical_region": bool(t.get("clerical_region")),
                "clerical_elector": t.get("clerical_elector"),
                "landless": bool(t.get("landless")),
                "key": str(t.get("key") or ""),
            })
        return out

    def _scope_tier(self, tid):
        """Title tier inside the arm-table scope: an ecclesiastical province (clerical region) counts as
        duchy tier.

        Game basis: the `clerical_region_duchy_*` family in `common/flavorization/20_pam_flavorization.txt`
        declares `tier = duchy` with `special_title = clerical_region`, while the save holds those titles as
        landless theocratic titles with keys prefixed `x_script_*` / `d_et_*`, so ranking by prefix would
        yield 0. This affects the arm-table scope only, leaving `_eff_rank` and primary-title selection alone
        (an ecclesiastical province never competes for a primary title)."""
        t = self._lt.get(str(tid)) or {}
        if t.get("clerical_region"):
            return 3
        return self._eff_rank(tid)

    def _theocracy_scope(self, cid, tid=None, date=None):
        """Evaluation scope for the theocratic office arm table, matching the trigger slots of
        `GetActualDukeTheocracyTitle` / `GetActualCountTheocracyTitle`: sex, faith key, religion key and
        family, rite and its doctrines, the doctrine set, held titles (tier / province / cardinal), and this
        title's own tier and province membership.

        `clerical_elector_title` is a special game scope (the title where a cardinal elector sits), satisfied
        by holding any title with a non-empty `clerical_elector` (the Cardinal Titles family in
        `07_pam_ecclesiastical_titles.txt`); its first available arm is 「枢机」."""
        s = {}
        if cid is None:
            return s
        d = date or self.as_of
        s["female"] = bool(self._is_female(cid))
        ftag, rtag = self._faith_tags(cid, d)
        s["faith"] = ftag
        s["religion"] = rtag
        fe = cl.faith_entry(self.melt, self._faith_id(cid, d)) or {}
        re_ = ((self.melt.get("religion") or {}).get("religions") or {}) \
            .get(str(fe.get("religion"))) or {}
        s["religion_family"] = str(re_.get("family") or
                                   (self._bishop_titles or {}).get("religions", {})
                                   .get(rtag) or "")
        rid = self._rite_id(cid, d)
        s["rite"] = self._rite_type(cid, d)
        try:
            s["rite_doctrines"] = list(cl.rite_data(self.melt, rid).get("doctrine")
                                       or [])
        except Exception:
            s["rite_doctrines"] = []
        try:
            s["doctrines"] = list(self.faith_doctrines(cid) or [])
        except Exception:
            s["doctrines"] = []
        titles = self._held_title_scope_entries(cid, d)
        s["held_titles"] = titles
        s["title_keys"] = [t["key"] for t in titles if t["key"]]
        s["clerical_elector_title"] = any(t["clerical_elector"] for t in titles)
        rank = self._scope_tier(tid) if tid is not None else 0
        s["tier"] = rank
        s["clerical_region"] = any(t["clerical_region"] for t in titles
                                   if rank and t["tier"] == rank)
        return s

    def _custom_loc_key(self, name, cid=None, tid=None, date=None, scope=None):
        """Custom-localization block name → localization key of the first matching arm ('' when the
        table is missing or nothing matches).

        `GetActualBishopTitle` uses the existing bishop arm table (`L.bishop_titles`, shared with the
        court chaplain); the rest (duke/count theocratic office words) use the newer table."""
        if not name:
            return ""
        sc = scope if scope is not None else self._theocracy_scope(cid, tid, date)
        if name == "GetActualBishopTitle":
            return L.pick_bishop_title(self._bishop_titles, sc)
        return L.pick_custom_loc(self._theocracy_titles, name, sc)

    def _loc_or_custom_word(self, key, cid=None, tid=None, date=None, scope=None):
        """Localization key → Chinese word; when the value is `[CHARACTER.Custom('X')]` the arm table is
        evaluated first.

        The game delegates Christian theocratic office words wholly to a custom localization
        (`duke_theocracy_male_christianity_religion =
        "[CHARACTER.Custom('GetActualDukeTheocracyTitle')]"`), which `localization.loc` strips as a whole
        `[...]` segment, leaving the generic 「公爵」. This resolves the delegation. Unresolved strings
        starting with `$` or `[` are filtered out."""
        raw = ""
        try:
            raw = str((self.table or {}).get(key) or "")
        except Exception:
            raw = ""
        m = _CUSTOM_REF_RE.match(raw.strip())
        if not m:
            v = L.loc(self.table, key)
            return v if v and not v.startswith(("$", "[")) else ""
        k2 = self._custom_loc_key(m.group(1), cid, tid, date, scope=scope)
        if not k2:
            return ""
        v = L.loc(self.table, k2)
        return v if v and not v.startswith(("$", "[")) else ""

    def chaplain_title(self, cid, date=None):
        """Clerical appellation of a court chaplain, e.g. 「托斯卡纳主教」 or 「日本和尚」; '' when unknown.

        Criterion: `cid` holds the court-chaplain seat (`council_task_manager.active[*].type ==
        task_religious_relations`) of some liege, whose primary title name supplies the place and whose
        religion group supplies the word. The word comes from the game's order-preserving arm table
        `GetActualBishopTitle` (`localization.bishop_titles`), first match wins; when that table is missing
        or matches nothing, the older "religion group × tier" index still supplies a word."""
        if cid is None or not self.melt:
            return ""
        act = (self.melt.get("council_task_manager") or {}).get("active") or {}
        liege = None
        for e in act.values():
            if not isinstance(e, dict):
                continue
            if (e.get("type") or "") not in self._CHAPLAIN_SEAT_TASKS:
                continue
            if e.get("owner") == cid:
                liege = e.get("court_owner")
                break
        if not isinstance(liege, int):
            return ""
        d = date or self.as_of
        _tier, tid = self._primary_title_at(liege, d)
        tier = _tier or self._RANK_TIER.get(5)
        place = ""
        if tid is not None:
            place = self._name_at_date(tid, d) or self.title_base_name(tid)
        if not place:
            return ""
        word = ""
        # ① the game's order-preserving arm table (first match wins)
        _k = L.pick_bishop_title(self._bishop_titles,
                                 self._bishop_scope(liege, cid, d))
        if _k:
            v = L.loc(self.table, _k)
            if v and not v.startswith("$") and not v.startswith("["):
                word = v
        # ② fallback: the religion group × tier index
        if not word:
            fid = self._faith_id(liege, d)
            rel = self.melt.get("religion") or {}
            fe = (rel.get("faiths") or {}).get(str(fid)) or {}
            re_ = (rel.get("religions") or {}).get(str(fe.get("religion"))) or {}
            rel_id = re_.get("religion_type") or re_.get("tag") or ""
            rel_tag = re_.get("tag") or ""
            word = self._chaplain_word(rel_id, rel_tag, tier,
                                       female=self._is_female(cid))
        if not word:
            return ""
        return f"{place}{word}"

    def court_position_scope(self, cid=None):
        """Evaluation scope for court position variants: the employer's government, independence, top
        tier and cultural heritage.

        Those are the only triggers the court_position_asset variants use (the variants carrying a
        localization_key rely on government_has_flag, is_independent_ruler, highest_held_title_tier and
        has_cultural_pillar)."""
        pid = self.cache.get("player_id") if cid is None else cid
        rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
        gov = (rec.get("landed") or {}).get("government") or ""
        rank = self._top_rank_now(pid)
        cul = rec.get("culture")
        if cul is None:
            cul = (self._chars.get(str(pid)) or {}).get("culture")
        heritage = ""
        if cul is not None:
            e = ((self.melt.get("culture_manager") or {}).get("cultures") or {}) \
                .get(str(cul))
            if isinstance(e, dict):
                heritage = str(e.get("heritage") or "")
        return {"gov_flag": L.government_prefix(gov), "tier": rank,
                "independent": bool(self._is_independent(pid, self.as_of)),
                "heritage": heritage, "culture": heritage or None}

    def court_position_word(self, type_key, cid=None):
        """Court position type key → the game's display name.

        The save stores the type key (`court_physician_court_position`) while the game picks a
        `localization_key` variant by the employer's government, independence, tier and cultural
        heritage (a non-imperial celestial realm gives 医学博士). Falls back to the type key's default
        localization when no variant applies."""
        if not type_key:
            return ""
        word = L.pick_court_position(self.table, self._cp_variants, type_key,
                                     self.court_position_scope(cid))
        if word:
            return word
        v = L.loc(self.table, type_key) or ""
        return "" if (not v or v == type_key) else v

    def court_positions_lines(self):
        """Retainers holding positions in the player's camp or court: (latest lines, change lines).

        Semantics: `cache.court_positions` holds only entries with employer == the player, i.e. posts in
        the player's camp or court filled by **retainers**, never the player's own offices (his own go
        through held titles and office words). Latest lines aggregate per holder with the holder as
        subject (「仲宣任丑角（自…任），又任盗贼大师（自…任）」), so the model cannot read a roster as the
        subject's own career. Change lines record a post changing hands between snapshots (the subject is
        already the holder). Truncated at as_of: only the last snapshot before as_of is used."""
        pid = self.cache.get("player_id")
        if pid is None:
            return [], []
        hist = self.cache.get("court_positions") or []
        if not hist:
            return [], []
        if self.as_of:
            hist = [h for h in hist
                    if cl.date_key(h.get("date")) <= cl.date_key(self.as_of)]
        if not hist:
            return [], []
        latest = hist[-1].get("positions") or []
        holder_roles = {}  # holder name -> [(position word, hire date)], in roster order
        order = []
        for p in latest:
            # the display name comes from the game's variant resolution (私人医生 → 医学博士)
            zh = self.court_position_word(p.get("type")) or ""
            if not zh or zh == p.get("type"):
                continue
            emp = p.get("employee")
            nm = self._office_name(emp) if emp is not None else ""
            if not nm:
                continue
            hire = self.date(p.get("hire_date")) if p.get("hire_date") else ""
            roles = holder_roles.setdefault(nm, [])
            if not roles:
                order.append(nm)
            roles.append((zh, hire))
        latest_lines = []
        for nm in order:
            roles = holder_roles[nm]
            # The holder is the subject, and several posts of one holder are chained with 「又任」 so
            # the line cannot read as a 「职位：人名」 career list, which would lead the model to
            # attribute the posts to the subject himself.
            # Appointment dates are in-clause adverbials (「自X起任…」) rather than parentheticals.
            zh0, hire0 = roles[0]
            s = f"{nm}自{hire0}起任{zh0}" if hire0 else f"{nm}任{zh0}"
            for zh, hire in roles[1:]:
                s += f"，{hire}起又任{zh}" if hire else f"，又任{zh}"
            latest_lines.append(s)
        # appointment changes: set difference of (type, employee) between adjacent snapshots
        change_lines = []
        prev = set()
        for h in hist:
            cur = {(p.get("type"), p.get("employee"))
                   for p in h.get("positions") or [] if p.get("type")}
            if prev and cur != prev:
                for t, emp in sorted(prev - cur):
                    zh = self.court_position_word(t) or ""
                    if not zh or zh == t:
                        continue
                    nm = self._office_name(emp) if emp is not None else "空缺"
                    if nm:
                        change_lines.append(f"{self.date(h.get('date'))}：{nm}卸任{zh}")
                for t, emp in sorted(cur - prev):
                    zh = self.court_position_word(t) or ""
                    if not zh or zh == t:
                        continue
                    nm = self._office_name(emp) if emp is not None else "空缺"
                    if nm:
                        change_lines.append(f"{self.date(h.get('date'))}：{nm}出任{zh}")
            prev = cur
        return latest_lines, change_lines

    def court_office_lines(self):
        """Offices **granted to** the subject, where he is the employee and someone else the employer
        (a 太师 or a ministry post).

        The opposite direction of `court_positions_lines`, which covers retainers in his own court.
        Per-tier records are aggregated into tenures: one latest line per (office, employer) pair carrying
        every appointment date, plus one change line per appointment or loss. The loss instant is inferred
        from the snapshot diff, a "by this time at the latest" convention shared with trait_history."""
        pid = self.cache.get("player_id")
        if pid is None:
            return [], []
        hist = self.cache.get("court_office_history") or []
        if not hist:
            return [], []
        if self.as_of:
            hist = [h for h in hist
                    if cl.date_key(h.get("date")) <= cl.date_key(self.as_of)]
        if not hist:
            return [], []
        W = _style.FACT_WORDING
        # per-tier office sets → tenure spans [(hire, loss snapshot or None, office)]
        stints = []          # [(hire_date, loss_date|None, office_dict)]
        open_run = {}        # (type, employer) -> office_dict
        for h in hist:
            cur = {(e.get("type"), e.get("employer")): e
                   for e in (h.get("offices") or [])}
            for key, office in cur.items():
                if key not in open_run:
                    open_run[key] = dict(office, _start=office.get("hire_date")
                                         or h.get("date"))
            for key in list(open_run):
                if key not in cur:
                    o = open_run.pop(key)
                    stints.append((o.pop("_start"), h.get("date"), o))
        for key, o in open_run.items():
            stints.append((o.pop("_start"), None, o))
        if not stints:
            return [], []
        stints.sort(key=lambda x: cl.date_key(x[0]))
        # latest lines: several tenures of one (position, employer) merge into one line (「两度受任」)
        latest_lines, change_lines = [], []
        by_office = {}
        order = []
        for hire, loss, o in stints:
            word = self.court_position_word(o.get("type"), cid=o.get("employer")) or ""
            if not word or word == o.get("type"):
                continue
            emp = o.get("employer")
            elab = self.person_label(emp, date=hire, style="brief") \
                if isinstance(emp, int) else ""
            key = (word, elab)
            item = by_office.setdefault(key, {"hires": [], "last_loss": None})
            if item is None:
                continue
            if key not in order:
                order.append(key)
            if hire:
                item["hires"].append(self.date(hire))
            if loss:
                item["last_loss"] = self._year_only(loss)
            if hire:
                change_lines.append(W["office_change_gain"].format(
                    date=self.date(hire), employer=elab or "朝廷",
                    gverb=self.grant_verb(emp), word=word))
            if loss:
                change_lines.append(W["office_change_lose"].format(
                    date=self.date(loss), word=word))
        for key in order:
            word, elab = key
            item = by_office[key]
            hires = item["hires"]
            if not hires:
                continue
            held = W["office_held"].format(employer=elab or "朝廷", word=word)
            if len(hires) == 1:
                # no parentheses: 「自869年6月28日起任唐皇帝李漼之太师」
                held = W["office_held_since"].format(
                    date=hires[0], employer=elab or "朝廷", word=word)
            else:
                held = W["office_held_multi"].format(
                    n=_count_zh(len(hires)), employer=elab or "朝廷", word=word,
                    dates="、".join(hires))
            if item["last_loss"]:
                held += W["office_lost_late"].format(year=item["last_loss"])
            latest_lines.append(held)
        # change lines are deduplicated and sorted by date
        seen = set()
        out_changes = []
        for ln in sorted(change_lines):
            if ln in seen:
                continue
            seen.add(ln)
            out_changes.append(ln)
        return latest_lines, out_changes

    def estate_place_name(self, cid=None):
        """Province name of the noble-family estate's seat: cached `landed.domicile_province` → province
        name (10282 → 宾州), falling back to the province holding the estate title's `capital`. '' when
        unknown.

        This is a different place from the 「治所」 (the office seat, `realm_capital`): the family seat
        sits in the ancestral province."""
        pid = self.cache.get("player_id") if cid is None else cid
        rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
        ld = rec.get("landed") or {}
        prov = ld.get("domicile_province")
        if not isinstance(prov, int):
            for t in (ld.get("domain") or []):
                if self._is_estate_title(t):
                    cap = (self._lt.get(str(t)) or {}).get("capital")
                    if isinstance(cap, int):
                        prov = cap
                    break
        if not isinstance(prov, int):
            return ""
        tid = self.county_at_province(prov)
        if tid is None and \
                ((self._lt.get(str(prov)) or {}).get("key") or "").startswith("c_"):
            tid = prov
        if tid is None:
            return ""
        nm = self._name_at_date(tid, self.as_of) or self.title_base_name(tid)
        return nm if nm and not nm.startswith(("c_", "b_")) else ""

    def grant_verb(self, granter_cid, date=None):
        """Verb for granting a title or office, taken from the **granter's** government (celestial or
        administrative = 任命, feudal = 册封, tribal or clan = 授予…); 「任命」 when unknown.

        `date` pins the government at that instant."""
        if not isinstance(granter_cid, int):
            return _style.TITLE_GRANT_VERB_FALLBACK
        gov = self._character_government(granter_cid, date)
        if not gov:
            rec = (self.cache.get("characters") or {}).get(str(granter_cid)) or {}
            gov = (rec.get("landed") or {}).get("government") or ""
        if not gov:
            gov = ((self._chars.get(str(granter_cid)) or {}).get("landed_data") or {}) \
                .get("government") or ""
        if not gov:
            # granter dead or landless: fall back to the government of his highest title
            ftid = self._former_high_title(granter_cid, date) \
                or self._primary_title_at(granter_cid, as_of=date)[1]
            if ftid is not None:
                gov = self._title_government(ftid, date)
        key = L.government_prefix(gov) if gov else ""
        return _style.TITLE_GRANT_VERBS.get(
            key, _style.TITLE_GRANT_VERB_FALLBACK)

    def grant_actor(self, cid, tid, date=None):
        """The **granter** of a title or office: holder of the title's `de_facto_liege` at `date`,
        walking up the chain while the holder is the character himself or nobody. None when unknown."""
        liege = (self._lt.get(str(tid)) or {}).get("de_facto_liege")
        seen = set()
        while liege is not None and str(liege) not in seen:
            seen.add(str(liege))
            holder = self.holder_at(int(liege), date)
            if isinstance(holder, int) and holder != int(cid):
                if self.name_or(holder, ""):
                    return holder
                return None
            liege = (self._lt.get(str(liege)) or {}).get("de_facto_liege")
        return None

    def revoke_actor(self, cid, tid, date=None, reason=""):
        """The **revoker/usurper** of a title: for `usurped` the new holder who took it, for `revoked`
        the liege of the time (holder of `de_facto_liege`). '' when unknown.

        The return value is an appellation string (through `event_name`, bare name for the subject)
        meant to be embedded in a sentence, not an id."""
        if tid is None:
            return ""
        if reason == "usurped":
            new_holder = self._next_holder(tid, date, exclude=cid)
            if isinstance(new_holder, int) and new_holder != int(cid):
                return self.event_name(new_holder, date=date)
            return ""
        actor = self.grant_actor(cid, tid, date)
        return self.event_name(actor, date=date) if actor else ""

    def _next_holder(self, tid, date=None, exclude=None):
        """First holder of the title after `date` (from the title history sequence) — identifies a
        usurper."""
        seq = self._title_seqs.get(int(tid)) or []
        dk = cl.date_key(date) if date else None
        for d, ev in seq:
            if dk is not None and cl.date_key(d) <= dk:
                continue
            entries = ev if isinstance(ev, list) else [ev]
            for e in entries:
                h = e.get("holder") if isinstance(e, dict) else e
                if isinstance(h, int) and h != exclude:
                    return h
        return None

    def title_office_text(self, cid, tid, date=None):
        """Office-style title name (place name + office word), e.g. 衢州刺史 — used by title gain/loss
        sentences.

        A barony or camp name, or a missing office word, returns '' and the caller falls back to the
        title display name."""
        if tid is None:
            return ""
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        rank = self._TT_RANK.get(key[:2], 0)
        if rank < 2:            # baronies (1) and camp names (0) get no office-style name
            return ""
        tier = self._RANK_TIER.get(rank)
        base = self._name_at_date(tid, date or self.as_of) or self.title_base_name(tid)
        if not base or not tier:
            return ""
        _indep = self._is_independent(cid, date)
        word = self._office_word(tier, self._gov_for_word(cid, tid, date),
                                 independent=bool(_indep) if _indep is not None else True,
                                 female=self._is_female(cid), tid=tid, cid=cid,
                                 date=date)
        return f"{base}{word}" if word else base

    # ---- culture name order / style ----

    def name_order(self, cid):
        """Name-order convention of the character's culture ('' = Western; DYNASTY_ALWAYS_FIRST /
        JAPANESE = family name first).

        Uses the same decision chain as `cl.display_name` (`cl.resolved_name_order`: own culture →
        paternal kin → dynasty template → maternal side or spouse). Reading only the cached `culture`
        field silently fell back to Western whenever the field was absent, contradicting the
        finished-text side."""
        return cl.resolved_name_order(self.cache, cid, melt=self.melt,
                                      chars=self._chars, memo=self._tpl_memo,
                                      date=self.as_of) or ""

    def is_eastern_culture(self, cid):
        """Eastern culture (family name first)? An unknown culture counts as False, the conservative
        fallback to Western/unknown."""
        return self.name_order(cid) in cl.EASTERN_NAME_ORDERS

    def is_custom_start(self, cid):
        """Whether the character is a "custom origin, no pedigree" character.

        Hit = listed in `ruler_designer_characters` (a player-designed character) **or** a save with no
        father/mother record but a scripted-start flag (landless adventurer etc.). For such a character
        the chronicle opens by telling when and where he started and how he rose (see
        `style.PROMPTS["custom_start_note"]`)."""
        return int(cid) in self._custom_starts

    def is_administrative(self, cid):
        """Administrative government? Based on cached `landed.government`."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        return (rec.get("landed") or {}).get("government") == "administrative_government"

    def is_landless(self, cid):
        """Landless adventurer?"""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        return (rec.get("landed") or {}).get("government") == "landless_adventurer_government"

    def emperor_of(self, cid):
        """Whether the character is an eastern or Chinese emperor, used for the daughter/sister test:
        returns (is_emperor, emperor_title), where is_emperor means he currently holds an h_/e_ empire
        tier title."""
        for h in reversed(self.cache.get("realm_history") or []):
            for tid, holder in (h.get("holders") or {}).items():
                if holder != cid:
                    continue
                key = (self._lt.get(str(tid)) or {}).get("key") or ""
                if key.startswith(("h_", "e_")):
                    return True, self.title(tid)
        return False, ""

    def east_empire_keys(self):
        """Empire keys of the eastern states: China (h_china) plus the East Asian empires (Japan, Goryeo,
        Vietnam and others)."""
        return {"h_china", "e_japan", "e_goryeo", "e_viet", "e_great_liao",
                "e_jin", "e_great_yuan", "e_mongol_empire", "e_kara_khitai",
                "e_zhongyuan", "e_yongliang", "e_jingyang", "e_liangyi",
                "e_lingnan", "e_andong", "e_amur", "e_goryeo"}

    def de_jure_top_key(self, county_tid):
        """County title → walk `de_jure_liege` up to the top empire and return that title key."""
        cur = str(county_tid)
        seen = set()
        top_key = ""
        while cur and cur not in seen:
            seen.add(cur)
            t = self._lt.get(cur) or {}
            if not t:
                break
            k = t.get("key") or ""
            if k:
                top_key = k
            dj = t.get("de_jure_liege")
            cur = str(dj) if dj is not None else None
        return top_key

    def player_top_empire_key(self):
        """De jure top empire key of the player's whereabouts: the player's location → county, or the
        camp's `capital`, then the de jure chain."""
        pid = self.cache.get("player_id")
        if pid is None:
            return ""
        prov = self.character_location_province(pid)
        county = self.county_at_province(prov)
        if county is None:
            rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
            camp = (rec.get("landed") or {}).get("domain") or [None]
            if camp[0] is not None:
                t = self._lt.get(str(camp[0])) or {}
                county = t.get("capital")
        if county is None:
            return ""
        return self.de_jure_top_key(county)

    def bio_style(self):
        """Biography style: 'east' (Chinese annalistic form) when the de jure empire of the player's
        location is eastern, else 'west' (Plutarchan)."""
        top = self.player_top_empire_key()
        if top in self.east_empire_keys():
            return "east"
        return "west"

    # ---- dates ----
    def date(self, d):
        return llm.fmt_cn_date(d)

    # ---- title chain / camp ----
    def liege_chain(self, tid):
        """Walk `de_facto_liege` from tid up to the top: [(title_id, holder_id)]."""
        chain = []
        seen = set()
        cur = str(tid)
        while cur and cur not in seen:
            seen.add(cur)
            t = self._lt.get(cur) or {}
            if not t:
                break
            chain.append((int(cur), t.get("holder")))
            liege = t.get("de_facto_liege")
            cur = str(liege) if liege is not None else None
        return chain

    def _prov_entry(self, province):
        """Province map entry: {"county": c_ key, "barony": b_ key} (older caches may hold a bare string)."""
        if province is None:
            return {}
        v = self.provmap.get(int(province))
        if isinstance(v, dict):
            return v
        if isinstance(v, str) and v:
            return {"county": v, "barony": ""}
        return {}

    def county_at_province(self, province):
        """Province id → county title id through the province map; None when unknown."""
        key = self._prov_entry(province).get("county") or ""
        if not key:
            return None
        return self.title_by_key(key)

    def barony_at_province(self, province):
        """Province id → barony (b_) title id, used to annotate a victim's location; None when unknown."""
        key = self._prov_entry(province).get("barony") or ""
        if not key:
            return None
        return self.title_by_key(key)

    def character_location_province(self, cid):
        c = self._chars.get(str(cid)) or {}
        loc = (c.get("alive_data") or {}).get("location") or {}
        return loc.get("location") if isinstance(loc, dict) else loc

    def station_place(self, cid, date=None):
        """Title name of the place the character was at on a date (the 「在XX」 of a feud sentence).

        Evidence exists only for the player of each save (`cache["player_locations"]` is the per-tier
        station track; the save holds no location history for other characters): the latest point not
        later than `date` → province → county → title name. '' when there is no track or no mapping, and
        the caller then drops the 「在XX，」 clause."""
        pid = self.cache.get("player_id")
        if pid is None or cid is None or int(cid) != int(pid):
            return ""
        lim = cl.date_key(str(date)) if date else None
        best = None
        for loc in (self.cache.get("player_locations") or []):
            d = loc.get("date")
            if not d:
                continue
            if lim is not None and cl.date_key(str(d)) > lim:
                continue
            if best is None or cl.date_key(str(d)) >= cl.date_key(str(best.get("date") or "")):
                best = loc
        if best is None:
            return ""
        county = self.county_at_province(best.get("province"))
        if county is None:
            return ""
        return self.title(county) or ""

    def _capital_province_at(self, date=None):
        """Province id of the subject's capital at `date` (None when unknown).

        The capital **moves**, while `cache.landed.realm_capital` holds only the last tier's value, so the
        per-tier latched `capital_history` is read (see cache_lib), with the last tier as fallback for
        older caches. Resolved title id → key → reverse `provmap` lookup."""
        ch = self.cache.get("capital_history") or []
        pid = self.cache.get("player_id")
        want = None
        if ch and date:
            dk = cl.date_key(str(date))
            for pt in ch:
                d = pt.get("date")
                if d and cl.date_key(str(d)) <= dk:
                    want = pt.get("title")
                elif d:
                    break
        if want is None:
            rec = (self.cache.get("characters") or {}).get(str(pid)) or {}
            want = (rec.get("landed") or {}).get("realm_capital")
        if want is None:
            return None
        key = (self._lt.get(str(want)) or {}).get("key") or ""
        prov = self._prov_inv().get(key)
        if isinstance(prov, int):
            return prov
        # when the title is gone (destroyed or re-id'd), fall back to that entry's `capital` (its county
        # title) and look that up instead
        cap = (self._lt.get(str(want)) or {}).get("capital")
        key2 = ((self._lt.get(str(cap)) or {}).get("key")
                if isinstance(cap, int) else "")
        prov = self._prov_inv().get(key2)
        return prov if isinstance(prov, int) else None

    def capital_place_at(self, date=None):
        """Place name of the subject's capital at that time (noble holding or county name; '' when
        unknown)."""
        prov = self._capital_province_at(date)
        if prov is None:
            return ""
        bid = self.barony_at_province(prov)
        if bid is not None:
            nm = self.title_base_name(bid)
            if nm and not nm.startswith("b_"):
                return nm
        cid2 = self.county_at_province(prov)
        if cid2 is not None:
            nm = self.title_base_name(cid2)
            if nm and not nm.startswith("c_"):
                return nm
        return ""

    @staticmethod
    def _executed_by(rec, pid):
        """Whether the character was **executed** by pid (the save stores only `death_execution`)."""
        d = (rec or {}).get("death") or {}
        if d.get("killer") != pid:
            return False
        return str(d.get("reason") or "") in _PRISON_EXEC_REASONS

    @staticmethod
    def _iv_covers(iv, ak):
        """Whether the holding interval (gain, loss, why) covers the date scalar ak."""
        gain = iv[0] if iv else None
        loss = iv[1] if iv and len(iv) > 1 else None
        if not gain:
            return False
        if cl.date_key(str(gain)) > ak:
            return False
        if loss and cl.date_key(str(loss)) < ak:
            return False
        return True

    def _prov_inv(self):
        """Reverse index title key → province (built once, lazily; about 10k entries)."""
        if getattr(self, "_prov_invmap", None) is None:
            inv = {}
            for prov, v in (self.provmap or {}).items():
                if isinstance(v, dict):
                    for k in ("county", "barony"):
                        key = v.get(k)
                        if key and key not in inv:
                            inv[key] = int(prov)
                elif isinstance(v, str) and v:
                    inv.setdefault(v, int(prov))
            self._prov_invmap = inv
        return self._prov_invmap

    def _primary_landed_at(self, cid, date=None):
        """Primary landed title id of a character at `date` (None when unknown).

        Same convention as `_primary_title_at` (a barony never counts as a primary title; at equal tier
        the earliest gain wins), with two tightenings:
          · titles lost that very day still count — an executed man holds until his death day, which ends
            the holding, and accepting only open intervals would leave him with no title at all;
          · noble-family estates (`_nf_`) and camps/yurts (rank 0) are excluded.
        `admin_title_noise` reuses it to obtain the highest title tier."""
        anchor = date or self.as_of
        if not anchor:
            return None
        try:
            cid = int(cid)
        except (TypeError, ValueError):
            return None
        ak = cl.date_key(str(anchor))
        best = None      # (rank, gain_key, tid)
        for tid, ivs in (self._hold_intervals(cid, anchor) or {}).items():
            key = (self._lt.get(str(tid)) or {}).get("key") or ""
            if not key or self._is_estate_title(tid):
                continue
            rank = self._TT_RANK.get(key[:2], 0)
            if rank <= 1:      # a barony is only a place name; camps and yurts (x_, rank 0) are no seat
                continue
            for iv in (ivs or []):
                if not self._iv_covers(iv, ak):
                    continue
                cur = (rank, cl.date_key(str(iv[0])), tid)
                if best is None or cur[:2] > best[:2]:
                    best = cur
        return best[2] if best else None

    def _celestial_like_at(self, cid, date=None):
        """Whether the character runs a celestial-like or administrative government that day (offices
        rotate and titles come through selection)."""
        gov = self._character_government(cid, date) or ""
        return gov in self._CELESTIAL_LIKE_GOVS

    def admin_title_noise(self, tid, date=None, pid=None):
        """Whether this title is **administrative appointment churn** that day (kept out of the chronicle).

        Under a celestial or administrative government, gains and losses of titles **below the subject's
        primary title** (appointment, succession, resignation, revocation, usurpation, transfer) are not
        part of his record: such titles pass by selection, and the subject only keeps one when nobody else
        qualifies. The primary title itself still appears (an appointment as emperor of Qin, say), and
        feudal fiefs under inheritance are untouched."""
        if tid is None:
            return False
        pid = self.cache.get("player_id") if pid is None else pid
        if pid is None or not self._celestial_like_at(pid, date):
            return False
        top_tid = self._primary_landed_at(pid, date)
        if top_tid is None:
            return False
        top_key = (self._lt.get(str(top_tid)) or {}).get("key") or ""
        top_rank = self._TT_RANK.get(top_key[:2], 0)
        key = (self._lt.get(str(tid)) or {}).get("key") or ""
        if not key:
            return False
        return self._TT_RANK.get(key[:2], 0) < top_rank

    def victim_place(self, cid):
        """Where the victim was: the nearest known barony name around his death.

        Lookup: ① still alive in the era's melt → `alive_data.location`; ② the cached death record's
        `location_province` (copied from `last_location` when the death was written); ③ the cached
        `last_location`. '' when nothing resolves, and the caller drops the place note.

        Anyone executed by the subject counts as being at the subject's capital of that time, since the
        execution happened there while the save records assorted execution sites; the capital place comes
        from `capital_history` for that tier, as the capital itself moves."""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        d = rec.get("death") or {}
        if self._executed_by(rec, self.cache.get("player_id")):
            nm = self.capital_place_at(d.get("date"))
            if nm:
                return nm
        loc = self.character_location_province(cid)
        if loc is None:
            loc = d.get("location_province")
        if loc is None:
            # Cross-campaign cache fallback: another cache from the same campaign may be the only one
            # recording this person's final whereabouts. Priority: a `location_province` copied at death
            # (most accurate) from any cache in the campaign, else the latest-dated `last_location`
            # rather than the first one found.
            best_dk = None
            for src in [self.cache] + list((self.campaign or {}).values()):
                r = ((src or {}).get("characters") or {}).get(str(cid)) or {}
                cand = (r.get("death") or {}).get("location_province")
                if isinstance(cand, int):
                    loc = cand
                    break
                ll = r.get("last_location") or {}
                if isinstance(ll.get("province"), int) and ll.get("date"):
                    dk = cl.date_key(str(ll["date"]))
                    if best_dk is None or dk > best_dk:
                        best_dk, loc = dk, ll["province"]
        if loc is None:
            return ""
        return self._place_of_province(loc)

    def _place_of_province(self, prov):
        """Province id → barony name (falling back to the county name; '' when neither).

        Extracted from `victim_place` so the death place and the birth place share one convention."""
        if not isinstance(prov, int):
            return ""
        bid = self.barony_at_province(prov)
        if bid is not None:
            nm = self.title_base_name(bid)
            if nm and not nm.startswith("b_"):
                return nm
        cid2 = self.county_at_province(prov)
        if cid2 is not None:
            nm = self.title_base_name(cid2)
            if nm and not nm.startswith("c_"):
                return nm
        return ""

    # ---- long-distance travel (travel_plans / activity_manager) ----
    @staticmethod
    def _plan_header(rec):
        """Travel plan record → the **plan header** (owner/activity/departure_date/destinations…).

        Shape: `database[<id>]` holds runtime state (`state` / `resume_date` / `progress_value` /
        `activity_completed`…) plus `data` → `{data: <plan header>, destinations: [...], path: {...}}`, so
        the header sits in the second level `data.data`, not the first."""
        d = (rec or {}).get("data") if isinstance(rec, dict) else None
        if not isinstance(d, dict):
            return {}
        inner = d.get("data")
        if isinstance(inner, dict) and ("owner" in inner or "departure_date" in inner):
            return inner
        return d

    @staticmethod
    def _plan_legs(rec):
        """Travel plan record → its legs [{province, arrival_date, estimated_arrival_date, path_index}];
        an unarrived leg keeps `arrival_date` = '-1.1.1'."""
        d = (rec or {}).get("data") if isinstance(rec, dict) else None
        legs = (d or {}).get("destinations") if isinstance(d, dict) else None
        return legs if isinstance(legs, list) else []

    @staticmethod
    def _act_body(rec):
        """Activity record → the activity object (type/host/current_phase/phases…), accepting the `data`
        wrapper."""
        if not isinstance(rec, dict):
            return {}
        inner = rec.get("data")
        if isinstance(inner, dict) and ("type" in inner or "host" in inner):
            return inner
        return rec

    @staticmethod
    def _plan_db(melt):
        """Melt → {plan_id: record}, keeping live plans only.

        The section is a top-level melt section and `Facts.melt` is the whole loaded melt, so reading it
        costs no extra I/O. Null slots and non-dict entries are skipped, since only part of the recorded
        slots hold live plans."""
        db = ((melt or {}).get("travel_plans") or {}).get("database") or {}
        return {str(k): v for k, v in db.items()
                if isinstance(v, dict) and isinstance(v.get("data"), dict)}

    def transit_facts(self, cid):
        """The travel plan this character is still on as of the melt instant.

        Covers a character who **died on the road**, where the text would otherwise say only 「卒于X」. Read
        from `travel_plans.database[<id>]` (runtime state plus the plan header, its legs `destinations[]`
        and `path`) and `activity_manager.database[<id>]` (the activity object). Three conventions hold: a
        plan disappears with death, so only the tier before death — this melt — can be read; the leg order
        `destinations = [activity place, home]` plus `activity_completed` distinguishes the outward and
        return legs, since the engine sets no hard flag; and a chapter cut-off earlier than the melt instant
        or the departure date suppresses everything, so a future journey never leaks into an early decade.

        Returns a data dict (None when there is no plan) for `transit_death_clause`, with keys
        `{role, plan_state, melt_date, departure_date, departure_place, to_place, to_arrived, activity,
        activity_type, activity_host_self, leg}`; stop counts and estimated arrivals are deliberately
        absent."""
        if cid is None:
            return None
        cid = str(cid)
        best = None                      # (优先级, plan_id, rec)
        for pid, rec in self._plan_db(self.melt).items():
            h = self._plan_header(rec)
            role = ""
            if str(h.get("owner")) == cid:
                role = "owner"
            elif str(h.get("travel_leader")) == cid:
                role = "travel_leader"
            elif any(str((c or {}).get("character")) == cid
                     for c in (h.get("companions") or [])):
                role = "companion"
            if not role:
                continue
            prio = {"owner": 3, "travel_leader": 2, "companion": 1}[role]
            if best is None or prio > best[0]:
                best = (prio, pid, rec, role)
        if best is None:
            return None
        _prio, _pid, rec, role = best
        h = self._plan_header(rec)
        legs = self._plan_legs(rec)
        melt_date = ((self.melt or {}).get("meta_data") or {}).get("meta_date") or ""
        dep = str(h.get("departure_date") or "")
        # ---- chapter gate, as with the death place: no future information in an early decade ----
        if self.as_of:
            ao = cl.date_key(str(self.as_of))
            if melt_date and cl.date_key(melt_date) > ao:
                return None
            if dep and dep != "-1.1.1" and cl.date_key(dep) > ao:
                return None
        dests = [d for d in (h.get("destinations") or []) if isinstance(d, int)]
        # ---- activity: plan header `activity` → activity_manager ----
        act_name, act_type, act_host_self = "", "", False
        aid = h.get("activity")
        if aid is not None:
            adb = ((self.melt or {}).get("activity_manager") or {}).get("database") or {}
            a = self._act_body(adb.get(str(aid)))
            act_type = str(a.get("type") or "")
            act_name = L.loc(self.table, act_type) or "" if act_type else ""
            act_host_self = str(a.get("host")) == cid
        first = legs[0] if legs else {}
        arrived = str(first.get("arrival_date") or "")
        arrived = "" if arrived in ("-1.1.1", "none") else arrived
        out = {
            "role": role,
            "plan_state": str(rec.get("state") or ""),
            "melt_date": melt_date,          # source tier, for the criteria and for tracing
            "departure_date": dep,
            "departure_place": self._place_of_province(h.get("departure_location")),
            "to_place": self._place_of_province(dests[0]) if dests else "",
            "to_arrived": arrived,
            "activity": act_name,
            "activity_type": act_type,
            "activity_host_self": act_host_self,
            # outward or return: leg order [activity place, home] plus `activity_completed` means the
            # activity is over and he is on the way home
            "leg": "回" if rec.get("activity_completed") else "去",
        }
        if not (out["to_place"] or out["departure_place"]):
            return None                  # no place resolvable, so nothing is emitted
        return out

    def transit_death_clause(self, t):
        """First half of a death sentence, e.g. 「1002年7月15日自秋田启程，赴坎特伯雷参加庆典，途中」.

        For a man who died on the road the sentence gives the departure day, where he set out from, where he
        was heading and for what, and whether he was outward or on the way back — never the stops already
        passed, the estimated arrival or the final stop. Prepended to `p["death"]` it forms one sentence. With
        `leg == "回"` (runtime `activity_completed` set) the wording is 「返程途中」; otherwise (outward,
        including a `paused` stay and a man already at his destination but still attending) it is 「途中」.
        `to_arrived` serves only as a cross-check and never enters the wording. '' when the departure date or
        the destination is unknown, since half a sentence is worse than none."""
        if not t or not t.get("to_place"):
            return ""
        dep = str(t.get("departure_date") or "")
        bits = []
        if dep and dep != "-1.1.1":
            bits.append(f"{self.date(dep)}自{t['departure_place']}启程"
                        if t.get("departure_place") else f"{self.date(dep)}启程")
        seg = f"赴{t['to_place']}"
        if t.get("activity"):
            seg += ("主办" if t.get("activity_host_self") else "参加") + str(t["activity"])
        bits.append(seg)
        bits.append("返程途中" if t.get("leg") == "回" else "途中")
        return "，".join(bits)

    def death_place(self, cid):
        """The character's **death place** (a barony).

        Shares its exit with `victim_place`, so the assassin chapter and the character file give the same
        place name (an executed man always counts as being at the subject's capital of that time). This
        function only gives that value a clearer name for the file layer. '' when unknown."""
        return self.victim_place(cid)

    def birth_place(self, cid):
        """The character's **birth place** (a barony).

        The save does **not** persist a birth place: the game places a newborn at the **mother's location**
        (`common/on_action/child_birth_on_actions.txt`), and the only birth-related persisted node is the
        `born_in_the_purple` trait, with no location field in the character record or a birth memory. So this
        uses only the location at the character's first appearance (`first_location`, latched in cache_lib),
        requiring it to fall within 400 days of birth because an infant does not travel alone. A first
        appearance much later than the birth returns '' rather than a wrong place; across campaign caches the
        earliest observation wins."""
        if cid is None:
            return ""
        rec = (self.cache.get("characters") or {}).get(str(cid)) or {}
        birth = rec.get("birth") or (self._chars.get(str(cid)) or {}).get("birth")
        if not birth:
            return ""
        if self.as_of and cl.date_key(str(birth)) > cl.date_key(str(self.as_of)):
            return ""                      # not yet born at this chapter's cut-off date
        best = None
        for src in [self.cache] + list((self.campaign or {}).values()):
            r = ((src or {}).get("characters") or {}).get(str(cid)) or {}
            fl = r.get("first_location") or {}
            if not fl.get("date") or not isinstance(fl.get("province"), int):
                continue
            if best is None or cl.date_key(str(fl["date"])) < cl.date_key(str(best["date"])):
                best = fl
        if best is None:
            return ""
        gap = date_gap_days(birth, best["date"])
        if gap is None or gap < 0 or gap > 800:
            return ""
        # Precise gate: when no other snapshot falls between the birth day and the first sighting, that
        # sighting is the first observation after birth, which matches the meaning better than a fixed
        # 400-day gate (a campaign missing snapshots would otherwise lose births in the gaps).
        bkey, fkey = cl.date_key(str(birth)), cl.date_key(str(best["date"]))
        if any(bkey < k < fkey for k in self._snapshot_dates()):
            return ""
        return self._place_of_province(best["province"])

    def _snapshot_dates(self):
        """All snapshot dates of this campaign, ascending (union of every character cache's `sources`).

        Used by `birth_place` to tell whether another snapshot falls between the birth and the first
        sighting, the premise that makes "first location = birthplace" hold."""
        if getattr(self, "_snap_keys", None) is not None:
            return self._snap_keys
        out = set()
        for src in [self.cache] + list((self.campaign or {}).values()):
            for d in ((src or {}).get("sources") or []):
                try:
                    out.add(cl.date_key(str(d)))
                except Exception:
                    continue
        self._snap_keys = sorted(out)
        return self._snap_keys

    def player_station_at(self, date):
        """County name of the player's last known station on or before `date`, from the location history in
        `cache.player_locations` (change points only).

        With no record at or before `date` the earliest entry is used; '' when there is no location history
        or the mapping fails."""
        hist = self.cache.get("player_locations") or []
        if not hist:
            return ""
        dk = cl.date_key(date) if date else None
        prov = None
        for loc in hist:
            if not loc.get("date"):
                continue
            if dk is None or cl.date_key(loc["date"]) <= dk:
                prov = loc.get("province")
        if prov is None:
            prov = (hist[0] or {}).get("province")
        county = self.county_at_province(prov)
        if county is None:
            return ""
        return self.title(county) or ""


