_REL_DIED_TYPES = ("relative_died", "rival_died", "friend_died", "lover_died",
                   "soulmate_died", "best_friend_died", "nemesis_died")


def _count_zh(n):
    """事物计数中文 (v28b): 一两桩/三桩…十桩/十二桩 (与世系编号 _ordinal_zh 区分)。"""
    digits = "零一二三四五六七八九"
    if n == 2:
        return "两"
    if n < 10:
        return digits[n]
    if n < 20:
        return "十" + (digits[n - 10] if n > 10 else "")
    if n < 100:
        t, r = divmod(n, 10)
        return digits[t] + "十" + (digits[r] if r else "")
    return str(n)


def _ordinal_zh(n):
    """世系编号中文 (v17): 二世…九世带「世」, 十起不带 (路易十一/路易十四)。
    n ≥ 2 才调用。"""
    digits = "零一二三四五六七八九"
    if n < 10:
        return digits[n] + "世"
    if n < 20:
        return "十" + (digits[n - 10] if n > 10 else "")
    if n < 100:
        t, r = divmod(n, 10)
        return digits[t] + "十" + (digits[r] if r else "")
    return str(n)


# v87 (问题1/P2): 游戏信封名 / 头衔名里的**罗马数字** → 项目世系汉字体
# (`教宗色尔爵III` → `教宗色尔爵三世`)。只在「汉字 + 尾部罗马数字」时折换,
# 避免把西文缩写当编号 (Rex/IV 之类); 数值上限 99 (超出的照旧原样)。
_ROMAN_RUN_RE = re.compile(r"([\u4e00-\u9fff])([IVXLCDM]+)$")
_ROMAN_VAL = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def _roman_value(s):
    """罗马数字串 → 整数 (不合法返回 0)。"""
    total, prev = 0, 0
    for ch in reversed(s or ""):
        v = _ROMAN_VAL.get(ch, 0)
        if not v:
            return 0
        total += -v if v < prev else v
        prev = max(prev, v)
    return total


def _roman_ordinal_zh(text):
    """「教宗色尔爵III」→「教宗色尔爵三世」(v87); 无尾部罗马数字则原样返回。"""
    s = str(text or "")
    m = _ROMAN_RUN_RE.search(s)
    if not m:
        return s
    n = _roman_value(m.group(2))
    if not 1 <= n <= 99:
        return s
    return s[:m.start(2)] + _ordinal_zh(n)


def _decade_lower_bound(f):
    """十年传记窗口下界 (v17): as_of 年 − 10 的年初, 不早于缓存起始年。
    返回 'YYYY.1.1' 或 None。"""
    if not f.as_of:
        return None
    try:
        y = int(str(f.as_of).split(".")[0])
    except Exception:
        return None
    start = None
    srcs = f.cache.get("sources") or []
    if srcs:
        try:
            start = int(str(srcs[0]).split(".")[0])
        except Exception:
            start = None
    lo = max(y - 10, start or (y - 10))
    return f"{lo}.1.1"


